insert into institution_regulations (regulation_id, institution_id, title, stage, lifecycle_state, current_state_note, updated_by) values
  ('reg_kagawa_conflict_of_interest', 'inst_kagawa', '香川大学利益相反委員会規則', 4, 'effective', '制定 平成18年4月1日、最終改正 令和4年4月1日。第2条で産学官連携に関する利益相反基準の策定・マネジメントの立案、利益相反事項の審議を所掌。第3条の委員構成は学長指名の理事又は副学長1人、各学部選出教員各1人、産学連携・知的財産センター長、副センター長、利益相反マネジャー、学外有識者1人等。第7条から第9条で利益相反審査会、利益相反不服審査会、利益相反マネジメントオフィスを設置。運用文書として「香川大学利益相反に係る審査手続」（令和4年4月1日修正、https://www.kagawa-u.ac.jp/files/6517/4787/4351/shinsatetsuduki202505.pdf ）と利益相反マネジメント方針がある。大学規程集で発見。', 'migration:385'),
  ('reg_kagawa_side_job', 'inst_kagawa', '国立大学法人香川大学職員兼業規程', 4, 'effective', '制定 平成17年4月1日、最終改正は令和6年4月1日施行。職員就業規則第38条に基づく兼業規程。第3条で学長が兼業許可権を部局長に委任するが、部局長自身の兼業、営利企業役員等兼業、自営兼業は除外。第5条で営利企業役員等兼業は香川大学営利企業役員等兼業審査委員会の議を経て許可。第10条で部局長の兼業はすべて学長の許可。大学発ベンチャーに特化した条項と株式保有の規定は本規程にない（株式は利益相反の審査手続が扱う）。関連規則として香川大学営利企業役員等兼業審査委員会規則（https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000058.html ）。大学規程集で発見。', 'migration:385'),
  ('reg_kagawa_ip_license', 'inst_kagawa', '香川大学職務発明規程', 4, 'effective', '制定 平成16年4月1日、最終改正 令和5年9月11日。第3条で大学は職務発明等に係る知的財産権の全部又は一部を承継し所有すると規定し、特別の事情がある場合は発明者帰属も可。第5条で権利帰属の決定プロセス、第9条で補償金（額は別に定める）。実施許諾の手続・対価は「別に定める」とされ本規程には含まれず、大学発ベンチャーへの優遇（独占的実施許諾、実施料減免、株式対価）の条項もない。技術移転は四国TLOと連携。大学規程集で発見。', 'migration:385'),
  ('reg_kagawa_joint_research', 'inst_kagawa', '香川大学共同研究取扱規程', 4, 'effective', '制定 平成19年4月1日、最終改正は令和7年10月1日施行。第2条で相手方を「企業等外部の機関」と定義し、大学発ベンチャーは企業等の枠に含まれるが個別の言及や専用条項はない。第3条で企業等の研究者を共同研究員として受け入れ、研究料は学長が定める額。第7条第2項で学長が特に認めた場合は間接経費を免除でき、大学発ベンチャーへの適用余地はあるが明文の優遇ではない。第8条第1項で共同研究のため新たに取得した設備等は本学の所有。別に「香川大学特別共同研究取扱規程」（x872RG00000930）もある。大学規程集で発見。', 'migration:385'),
  ('reg_kagawa_shared_equipment', 'inst_kagawa', '香川大学における研究設備・機器の共用に関する規程', 4, 'effective', '令和6年1月31日施行。共用方針（令和4年12月15日制定）及び共用設備・機器運用方針（令和5年3月1日制定）に基づく。第6条で利用者の範囲を、学内外における共同研究・プロジェクト研究等の関係者、受託試験・検査等の依頼者、管理部局長が認めた者と規定し、学外の企業・大学発ベンチャーも利用可能。第7条で申請は管理部局所定の手続、第8条で変更時の届出、第10条第1項で管理部局が別に定める利用料を負担。学内外の料金区分と認定ベンチャー優遇の記載はない。大学規程集で発見。', 'migration:385'),
  ('reg_nims_conflict_of_interest', 'inst_nims', '国立研究開発法人物質・材料研究機構 利益相反マネジメント規程', 4, 'effective', 'NIMS規程類一覧（情報公開）から取得したPDF本文を確認。平成29年7月12日 29規程第47号。第2条で利益相反・産独連携活動・経済的利益等を定義し、第6号の「援助措置等」でNIMSベンチャー援助等規程第9条・第15条、成果活用事業者から対価として取得する株式等取扱規程第3条を明示的に取り込む。第3条で利益相反マネジメント委員会を設置（委員長は法務・コンプライアンス室担当理事、委員に外部有識者を含む）、第7条で事務は法務・コンプライアンス室。産独連携活動の相手方株式等を保有する場合（公開株は5%以上）等に自己申告義務。', 'migration:385'),
  ('reg_nims_side_job', 'inst_nims', '国立研究開発法人物質・材料研究機構 兼業等規程', 4, 'effective', 'NIMS規程類一覧（情報公開）から取得したPDF本文を確認。平成18年3月28日 18規程第10号。第2条で役員兼業（営利企業の役員等を兼ねること）を定義、第3条で兼業等審査委員会を設置。第5条で役員兼業開始予定日の1箇月前までに理事長へ申請、第6条で委員会審査を経て許可（許可は原則2年を超えない期間）、第8条に許可取消、第9条に勤務時間内役員兼業、第10条に役員兼業休職。第6章（第34条・第35条）で兼業先からのエクイティ報酬の事前届出と半期ごとの受領報告を義務付ける。', 'migration:385'),
  ('reg_nims_joint_research', 'inst_nims', '国立研究開発法人物質・材料研究機構 共同研究の実施に関する規程', 4, 'effective', 'NIMS規程類一覧（情報公開）から取得したPDF本文を確認。平成13年11月8日 13規程第72号、直近改正 令和5年2月28日 2023規程第50号。NIMSベンチャー援助等規程第14条が本規程を指定し、機構はNIMSベンチャーと共同研究契約を締結して同規程に基づく共同研究者への援助等を行える。第3条で共同研究の種類、第15条で共同研究者への独占的通常実施権の付与、第20条で研究施設及び装置の相互使用（対価は無償又は有償）、第27条で事務は外部連携部門企業連携室。', 'migration:385'),
  ('reg_ehime_equity_stock_option', 'inst_ehime', '愛媛大学におけるライセンス等の対価として取得する株式等取扱細則', 4, 'effective', '令和元年8月1日学長裁定。知的財産権規程第21条（ライセンス等の対価の特例）に基づく細則で、ライセンス対価を現金で支払うことが困難な大学発ベンチャーから株式・新株予約権を取得できる。知的財産委員会が財務状況等を踏まえ審査し、研究・産学連携担当理事が取得を決定して学長へ報告、契約を締結する。新株予約権の変更・処分も委員会審査と理事承認が必要。発明者報酬は換金時に支払う。附則に令和4年4月1日・令和6年4月1日施行の改正。愛媛大学規則集（第04編 社会連携／第02章 知的財産）のファイル名検索で発見。', 'migration:385'),
  ('reg_ehime_recognition_committee', 'inst_ehime', '愛媛大学研究・産学連携推進機構研究・産学連携推進会議規程', 4, 'effective', '令和6年4月1日規則第23号、最終改正は令和8年7月8日施行。認定規程第3条2項が「認定の適否を審議する」と定める研究・産学連携推進会議の組織・運営規程。委員は機構長、副機構長、機構長補佐、研究イノベーション推進本部長、学術支援センター長、各学部等の統括研究・産学連携コーディネーター、研究・産学連携支援部長ほか。議長は機構長。委員の過半数出席で開議し、出席委員の過半数で議決、可否同数は議長決。大学発ベンチャー認定専用の委員会内規は規則集のファイル名検索では存在しない。', 'migration:385'),
  ('reg_qst_ip_license', 'inst_qst', '職務発明等取扱規程', 4, 'effective', 'QST規程集ページ（about-qst/1312.html）掲載のPDF本文を全文確認。平成28年4月1日制定 28（規程）第79号、最終改正 令和5年1月1日 令04（規程）第32号。第5条・第6条で職務発明の認定と権利の機構承継、第9条・第10条で実施許諾と実施契約、第11条で独占的実施の要件、第12条で独占停止、第13条で権利譲渡、第14条で実施補償金、第16条で知的財産審査会を規定。ベンチャー限定の優遇条項は本規程にはなく、認定ベンチャーへの独占許諾はベンチャー支援制度側で措置。', 'migration:385'),
  ('reg_qst_shared_equipment', 'inst_qst', '高崎量子技術基盤研究所施設供用規則', 4, 'effective', '施設供用の「申請様式・約款・規則」ページ掲載のPDF本文を確認。令和6年4月1日 令06高（規則）第17号。機構法第16条第4号に基づき、あらかじめ指定した供用施設を機構外で研究開発を行う者の利用に供する基本事項を定める。第6条で成果公開課題の年2回以上の公募と成果非公開課題の随時受付、第7条で所長による採択（成果公開課題は施設供用課題審査委員会の意見聴取）、第14条で所定の利用料金の徴収を規定。高崎地区の規則で、認定ベンチャー専用ではない。', 'migration:385'),
  ('reg_c030bad12839_shared_equipment', 'inst_catalog_c030bad12839', '九州大学研究環境整備事業に係る研究機器・設備利用規程', 4, 'effective', '令和3年度九大規程第69号。施行 令和3年8月6日、最終改正 令和6年5月31日（令和6年度九大規程第9号）。大学公式規則集 第7編 会計のPDF一覧から到達し、本文をテキスト抽出して全条文を確認した。第2条で利用希望者・分析依頼者は所定手続で申請し許可を得る、第5条と別表で「本学が管理する経費から支出される場合」と「左記以外の経費から支出される場合」の2区分の時間単価を設定（学外資金からの支払いは高い方の単価）、総長が特に認めれば減免可。', 'migration:385'),
  ('reg_c030bad12839_support_rules', 'inst_catalog_c030bad12839', '大学発ベンチャーに対するライセンス等の対価の優遇措置に関するガイドライン', 4, 'effective', '平成31年3月1日実施。学術研究・産学官連携本部（AiRIMaQ）の「各種ポリシー・規則」ページから到達し、本文3ページ全文を確認した。九大で唯一、大学発ベンチャーへの起業後支援の対象・内容・期間を明文化した文書。対象は教職員（又は学生）が出資・役員・技術顧問として参画し本学知財を活用する企業のうち外部資金またはギャップファンドで事業化検証の成果を得たもの。優遇は起業後5〜6年目まで（協議で延長可）。脚注iに「本学では、『大学発ベンチャー』の公式の認定は行っていない。」と明記。', 'migration:385'),
  ('reg_c030bad12839_recognition_committee', 'inst_catalog_c030bad12839', '九州大学における株式等の取得に関する専門家会議実施要項', 4, 'effective', 'AiRIMaQ「各種ポリシー・規則」ページの知的財産の区分に「学内限定」の印つきで掲載されている実施要項。九大には認定委員会が存在せず、株式等取扱規程第4条第2項および出資規程第4条第2項に基づき産学官連携戦略会議の下に置かれる専門家会議が支援対象と対価の審査を行うため、認定委員会内規に相当するのはこの要項。PDF本体（kabushikitounosyutoku_senmonkakaigi_jissiyoukou_20240401.pdf）はシングルサインオン認証が必要で本文は確認できず、URLは実際に開いて掲載を確認した一覧ページを記載。ファイル名から令和6年4月1日版と読める。［検証エージェントは出典を開けず未照合］', 'migration:385'),
  ('reg_be0174a565d7_recognition_committee', 'inst_catalog_be0174a565d7', '九州工業大学発スタートアップ支援審査会要項', 4, 'effective', '令和8年6月19日研究本部長裁定。研究本部細則第15条第2項に基づき設置。第2条でSU支援規程第4条の支援申請の審議を所掌。第3条で委員は研究本部長、研究副本部長、産学イノベーションセンター長、未来思考実証センター長、社会実装推進部門長、本部長推薦の若干名。第5条で研究本部長が委員長。第6条で委員の3分の2以上の出席で成立、出席委員の過半数で議決、可否同数は委員長決。第8条で審査結果を研究推進機構運営会議へ報告。大学規則集で本文を確認。', 'migration:385'),
  ('reg_be0174a565d7_shared_equipment', 'inst_catalog_be0174a565d7', '九州工業大学設備共用推進領域規程', 4, 'effective', '令和2年3月9日制定・九工大規程第10号。第2条で研究設備・機器等を集中管理し「学内外の者に共同利用を供する」と定め、第3条でマイクロ化総合技術センターと機器分析センターを置く。九工大発スタートアップの設備利用の根拠はSU支援規程第5条第1項(3)の優遇措置で、料金・安全・責任は各センターの規程が担う（超小型衛星試験センター機器利用取扱要項は学内移算／学外協議の料金区分と免責を規定）。スタートアップ専用の共用機器規程は規則集335件を通覧しても存在しない。', 'migration:385'),
  ('reg_0278b48721bd_support_rules', 'inst_catalog_0278b48721bd', 'ベンチャーインキュベーションセンター内規', 4, 'effective', '成長戦略本部のKUViC利用申込ページから公募要領一式のzipを取得し、内規本文PDF（07_kuvic_rule.pdf）を通読して確認した。平成28年7月1日に統括管理者（産官学連携本部長）裁定で制定、令和6年4月1日に統括管理者（成長戦略本部長）裁定で改正。京都大学国際科学イノベーション棟規程第3条第2項に基づき、使用者の範囲（第6条）、使用期間6月以上1年以内・通算3年（第7条）、申請と教職員紹介（第8条）、運営委員会の議を経たセンター長の許可（第9条・第18条）、使用料別表を定める。認定規程ではなく大学発スタートアップ向け支援施設の運用細則。', 'migration:385'),
  ('reg_f77a046888fb_shared_equipment', 'inst_catalog_f77a046888fb', '京都府公立大学法人における大学発ベンチャー企業の認定等に関する規程 第7条第1項第3号（研究設備等の利用許可）', 4, 'effective', '独立した共用機器利用規程は法人サイトの規則・規程一覧（規則4本、規程第1〜49号、ポリシー6本）に存在しない。認定規程第7条第1項第3号が認定ベンチャーへの「研究設備等の利用を許可すること」を便宜措置として規定し、便宜措置申請書（様式第5号）に「□第3号：研究設備等の利用許可」のチェック欄がある。申請先は称号授与大学の学長、期間は認定期間の末日までの範囲で学長が定める（第7条第2項）。料金区分・利用料の定めは同規程内になし。PDF全文（12ページ）で確認。', 'migration:385'),
  ('reg_355ac37a0d09_equity_stock_option', 'inst_catalog_355ac37a0d09', '国立大学法人信州大学における認定大学発スタートアップを対象としたライセンス等の対価として取得する株式等取扱規程', 4, 'effective', '令和4年11月16日制定（規程第183号）、令和4年12月1日施行。改正は令和6年3月18日（令和5年度規程第113号）と令和7年10月2日（令和7年度規程第80号、令和7年10月3日施行）で、施行中の最新版を規程集ページで全文確認した。認定規程第13条と知的財産権実施許諾等取扱規程第5条に基づく下位規程。株式等＝株式及び新株予約権と定義（第2条第3号）、取得3要件（第3条）、機構長を委員長とする審査委員会（第4条）、学長決定と契約締結（第5条）、財務部管理（第6条）、共益権の原則不行使（第8条）、換金可能後の速やかな売却（第9条）、インサイダー取引防止（第11条）を定める。信州大学規則集の現行規則一覧から発見。', 'migration:385'),
  ('reg_355ac37a0d09_recognition_committee', 'inst_catalog_355ac37a0d09', '信州大学学術研究・産学官連携推進機構大学発スタートアップ認定委員会細則', 4, 'effective', '平成30年3月28日制定（信州大学細則第107号）、平成30年4月1日施行。改正は令和4年3月31日（令和3年度細則第47号）と令和6年3月18日（令和5年度細則第27号、令和6年4月1日施行）で、施行中の最新版を規程集ページで全文確認した。認定規程第4条第2項に基づく下位細則。審議事項（認定、認定・称号授与の取消し等／第2条）、機構長ほか10職を含む委員構成（第3条）、機構長が委員長（第4条）、定足数3分の2以上・出席委員の過半数で議決（第5条）、庶務は研究推進部（第7条）。信州大学規則集の現行規則一覧から発見。', 'migration:385'),
  ('reg_355ac37a0d09_shared_equipment', 'inst_catalog_355ac37a0d09', '信州大学共同利用大型機器利用規程', 4, 'effective', '平成16年4月1日制定（信州大学規程第6号）、同日施行。信州大学規則集の現行規則一覧から発見し、全文を確認した。大学発スタートアップ専用の規程ではなく全学の共用機器規程である点に注意。利用資格は本学職員・学生のほか「機器管理責任者が適当と認めた者」（第2条第3号）で、認定スタートアップはこの号を通じてのみ利用しうる。利用の範囲（第3条）、申請と承認（第4-5条）、経費は利用者負担で額は別に定める（第10条）、故意重過失時の原状回復・損害賠償（第11条）を規定。料金額を定める信州大学共同利用大型機器利用細則（規程集ID 110000172）が別に存在する。［検証エージェントは出典を開けず未照合］', 'migration:385'),
  ('reg_7c5298d724e8_shared_equipment', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学オープンファシリティ使用規程', 4, 'effective', '公式規程データベース（Reiki-Base）で本文を確認。平成17年10月24日 海大達第231号制定、令和8年7月1日 海大達第108号最終改正。第3条が使用できる者を6区分で定め、第5号に「研究開発等のために設備を利用する民間企業その他の法人に所属する者」を含む。第5条が学内利用者と学外利用者の使用料（基本料＋時間単価）を区分し、管理責任者が特に認めるときの全部または一部免除を定める。管理責任者は創成研究機構長。大学発ベンチャー・認定スタートアップ企業に固有の条項はなく、一般の民間企業と同じ扱い。', 'migration:385'),
  ('reg_656caf0f3d72_support_rules', 'inst_catalog_656caf0f3d72', '北陸先端科学技術大学院大学ベンチャー・ビジネス・ラボラトリー利用規則', 4, 'effective', '平成14年9月24日北院大規則第19号。令和7年10月1日規則第106号改正まで反映。例規集の分野別検索「共創活動推進課」一覧から到達し全文を確認。認定規則第12条の支援（VBL利用・登記住所）を実施するための細目規程で、第2条第2号が「認定後3年を経過していない大学発ベンチャー」を利用資格者とし、第3条で学長の許可、第4条で利用申請書、第5条でベンチャー・ビジネス研究課題選定・評価委員会と施設マネジメント委員会の議を経た審査・決定、第7条で利用期間3年以内（認定前の利用期間は含めない）、第9条で規則遵守と許可取消しを定める。費用面は「同ラボラトリーの利用に係る経費の負担額及び負担方法に関する細則」(act/110000259.html)が別に定める。', 'migration:385'),
  ('reg_c6d191a944c4_shared_equipment', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学研究設備等利用規程', 4, 'effective', '規程集の体系目次（第1編全学共通・第7章学術研究）で発見し本文を確認。令和6年4月1日制定、令和8年7月1日施行の改正あり。「千葉大学研究設備戦略的整備・運用計画」に定めるコアファシリティの利用を対象とし、第3条で管理責任者が利用料金を算定し研究基盤管理機構ファシリティ戦略会議へ報告・学長承認後に公表、第4条で管理部局の所定手続による申請と許可、第5条で利用料金の支払義務と善管注意義務、第7条で損害賠償、第8条で目的外利用・第三者利用の禁止を規定。大学発スタートアップ専用の規程ではなく全利用者共通の設備利用ルール。', 'migration:385'),
  ('reg_c6d191a944c4_recognition_committee', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学学術研究・イノベーション推進機構学術研究・イノベーション戦略企画本部会議規程', 4, 'effective', '規程集の体系目次（第2編部局等・第8章学術研究・イノベーション推進機構）で発見し本文を確認。平成26年10月1日制定、令和7年4月1日施行の改正あり。関連スタートアップ支援規程第6条が支援の可否決定にあたり「学術研究・イノベーション戦略企画本部会議の議を経て」と定めており、本会議が事実上の認定審議体。第3条で機構長・副機構長・研究担当副学長・その他機構長が必要と認める者により構成（任期2年・再任可）、第4条で議長は機構長、第5条で議長が必要と認めるとき開催、第7条で執行部会へ付託しその議決を本部会議の議決とできる。スタートアップ認定専用の委員会内規ではない点に留意。', 'migration:385'),
  ('reg_ad192eae70e9_equity_stock_option', 'inst_catalog_ad192eae70e9', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則', 4, 'effective', '東海国立大学機構規則集（LegalCRUD公開版）の現行規則一覧から特定し全文を確認。令和2年4月1日機構細則第61号として制定、令和5年3月31日機構規程第83号により改正（令和5年4月1日施行）。知財の運用・処分に際し成果活用事業者の現金支払を免除・軽減し、代わりに無償発行の株式又は新株予約権を取得できると規定（第2条）。取得株式は発行済総数の半数未満（第3条）、議決権不行使（第4条）、利益相反防止措置（第5条）、収入分配（第7条）。旧「名古屋大学における知的財産権の実施の許諾又は処分に伴う株式等の取扱細則」を廃止し承継。', 'migration:385'),
  ('reg_ad192eae70e9_shared_equipment', 'inst_catalog_ad192eae70e9', '名古屋大学全学技術センター技術支援業務等に関する取扱規程', 4, 'effective', '東海国立大学機構規則集の現行規則一覧から特定し全文を確認。令和3年12月21日名大規程第42号として公布、令和4年1月1日施行、直近改正は令和7年12月2日名大規程第19号。全学技術センターが保有する専門的知識・技術を提供する技術支援業務と技術コンサルティングの依頼手続（第3条）、技術料等の徴収（第4条）、依頼者区分別の料金（第5条、別表1〜5）を規定。機構外の企業も依頼可能で、中小企業等は技術料3,900円/時、大企業等は6,500円/時。大学発ベンチャー向けの優遇区分はない。', 'migration:385'),
  ('reg_ad192eae70e9_support_rules', 'inst_catalog_ad192eae70e9', '名古屋大学インキュベーション施設のプロジェクト開発室使用細則', 4, 'effective', '東海国立大学機構規則集の現行規則一覧から特定し全文を確認。平成17年4月1日細則第50号として制定、直近改正は令和7年7月23日名大細則第3号（令和7年10月1日施行）。称号授与企業への施設支援の申請・審査・期間・条件を定める実施細則で、使用承認は学術研究・産学官連携推進本部会議の審査を経る（第2条・第3条）、使用期間は2年以内で2年ごと更新・5年限度（第4条）、成果報告義務（第5条）、光熱水料は実費（第7条）、負担金と新株予約権割当による貸付料免除（第8条第3項）を規定。', 'migration:385'),
  ('reg_c8343bcae1a5_shared_equipment', 'inst_catalog_c8343bcae1a5', '起業活動拠点ものづくりスペースM-STUDIO 利用ルール', 4, 'effective', '社会連携センターPLATのM-STUDIOページの「利用案内」リンクからPDFを取得し全文を確認。利用可能者を①本学の学生/教職員 ②Tongaliプロジェクトによるプログラム参加者 ③企業・自治体・NPOの方で本学とプロジェクトにて連携する方、と定め、利用料は「スペースや設備利用は無料。Fab機器等の材料費については活動目的により異なる」。3Dプリンター等は事前講習とライセンス取得が必要、拠点利用は原則予約不要、Fab機器は事前申込制。制限事項に営利目的利用を挙げ販売目的の施設利用を禁止、破損・紛失時は相当額弁償と規定。制定日の記載は無い。', 'migration:385'),
  ('reg_18402bd4d9e6_external_program_support', 'inst_catalog_18402bd4d9e6', '令和7年度第2回公募 募集要項（大学発医療系スタートアップ支援拠点事業 補助事業 S0〜S2共通）', 4, 'effective', '令和8年1月付、橋渡し研究推進センター（CPOT）発行。全21ページを取得して全文確認。AMED大学発医療系スタートアップ支援拠点（令和6年9月1日採択、NCC SAP）の起業前後支援ルールで、募集対象と応募条件、支援額・期間（S0最大1,000万円／年度、S1最大3,000万円／年度、S2最大1億5,000万円／年度）、委託研究開発契約、伴走支援・教育・海外展開の内容、支援対価の料金表徴収予定、成功報酬（新株予約権を想定）の検討、目標達成（法人登記またはシリーズA相当の調達）による委託終了条件を規定。NCC SAP応募方法ページから取得。', 'migration:385'),
  ('reg_18402bd4d9e6_conflict_of_interest', 'inst_catalog_18402bd4d9e6', '国立研究開発法人国立がん研究センター組織COI管理規程', 4, 'effective', '規程本文は非公開。「組織としての利益相反（組織COI）に関する情報公開」ページ（更新日2026年5月11日）に、同規程を定めて組織としての利益相反を管理し情報公開すると明記されており、規程の存在と正式名称をここで確認した。同ページはARC Therapiesの新株予約権・株式の保有（2024年9月28日〜）、出資行為なし、企業との人事交流を開示。研究者個人の利益相反はCOI管理室と利益相反委員会が担当。登録URLは規程名の出典ページであり規程本文ではない点に注意。', 'migration:385'),
  ('reg_18402bd4d9e6_joint_research', 'inst_catalog_18402bd4d9e6', '国立がん研究センター共同研究取扱規程', 4, 'effective', '規程本文は非公開。産学連携・知財戦略課Q&Aの企業向け・研究者向け双方に「本センター共同研究取扱規程を踏まえ」共同研究審査委員会への申請書類・契約書を作成する旨が記載され、規程の存在と名称をここで確認した。共同研究の新規開始には共同研究審査委員会の審査が必要で、同課が事務局。共同研究から生じた発明は共同出願とし、相手先に優先的な使用権を認める運用。登録URLは規程名の出典ページであり規程本文ではない点に注意。', 'migration:385'),
  ('reg_4dd74810eb71_support_rules', 'inst_catalog_4dd74810eb71', '大阪大学テクノアライアンス棟利用規程', 4, 'effective', '共創機構サイトが公開するPDF本文を実際に読み確認。平成23年4月1日施行、直近改正は令和7年3月21日施行。第3条第3号が「本学で得られた研究成果を基に設立されたベンチャー(大学発ベンチャー)の役職員及び大学発ベンチャーの設立を目指す研究プロジェクトの研究開発者」を利用資格に明記し、第4条〜第9条で利用目的、申込み、管理運営委員会の議による可否決定、利用期間(大学発ベンチャー目的は原則1年以上5年以下)、経費の原則利用者負担を定める。認定を前提とした支援細則ではなく、大学発ベンチャーへの施設提供という支援の申請・審査・期間・条件を定める規程としてこの種別に登録した。', 'migration:385'),
  ('reg_e61783be8ca3_recognition_committee', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学研究・イノベーション推進機構規程', 4, 'effective', '平成27年3月25日制定・規程第7号。PDF本文（目次〜第4条の3）を実際に開いて確認。第3章が「研究・イノベーション推進会議」で、第4条の2第1項が審議事項（研究成果の社会への還元に係る支援の実施に関する事項を含む）、第2項が委員構成（機構長、各領域長、研究推進部門長、イノベーション推進部門長、事業推進部長、その他学長が必要と認める職員）、第3項〜第5項が議長・代理、第4条の3が部会設置を定める。大学発スタートアップ認定規程第3条第2項が本会議の議を経ることを明示しており、独立した認定委員会内規は存在せず本規程が委員構成・審議の根拠になっている。規程集索引の表記は「研究推進機構規程」だが本文の正式名称は上記のとおり。', 'migration:385'),
  ('reg_634ea0a5f19c_conflict_of_interest', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学利益相反マネジメント規程', 4, 'effective', '平成23年9月14日制定。大学規則集で本文を確認。山形大学利益相反マネジメントポリシー（平成21年9月9日制定）に基づき、兼業報酬・特許収入・未公開株式の保有等の個人的利益を管理対象とする（第2条第3号）。全学委員会（第8条〜）と部局委員会（第15条〜）の二層で審査し、全学委員会は学外の専門家も委員に含む（第10条第1項第4号）。認定規程第4条第4号が本規程の手続履行を認定申請の条件として参照している。', 'migration:385'),
  ('reg_634ea0a5f19c_joint_research', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学における外部機関との共同研究取扱規程', 4, 'effective', '平成16年4月1日制定。大学規則集の体系目次「第4編第2章 産学官地域連携・知的財産」から到達し本文を確認。会社を含む外部機関一般との共同研究を対象とし、大学発ベンチャー専用の規程ではない。受入決定・契約締結は学長（1億円未満は法人部局長へ委任、第3条）、共同研究員の研究料は6か月以内22万円・1年以内44万円（第5条）、直接経費のほか間接経費規程による間接経費を徴収（第6条）。', 'migration:385'),
  ('reg_634ea0a5f19c_recognition_committee', 'inst_catalog_634ea0a5f19c', '山形大学研究戦略企画本部規程', 4, 'effective', '令和5年3月22日制定、令和5年4月1日施行。本文を確認。山形大学は専用の「認定委員会」を置かず、認定規程第3条第2項により研究戦略企画本部の議を経て学長が認定する。本規程は同本部の構成員（研究・産学連携担当理事又は副学長、研究ディレクター、研究情報部長、本部長指名者）と業務、本部長、事務（研究情報部）を定めるが、ベンチャー認定の審議手続や議決要件までは規定していない。', 'migration:385'),
  ('reg_634ea0a5f19c_shared_equipment', 'inst_catalog_634ea0a5f19c', '山形大学研究設備・機器の整備・共用推進に関する方針', 4, 'effective', '令和5年3月29日役員会決定。大学サイト「研究機器の利用・依頼分析」からPDFを取得し本文を確認。規程ではなく全学方針で、大学発ベンチャー限定でもない。汎用性があり一定規模以上の設備・機器は原則共用（2項）、研究基盤本部が共用を推進（3項）、利用者から適正な利用料金を徴収し経費配分（4項）、学外者への共用体制を構築し地域・産業界の活性化に貢献（6項）と定める。', 'migration:385'),
  ('reg_5617b63909d5_conflict_of_interest', 'inst_catalog_5617b63909d5', '国立大学法人山梨大学利益相反マネージメントポリシー', 4, 'effective', '制定 平成16年4月1日、改正 平成19年2月21日・平成20年4月1日・平成26年4月1日・平成28年3月29日。全3ページ、機構サイト「機構概要＞ポリシー」に掲載（整理番号Ⅱ-5）。対象者は常勤・有期・非常勤職員、再雇用職員、雇用関係にあるポスドク・大学院生・学部生、共同研究員、受託研究員。対象事象の第一に職員兼業規程による兼業活動を挙げ、年1回の利益相反自己申告書提出を義務化。利益相反アドバイザーの検討と利益相反専門委員会の対応方策決定という5段階の手続を規定。原URLは https://www.scrs.yamanashi.ac.jp/wp-content/uploads/2015/08/2f02d53c73093ceafadc939b3f5ca02c.pdf だが当方の回線からは403のため、Wayback Machineの保存版を開いて本文を確認した。関連文書に「国立大学法人山梨大学医学研究に係る利益相反マネージメントポリシー」（Ⅱ-6、平成22年3月24日制定）がある。', 'migration:385'),
  ('reg_5617b63909d5_ip_license', 'inst_catalog_5617b63909d5', '国立大学法人山梨大学知的財産ポリシー', 4, 'effective', '制定 平成16年4月1日、改正 平成24年4月1日・平成26年4月1日・平成28年3月29日。全3ページ、機構サイト「機構概要＞ポリシー」に掲載（整理番号Ⅱ-2）。職務発明等・職務著作物等の大学帰属、発明審査・評価専門委員会への諮問による承継判断、出願補償金・実施補償金の支払を規定し、下位規程として「職務発明等取扱規程」「職務著作物等取扱規程」「共同研究取扱規程」「職務発明等に対する補償金支払内規」を参照する。大学発ベンチャーへの優先実施許諾や対価優遇の条項は含まない。原URLは https://www.scrs.yamanashi.ac.jp/wp-content/uploads/2015/08/9cfb4b59318481d1b4cb56098791bdf9.pdf （当方の回線からは403のためWayback Machineの保存版で本文確認）。関連して「国立大学法人山梨大学研究ライセンスポリシー」（Ⅱ-4、平成21年3月18日制定）が非営利研究目的の非排他的実施許諾をロイヤリティ・フリー又は合理的ロイヤリティで供与すると定める。', 'migration:385'),
  ('reg_84b7d5c12a65_support_rules', 'inst_catalog_84b7d5c12a65', '東海国立大学機構Tokai Open Innovation Complex岐阜サイト産学連携オープンラボ使用内規', 4, 'effective', '岐阜大学学術研究・産学官連携推進本部サイトの「入居者募集について」から参考資料として公開されているPDFを開いて全文を確認。制定令和5年5月17日、改正令和6年2月2日、令和7年10月1日。機構TOIC規程第3条第4項に基づく施行規則で、認定後の支援の中核である施設提供と本店登記の申請・審査・期間・条件を定める。第5条使用資格、第6条使用申請（第2項でベンチャー企業の商業登記先としての利用申請）、第7条・第8条で推進本部運営会議による審査、第10条で使用期間は1回3年、第13条で使用許可の取消し、第14条で負担金・貸付金、第15条で光熱水料、第16条で原状回復と登記変更を規定。', 'migration:385'),
  ('reg_faf4fe8290f5_equity_stock_option', 'inst_catalog_faf4fe8290f5', '国立大学法人岡山大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程', 4, 'effective', '研究・イノベーション共創機構（ORSD）の「規程・様式」ページの「大学発ベンチャー支援関連（学内限定）」区分で、この正式名称と「2024年3月改正」の表示を確認した。同区分には「株式等による支払い申込書（2021年5月改正）」も併載されており、実施許諾等の対価を株式等で受け取る運用が様式まで整備されている。本文PDF（wp-content/uploads/gakunai/venture_kitei_2024.pdf）は学内限定でHTTP 403のため条文は未確認、制定日も不明。規程名と最終改正年月のみ公開ページで裏取り済み。', 'migration:385'),
  ('reg_9e581f664d73_side_job', 'inst_catalog_9e581f664d73', '川崎医科大学　大学発ベンチャー企業起業にかかる兼業に関する規程', 4, 'effective', '「川崎医科大学発ベンチャー」ページ（/sanchi/venture.php）から公開されている「大学発ベンチャー兼業許可申請書」（様式１（第５条関係））をダウンロードして本文を確認した。申請文に「川崎医科大学　大学発ベンチャー企業起業にかかる兼業に関する規程第５条に基づき、下記のとおり兼業の申請をいたします」と規程名が明記されている。申請先は学長。記載欄は法人名、所在地、代表者、兼業職名、兼業内容、事業概要、所定労働時間内の兼業の有無と週あたり従事時間、兼業開始日、報酬の有無と金額、⑩「大学発ベンチャーの申請資格　規程第２条第（１・２・３・４）号」。規程本文PDFは学外非公開（規程・ポリシーページは学内専用で401）。制定日は不明。', 'migration:385'),
  ('reg_9e581f664d73_support_rules', 'inst_catalog_9e581f664d73', '川崎医科大学発ベンチャー支援に関する規程', 4, 'effective', '「川崎医科大学発ベンチャー」ページから公開されている様式ファイルをダウンロードして本文を確認した。様式３「大学発ベンチャー事業報告」に「川崎医科大学発ベンチャー支援に関する規程により、下記のとおり事業報告をいたします」と規程名が明記されている。同ファイルは様式１「大学発ベンチャー支援申請書」（学長宛。支援希望内容として称号、施設・設備の使用、知的財産権等の優遇措置、登記住所を本学所在地とすること、その他。支援期間は最長２年を限度。添付書類６点。免責の付帯事項）と、様式２「大学発ベンチャー支援決定申請書」（学長名で支援決定・不支援と理由を通知）を収める。規程本文は学外非公開で、制定日は不明。', 'migration:385'),
  ('reg_b23ba1a5f5b4_ip_license', 'inst_catalog_b23ba1a5f5b4', '広島大学技術移転細則', 4, 'effective', '規程集で全8条＋附則を確認。平成16年7月21日副学長（社会連携担当）決裁で制定、令和7年1月10日一部改正が最新。第3条で実施権許諾・譲渡は原則有償、第4条・第5条で共同研究・受託研究の優先実施、第6条が「ベンチャー企業の支援」として直接経費を目安とした有償譲渡、低率な実施料による独占的通常実施権の許諾、設立から3年を上限とする実施料免除を定める。第7条で実施料収入の分配率（発明者40％等）を規定。大学発ベンチャーへの知財優遇の一次根拠。', 'migration:385'),
  ('reg_b23ba1a5f5b4_equity_stock_option', 'inst_catalog_b23ba1a5f5b4', '広島大学におけるライセンス等の対価として取得する株式等取扱細則', 4, 'effective', '規程集で全10条＋附則を確認。平成29年2月21日理事（社会産学連携担当）決裁で制定、令和7年1月10日一部改正が最新。職務発明規則第26条に基づき、大学発ベンチャー企業の育成を目的として、知財のライセンス対価を現金に代えて株式・新株予約権で取得する取扱いを定める。第3条で対象はベンチャー企業かつ現金支払が困難な場合、第4条で発明審査会が審査、第5条で理事が決定、第6条で新株予約権の行使、第7条で公開後の速やかな売却、第8条で経営参加権を原則不行使と規定。', 'migration:385'),
  ('reg_b23ba1a5f5b4_shared_equipment', 'inst_catalog_b23ba1a5f5b4', '広島大学共用機器に関する規則', 4, 'effective', '規程集で全17条＋別表を確認。令和2年10月23日規則第212号で制定（令和2年11月1日施行）、令和8年6月30日規則第43号が最新改正。第2条で共用機器を「学内又は学外での共同利用に供する」研究用機器と定義、第7条で研究・教育・開発・診療目的の利用を認め、第8条で利用者を大学連携研究設備ネットワーク登録者及び理事が適当と認める者とする。第14条と別表が機器ごとに学外者・学内者の料金を分けて定める。附則で平成20年の学外者利用要項を廃止。', 'migration:385'),
  ('reg_b23ba1a5f5b4_support_rules', 'inst_catalog_b23ba1a5f5b4', '広島大学における教育・研究施設の有効活用に関する規則', 4, 'effective', '規程集で全18条＋別表を確認。平成16年4月1日規則第121号で制定、令和7年3月26日規則第33号（令和8年4月1日施行）が最新改正。大学発ベンチャー専用の支援細則ではなく施設全般の規則だが、大学が公表するインキュベーションオフィス提供の根拠規則であり、認定後の場所支援の申請・許可・期間・料金を実際に規律している。第5条第1項第3号の産学連携使用スペースが「本学の研究成果を活用した事業を行う者」を対象とし、第6条で原則3年、第7条で学長への申請と許可、第8条で学外者の不動産使用許可、第9条で料金と免除、第10条で継続申請を定める。附則（平成29年3月7日規則第14号）で旧インキュベーションオフィス利用規則を廃止し本規則へ統合。［検証エージェントは出典を開けず未照合］', 'migration:385'),
  ('reg_3a28a90ae0d9_recognition_committee', 'inst_catalog_3a28a90ae0d9', '徳島大学研究支援・産官学連携センター規則', 4, 'effective', '平成27年3月17日規則第45号制定、平成27年4月1日施行（最終改正 令和6年3月29日規則第86号・令和6年4月1日施行）。センターの規則・様式一覧ページからPDFを開き全文確認。大学発ベンチャー認定の議決機関である「徳島大学研究支援・産官学連携センター会議」を第11条で設置し、第12条で審議事項、第13条で委員構成（センター長、副センター長、部門長、研究・産学連携部長、その他センター会議が必要と認める者＝学長が命ずる）、第14条で任期2年、第15条で議長、第16条で定足数（委員の過半数の出席）と議事（出席委員の過半数）、第17条で委員以外の意見聴取、第18条で専門委員会の設置を定める。認定規則第3条第2項がこの会議の議を経ることを求めており、専用の認定委員会内規はこの規則が代替している。第4条第1項第6号で大学発ベンチャーへの役員兼業の利益相反審査を知財法務部門の業務としている。', 'migration:385'),
  ('reg_2e634684f6dc_joint_research', 'inst_catalog_2e634684f6dc', '慶應義塾大学受託研究等受入れ規程', 4, 'effective', '平成20年6月10日制定。第2条第1項第2号で「共同研究」を定義し受託研究と併せて受入れ手続きを規定。第3条は慶應義塾産官学連携ポリシーに基づく受入れ、第4条第7号は成果知財を慶應義塾発明取扱規程等に従い取り決めること、第6条は間接経費を直接経費の30％以上、第7条は一般管理費を研究費総額の15％、第10条は契約金額3000万円以下を部門長決裁・超過は稟議規程と定める。スタートアップ専用ではなく全学共通の共同研究・受託研究規程。研究連携推進本部の規程集・ガイドライン「産学官連携」区分から取得。', 'migration:385'),
  ('reg_2e634684f6dc_equity_stock_option', 'inst_catalog_2e634684f6dc', '慶應義塾対価収入の配分に関する細則', 4, 'effective', '平成19年3月27日制定、2023年3月24日改正（2023年4月1日施行）。慶應義塾発明取扱規程第15条等に基づき、実施許諾・譲渡の対価として第三者から得た一時金、ロイヤルティおよび株式・新株予約権等の売却収入を「実施料収入」と総称し、出願・権利化・維持・技術移転および株式・新株予約権等の売却等に要した費用を控除のうえ、発明者等50％・発明等提案時の所属学部等25％・義塾25％で配分すると規定（1項）。配分事務はイノベーション推進本部（3項）。株式等の取得方針自体はスタートアップ向け技術移転ガイドライン3項(1)が定め、専用の出資・新株予約権取扱規程は規程集に存在しない。', 'migration:385'),
  ('reg_ff01bb8086e3_support_rules', 'inst_catalog_ff01bb8086e3', '東京大学アントレプレナープラザ 募集要項', 4, 'effective', '2025年6月付、産学協創推進本部が発行。支援内容（オフィス・実験室提供、経営アドバイス、専門家紹介、投資家紹介）、利用条件、支援対象企業4区分、審査委員会の構成と選考基準、申請書類一覧、面接審査会、入居手続、四半期ごとの事業化進捗報告義務までを定め、認定後の支援申請と条件を規律する文書として機能している。産学協創推進本部のアントレプレナープラザ紹介ページからリンク。学内規程ではなく募集要項である点に留意。', 'migration:385'),
  ('reg_ff01bb8086e3_external_program_support', 'inst_catalog_ff01bb8086e3', '2026年度 スタートアップ創出支援事業のご案内', 4, 'effective', '産学協創推進本部が株式会社先端技術共創機構（ATAC）と連携し、東京都大学発スタートアップ創出支援事業の採択を受けて東京都との協定のもと実施する支援の要件を定めたページ。対象者（2年以内に起業を目指す教職員・学生、本学研究成果のライセンスを受けた者、教職員が役員兼業するSU、在学生・卒業生創業SU、入居SU）、対象経費、実施期間2027年3月31日まで、事務局ヒアリングと審査を規定。学内規程ではなく事業案内ページである点に留意。', 'migration:385'),
  ('reg_251654a7c128_support_rules', 'inst_catalog_251654a7c128', '東京科学大学Innovation Design Studio使用細則', 4, 'effective', '令和6年10月4日細則第67号。認定後の支援の申請・審査・条件を定める唯一の公開細則。第4条で使用者に「東京科学大学認定ベンチャー」を明示し、第6条で入居申請を施設長へ提出し入居審査専門委員会の審査を経て可否決定、第7条でセットアップオフィスは定期建物賃貸借契約、第9条で使用料納付（教職員・学生は大学予算から支出可）、第11条で使用許可の取消しを定める。設置根拠は同名の規則（令和6年規則第134号、x385RG00002098）。称号規則第7条が「別に定める」とする包括的な支援細則は規程集に見当たらず、支援内容を定める規程としてはこれとTIP関係細則が該当する。規程集の体系目次「第6編 施設・設備」で発見。', 'migration:385'),
  ('reg_e437d589dc87_conflict_of_interest', 'inst_catalog_e437d589dc87', '学校法人東京理科大学利益相反ポリシー', 4, 'effective', '産学連携機構「ポリシー」ページから公開されているPDF本文を取得して全文を確認。目的（産学官連携活動に伴う利益と本来の責務の相反を予防する体制構築）、利益相反マネジメントの基本的考え方4項（体制整備、透明性と説明責任、教職員等への情報開示要求と必要な措置、健全な産学官連携を阻害しない配慮）、学内啓発と社会への説明責任を規定。規程本文ではなく法人レベルのポリシーで、実務要件（自己申告書の毎年提出等）は起業ハンドブック11章に記載。制定日の記載なし、2022年4月掲載。', 'migration:385'),
  ('reg_e437d589dc87_ip_license', 'inst_catalog_e437d589dc87', '学校法人東京理科大学知的財産ポリシー', 4, 'effective', '産学連携機構「ポリシー」ページから公開されている全5ページのPDF本文を取得して確認。用語定義、適用対象（教職員等・学生・外部研究者等）、職務発明等の法人帰属、届出と理事長による承継決定、産学連携機構による評価・実施許諾業務、Ⅴ-1で「ベンチャー企業や中小企業に対しては、特段の配慮を行うこととし、別に定める」と優遇方針を明示、実施補償金、共同研究・受託研究成果の共有、異議申立て手続を規定。職務発明等規程は別に存在するが非公開。制定日の記載なし、2022年4月掲載。', 'migration:385'),
  ('reg_b8027b627d19_equity_stock_option', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学における研究開発成果活用促進支援に伴う株式等の取得に関する規則', 4, 'effective', '令和6年10月1日規則第116号（令和8年6月16日規則第72号で改正、令和8年4月1日から適用）。規程集の本文ページを開いて全条文を確認。第2条第6号で株式等を株式及び新株予約権と定義し、第3条で理事長が株式等受入審査委員会の議を経て取得の可否を決定。第6条で委員会構成、第10条で評価・売却を別に定める。附則で旧東工大規程（平成29年規程第13号）と旧東京医科歯科大規則（令和4年規則第113号）等を廃止。', 'migration:385'),
  ('reg_b8027b627d19_shared_equipment', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学TIPに係る共用実験室利用細則', 4, 'effective', '令和6年12月6日細則第82号（令和8年4月22日改正）。規程集の本文ページを開いて全条文と別表を確認。第3条で研究開発型スタートアップ（起業準備を含む）を利用対象とし、湯島地区の共通実験機器等を利用可。第8条と別表でベンチ1台月額を学外者1が15万円、学外者2が25万円、学内者が7万円と区分、第9条で原則3年・最大5年、第12条でシェアラボへの本店登記を認める。', 'migration:385'),
  ('reg_1abfa9e22bbc_conflict_of_interest', 'inst_catalog_1abfa9e22bbc', '東京都公立大学法人利益相反規程', 4, 'effective', '平成20年3月31日制定、平成19年度法人規程第102号。法人例規集の規程集第5章および産学公連携センター「規程・様式等」ページからたどって本文を確認。第1条で利益相反ポリシー（平成20年3月31日制定）に基づく産学公連携活動の利益相反マネージメントを定める。第3条で管理対象を教職員等の企業等における兼業活動、共同研究・受託研究・寄附、知的財産の譲渡および実施許諾とし、対象行為に一定額以上の金銭または株式等経済的利益の取得を含む。第5条で利益相反マネージメント委員会を運営委員会として設置、事務局は総務部監査・内部統制担当。', 'migration:385'),
  ('reg_1abfa9e22bbc_side_job', 'inst_catalog_1abfa9e22bbc', '東京都公立大学法人教職員の兼業等に関する規程', 4, 'effective', '平成19年3月30日制定、平成18年度法人規程第27号。産学公連携センター「規程・様式等」ページが「教職員の兼業等に関する規程」として掲載しているリンクから本文を確認。第1条で教職員の兼業等に関する規則（平成17年度法人規則第23号）の施行事項を定める。第2条で兼業許可期間は原則3年まで、営利企業の役員兼業は任期を考慮した期限付き許可が可能。第4条が技術移転兼業、第5条が研究成果活用兼業（研究成果を活用する事業の役員就任）、第6条が監査役兼業、第7条が社外取締役兼業、第8条が産業成果活用兼業の許可要件を規定。', 'migration:385'),
  ('reg_1abfa9e22bbc_ip_license', 'inst_catalog_1abfa9e22bbc', '東京都公立大学法人知的財産取扱規則', 4, 'effective', '平成17年4月1日制定、平成17年度法人規則第47号。産学公連携センター「規程・様式等」ページからたどって本文を確認（同名の他大学規程との取り違えを避けるため再取得して条文を再確認済み）。第3条で職務発明の権利は法人帰属、第8条で出願時補償（特許1件1万円）と実施時補償（実施料・譲渡収入の50%）、第28条で譲渡・放棄・実施許諾は審査会の審議に基づきセンター長が決定。第29条「大学発ベンチャーに対する優遇措置」で、教職員等が設立したベンチャー企業への実施許諾について実施料の延払い及び減免等の優遇措置を講じることができる。第30条で専用実施権の設定等も可能。', 'migration:385'),
  ('reg_1abfa9e22bbc_joint_research', 'inst_catalog_1abfa9e22bbc', '東京都公立大学法人共同研究取扱規程', 4, 'effective', '平成17年4月1日制定、平成17年度法人規程第33号。産学公連携センター「規程・様式等」ページからたどって本文を確認。大学発スタートアップ専用ではなく、民間企業等外部の団体との共同研究一般を対象とする規程で、認定ベンチャーもこの枠組みで契約する。第2条で共同研究を「外部団体等から共同研究費を受け入れ、主に法人の施設及び設備を使用して教員が外部団体等の研究者と共同して行う研究」と定義し、共同研究費は直接経費・管理費・研究料で構成。第3条で法人が施設設備と経常経費、外部団体等が共同研究費を負担する。', 'migration:385'),
  ('reg_1abfa9e22bbc_shared_equipment', 'inst_catalog_1abfa9e22bbc', '東京都立大学日野キャンパス6号館インキュベーションルーム管理運営規程', 4, 'effective', '令和5年6月8日制定、令和5年度法人規程第3号。スタートアップが使う設備の利用条件・料金・義務・責任を定める唯一の公開規程のためこの種別に登録するが、文書自体はインキュベーション施設の管理運営規程であり、機器共用専用の規程ではない。第5条第4号で認定ベンチャーのうち起業後5年以内のものを入居対象とし、第6条第2号で入居期間は創業後10年目を超えない範囲で3年以内・2年以内の更新を2回まで。第9条第3項で入居期間中の本店登記を許容。第10条と別表で入居料月額108,000円〜219,000円、機器使用料月額21,000円、第12条で保全・騒音等の義務、第16条で損害賠償を規定。なお研究機器共用センター設置要綱は学内限定で非公開。', 'migration:385'),
  ('reg_35b5c217ec7b_ip_license', 'inst_catalog_35b5c217ec7b', '東京電機大学 知的財産ポリシー', 4, 'effective', '研究推進社会連携センター（産官学連携担当）の「企業・地域の方へ」配下で公開。掲載構成は目的、基本的考え方、定義、対象者（教育職員および契約者）、推進体制の5項目。発明の帰属、実施許諾の条件、大学発ベンチャーへの優遇、株式対価、収入配分の条項は本ページに記載がない。制定日の表示なし。知財の詳細規程は学内者専用の規程集にあると見られ外部確認不可のため、ip_license に該当する唯一の公開一次資料として登録する。', 'migration:385'),
  ('reg_77be07932123_equity_stock_option', 'inst_catalog_77be07932123', '国立大学法人神戸大学株式等取扱規則', 4, 'effective', '神戸大学規則集で全文を確認。令和2年3月13日制定、令和2年3月31日・令和5年3月31日改正。第1条で寄附及び知的財産のライセンス、施設・設備の提供、技術指導等の支援の対価等として取得する株式・新株予約権・新株予約権付社債を対象と定義。株式等受入審査会（第4条）・受入基準（第5条）・株式等評価会（第7条）・共益権の原則不行使（第8条）・役員会の議を経た学長決定（第10条）を規定。体系は第5編業務第2章財務、所管は財務部財務戦略課。', 'migration:385'),
  ('reg_77be07932123_shared_equipment', 'inst_catalog_77be07932123', '神戸大学学術・社会共創機構施設利用規程', 4, 'effective', '神戸大学規則集で全文を確認。令和8年6月30日制定、令和8年7月1日施行（令和8年4月1日から適用）。第2条で共用施設の利用（入居を含む）、機構が管理・運用する設備及び機器の利用、受託分析サービスを利用の範囲とし、第3条で教育・研究・産官学連携・地域貢献等の目的での利用を認める。第4条で利用資格と承認手続は各施設が定め、第7条で経費は利用者負担・機構長が減免可、第8条で損害弁償、第9条で事故補償を行わない旨を規定。', 'migration:385'),
  ('reg_77be07932123_external_program_support', 'inst_catalog_77be07932123', '2026年度 神戸大学GAPファンドプログラム（うりぼーファンド）応募要領', 4, 'effective', '社会共創部門（旧産官学連携本部）サイト掲載のPDFを全文確認。2026年2月16日付、産官学連携本部長名。JST START事業大学・エコシステム推進型（2020年度採択）と、KSACのJST基金事業「スタートアップ・エコシステム共創プログラム」を背景に置く学内GAPファンドの公募ルールで、助成額・採択件数・助成期間・対象経費・審査（うりぼーファンド選考委員会）・経過報告およびDemoDayでの報告義務・知財の大学帰属を定める。対象は起業前の事業化検証であり、起業後支援の終了条件を定めた文書は公開情報では見つからなかった。', 'migration:385'),
  ('reg_75953cdd2d43_equity_stock_option', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学大学発ベンチャー企業等から対価として取得する株式等取扱規程', 4, 'effective', '群馬大学規則集 第6章 研究の一覧から発見し、PDF全文を確認した。令和6年8月1日制定・施行で、認定規程（061340）と同日施行の対。第1条で認定大学発ベンチャーからライセンス供与等の対価として取得する株式・新株予約権の取扱いを定める。第3条に株式等での収納要件、第4条に機構長を委員長とする審査委員会（3分の2以上の出席で議決、外部専門家の意見活用可）、第5条に学長の取得決定と契約締結、第6〜7条に新株予約権の行使・保有、第8条に議決権の原則不行使、第9条に役員会の議を経た売却、第10条にインサイダー取引防止責任者、第11条に発明者補償金の換金後支払を規定。', 'migration:385'),
  ('reg_75953cdd2d43_external_program_support', 'inst_catalog_75953cdd2d43', '大学発新産業創出基金事業 スタートアップ・エコシステム共創プログラム スタートアップ創出プログラム IJIE-GAPファンドプログラム2026 ステップ2「スタートアップ枠」募集要項', 4, 'effective', '群馬大学ベンチャー支援サイトの公募要項ページからリンクされているPDFを開いて確認した。群馬大学単独の学内規程ではなく、群馬大学が参画するIJIE（北関東・甲信地域の大学等プラットフォーム）がJST大学発新産業創出基金事業の下で運営する外部助成の募集要項。起業後支援の線引きが明記されており、第1章で「基礎的な研究への支援、および起業後の企業に対する支援につきましては、本プログラムの支援対象となりません」と規定。第3章で1件あたり直接経費最大3,000万円（スタンダード）／6,000万円（スタンダード＋α）＋間接経費30％、第8章で要件審査・書面審査・面接審査と利益相反マネジメントの実施、第9章で採択後の委託研究契約締結、起業に関する研修等の受講、研究成果報告会への参加、評価を定める。制定日の記載は確認できなかった。', 'migration:385'),
  ('reg_46957a06d459_recognition_committee', 'inst_catalog_46957a06d459', '自治医科大学産学連携推進委員会設置規程', 4, 'effective', '産学官連携トップページの規程等一覧からPDF本体を全文確認。平成31年規程第28号、平成31年4月1日施行、改正は令和2年規程第3号・令和5年規程第29号・令和6年規程第29号。認定規程第3条第2項が認定の議を経る委員会として指定するのがこの委員会で、第2条第8号「大学発ベンチャーに関すること」、第9号「大学発ベンチャーが発行する株式及び新株予約権の取得に関すること」、第10号「取得した株式等の売却、権利行使、処分等に関すること」を審議事項とする。構成は副学長（委員長）、学長委嘱の医学部基礎系2名以上・臨床系2名以上・看護学部1名以上、総務部長、大学事務部長ほか（第3条）。任期2年・再任可（第6条）、委員総数の過半数出席で成立し出席委員の過半数で議決、可否同数は議長決（第7・8条）。第9条で下部組織として株式等取得検討部会を置き、オープンイノベーションセンタークリエイティブマネージャー、知財コーディネーター、VC・法律・財務会計の識見者等で構成する。庶務は研究推進課（第11条）。', 'migration:385')
