  ('regver_b8027b627d19_shared_equipment_20260905', 'reg_b8027b627d19_shared_equipment', '現行規程', 'effective', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2024-12-06', true, 'migration:385'),
  ('regver_1abfa9e22bbc_conflict_of_interest_20260905', 'reg_1abfa9e22bbc_conflict_of_interest', '現行規程', 'effective', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000315.html', '2008-03-31', true, 'migration:385'),
  ('regver_1abfa9e22bbc_side_job_20260905', 'reg_1abfa9e22bbc_side_job', '現行規程', 'effective', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000215.html', '2007-03-30', true, 'migration:385'),
