  ('regver_1abfa9e22bbc_joint_research_20260905', 'reg_1abfa9e22bbc_joint_research', '現行規程', 'effective', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000265.html', '2005-04-01', true, 'migration:385'),
