  ('regver_35b5c217ec7b_ip_license_20260905', 'reg_35b5c217ec7b_ip_license', '現行規程', 'effective', 'https://www.dendai.ac.jp/crc/tlo/corporation/policy.html', null, true, 'migration:385'),
  ('regver_77be07932123_equity_stock_option_20260905', 'reg_77be07932123_equity_stock_option', '現行規程', 'effective', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000839.html', '2020-03-13', true, 'migration:385'),
  ('regver_77be07932123_shared_equipment_20260905', 'reg_77be07932123_shared_equipment', '現行規程', 'effective', 'https://www.office.kobe-u.ac.jp/plan-rules/act/119000076.html', '2026-06-30', true, 'migration:385'),
  ('regver_77be07932123_external_program_support_20260905', 'reg_77be07932123_external_program_support', '現行規程', 'effective', 'http://www.innov.kobe-u.ac.jp/document/2026Uribofund.pdf', '2026-02-16', true, 'migration:385'),
  ('regver_75953cdd2d43_equity_stock_option_20260905', 'reg_75953cdd2d43_equity_stock_option', '現行規程', 'effective', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061350.pdf', '2024-08-01', true, 'migration:385'),
  ('regver_75953cdd2d43_external_program_support_20260905', 'reg_75953cdd2d43_external_program_support', '現行規程', 'effective', 'https://ijie.jp/cms/wp-content/uploads/2025/12/IJIE_GAP%E3%83%95%E3%82%A1%E3%83%B3%E3%83%89%E3%83%97%E3%83%AD%E3%82%B0%E3%83%A9%E3%83%A02026%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85%E3%82%B9%E3%83%86%E3%83%83%E3%83%972%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%88%E3%82%A2%E3%83%83%E3%83%97%E6%9E%A0.pdf', null, true, 'migration:385'),
  ('regver_46957a06d459_recognition_committee_20260905', 'reg_46957a06d459_recognition_committee', '現行規程', 'effective', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/index_kitei_01.pdf', '2019-04-01', true, 'migration:385')
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, source_url, confirmed_at, evaluator) values
  ('inst_kagawa', 'pol_cert_rule', 'established', '香川大学発ベンチャー（認定規則・認定証交付）', '「国立大学法人香川大学における大学発ベンチャーの認定に関する規則」（令和3年6月1日施行、令和4年4月1日一部改正）。第1条で大学発ベンチャーの円滑かつ適正な支援を図るための認定制度と規定。第3条第3項で「香川大学発ベンチャー認定証」を交付。第6条で称号使用を認める。規程集のHTML全文で条文を確認。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・知財活用型', '第2条。NPO法人を除く法人格を有する企業のうち、(1)本学又は本学の教職員が所有する知的財産権を活用して設立した企業、(2)本学の教職員（退職から設立まで3年以内の者を含む）が本学で得られた研究成果又は技術等を基に設立又はその設立に深く関与した企業、(3)本学の学生又は卒業等から3年以内の者が本学で得られた研究成果又は修得した知識、技術等を基に設立又は深く関与した企業、(4)学長が前3号に準ずると認めたもの。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_recognition_decider', 'established', '学長（産学連携・知的財産センター会議の議）', '第3条第1項で申請者は認定申請書を学長に提出。第2項で学長が産学連携・知的財産センター会議の議を経て認定の可否を決定。第4項でセンター長は外部有識者に意見を求め、又は申請者への面接を行うことができる。第9条の取消しも同じくセンター会議の議を経て学長が決定。第13条で事務は同センターと地域創生推進部地域連携推進課が連携して処理。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cert_pre_registration', 'not_started', '不可（法人格を有する設立済み企業が対象）', '第2条が対象を「法人格を有するもの」の企業に限定し、各号も「設立した企業」「設立に深く関与した企業」と規定。第3条から第5条に、設立登記前の申請、認定予定通知、条件付認定を認める条項はない。規則本文（令和4年4月1日改正）を全文確認した上での判定。2026-05-31入力の既存評価（申請様式が登記簿謄本等を前提）とも整合。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_validity_years', 'established', '3年・更新可（満了1年前〜3か月前に申請）', '第5条第1項で認定の有効期間は当該認定の日から起算して3年。第2項で継続を希望する場合は有効期間の満了の1年前から3か月前までの間に学長に更新の申請。第3項で更新後の有効期間は更新前の有効期間の満了の日の翌日から起算。第4項で更新申請には第3条（手続）及び第4条（基準）を準用。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_head_office_registration', 'unknown', null, '認定規則、及び「香川大学における施設の有効活用に関する規程」（平成17年6月13日制定、令和6年4月1日改正）のいずれにも、会社の本店所在地としての商業登記を受け入れる条項はない。同規程は第3条で全学共同利用等のための共用スペースを定義する学内向けの内容で、学外者・企業への貸与を定めていない。入居型インキュベーション施設の公開要項も見つからなかったため、可否を公開情報から判定できない。', 'unknown', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000426.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_facility_lease', 'unknown', null, '認定規則第12条第1項は「本学の管理運営及び教育研究に支障のない範囲において、支援を行うことができる」と包括的に定めるのみで、支援メニューを列挙しておらず施設貸与の明記がない。第2項で支援期間は原則として認定後3年を限度。施設の有効活用に関する規程は学内共用スペースが対象。認定ベンチャー向けの入居施設・研究室貸与の要項は公開情報で確認できなかった。', 'unknown', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_shared_equipment', 'established', '共同研究関係者・受託試験依頼者として利用可', '「香川大学における研究設備・機器の共用に関する規程」（令和6年1月31日施行）第6条で、学内外における共同研究・プロジェクト研究等の関係者、受託試験・検査等の依頼者、管理部局長が認めた者を利用者の範囲と規定し、企業・大学発ベンチャーもこの枠で利用できる。第10条第1項で管理部局が別に定める利用料を負担。学内料金と学外料金の区分、認定ベンチャーへの料金優遇は規程本文にない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001256.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 称号根拠は別URL(1059条文)、本URLはロゴのみ］元の主張(established): 称号は有効期間中使用可・ロゴは学長の個別許可。認定規則第6条で認定大学発ベンチャーは「香川大学発ベンチャー」の称号を有効期間に限り使用できる。第11条で本学は製品・サービスの内容及び品質を保証せず、事業から生じた結果・損害の法的責任を負わない。ロゴは別規程の「香川大学ロゴマーク等使用規程」（令和6年10月1日制定）で、許可対象は大学構成員、学生課外活動団体、校友会・指定同窓会、生協、学長が個別に許可した者。形状及び色彩の改変と第三者への転用は禁止。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_ip_license', 'unknown', null, '「香川大学職務発明規程」（平成16年4月1日制定、令和5年9月11日最終改正）第3条で職務発明等に係る知的財産権は大学が承継・所有すると定めるが、実施許諾の手続・対価は「別に定める」とされ本規程にない。第9条の補償金も金銭補償のみで額は別途。認定規則第2条第1号は知的財産権活用型を認定対象に含むが、認定と実施許諾を結び付ける優遇条項（独占的実施許諾、実施料減免、株式対価）は認定規則・職務発明規程のいずれにも見当たらない。', 'unknown', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000333.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_equity_rule', 'unknown', null, '大学法人が株式・新株予約権を取得、評価、保有、処分する規程は公開規程集で確認できなかった。「香川大学利益相反に係る審査手続」（令和4年4月1日修正）の2)株式等の取得の場合の取扱いは、教職員本人・配偶者・一親等の同居の親族がベンチャー企業等の株式を取得する場合の事前報告義務を定めるもので、大学側の取得規程ではない。株取得申請書の様式も個人向け。', 'unknown', 'https://www.kagawa-u.ac.jp/files/6517/4787/4351/shinsatetsuduki202505.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_gap_fund', 'unknown', null, '産学連携・知的財産センターのページ（共同研究・受託研究、知的財産、競争的資金、産学官交流の4業務を掲載）と産官学連携統括本部のページを確認したが、GAPファンド、JST大学発新産業創出基金、PSI（Peace & Science Innovation Ecosystem）への共同機関としての参画を示す記述は現在の公開ページに見当たらない。学内独自の起業準備資金・POC資金の要項も見つからなかった。', 'unknown', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_accelerator', 'unknown', null, '産学連携・知的財産センターの業務内容に「ベンチャー起業支援」が挙げられ、技術相談お申込みフォームによる随時受付と、企業からの依頼に応じ研究者が指導・評価・助言を行う学術・技術コンサルティング制度がある。ただしこれらは企業向け技術相談の窓口で、起業家向けの相談窓口、メンタリング、アクセラレーションプログラムを制度として定めた要項は公開ページで確認できなかった。', 'unknown', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_coi_sidejob', 'established', '役員兼業は審査委員会の許可・株式取得は事前届出', '認定規則第4条第4号は、教職員が設立した企業の場合、職員兼業規則、利益相反に係る諸規則等に定める所要の手続・許可が適正になされていることを認定基準とする。「国立大学法人香川大学職員兼業規程」（平成17年4月1日制定、令和6年4月1日改正）第5条で営利企業役員等兼業は営利企業役員等兼業審査委員会の議を経て許可。「香川大学利益相反に係る審査手続」2)3)で、ベンチャー企業等の株式取得と営利企業兼業は事前報告が必要で、利益相反マネジメントオフィス、利益相反審査会、利益相反委員会の3段階で審査。', 'official', 'https://www.kagawa-u.ac.jp/files/6517/4787/4351/shinsatetsuduki202505.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_support_fee', 'unknown', null, '認定規則第12条第1項は本学の管理運営及び教育研究に支障のない範囲において支援を行うことができるとし、第2項で支援期間を原則として認定後3年間を限度とする。ただし支援の有償無償、認定申請の手数料、施設使用料、実施料の定めはなく、支援メニュー自体が限定列挙されていないため、対価の要否を規則本文から判断できない。', 'unknown', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_certified_count', 'established', '現在3社・累計12社・一覧公開', '公式「香川大学発ベンチャー」ページに2026年4月現在の認定企業3社を社名・設立年・事業内容つきで掲載。株式会社未来機械（2004年3月設立、ロボット・メカトロニクス製品の製造、3次元精密測定器の販売）、株式会社レアスウィート（2010年3月設立、希少糖関連商品の開発・販売）、メロディ・インターナショナル株式会社（2015年7月設立、周産期遠隔医療プラットフォーム）。過去認定分を含め累計12社と記載。', 'official', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/23923/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_cert_rule', 'drafting', '大学発スタートアップ認定規程を審議中（未施行）', '公式サイトのスタートアップ支援ページ・産学連携ページに認定制度の記載はない。2025/12/03公式プレスリリース「東京都大学発スタートアップ創出支援事業に、工学院大学の事業が採択」に「研究成果の社会実装を目的とする研究者起業を支援する体制は未整備でした。今回の採択を機に…起業プロセスの標準化及び持続的な創出サイクルを構築します」と明記。AMD保有の内部資料では「大学発スタートアップ認定規程」2026-06-24確定版がメール審議中、称号案は「工学院大学発ベンチャー」。制定済みとしては扱わない。', 'official', 'https://www.kogakuin.ac.jp/news/2025/120391.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_eligible_scope', 'drafting', '規程案: 教職員・学生・退職卒業後3年以内・研究成果型・知財型', '公開情報では認定対象の定義を確認できない。AMD保有の内部規程案第2条で、研究成果型、知財型、教職員・学生型、退職・卒業等から起業まで3年以内、その他学長が必要と認めたものを対象と整理。作業記録では「他職に就かず」要件の削除・緩和、第三者代表会社の実質的関連性の拾い方が検討事項として残る。規程案段階のため確定値ではない。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_recognition_decider', 'drafting', '規程案: 理事長が認定、学長が称号授与、審査は認定委員会', '公開情報では決裁者を確認できない。AMD保有の内部規程案は理事長が認定決定・学長が称号授与、第4条で大学発ベンチャー認定委員会を設置し認定審査を行うと規定。2026-05-25の決裁者比較資料で法人主体案・大学主体案・ハイブリッド案の3案を比較し、認定/称号/更新/解除は学長、取消・株式/新株予約権は理事長とするハイブリッド案をAMDが推奨。最終決定は大学側の意向待ち。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_cert_pre_registration', 'drafting', '設立前申請・条件付認定を検討中（条文化未確定）', '公開情報に登記前申請の可否は記載がない。AMD保有の作業記録で「設立前でも申請又は事前相談を受けられる余地」「認定予定通知又は条件付認定」を検討事項として整理しているが、条文化は未確定。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_validity_years', 'drafting', '規程案: 称号5年・再申請可', '公開情報に有効期間の記載はない。AMD保有の内部規程案第6条で称号は5年間使用可能、再申請可（再申請は認定手続を準用）と整理。更新審査の粒度・要件は再確認事項として残る。作業記録では称号期間5年と支援メニューごとの支援期間を分ける整理をしている。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_head_office_registration', 'drafting', '規程案第13条で学内住所での商業登記を許可', '公開情報（産学共同研究センター利用案内、スタートアップ支援ページ）に商業登記の受け入れに関する記載はない。AMD保有の内部規程案第13条に施設貸与と、当該所在地を本店所在地とする商業登記の許可が支援メニューとして置かれている。有償無償の区分は規程案段階で個別決定とされ未確定。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_facility_lease', 'drafting', '規程案に施設貸与。現行の共同研究センターは教員主体', '公開の産学共同研究センター（CORC、八王子キャンパス、60平米を基本ユニットとする研究室18室）利用案内は「本学専任教員が研究責任者となって手続き」する共同研究施設で、研究室利用料は1室月額4万円、継続利用は5年以内。ベンチャー入居用の制度ではない。AMD保有の内部規程案第13条に認定ベンチャーへの施設貸与が支援メニューとして置かれているが規程案段階。', 'official', 'https://www.kogakuin.ac.jp/research/corc/use.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_shared_equipment', 'drafting', '規程案で共有機器利用を許可、利用規程は未整備', '公開情報に認定ベンチャーの共用機器利用や料金区分の記載はない。AMD保有の内部規程案第13条に研究設備・共有機器等の利用許可が支援メニューとして置かれている。2026-04-30打合せ資料では「大学発SUの共有機器利用規程」は既存なしで整備対象と整理されており、料金区分（学内料金か外部料金か）は未確定。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_name_logo_use', 'drafting', '称号「工学院大学発ベンチャー」5年（案）、ロゴ条件不明', '公開情報に称号やロゴ使用の規定はない。AMD保有の内部規程案で称号を「工学院大学発ベンチャー」とし、第6条で5年間の使用を認める。免責条項と、認定取消後に認定の事実を事業活用することの禁止を置く。大学ロゴ・校章の使用条件は規程案でも公開情報でも確認できない。スタートアップ呼称との併記も未確定。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_equity_rule', 'drafting', '出資・新株予約権規程は未整備、整備対象', '公開情報に大学が株式・新株予約権を取得する規程は存在しない。AMD保有の2026-04-30打合せ資料で「株式及び新株予約権取得等規程」は既存なし・整備対象と明記。決裁者比較資料では株式・新株予約権の取得処分は法人マターとして理事長決裁を標準案と整理。知財ライセンス対価として株式・新株予約権を受ける運用の可否も未確定。［検証エージェントは出典を開けず未照合］', 'inferred', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_gap_fund', 'established', '外部GAPファンド・NEDO NEPの申請支援（学内資金なし）', '公式スタートアップ支援ページに、目指すゴールとして「実証研究のためのGAPファンド獲得」、ビジネスピッチコンテスト後の支援として「NEDO NEP申請やGAPファンド申請を含め、引き続き学内外の専門支援人材によるサポート」、外部公募情報欄に「申請書の作成指導を希望する本学教員は、研究企画課にお申し出ください（指導：福井達雄 NEDO審査員、本学特任教授スタートアップ統括）」と明記。GTIE共同機関。大学独自のGAPファンド・起業準備資金の記載はない。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_accelerator', 'established', 'KUTE-TOKYOプログラム（WS・伴走・ピッチ・メンタリング）', '公式スタートアップ支援ページに「2026工学院大学KUTE-TOKYOスタートアップ創出支援プログラム」として、01.基調講演、02.ワークショップ（基礎編・応用編、ビジネスモデルキャンバスで仮説検証）、03.インキュベーションプログラム（2026年度から開催）、04.FINALビジネスピッチコンテストの4段構成を明記。「個別メンタリングも可能です」と記載。相談窓口は研究企画課（新宿・八王子）。特任教授スタートアップ統括、太陽国際特許事務所、ティーエスアイ（2026年9月よりツクリエ）が支援体制。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_support_fee', 'established', '専門家指導・イベント参加は無料、認定後の対価は未確定', '公式スタートアップ支援ページに「学内外の専門家による指導やイベントへの参加は、いずれも無料です」と明記。現行の支援プログラム（基調講演・ワークショップ・インキュベーションプログラム・ピッチコンテスト・個別メンタリング）は無償。認定制度に紐づく施設貸与・共有機器等の対価は、AMD保有の内部作業記録で支援内容ごとに期間・条件・対価を個別決定する方向とされ未確定。参考として共同研究センターの研究室利用料は月額4万円だが教員主体の共同研究用。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_certified_count', 'unknown', null, '公式サイトのスタートアップ支援ページ・産学連携ページに認定ベンチャー一覧や認定社数の公開はない。認定規程が審議中で未施行のため認定実績を公表する段階に至っていないと見られるが、社数を示す公開情報が存在しないため unknown とする。公式に確認できるのは、2026年度NEDO NEP開拓コースに本学教員2名採択、SusHi Tech Tokyo 2026に2テーマ出展、TTCPに本学教員1名採択という個別実績のみ。', 'unknown', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cert_rule', 'established', 'NIMS発ベンチャー／NIMS成果活用ベンチャーの名称使用許可制度', '「NIMSベンチャー援助等規程」（平成15年1月23日 15規程第2号、直近改正 令和8年3月18日 2026規程第32号・令和8年4月1日施行）。第2条第3号でNIMSベンチャーを「機構の特許等成果を活用した事業を主たる事業として行う成果活用事業者であって第4条第2項の名称使用許可を得たもの」と定義し、第3条で「NIMS発ベンチャー」「NIMS成果活用ベンチャー」の呼称使用を認める。第19条で事務は外部連携部門スタートアップ支援室。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_eligible_scope', 'established', '職員起業のNIMS発と成果活用の2区分、職員の主体的関与が要件', '第2条第4号・第5号で、機構の職員が起業したものを「NIMS発ベンチャー」、それ以外を「NIMS成果活用ベンチャー」と区分。特許等成果は職員等（キャリア形成職員、任期制職員及び退職者を含む）が在職中になした成果（第2条第1号）。第5条第2項の適格性9要件に、機構の職員等が役員就任・株式保有等で運営に主体的関与できること（第6号）、職員が兼業等又はクロスアポイントメント出向をしていること（第7号）を含む。退職後の年数制限は規定なし。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_recognition_decider', 'established', '理事長（NIMSベンチャー等審査委員会の審査、理事会議で決定）', '第4条第2項で名称使用を許可するのは理事長。援助対象適格性は、第6条第2項で理事長が第7条のNIMSベンチャー等審査委員会に審査を付託し、同条第3項で理事会議において該否を決定。第7条第2項で審査委員会は理事長の委嘱を受け審査及び重要事項の審議を行い、第3項で運営は別に定めるとする（当該内規は公開されていない）。出資は出資業務実施規程第6条で出資業務審査委員会の審査を踏まえ理事会議が決定。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cert_pre_registration', 'established', '可（起業しようとする者も申請可、登記簿写は設立後に提出）', '第4条第1項で申請できるのは「成果活用事業者又はこれを起業しようとする者」。様式1（NIMSベンチャー名称使用申請書）は「設立又は定款変更（予定）年月日」「役員（就任予定の者を含む。）」を記載欄とし、添付書類は定款（計画中の場合は定款案を提出し設立後に認定された定款を改めて提出）、登記簿写（計画中の場合は設立又は変更後に提出）とする。様式3の援助措置対象申請をもって第4条第1項の申請を行ったものとみなす（第6条第1項後段）。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_validity_years', 'established', '援助対象期間は5年以内、3年以内の延長可。名称使用に期限なし', '第8条第1項「NIMSベンチャーへの援助対象期間は、5年を超えない期間とする。ただし、理事長が特に必要と認めるときは、3年を超えない範囲で、その期間を延長することができる」。第2項で延長の審査・決定は第6条を準用（様式3は「新規・更新」の別を選ぶ）。第9条第2項で、NIMS発ベンチャーは援助対象期間終了後も継続的な援助措置を受けられるが、別記の注記でNIMS成果活用ベンチャーは継続的援助措置の対象としない。名称使用許可自体の有効期間は規定なし。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_head_office_registration', 'not_started', '本店登記の定めなし。名刺等への機構内住所表記のみ許可', '別記は「次の（1）から（10）までに掲げる援助措置の全部又は一部を行うことができる」と支援メニューを限定列挙する。住所に関する項目は（7）機構内の住所表記使用の許可のみで、内容は「NIMSベンチャーが機構内に連絡事務所等を設置した場合、名刺等に機構内の住所を表記することができるものとすること」。商業登記上の本店所在地としての利用を認める条項は、援助等規程・出資業務実施規程・共用規程のいずれにも見当たらない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_facility_lease', 'established', '機構内スペースを有償貸与、利用料75%減額。共同研究時は無償', '第15条で機構の業務に支障を及ぼさない場合に限り施設又は設備を貸与できる。別記1（3）で共同研究の実施に当たり必要なスペース等の無償利用を認め、（4）①で共同研究の範囲外でも研究開発又は連絡事務のためのスペースその他の施設等の有償利用を認める（収益事業専用の場合、共用規程の共用に該当する場合等は除く）。②で利用料は減価償却費按分額から75%を減じた額、③光熱水料等は実費、④間接経費は免除、⑤賃貸借契約で合意すれば株式又は新株予約権の譲渡で支払可。専用インキュベーション棟の名称は公開情報になし。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_shared_equipment', 'established', '研究設備を有償利用可、利用料75%減額。共用規程扱いは対象外', '別記1（5）①で共同研究の範囲外でも固定資産等管理細則第5条に基づき研究設備等の利用を認める。②で利用料（日額・1時間又は1回当たり）は減価償却費から算定した額の75%減額（消費税別）、③光熱水料等は実費徴収、④維持費等の間接経費は免除、⑤賃貸借契約で合意すれば株式又は新株予約権の譲渡で支払可。ただし収益事業専用の場合、職員等が物品管理者となる場合、施設及び設備の外部への共用に関する規程（平成14年5月23日 14規程第34号）第2条第1項の共用に該当する場合は除く。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_name_logo_use', 'established', '称号は理事長の許可制で使用可。ロゴ使用の定めなし', '第3条第1項で許可を得た成果活用事業者は「NIMS発ベンチャー」又は「NIMS成果活用ベンチャー」の名称を使用できる。第4条第3項で理事長が名称使用許可書（様式2）を交付し、第4項で許可の事実を機構内外に周知又は公表。第3条第2項で機構は名称使用や援助を受けたことによる損失・損害の責任を負わない。第12条第1項第6号で、機構が保証を行うかのような誤認を第三者に故意に生じさせた場合は援助対象決定の取消事由。機構ロゴ・シンボルマークの使用条件は本規程に規定なし。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_ip_license', 'established', '契約一時金免除、独占的通常実施権、新発明の優先開示', '別記1（1）で、イ 特許権等の実施許諾等に当たり契約一時金の免除、ロ 独占的通常実施権又は再実施権付実施を認めること、ハ 実施許諾した特許権等に関連する新たな発明等の出願をしたときはNIMSベンチャーに優先的に開示すること、の全部又は一部を行える。加えて「成果活用事業者から対価として取得する株式等取扱規程」（令和4年4月26日 2022規程第25号）第3条第1号で、知的財産権に係るライセンス供与の対価を株式又は新株予約権で収納できる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_gap_fund', 'not_started', '援助措置に資金助成なし。資金支援は出資業務実施規程の出資のみ', '別記1は援助措置を（1）から（10）まで限定列挙し、資金拠出に当たるのは（2）出資業務実施規程に基づく出資だけで、GAPファンド・POC資金・起業準備資金に相当する助成金の項目はない。NIMSはSIP第3期「マテリアル事業化イノベーション・育成エコシステムの構築」の研究推進法人としてBRIDGE施策「マテリアルスタートアップインキュベーション促進事業」（初年度委託研究費上限2億円、最長3年度、広く公募）を実施していたが、当該SIP課題は2026年3月31日をもって終了と公式ページに明記されている。', 'official', 'https://www.nims.go.jp/nims/activity/sip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_accelerator', 'established', '専門家相談は無料、VC紹介・連携構築援助。支援室が窓口', '別記1（8）で機構が顧問契約等を締結している法務・知的財産等の専門家への相談機会を提供し、相談料は無料（株式上場後は実費相当額を徴収）。（9）でベンチャー企業活動の促進に資する情報の提供（機構と関係を持つベンチャーキャピタル等の紹介を含む）。（10）で第三者との連携構築に関する助言その他の援助。第19条で名称使用許可・援助対象決定・援助等の事務は外部連携部門スタートアップ支援室が行い、同室は「NIMSの研究成果を活用するスタートアップ及びその創業の支援を行っています」と公式組織ページに記載。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_coi_sidejob', 'established', '役員兼業は許可制（原則2年）、利益相反マネジメント委員会が審査', '兼業等規程（平成18年3月28日 18規程第10号）第5条で役員兼業は開始1箇月前までに理事長へ申請、第6条で兼業等審査委員会の審査を経て許可、第6条第3項で許可は原則2年を超えない期間、第9条に勤務時間内役員兼業、第10条に役員兼業休職の制度。第34条・第35条で兼業先からのエクイティ報酬（株式・新株予約権等）の事前内訳書提出と半期ごとの報告を義務付ける。援助等規程第18条が利益相反マネジメント規程（平成29年7月12日 29規程第47号）を明示的に接続し、同規程第3条の利益相反マネジメント委員会が自己申告を審査（公開株は5%以上の保有で申告対象）。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005s9e.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_support_fee', 'established', '認定・専門家相談は無償。施設設備は有償で利用料75%減額', '名称使用許可・援助対象決定について手数料の定めはなく、別記1（6）で援助措置に必要な機構の事務的経費（間接経費）を免除。（8）②で専門家への相談料は無料（ただし株式上場後は実費相当額を徴収）。（1）イで特許等実施許諾の契約一時金を免除。他方、（4）（5）の施設等・研究設備等の利用は有償で、利用料は算定額から75%減額、光熱水料等は実費徴収。第9条第2項の継続的援助措置では、別記2（2）（3）により施設・設備の措置から利用料の減額が外れる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_certified_count', 'established', '18社を一覧公開（NIMS発17社・成果活用1社）。事業終了は非掲載', '公式「NIMSベンチャー企業情報」（2025年4月28日更新）で、NIMS発ベンチャー17社（第2号 株式会社オキサイドから第24号 株式会社Blue Water Energyまで）、NIMS成果活用ベンチャー1社（第19号 日本超電導応用開発株式会社）を、通し番号・企業名・事業内容・設立日つきで公開。ページに「事業を終了したベンチャー企業については、記載しておりません」と明記されており、通し番号は第24号まで発番されている。', 'official', 'https://www.nims.go.jp/business/venture-lab.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cert_rule', 'established', '愛媛大学発ベンチャー認定制度（規則第91号）', '「国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程」（令和2年10月21日規則第91号、最終改正は令和8年7月8日施行）。第1条で愛媛大学発ベンチャーへの円滑かつ適正な支援を目的と定め、第5条1項で学長が認定証（別紙様式第2号）を授与し「愛媛大学発ベンチャー」と称することを認める。第10条で認定事務は研究・産学連携支援部研究・産学連携課が処理。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_eligible_scope', 'established', '大学知財型・役職員/学生知財型・退職卒業者型・研究成果活用型の4類型', '第2条各号。(1)本学所有の知的財産権を基に設立、(2)本学の研究成果等に基づき役職員・学生所有の知財を基に設立、(3)在籍時の研究成果等に基づき退職・卒業・修了者所有の知財を基に設立、(4)その他本学で達成された研究成果等に基づき設立し国立大学法人法22条1項5号の業務遂行に寄与するもの。退職・卒業後の年限規定は本文になし。第4条で公序良俗違反・名誉毀損等のおそれがないことも申請条件。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_recognition_decider', 'established', '学長（推進会議の審議を経て機構長が推薦）', '第3条。申請者が認定申請書（別紙様式第1号）を研究・産学連携推進機構長へ提出し、機構長が研究・産学連携推進会議で適否を審議、適当と判断すれば学長に推薦、学長が認定を決定、機構長が文書で通知。第3条5項で機構長は外部有識者への意見聴取と申請者面接が可能。推進会議は機構長を議長とし、委員の過半数出席・出席委員の過半数で議決（推進会議規程第3〜5条）。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cert_pre_registration', 'unknown', null, '認定規程に登記前申請・認定予定通知・条件付認定の条項はない。第2条は4類型とも「設立したもの」と定義し、認定証様式に設立年月日欄がある。2026年1月7日認定の株式会社HBNETは2025年10月1日設立で、設立後の認定。他方、固定資産等貸付基準第2条1項4号は「創業準備を含む」個人・中小企業への施設貸付を認めており、施設利用は登記前でも経路がある。認定の登記前受付可否は公開情報から確定できない。', 'unknown', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_validity_years', 'established', '認定日から5年・更新可', '第5条2項で認定期間は認定した日から5年、更新可。第5条3項で更新は代表者が機構長へ申請し、手続は第3条（推進会議の審議→学長決定）を準用。第6条で決算日から3か月以内に事業報告書・収支決算書を機構長へ提出。第8条で定義からの著しい逸脱、社会的信用の失墜、報告書未提出、その他不名誉のおそれで学長が取消でき、取消後は認定証返付と認定事実の事業使用禁止。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_head_office_registration', 'established', '貸与施設で商業登記可（有償・EUICは登記可）', '第9条1項2号「貸与した施設について、当該認定大学発ベンチャーの所在地とする商業登記を認めること」。登記は施設貸与とセットで、貸与は固定資産等貸付基準第2条1項4号（本学の研究成果を活用した事業）に基づく有償貸付（同基準第3条の無償貸付事由に該当しない）。E.U. Innovation Commonsは「レンタルラボ・オフィス（登記可）」と明記。学外本店も可能で、2026年1月認定のHBNETの所在地は東京都港区。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_facility_lease', 'established', 'E.U. Innovation Commonsに有償入居・原則2年', '認定規程第9条1項1号で事務室・研究室として学内施設を貸与。E.U. Innovation Commons施設管理規程（令和7年1月15日規則第1号、最終改正令和8年3月25日施行）第5条1項3号で利用対象を「愛媛大学発ベンチャー（原則として設立後5年以内）」とし、第7条で利用期間は原則2年以内・1年を限度に延長可、第9条で推進会議の議を経て機構長が可否決定。施設利用内規でオープンラボ52㎡が年1,497,600円（税別、特定利用者52万円）、研究員室19.5㎡が608,400円、コワーキング1席月1万円。光熱水料は別途。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０８編　各施設/第０２章　学内施設/31◎愛媛大学E.U. Innovation Commons施設管理規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_shared_equipment', 'established', '研究設備等の利用許可・料金区分は非公開', '認定規程第9条1項3号「研究設備等の利用を許可すること」。学内の大型設備は大型設備学内共同利用促進要項（規則第132号）で取得価格500万円以上をデータベース公開し、利用料は設備管理セグメントが定める（第7）。同要項は学内利用者の内部取引を前提としており、認定ベンチャーに適用される料金区分は公開されていない。E.U. Innovation Commons施設利用内規1.3で、専有型スペース利用者が共同実験室の設備・機器を併用する場合は別途利用負担金。産学連携推進本部は3Dプリンター・3Dスキャナーの利用予約を受け付けている。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_name_logo_use', 'established', '称号「愛媛大学発ベンチャー」使用可・ロゴ規程なし', '認定規程第5条1項で学長が認定証を授与し「愛媛大学発ベンチャー」と称することを認める。第8条3項で認定取消後は認定証を返付し、取消日以降は認定を受けていた事実を事業に使用してはならない。第9条1項5号で本学主催イベント・広報誌・ホームページでの広報支援。大学ロゴ・校章の使用規程は、規則集のファイル名検索（標章・ロゴ・商標）で該当がなく、使用条件は外部から確認できない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_ip_license', 'established', 'ライセンス対価の株式等払いを特例で許容', '知的財産権規程第4条で職務発明等の知財は原則本学に帰属、第18条でライセンス等は原則として技術移転機関等を通して行う、第22条2項で報酬は対価から必要経費を控除した収益の50%を発明者等に支給し残額を本学に配分。第21条「ライセンス等の対価の特例」で株式等取扱細則を適用し、大学発ベンチャーは対価を現金に代えて株式等で支払える。認定ベンチャー向けの独占的実施許諾や実施料減免を定めた明文規定は確認できない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/02◎国立大学法人愛媛大学知的財産権規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_equity_rule', 'established', 'ライセンス対価として株式・新株予約権を取得（細則あり）', '「愛媛大学におけるライセンス等の対価として取得する株式等取扱細則」（令和元年8月1日学長裁定、最終改正令和6年4月1日施行、知的財産権規程第21条に基づく）。第2条で株式等＝株式及び新株予約権。第3条でライセンス等の対価の全額または一部を現金で支払うことが困難と認める大学発ベンチャーから株式等を取得できる。第4条で知的財産委員会が財務状況等を踏まえ可否を審査、第5条で研究・産学連携担当理事が決定し学長へ報告のうえ契約締結。第7条で発明者報酬は換金時に支払う。現金出資の規程は確認できない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/05◎愛媛大学におけるライセンス等の対価として取得する株式等取扱細則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_coi_sidejob', 'established', '兼業許可・利益相反手続の完了が認定申請条件', '認定規程第4条4号で、本学の教職員が設立したものについては「国立大学法人愛媛大学兼業規程及び国立大学法人愛媛大学利益相反管理規程その他本学における関係規則等に定める所要の手続、許可等が適正になされていること」を申請条件とし、兼業許可と利益相反管理を認定手続に接続している。株式等取扱細則第4条2項では、知的財産委員会が大学発ベンチャーの財務状況その他取得の妥当性を判断するために必要な事項を踏まえて審査する。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_support_fee', 'established', '認定は無償・施設貸与とファンドは有償かつ別審査', '認定規程に認定手数料の定めはない。第9条2項で支援は認定日から原則5年間を限度、同3項で支援は本学の関係諸規則等による。産学連携推進本部は、認定によりインキュベーション施設の有償貸与とファンドからの投資が可能になるが、いずれも別途審査があり保証するものではないと明記。施設は固定資産等貸付事務取扱細則第9条により貸付料算定基準で算定した額に消費税を加えた額で、業務遂行に特に有益等の場合に減額可。同細則第8条1項3号で貸付期間は5年。', 'official', 'https://ccr.ehime-u.ac.jp/ccr/university-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_certified_count', 'unknown', null, '産学連携推進本部の大学発ベンチャーページに認定企業一覧はなく、認定は個別のニュース記事で公表される（2025年10月29日 PLANT CASE株式会社、2026年1月7日 株式会社HBNET）。ニュース一覧を確認した範囲でも累計認定社数の公表は見当たらず、機関自身の公開情報からは社数と一覧公開の有無を確定できない。', 'unknown', 'https://ccr.ehime-u.ac.jp/ccr/university-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_cert_rule', 'established', '「山口大学発ベンチャー」の登録・公表制（認定規程なし）', '産学公連携・研究推進センターの「大学発ベンチャー」ページが定義を示し（①本学又は本学職員が所有する特許をもとに起業 ②本学で達成された研究成果又は習得した技術等にもとづく起業 ③本学職員若しくは学生が設立者又は設立に深く関与 ④その他本学と密接な関係を有するもの）、該当企業を設立年つきで一覧掲載する。登録・削除・修正の要望窓口は学術研究部産学連携課産学連携係（venture@yamaguchi-u.ac.jp）。山口大学規則集（2026年8月1日現在）の現行規則一覧には「ベンチャー」「起業」「スタートアップ」を含む規程が0件で、認定規程・称号付与手続は公開されていない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業1年以内・知財／研究成果活用型', '大学発ベンチャーの定義は4類型。第3類型は「本学職員若しくは本学の学生が設立者である場合又はその設立に深く関与して起業した場合（ただし，当該職員が退職又は学生が卒業等している場合は，その起業まで他の職に就かなかった場合又は起業までの期間が1年以内の場合に限る）」。他に特許活用型、研究成果・技術活用型、その他密接関係型。なおベンチャー起業支援室の相談支援対象は別基準で「学生，教職員及び卒業生」、FAQは卒業年を問わず学部・大学院・社会人入学を含む全卒業生・修了生が対象と明記（保存版ページで確認）。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_recognition_decider', 'unknown', null, '認定・登録の決裁者、審査機関、審査基準はいずれも公開されていない。大学発ベンチャーのページに書かれているのは登録・削除・修正の連絡先（学術研究部産学連携課産学連携係）だけで、審査主体の記載が無い。規則集にも認定委員会に相当する規程は無い。参考として、レンタルスペース（新事業創出支援スペース）の利用資格には「機構長が利用を許可した学外者」とあり、申請書を提出後センターで審議して可否を通知する運用が保存版ページに記載されている。', 'unknown', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_cert_pre_registration', 'unknown', null, '設立登記前の申請可否、認定予定通知、条件付認定のいずれについても記載が無い。大学発ベンチャーのページは登録窓口だけを示し、申請時期に触れていない。ベンチャー起業支援室のページも起業前の相談は受けるとするが、登録申請の時期の定めは書いていない。規則集にも根拠規程が無いため、判断材料が公開情報に存在しない。', 'unknown', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_validity_years', 'unknown', null, '有効期間・更新の定めは公開されていない。大学発ベンチャーのページは登録・削除・修正の要望を随時受ける運用だけを示し、期限や更新審査に触れていない。なお、レンタルスペースの利用期間は「原則として，3年以内であり，更新の際は審査が必要」と保存版ページに明記されているが、これは施設利用の期間であって登録の有効期間ではない。', 'unknown', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_head_office_registration', 'established', '可（新事業創出支援スペース入居者・有償）、研究室は不可', 'ベンチャー起業支援室のよくある質問に「起業するための場所を借りることはできますか？」→「産学公連携･研究推進センターのレンタルスペースに空室がある場合は，新事業創出支援スペースとして貸し出しをしています。また，会社の登記所在地とすることも可能です。」と明記。直後に「研究室を起業する会社の登記所在地とすることはできますか？」→「できません。」とある。入居は有償（新事業創出支援スペース1,500円/m2/月＋光熱水費実費）。現行ページは学内限定で外部から閲覧できないため、2025年12月18日時点の保存版で確認。', 'official', 'https://web.archive.org/web/20251218185608/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=3949', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_facility_lease', 'established', '新事業創出支援スペース（1,500円/㎡月・原則3年）', '大学研究推進機構が常盤地区の一部をレンタルスペースとして運用。区分は「研究開発支援スペース」（共同研究・受託研究の研究開発支援、学内限定、3,200円/m2/年）と「新事業創出支援スペース」（技術シーズの育成支援および大学発ベンチャーの創出支援・育成、1,500円/m2/月）の2つ。光熱水費は実費負担。利用期間は原則3年以内で更新時に審査。利用資格は役職員、学生、機構長が許可した学外者ほか。根拠文書は「山口大学大学研究推進機構レンタルスペース利用要項」「同利用内規」だが、PDFの配信先ホストが現在到達不能。2026年2月16日時点の保存版で確認。', 'official', 'https://web.archive.org/web/20260216031356/http://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=43', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_shared_equipment', 'established', '研究室機器の事業使用は不可、共用機器は学外者として要申請', 'ベンチャー起業支援室FAQは「研究室にある機器・装置類を企業の生産活動など事業に使用することはできますか？」→「できません。大学の資産と企業活動は明確に区分してください。」と明示。一方、産学公連携センターの「機器利用（学外向け）」ページは、総合科学実験センター常盤分室の研究用機器、本学が有する研究用機器、地域産学官共同研究拠点をいずれも学外利用可（要申請）としている。認定ベンチャー向けの学内料金区分や減免は公開されていない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/equipment/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_name_logo_use', 'unknown', null, '「山口大学発ベンチャー」の呼称は大学のページに一覧掲載される形で使われるが、企業が称号やロゴを自社広報に使う条件を定めた公開文書は見つからなかった。規則集（2026年8月1日現在）の現行規則一覧に、ロゴ・マーク・標章・校章を含む題名の規程は0件。「国立大学法人山口大学等名義の使用承認に関する要項」は第2条第1号で対象の「事業」を会議・研究会・シンポジウム・競技会などの催事と定義し、共催・後援・協力の名義使用に限る要項であるため、ベンチャーの称号使用の根拠にはならない。', 'unknown', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000076.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_ip_license', 'established', 'ライセンスポリシーで大学発ベンチャーに特別の配慮', '国立大学法人山口大学ライセンスポリシー（平成25年3月11日規則第8号、平成25年4月1日施行）2(2)エ「地域の活性化及び雇用の創出並びに大学発ベンチャーの活性化につながることが期待される知的財産のライセンス活動については，地域社会連携及び起業家精神（アントレプレナーシップ）育成の観点に応じた特別の配慮を講じること」。ただし独占実施権、対価の減免、株式・新株予約権による対価といった具体的な優遇条件は規定されていない。企業向け技術移転の実務窓口は有限会社山口ティー・エル・オー。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000223.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_equity_rule', 'unknown', null, '大学がベンチャーの株式・新株予約権を取得する規程は確認できなかった。山口大学規則集（2026年8月1日現在）の現行規則一覧に「株式」「新株」「出資」を含む題名の規程は0件。ベンチャー起業支援室FAQは「教職員です。自分が起業する会社への出資，株式保有はできますか？」→「可能ですが，兼業や利益相反・責務相反の関係がありますので，まずは人事課服務管理係にご相談下さい。」とするが、これは教職員個人の保有の話であり、大学法人による取得ではない。', 'unknown', 'https://public2.legalcrud.com/yamaguchi_univ/aggregate/catalog/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_gap_fund', 'not_started', '学内の起業資金支援なし（国の競争的資金の活用支援のみ）', 'ベンチャー起業支援室のよくある質問に「起業にかかる費用（法務局での会社登記手続きにかかる費用等）や資本金を大学が支援してくれますか？」→「経費的支援はありません。」と明記。同ページは支援メニューを「起業に関する相談や知財相談，国の競争的資金（研究開発型ベンチャー支援事業）等を活用した支援，起業に関する各種情報の提供」と限定列挙しており、学内GAPファンド、起業準備資金、POC資金はそこに含まれない。2025年12月18日時点の保存版で確認。', 'official', 'https://web.archive.org/web/20251218185608/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=3949', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_accelerator', 'established', 'ベンチャー起業支援室（山口・宇部）＋「志」イノベーション道場', 'ベンチャー起業支援室を山口地区（学生支援センター内、窓口は共通教育棟1階自主活動ルーム）と宇部地区（産学公連携･研究推進センター、窓口は共同研究開発棟2階産学連携課）に設置。活動は①山口フィナンシャル・グループ専門家および山口ティー・エル・オーとの協働による起業支援 ②「志」イノベーション道場をハブとしたイベント開催 ③起業のための知財相談 ④情報発信。相談はヒアリングシート事前提出による予約制で、対面・オンライン・メールに対応。道場サイトは学生向け新事業開発体験プログラム「Mirise」やまぐちアクセラレーションプログラムを告知している。', 'official', 'https://web.archive.org/web/20251218185608/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=3949', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_coi_sidejob', 'established', '役員兼業は承認制、研究成果活用企業役員は休職可', '国立大学法人山口大学職員兼業規則は役員等兼業を承認制とし（第6条、承認基準等は別に定める）、第8条で学長が役員等兼業の承認状況を半期ごとに公表する。第11条第3項は技術移転兼業・研究成果活用兼業その他の産学公連携活動推進に資する兼業のうち利益相反・責務相反マネージメント委員会が適当と判断したものについて勤務時間をさいた従事を認める（その時間は給与減額）。第11条第4項は研究成果活用企業の役員等を主として務める場合に職員休職規則第7条に基づき休職とする。利益相反審査は利益相反・責務相反マネージメント委員会規則による。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000128.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_support_fee', 'established', '登録は無償、施設は有償、起業費用の金銭支援なし', '大学発ベンチャーの登録に費用の記載は無い。レンタルスペースは有償で、新事業創出支援スペース1,500円/m2/月、研究開発支援スペース3,200円/m2/年、いずれも光熱水費は実費負担（保存版のレンタルスペースページ）。ベンチャー起業支援室FAQは起業費用・資本金について「経費的支援はありません」と明記。起業相談・知財相談そのものの有償無償は明示されていない。', 'official', 'https://web.archive.org/web/20260216031356/http://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=43', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_certified_count', 'established', '23社を一覧公開（うち学内入居9社）', '「大学発ベンチャー」ページに2002年から2025年設立の23社を設立年つきで掲載（HTML上さらに1社が非表示化されている）。青背景の学内入居企業は9社で、常盤キャンパスが7社（Blue Water Energy、Biomeca TriTech、ヘリックスエクステンション、CNV技研、ドボクリエイト、MOT総合研究所、TSテクノロジー）、吉田キャンパスが2社（ファインベジプロジェクト、アグリライト研究所）。ページには「本学は，これらのベンチャー企業に対する法的責任を負うものではありません」との留意事項がある。2026年9月5日閲覧。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_cert_rule', 'established', 'QST認定ベンチャー（QSTベンチャー支援制度規程）', '文科省・国立研究開発法人審議会QST部会（平成31年2月1日）へQSTが提出した資料「QSTベンチャー支援制度の構造」に、設置規程類として「QSTベンチャー支援制度規程、QSTベンチャー審査委員会設置細則ほか」と明記。QST第1期中長期目標期間業務実績等報告書も、平成28年度にQSTベンチャー支援規程を整備し平成29年度から運用開始と記載。公式サイトは認定企業を「QST認定ベンチャー企業」として掲載。規程本文は非公開。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_eligible_scope', 'established', 'QST職員が設立し、QST知財の実用化を主業とする企業', '同資料「支援の対象」は、①QSTの研究開発成果の普及・実用化で社会還元を行う企業、②QSTに正当な対価を支払いQSTの研究開発を推進する企業、③その目的達成のためQST職員が設立しようとする企業。審査委員会の認定基準は、①QSTの特許・ノウハウ等の普及実用化を主たる事業とし事業計画を有すること、②設立時に申請者が出資していること、③QST知財の最大活用と利益のQSTへの還元が見込めること。出資対象は株式会社に限定。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_recognition_decider', 'established', 'QSTベンチャー審査委員会が認定審査', '同資料に「審査委員会による認定基準」と「QSTベンチャー審査委員会設置細則」が明記。第1期業務実績等報告書は、ベンチャー審査委員会を年平均4回開催し、認定希望ベンチャーの認定審査、兼業の可否の審査、認定ベンチャーの事業報告を行ったと記載。出資は審査委員会の下の専門部会（外部有識者複数名とQST役職員1名で構成）で審議し、理事会議等の審議を経て可否を決定。最終認定権者の明記は公開資料になし。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_cert_pre_registration', 'established', '可（職員が設立しようとする企業も対象）', '同資料の支援対象③は「QSTの職員が設立しようとする企業」と明記し、認定基準②も「設立時において申請者が出資していること」と設立前提。QST公式の認定ベンチャー一覧でも、リンクメッド（設立 令和4年7月7日／認定期間 令和4年6月22日から）とType-I Technologies（設立 令和6年9月2日／認定期間 令和6年8月1日から）は認定期間の開始日が設立登記日より前で、登記前の認定運用と整合する。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_validity_years', 'established', '認定日から5年・再審査で2年延長可', '同資料「認定／支援期間」は、①認定日より5年間、②認定ベンチャーから申請がある場合は審査委員会で再審査のうえ2年間の延長が可能、と明記。公式一覧でも近年の認定は5年（例 Type-I Technologies 令和6年8月1日〜令和11年7月31日）。ただしPerfect Imaging Laboratoryは令和2年11月2日〜令和12年11月1日の10年、ライトタッチテクノロジーも約10年で、初期は運用が異なる。認定期間が終了した企業も3社ある。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_head_office_registration', 'unknown', null, '認定ベンチャーへのQST内居室等の貸与は制度として明記されているが（文科省QST部会提出資料「３．QST施設の貸与等」）、その住所を会社の本店所在地として商業登記できるかどうかの記載は、QST公式サイト、規程集、業務実績等報告書、施設供用の規則・約款のいずれにも見当たらなかった。可否は非公開情報のため判定不能。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_facility_lease', 'established', 'QST内の居室等を貸与（有償）', '同資料「３．QST施設の貸与等」に、QSTが有する研究施設等を貸与し、又は使用させることができる（ただし、有償とする）と明記。一般企業等には共用施設を条件付きで使用させるが居室等の貸付は行っておらず、認定ベンチャーには希望があれば共用施設の使用に加えて居室等を貸し付ける便宜が供与される、と対比して記載されている。インキュベーション施設名や貸与期間の定めは公開資料になし。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_shared_equipment', 'established', '共用施設・設備を有償で使用可', '同資料は出資以外の支援策として「QST共用施設・設備の使用、QST内居室の貸与等」を挙げる。施設供用制度は機構外で研究開発を行う者が対象で、高崎量子技術基盤研究所施設供用規則（令和6年4月1日 令06高（規則）第17号）第14条は、施設供用に際し利用者から所定の利用料金を徴収すると定める。利用区分は成果公開（学術／産業・実用化）と成果非公開。認定ベンチャー専用の料金区分や減免の記載は確認できなかった。', 'official', 'https://www.qst.go.jp/uploaded/attachment/39310.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_name_logo_use', 'established', '「QST認定ベンチャー」の称号を公式に付与', 'QST公式サイトのQSTベンチャー支援制度ページは、認定企業を「QST認定ベンチャー企業」として社名・設立日・認定期間つきで一覧掲載。令和7年5月9日のQSTプレスリリースも「認定ベンチャーであるLiSTie株式会社」と表記し、称号が公式に付与・使用されていることが確認できる。企業側が称号やQSTロゴを自社広報で使用する際の条件を定めた規程は、公開資料には見当たらない。', 'official', 'https://www.qst.go.jp/site/qst-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_ip_license', 'established', '再実施権付き・独占的実施許諾を原則付与', '同資料「２．QST知財の実施許諾」に、認定ベンチャーへはQST保有知的財産権の再実施権付き実施許諾を認め、一定期間の独占的実施権を認めると明記。一般企業には社会還元の観点から非独占許諾が原則で、認定ベンチャーには独占的実施権を原則認める便宜が供与されると対比。QST職務発明等取扱規程（最終改正 令和5年1月1日）第9条・第10条が実施許諾と実施契約、第11条が独占的実施の要件、第12条が独占停止事由を定める。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_equity_rule', 'established', '金銭・現物出資可。令和7年3月に初の株式取得', '文科省QST部会提出資料「QSTの出資業務について」に、出資対象はQST認定ベンチャー（認定資格を持つ株式会社に限定）、方法は金銭出資又は現物出資、原資は知財ライセンス収入・寄附収入、審査は審査委員会に設置する専門部会、決定は理事会議等と明記。令和7年5月9日のQSTプレスリリースは、令和7年3月24日にLiSTieへ知財の実施許諾の対価として普通株式を取得し、平成28年の設立以降初の出資と公表。', 'official', 'https://www.qst.go.jp/site/press/20250509.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_gap_fund', 'not_started', '資金支援は出資のみ（起業前資金の制度なし）', '文科省QST部会提出資料は、支援内容を職員の兼業許可、QST知財の実施許諾、QST施設の貸与等、認定ベンチャーへの出資の4本とし、出資以外の支援策を兼業の許可、共同研究の実施、QST共用施設・設備の使用、QST内居室の貸与等と限定列挙しており、起業前のGAPファンドや起業準備資金は含まれない。令和7年度業務実績等報告書にも該当制度の記載はなく、リチウム回収技術ではJSTのSTART等の外部資金を利用している。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_accelerator', 'unknown', null, '［自動検証で否認: VC包括協定の記述が本文に無い］元の主張(established): VCとの包括協定・研究者向けセミナー・専門機関紹介。第1期業務実績等報告書は、令和4年11月28日にベンチャーキャピタルBeyond Next Venturesと包括協定を締結して起業検討研究者に個別相談の場を設けたこと、令和4年10月17日に千葉銀行と産学連携・ベンチャー支援の連携協定を締結したこと、客員研究員が起業検討者に助言することを記載。令和7年度業務実績等報告書は、VCによる研究者向けセミナー（1月23日、35名参加）の開催、相談先の専門機関の拡充、展示会での認定ベンチャー事業紹介を記載。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 許可制の規程根拠が本文に無い］元の主張(established): 役員兼業可（許可制）・令和6年度改正で報酬受領可。文科省QST部会提出資料は、認定ベンチャーの責任者への兼業を認め、役員兼業は非常勤かつ無報酬に限り許可、役員以外の兼業は月40時間又は年60日以内を基準と記載（平成31年時点）。令和7年度業務実績等報告書は、認定ベンチャーへの兼業・出向で得る収入等の取扱いについて規程を改正し、役員として兼業する職員が報酬を得ることを可能としたと記載。定年制職員就業規程第9条第1項が兼業の許可制の根拠。利益相反マネジメント規程は兼業収入と責務相反を対象に年1回の自己申告と委員会審査を定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 「無償」の明記が本文に無い］元の主張(established): 認定・兼業許可は無償、施設の貸与と利用は有償。文科省QST部会提出資料は、QST施設の貸与・使用について「ただし、有償とする」と明記。高崎量子技術基盤研究所施設供用規則第14条も、施設供用に際し利用者から所定の利用料金を徴収すると定める。一方、認定そのものや兼業許可、共同研究、出資に係る申請料・年会費の定めは公開資料に記載がなく、認定手続に対価を求める記述は確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_certified_count', 'established', '認定中7社・認定終了3社（一覧公開）', 'QST公式のQSTベンチャー支援制度ページが、認定中7社（Type-I Technologies、LiSTie、MiRESSO、アニマルブライト、リンクメッド、Perfect Imaging Laboratory、ライトタッチテクノロジー）と認定期間の終了した3社（OKファイバーテクノロジー、ビードットメディカル、フォトンラボ）を、設立日・認定期間・代表者・事業内容・関係研究所つきで一覧公開。第1期業務実績等報告書は令和4年度末までの認定を合計7件と記載。', 'official', 'https://www.qst.go.jp/site/qst-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_cert_rule', 'not_started', '公式の認定制度なし（称号付与も行わない）', '「大学発ベンチャーに対するライセンス等の対価の優遇措置に関するガイドライン」（平成31年3月1日実施）脚注iに「本学では、『大学発ベンチャー』の公式の認定は行っていない。」と明記。公開規則集（第1〜8編・PDF576件）を全件照合しても認定規程・称号付与規程は存在しない。実際の運用は同ガイドラインと「成果活用事業者への支援に伴い取得する株式等の取扱に関する規程」（平成26年度九大規程第124号）による支援対象の切り分けで行われている。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_eligible_scope', 'established', '教職員・学生・卒業生（本学知財活用に限る）', '起業相談ページの相談対象は、(1)本学の教職員・学生が主に本学の研究成果等を活用して行う起業、(2)本学所属以外の個人（卒業生含む）が本学の知的財産権を活用して行う起業。優遇措置ガイドライン2は「本学の教職員（又は学生）が出資又は役員や技術顧問として参画し、本学が保有する知的財産を活用する大学発ベンチャー」のうち外部資金またはギャップファンドによる事業化検証で成果を得た知財を活用する企業を対象とする。脚注iiiで起業後の退職・異動・卒業も対象に含め、参画者が離職した場合は対象から除外。', 'official', 'https://airimaq.kyushu-u.ac.jp/about/starting-business/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_recognition_decider', 'established', '総長決定（産学官連携戦略会議・専門家会議が審査）', '認定制度がないため認定決裁者は存在しない。支援の対価としての株式等収納は、株式等取扱規程第4条で学術研究・産学官連携本部長あてに申出→産学官連携戦略会議規程第8条に基づく専門家会議が資力等を勘案して審査→戦略会議へ報告・審議→第4条第6項で総長が決定。個別研究プロジェクト出資規程（令和6年度九大規程第15号）第4条も同じ流れで、最後に総長が文部科学大臣へ認可申請する。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/254/1/2014kitei124.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_cert_pre_registration', 'established', '創業準備段階から施設貸付の対象（認定通知なし）', '国立大学法人九州大学不動産貸付細則（平成16年度九大細則第32号、最終改正令和6年4月1日）第2条第1項第5号ニは「本学の研究成果を活用した事業（創業準備を含む。）を行う中小企業又は個人にその事業の用に供するため本学の施設を使用させる」場合を貸付許可の範囲に挙げており、設立登記前の創業準備段階でも施設使用の申請対象になる。認定制度自体がないため、認定予定通知や条件付認定の仕組みは存在しない。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/1043/1/2004saisoku032.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_validity_years', 'established', 'ライセンス優遇は起業後5〜6年目まで・延長可', '優遇措置ガイドライン4「この優遇措置は、起業後5〜6年目までの大学発ベンチャーに対して実施する。ただし、当該大学発ベンチャーの経営状況を十分に勘案して、協議により期間を延長することができる。」。同3(3)でライセンス契約期間は5年から10年程度を目安とし、その期間中は限定条件を定めない独占を認める。認定制度がないため、認定の有効期間・更新という概念そのものが存在しない。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_head_office_registration', 'unknown', null, '公開情報では確認できなかった。不動産貸付細則は研究成果活用事業（創業準備を含む）への施設貸付を許可範囲に入れ、第5条で総長の許可のうえ不動産賃貸借契約を締結すると定めるが、商業登記上の本店所在地としての利用可否には触れていない。AiRIMaQのインキュベーション施設・入居要項に相当する公開ページも見当たらず、規則集576件にも本店登記に関する規程はない。推測で可否を書ける材料がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_facility_lease', 'established', '不動産貸付可・原則5年以内・貸付料4割以内減額', '不動産貸付細則第2条第1項第5号ニで研究成果活用事業（創業準備を含む）を行う中小企業・個人への施設貸付を許可範囲に規定。第5条第3項で貸付期間は原則5年以内（事業用定期借地権等の場合は別途）。第7条第1項ただし書で同号ニに該当する場合は算定額から4割以内を減額でき、第7条第3項で光熱水料等の附帯使用料は別途実費。手続は部局長経由で総長が許可し賃貸借契約を締結（第4条・第5条）。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/1043/1/2004saisoku032.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_shared_equipment', 'established', '学内経費と学外経費で二段階の利用料', '九州大学研究環境整備事業に係る研究機器・設備利用規程（令和3年度九大規程第69号、最終改正令和6年5月31日）第5条と別表が、同一機器に「本学が管理する経費から支出される場合」と「左記以外の経費から支出される場合」の2区分の時間単価を設定（例：電界放出型走査電子顕微鏡 4,200円/時 対 7,800円/時）。総長が特に認めた場合は全部または一部を免除できる。機器の検索・予約は全学ポータル ShareAid で行う。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/3408/1/2021kitei069.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_name_logo_use', 'established', '名称使用は許可制・ロゴと施設写真は使用不可', '大学公式の産学連携案内（研究・産学官連携推進部）の「名称使用申請」欄によると、企業等が本学との共同研究・受託研究・技術指導・研究開発コンサルティングの成果を活用した製品等に本学の名称を使用する場合、「九州大学の名称使用に関する許可申請書」を提出し、関係教員への確認・精査のうえ許可の可否を決定する。基本的な考え方として「本学の施設・教職員等の写真・画像、ロゴ等は使用しないこと」と明記。称号としての「九大発ベンチャー」付与は行っていない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.kyushu-u.ac.jp/f/43082/%E7%94%A3%E5%AD%A6%E9%80%A3%E6%90%BA.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_ip_license', 'established', '起業後VBへ優先許諾・オプション対価50%・独占', '特許等ライセンスポリシー（平成27年10月1日実施）2(3)「本学に帰属する研究成果が九州大学発ベンチャー企業によって実用化・事業化される可能性があるときは、当該企業に優先的に知的財産のライセンスを行う」。優遇措置ガイドライン3は、対価の株式等払いを原則受入、試行的実施許諾は通常の50%対価かつ原則1年間は限定条件のない独占、ライセンス契約は5〜10年の独占で契約一時金を抑制、エクイティ保有先には知的財産の譲渡にも積極対応、と定める。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_equity_rule', 'established', '株式等取得規程と現物出資規程の2本立て', '(1)成果活用事業者への支援の対価として株式・新株予約権を収納する規程（平成26年度九大規程第124号、平成27年4月1日施行、最終改正令和6年7月1日）。(2)国立大学法人法第22条に基づく個別研究プロジェクトへの現物出資規程（令和6年度九大規程第15号、令和6年7月1日制定。知財対価・施設設備使用料・受託共同研究費を現物出資）。両規程とも第5条で株主総会の議決権は原則不行使。優遇ガイドライン5(1)は上場時の議決権ベースで10%以内、無議決権株式か新株予約権が望ましいとする。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/4510/1/2024kitei015.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: 42件17社起業の記述が原文に無い］元の主張(established): 九大ギャップファンド・ステップファンド・共創基金。大学発ベンチャー事業シーズ育成支援プログラム（通称 九大ギャップファンド、平成28年度〜）は事業化検証資金として1件あたり200万円程度を上限に助成し、第Ⅶ期は採択最大5件。後段に九大ステップファンドを置く。加えてスタートアップ共創基金が事業化検証資金を1件につき年間500〜1000万円を目安に提供。令和4年度お知らせによると、それまでの採択42件のうち17社が起業している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_accelerator', 'established', '起業相談窓口＋プレCXO紹介・セミナー・メンタリング', '学術研究・産学官連携本部 知財・ベンチャー創出グループ（九大OIP株式会社サイエンスドリブンチーム）が起業相談を制度として設置。フローは起業相談申込書の提出→受付・受入可否判断→コーディネーターとの二者面談→外部専門家との三者面談。スタートアップ共創基金は、事業化推進・経営人材を「プレCXO」として紹介するマッチング、ビジネスプラン策定や資金調達の座学セミナー、専門家・士業によるメンタリングを実施メニューに掲げる。', 'official', 'https://airimaq.kyushu-u.ac.jp/startupkikin/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業可（許可制・2年更新）', '国立大学法人九州大学職員兼業規程（平成16年度九大就規第18号、最終改正平成30年1月31日）第9条第2号が「研究成果活用企業の役員（監査役は除く。）、評議員又は顧問の職」の兼業を認める。許可期間は原則2年以内で更新可、兼業審査委員会が審議し、営利企業の役員等兼業の許可権限は部局長へ委任されない。利益相反は九州大学利益相反ポリシー（平成16年3月19日評議会承認）と利益相反マネジメント要項に基づき、毎年度の定期自己申告で連携先のエクイティ保有状況まで申告させ、利益相反マネジメント委員会とアドバイザーが審査する。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.kyushu-u.ac.jp/f/32503/2004syuki018.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_support_fee', 'established', '相談は原則無償・施設と機器は有償', '起業相談は窓口・面談での対応が基本だが、三者面談の段でページに「支援内容によっては、有料になる場合（事前確認あり。）がございます」と明記。施設は不動産貸付細則に基づく有償貸付（研究成果活用事業は4割以内減額可、光熱水料等は別途実費）。研究機器は利用料規程の別表単価で有償、総長が認めれば減免。知財ライセンスは対価を株式等で受けられ、試行的実施許諾は通常の50%対価。認定料という概念は認定制度がないため存在しない。', 'official', 'https://airimaq.kyushu-u.ac.jp/about/starting-business/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_certified_count', 'not_started', '認定制度なし・大学公式の一覧は非公開', '公式の認定を行っていない（優遇措置ガイドライン脚注i）ため認定社数は存在しない。AiRIMaQのメニューに「九州大学の研究成果から生まれたベンチャー企業」へのリンクがあるが、実URL（?page_id=775）は現在404で閲覧できず、大学自身が公開する一覧は確認できなかった。参考値として、大学公式の産学連携案内にギャップファンドからの会社設立10件（社名付き）、令和4年度のお知らせに採択42件中17社が起業との記載がある。いずれも認定社数ではない。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_cert_rule', 'established', '九工大発スタートアップ（SU支援規程）', '令和6年11月1日制定・九工大規程第24号「国立大学法人九州工業大学における大学発スタートアップの支援に関する規程」（SU支援規程、令和8年6月19日改正）。第2条第2項で「九工大発スタートアップ」を、九工大発ベンチャーのうち第3条の支援条件を満たし第5条の支援決定を受けた企業と定義。称号は「九工大発スタートアップ」。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_eligible_scope', 'established', '教職員・学生等が設立、設立5年内の共研・技術移転先', 'SU支援規程第2条第1項が九工大発ベンチャーを5類型で定義。(1)本学研究成果に基づく特許・新技術・新ビジネス手法の事業化目的で新設、(2)設立から5年以内に本学と事業化のための共同研究を実施、(3)設立から5年以内に本学から技術移転等を受けた、(4)本学の教職員・学生等が設立者となる又は設立に深く関与、(5)準ずるもの。第3条で革新的研究成果の活用、急成長志向、公序良俗、兼業・利益相反手続の完了を追加要件とする。卒業生を年限付きで明示する条項はない。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_recognition_decider', 'established', '学長（研究推進機構運営会議の議・支援審査会が審査）', 'SU支援規程第4条第2項で、学長が研究推進機構運営会議の議を経て支援の可否を決定し、第3項で支援決定通知（別記様式第2号の1）又は不支援決定通知（同2号の2）により申請者へ通知。審査は令和8年6月19日研究本部長裁定「九州工業大学発スタートアップ支援審査会要項」第2条に基づく支援審査会が行う。委員は研究本部長（委員長）、研究副本部長、産学イノベーションセンター長、未来思考実証センター長、社会実装推進部門長ほか。第8条で審査結果を研究推進機構運営会議へ報告。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/115401', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_cert_pre_registration', 'not_started', '不可（履歴事項全部証明書の写しが必須）', 'SU支援規程第2条は既に設立された企業を前提に九工大発ベンチャーを定義し、第4条第1項は「企業の長」が学長へ申請すると定める。別記様式第1号（大学発スタートアップ支援申請書）は添付書類として履歴事項全部証明書（写）と定款（写）を必須とし、記載例（shien_ex.pdf）も同様。設立予定段階での申請、認定予定通知、条件付認定を認める条項は規程にも様式にも置かれていない。', 'official', 'https://www.ccr.kyutech.ac.jp/themes/innovation/f_venture/files/shien1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_validity_years', 'established', '3年以内（再申請による延長可）', 'SU支援規程第5条第3項「支援期間は、前条第3項に規定する支援の決定通知日から起算して3年を超えない範囲で、学長が必要と認める期間とする」。同条第4項で「九工大発スタートアップの長による再申請（支援期間の延長等を行うための申請）を妨げない」。申請書記載例も希望支援期間に「⇐3年以内」と注記。第7条第1項で支援期間内は毎年度、翌年6月末日までに事業報告書（別記様式第3号）の提出義務。第8条に取消事由を列挙。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_head_office_registration', 'unknown', null, 'インキュベーション施設規程（平成15年九工大規程第20号）、同使用細則（同細則第14号）、施設の有効活用に関する規程（平成17年九工大規程第4号）、産学イノベーションセンター研究スペース等利用内規、および施設紹介ページを確認したが、会社の本店所在地としての商業登記の可否に触れた記述はない。使用細則第6条第2項は転貸を禁止するが登記には言及がない。公開情報では判断できないためunknown。', 'unknown', 'https://bap.jimu.kyutech.ac.jp/publishes/10358', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 3年以内は10357本文に無く使用細則側の記載］元の主張(established): インキュベーション施設に入居可・有償・3年以内。SU支援規程第5条第1項(2)「本学が所有するインキュベーション施設等の使用に関する優遇措置」。インキュベーション施設規程第3条第1項(8)が九工大発スタートアップを使用資格者に明記。使用細則第4条(2)で使用期間は3年以内、特別の事由があれば1年単位で2年を限度に延長（本学職員等は3年単位で最長9年）。規程第8条・第9条で光熱水料と施設負担金（月額・別表）を負担。飯塚キャンパスにインキュベーション・ルーム9室とプレインキュベーション・ルーム。審査は研究施設等審査会。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_shared_equipment', 'established', '研究設備等の使用に優遇措置（対価は検討中）', 'SU支援規程第5条第1項(3)「本学が所有する研究設備等の使用に関する優遇措置」。令和7年3月1日付「九工大発スタートアップに対する支援強化について」の支援メニュー表では、学内施設・設備の使用の対価を「支払いの一部を新株予約権の取得に代える等、柔軟な対応を行うことを想定（詳細は検討中）」とし、金額区分は未公表。設備共用推進領域規程（令和2年九工大規程第10号）第2条が機器分析センター等の設備を学内外の共同利用に供する。超小型衛星試験センター機器利用取扱要項は学内移算・学外協議の料金区分を持つ。', 'official', 'https://www.ccr.kyutech.ac.jp/themes/innovation/f_venture/files/shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 校章の別途許可はshien.pdfに記載無し］元の主張(established): 称号・ロゴ使用は無料（校章等は別途許可）。SU支援規程第5条第1項(1)「『九工大発スタートアップ』の称号及びロゴを使用させること」。支援強化についての支援メニュー表は、称号及びロゴマーク使用と本学ホームページ掲載等による広報協力の対価を「無料」と明記。大学の校章・ロゴマークそのものは校章及びロゴマークに関する規程（平成21年九工大規程第12号）第7条で職員等以外は学長の許可が必要、第8条で商業利用は許可のうえ使用に関する契約を締結。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_ip_license', 'established', '実施権許諾に優遇措置・対価を株式等で取得可', 'SU支援規程第5条第1項(4)「本学が所有する知的財産権又は研究成果等の実施権の許諾に関する優遇措置」。株式等取扱規程（令和7年九工大規程第19号）第2条(3)(8)がライセンス等を支援事業に位置づけ、第3条第1項(2)で「現金による支払いを免除又は軽減することが、当該大学発スタートアップの経営の加速のために特に必要と認められる場合」に株式等で対価を取得できると定める。独占的実施許諾の明文や対価料率の減免率は確認できなかった。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64511', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_equity_rule', 'established', '株式等取扱規程あり（株式・新株予約権・社債）', '令和7年4月9日制定・九工大規程第19号「国立大学法人九州工業大学における大学発スタートアップの支援として実施する収益を伴う事業の対価として取得する株式等取扱規程」。第2条(5)で株式等＝株式・新株予約権・新株予約権付社債。第4条で職務発明取扱規程第13条の発明審査委員会が審査、第5条で学長が役員会の議を経て取得を決定。第9条で上場時は速やかに新株予約権を行使、第10条第2項で議決権は原則不行使、第12条でインサイダー取引防止のため保有状況を調査し利益相反委員会へ報告。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64511', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: PARKSのGAPファンドはentry-11943に無し］元の主張(established): プレGAPファンド＋PARKSのGAPファンド。2025年度に事業化助成制度「プレGAPファンド」を創設。市場調査、ビジネスモデルのブラッシュアップ、試作品作製、仮説検証のためのデータ取得に充当でき、第1回学内公募（2025年11〜12月）では研究者・事業プロデューサー・大学院生から21件の応募、外部審査員の面接審査で17件採択。実施主体は未来思考実証センターで、J-PEAKSのKPI達成に向けた取組と位置づけ。加えてPARKS採択の「JST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラム」のGAPファンドも活用。上限額は未公表。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 事業プロデューサー・伴走はstartup.htmlに無し］元の主張(established): 未来思考実証センターが窓口・事業プロデューサー伴走。2024年4月に社会実装本部未来思考実証センターを設置。スタートアップ推進部門が支援申請の提出先兼相談窓口となり募集は随時受付。KYUTECH REPORTでは「PoCテクニシャン、EIR等の支援人材の配置を進めていきます」と記載し、プレGAPファンドの応募区分にも事業プロデューサーが含まれる。2022年からPARKS（九州・沖縄圏19大学・機関）の共同主幹機関として起業活動支援、アントレ教育、起業環境の整備を推進。定型名のアクセラレーションプログラムは公開情報では確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_coi_sidejob', 'established', '兼業許可・利益相反手続の完了が認定要件', 'SU支援規程第3条(5)は、本学の教職員が関係する場合、国立大学法人九州工業大学職員兼業規程（平成24年九工大規程第9号）、九州工業大学利益相反マネジメント規程（平成29年九工大規程第7号）その他関係規程に定める所要の手続き・許可が適正になされていることを支援条件とする。支援申請ページの必要書類にも兼業許可申請書の写し（該当者のみ）。役員は役員兼業規程が別にある。株式等取扱規程第12条第2項は職員等の株式保有状況の調査結果を利益相反委員会へ報告すると定める。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_support_fee', 'established', '称号・広報は無料、施設・設備・知財は有償', '令和7年3月1日付「九工大発スタートアップに対する支援強化について」の支援メニュー表は、称号及びロゴマーク使用と本学ホームページ掲載等による広報協力を「無料」、学内インキュベーション施設への入居、学内施設・設備の使用、知的財産権又は研究成果等の実施権の許諾、KyuTechコラボへの入会を「支払いの一部を新株予約権の取得に代える等、柔軟な対応を行うことを想定（詳細は検討中）」とする。SU支援規程第5条第2項も支援内容に応じた対価を要求できると定める。', 'official', 'https://www.ccr.kyutech.ac.jp/themes/innovation/f_venture/files/shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_certified_count', 'established', '5社・一覧公開', '未来思考実証センターの大学発スタートアップ支援ページに、支援している九工大発スタートアップとして株式会社TriOrb、KiQ Robotics株式会社、キックスペーステクノロジーズ株式会社、株式会社Kyutech Space Solution for Emergings、Human Physical Intelligence株式会社の5社を掲載。2026年9月5日時点の同ページの掲載社数。文科省等の外部調査の件数は使用していない。', 'official', 'https://www.ccr.kyutech.ac.jp/f_venture/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_cert_rule', 'unknown', null, '成長戦略本部（IAC）「京都大学のスタートアップ支援の概要」の支援メニュー（GAPファンド、起業支援プログラム、施設利用支援、起業相談、KUEP）に認定制度・称号授与制度の記載はない。株式等取扱規程第2条は「大学発ベンチャー企業＝大学の研究成果を基に起業したベンチャー企業、大学との共同研究により起業したベンチャー企業その他大学と関連のあるベンチャー企業」と定義するが、認定手続きや称号付与は定めていない。公開情報の範囲で認定制度は確認できなかった。', 'unknown', 'https://iac.kyoto-u.ac.jp/info/cat-1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_eligible_scope', 'unknown', null, '認定制度が確認できないため認定対象の定めも確認できない。支援対象の範囲としては、ベンチャーインキュベーションセンター内規第6条が(1)本学の研究成果を活用した事業を実施し又は事業化のための活動を行う法人で設立登記の日から5年を経ていないもの、(2)同種の活動を行う個人で施設使用開始日から3年以内に法人設立を予定するもの、(3)その他センター長が適当と認める者、と定める。教職員・学生・卒業生といった身分別の区分は見当たらない。', 'unknown', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_recognition_decider', 'unknown', null, '認定制度が確認できないため認定の決裁・審査主体も確認できない。近い決裁として、KUViCの施設使用はベンチャーインキュベーションセンター運営委員会の議を経てセンター長が許可・不許可を決定（内規第9条、委員会は第18条）。ライセンス対価としての株式等取得は成長戦略本部長が財務状況等を審査して可否を決定し総長へ報告（株式等取扱規程第4条）。', 'unknown', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_cert_pre_registration', 'established', '可（法人設立前の個人も施設使用を申請可）', 'ベンチャーインキュベーションセンター内規第6条第2号が、施設の使用開始の日から3年以内に法人設立を予定する個人を使用者として認める。同第7条第3項は、個人が使用期間中に法人を設立して契約者が個人から法人に変更された場合、使用期間を個人での期間を含め通算3年以内とする扱いを定める。認定制度としての登記前申請ではなく、施設支援における設立前受付。', 'official', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_validity_years', 'unknown', null, '認定制度が確認できないため、認定の有効期間・更新の定めも確認できない。施設支援の期間は内規第7条で6月以上1年以内の範囲でセンター長が許可し、所定の手続を経て更新できるが引き続き3年を超えることはできない、と定める。', 'unknown', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_head_office_registration', 'established', '可（KUViC入居期間中に限り本店登記可）', '成長戦略本部のベンチャーインキュベーションセンター（KUViC）ページに「会社の住所として登記いただくことも可能です（ただし、入居期間中のみ）」と明記。所在地は国際科学イノベーション棟西館1階104号室（京都市左京区吉田本町36番地1）。施設使用は有償のため、登記のみを無償で受け入れる制度ではない。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-8/if08-08/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_facility_lease', 'established', 'KUViCの個室・半個室（有償・通算3年上限）', 'KUViC（国際科学イノベーション棟西館1階）に個室2室（2・3号室、各28.1㎡）、半個室5室（1・4〜7号室、10.4〜12.8㎡）、フリーアドレスデスクを設置。使用料は内規別表で月額・税込、個室69,000円、半個室33,000円（4号室のみ26,000円）、フリーアドレス11,000円。使用期間は6月以上1年以内で更新可、通算3年まで（内規第7条）。申請は使用開始希望日の2月前まで、運営委員会の審査を経てセンター長が許可（第8・9条）。学外者の申請には本学教職員の紹介を要する（第8条第2項）。', 'official', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_shared_equipment', 'established', '学外者として設備サポート5拠点を利用可', '大学公式ページ「学外の研究者も利用できる設備」が、本部構内設備サポート拠点（MaCBES）、医学・生命科学研究支援機構（iSAL）、宇治地区設備サポート拠点、桂結、北部キャンパス機器分析拠点の5拠点を挙げ「学外の方も利用が可能です。ご希望の方は、各設備の問い合わせ先に連絡をしていただき、所定の手続きを行ってください」と記載。大学発ベンチャーへの学内料金適用など料金上の優遇の記載は確認できなかった。', 'official', 'https://www.kyoto-u.ac.jp/ja/research/resource/equipment', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_name_logo_use', 'established', '名義・ロゴは許可制（学外者は教職員経由で申請）', '「京都大学の名義並びにエンブレム、ロゴタイプ及びスクールカラーに関する規程」に基づく名義使用ページが、使用できるのは「原則、本学の教職員に限られます」とし、教育・研究活動等で関係がある学外者は関係する教職員に相談のうえ申請すること、審査に案件によっては2か月程度を要することを案内。「京都大学発ベンチャー」等の称号使用を認める制度は確認できなかった。', 'official', 'https://www.kyoto-u.ac.jp/ja/about/operation/symbol/name', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_ip_license', 'established', 'ライセンス対価を株式等で受領可（個別審査）', '「京都大学におけるライセンス等の対価として取得する株式等取扱規程」第3条が、実施許諾等の相手方が大学発ベンチャー企業であり、その資力その他の事情を勘案して特に必要と認める場合に、対価として株式等を取得できると定める（現金対価の負担を軽減する優遇にあたる）。知的財産ポリシー（平成19年6月28日役員会決定）5(3)は「研究成果活用型起業支援」として成果活用型起業の支援を掲げる。独占的実施許諾や実施料減免を定めた条項は確認できなかった。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_equity_rule', 'established', '株式・新株予約権をライセンス対価として取得可', '「京都大学におけるライセンス等の対価として取得する株式等取扱規程」（平成24年3月6日総長裁定制定、令和7年3月25日改正・施行）。第2条で「株式等」を株式、新株予約権及び新株予約権付社債と定義し、「大学発ベンチャー企業」も定義。第4条で成長戦略本部長が財務状況等を審査して取得の可否を決定し、取得した場合は総長に報告する。現金出資ではなく対価としての取得を定める規程。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_gap_fund', 'established', 'KSAC-GAPファンドとStartup Catapult（年最大2千万円）', '京都大学・三菱商事Startup CatapultはステージⅠが年間上限400万円（学内研究者単独で申請可）、ステージⅡが年間上限2,000万円（研究代表者と事業化プロデューサーの共同申請が必須。後者は設立後2年以内のスタートアップ代表者または起業予定の個人）、支援期間は原則1年間。KSAC-GAPファンドはJST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムの一つ。IPG-Advanceは新規公募終了。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-1/if01-04/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_accelerator', 'established', '起業相談窓口・KUEP・採択課題への伴走支援', 'Startup Catapultは採択後に担当職員を割り当て「事業開発面での伴走支援を行」い、四半期ごとに進捗状況報告会を開催、成果報告書の提出を求める。KSAC-GAPファンドも採択課題に対し研究代表者が所属する大学の起業支援人材が伴走型の支援を提供。起業相談は学外・卒業生も対象で問い合わせフォームから受付。京都大学アントレプレナープラットフォーム（KUEP）が相談機能とデジタル・ファブリケーション設備EP LABを提供。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-1/if01-04/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_coi_sidejob', 'established', '役員兼業は総長許可制・利益相反審査委員会が審査', '兼業に関する指針（平成16年4月1日）第9〜11条で、教員が研究成果活用企業の役員等を兼ねる場合は総長の許可を要し、活用される研究成果を自ら創出していること等の許可基準を満たす必要がある。第12条は当該職務に主として従事する場合の休職を認め、第14条は兼業終了後2年間の利害関係業務への従事制限を定める。利益相反マネジメント規程（平成19年2月26日制定、平成26年1月21日全部改正）は兼業報酬・未公開株等を含む個人レベル利益相反を対象とし、利益相反審査委員会（委員長は法務・コンプライアンス担当副学長）が審査する。', 'official', 'https://www.kyoto-u.ac.jp/sites/default/files/embed/jaresearchAdditional_Positiondocuments01.shishin.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_support_fee', 'established', '施設使用は有償（月額1.1万〜6.9万円）', 'KUViCの使用料は内規別表で月額・税込、個室69,000円、半個室33,000円・26,000円、フリーアドレスデスク11,000円と定められ、第12条で前納。国際科学イノベーション棟規程も事務室2,200円/㎡/月等の使用料を定める（ラウンジ一時使用は教職員無料）。起業相談・GAPファンド・KUEPについては申込者から料金を徴収する記載が見当たらず、支援は有償の施設利用と、料金の定めのない相談・助成に分かれる。', 'official', 'https://iac.kyoto-u.ac.jp/wp-content/uploads/2025/05/kuvic_koboyoryo.zip', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_certified_count', 'unknown', null, '認定制度が確認できず、大学が公表する認定ベンチャー一覧も見つからなかった。成長戦略本部サイトには支援メニューと京都大学関連ベンチャーファンドの紹介はあるが、社名を列挙した認定企業一覧ページは確認できていない。経産省・文科省の大学発ベンチャー実態調査の機関別件数は機関自身の公開情報ではないため採用しない。', 'unknown', 'https://iac.kyoto-u.ac.jp/info/cat-1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_cert_rule', 'established', '大学発スタートアップ支援規則に基づく支援決定制度', '「国立大学法人京都工芸繊維大学における大学発スタートアップの支援に関する規則」(令和7年2月13日制定、同年3月1日施行)本文を確認。単独の「認定規程」ではなく支援決定型で、第6条の決定を受けた企業を第7条で「大学支援スタートアップ」と呼ぶ。第2条が「大学発スタートアップ」の定義を置く。称号を付与する条文は無い。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_eligible_scope', 'established', '知財・研究成果活用型かつ職員・学生・離籍後3年以内が発起人', '支援規則第2条。次の各号「のいずれにも該当する」企業。第1号=本学所有の知的財産権、または本学の役員・職員・学生が創出した研究成果・習得した技術を基に起業したもの。第2号=本学の職員等・学生、または本学を退職・卒業・修了・退学した者が発起人となるか設立に深く関与したもの。ただし退職等から設立までが3年以内に限る。第4条で公序良俗違反でないこと、大学への名誉毀損等のおそれが無いことも条件。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_recognition_decider', 'established', '産学公連携推進センター長（推進室審査・運営委員会の議）', '支援規則第6条。施設貸与と商業登記(第3条第1項第1号・第2号)はスタートアップ推進室の審査と産学公連携推進センター運営委員会の議を経てセンター長が決定。知財の優遇条件(第3号)はさらに知的財産戦略室の審査が加わる。株式等(第4号)は株式等取扱規則第4条・第5条により決定し、同規則第6条で契約締結は学長。学長決裁ではなくセンター長決裁である点が特徴。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_cert_pre_registration', 'unknown', null, '支援規則に登記前申請の可否を定めた条文が無い。第2条が「起業したもの」「設立までの期間が3年以内」と規定し、第4条第1号が同定義への該当を支援条件としているため設立済みを前提とする読みが自然だが、明文の禁止は無く、第5条の申請者は「支援を受けようとする者」と人を指す書き方。第5条の別記様式(大学発スタートアップ支援申請書)は公開されておらず内容を確認できなかった。可否を断定できないため unknown。', 'unknown', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_validity_years', 'established', '3年を超えない範囲でセンター長が定める期間、再申請可', '支援規則第7条「支援期間は、3年を超えない範囲で、センター長が必要と認める期間とする。ただし、再申請を妨げないものとする。」更新ではなく再申請による継続。第10条で、条件からの著しい逸脱、社会的信用の失墜、企業活動の実態消滅、第9条の事業報告書等の未提出などがあれば運営委員会の議を経て支援を中止できる。第9条で決算日から3か月以内の事業報告書・収支決算書の提出義務がある。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_head_office_registration', 'established', '貸与施設を所在地とする商業登記を許可（対価を求めうる）', '支援規則第3条第1項第2号「貸与した施設について、大学発スタートアップの所在地とする商業登記を認めること」。第1号の施設貸与を受けたことが前提で、貸与なしの住所のみの登記は想定されていない。同条第1項後段に「本学は、支援内容に応じて一定の対価を求めることができるものとする」とあり無償とは明記されていない。規則本文に明記された制度として整備されている点が特徴。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_facility_lease', 'established', '学内施設を事務室・研究室として貸与（3年以内）', '支援規則第3条第1項第1号「事務室又は研究室として、本学内の施設を貸与すること」。第3条第1項柱書で「本学の管理運営及び教育研究に支障のない範囲で」という留保付き。期間は第7条により3年以内・再申請可。同条後段により対価を求めうる。専用のインキュベーション施設や起業家向け貸与スペースの名称・入居要項は、大学サイトおよび産学公連携推進センターサイトに記載が見当たらず、施設名までは特定できなかった。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_shared_equipment', 'established', 'オープンファシリティセンター設備を学外料金で利用可', '「本学が所有する設備等の共用・共同利用における利用料等に関する規則」本文を確認。料金は「本学に所属する者」と「本学以外の機関に所属する者」の2区分のみで、大学発スタートアップ向けの優遇区分は無い。学外料金は学内料金のおおむね10倍前後(例: NMR600MHz 840円/時に対し12,600円/時)。事前講習・技術補助5,000円/時、技術代行10,000円/時。支援規則第3条第1項の支援列挙にも設備利用は無く、第5号の包括条項の余地のみ。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000165.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_name_logo_use', 'unknown', null, '支援規則第3条第1項の支援列挙(第1号から第4号)に称号やロゴの使用は含まれず、第5号「その他産学公連携推進センター長が必要と認める支援」の包括条項があるのみ。規則集(Reiki-Base)の体系目次全19章を通して確認したが、大学の名称・標章・ロゴ・校章の使用に関する規則は見当たらなかった。産学公連携推進センターのサイトにも記載が無く、可否を確認できなかったため unknown。', 'unknown', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_ip_license', 'established', '知財の譲渡・実施許諾に優遇的条件を設定可', '支援規則第3条第1項第3号「本学が所有する知的財産権の譲渡及び提供又は実施権の設定、実施許諾及び利用許諾に関する優遇的条件を設けること」。第6条第2項により、スタートアップ推進室の審査、知的財産戦略室の審査、運営委員会の議を経てセンター長が可否を決定する二段審査。独占許諾の可否や対価の減免率など具体的水準は規則に定めが無く非公開。一般規定は発明等規則第17条(実施許諾契約)。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_equity_rule', 'established', 'ライセンス対価を株式・新株予約権で取得可', '支援規則第3条第1項第4号と「ライセンス等の対価として取得する株式等取扱規則」(令和7年2月13日制定、同年3月1日施行)。同規則第2条第4号で対象を支援規則第7条の大学支援スタートアップと定義。第3条で対価を株式等により取得可、第5条第1項でセンター長が審査と運営委員会の議を経て可否を決定、第6条で学長が契約締結。第7条で学長が資金担当に管理させ、第8条の評価は国立大学法人会計基準、第11条で公開後速やかに売却。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000062.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_gap_fund', 'established', 'KSAC-GAPファンドの参画大学（JST基金事業）', 'KSAC(関西スタートアップアカデミア・コアリション)公式サイトのKSAC-GAPファンドのページで、参画大学(対象となる大学)一覧に京都工芸繊維大学が明記されているのを確認。JST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムのスタートアップ創出プログラムで、事業化に向けた仮説検証・試作・ビジネスモデル磨き上げを支援する。学内独自のGAPファンドや起業準備資金の制度は、大学サイトおよび産学公連携推進センターサイトでは確認できなかった。', 'official', 'https://ksac.site/activity/corporate/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_accelerator', 'established', 'スタートアップ相談室（実務家教員による起業相談）', '産学公連携推進センターのスタートアップ相談室のページを確認。相談対象は「スタートアップにご関心のある(準備中、既に設立済も含む)京都工芸繊維大学の教職員・学生・卒業生」。相談員は未来デザイン・工学機構准教授と産学公連携推進センター准教授(公認会計士)の2名。事業計画策定、増資時の株価設定(バリュエーション)、資本政策、IPO/M&A、知財戦略・先行技術調査、ファイナンス交渉の支援に対応。年次アクセラレーションプログラムの記載は無い。', 'official', 'https://www.liaison.kit.ac.jp/liaison/sangaku/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_coi_sidejob', 'established', '兼業規則・利益相反規則の手続完了が支援の条件', '支援規則第4条第4号「職員等が設立したものにあっては、国立大学法人京都工芸繊維大学職員兼業規則(平成16年4月1日制定)、国立大学法人京都工芸繊維大学役職員利益相反マネジメント規則(平成19年2月15日制定)その他関係規則等に定める所要の手続、許可等が適正になされていること」。兼業許可と利益相反管理の完了が支援の前提条件として規則本文に接続されている。兼業規則は令和7年3月1日施行版が支援規則と同時改正。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_support_fee', 'established', '支援内容に応じ一定の対価を求めることが可能', '支援規則第3条第1項後段「この場合において、本学は、支援内容に応じて一定の対価を求めることができるものとする」。無償と明記した条文は無く、施設貸与・商業登記・知財ライセンスのいずれについても有償化しうる建て付け。対価の算定基準や金額表は規則に定めが無く公開されていない。第8条で大学は製品・サービスの品質や経営状況を保証せず、支援や支援中止で生じた損害の賠償義務も負わないと免責を明記。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_certified_count', 'unknown', null, '支援決定を受けた大学支援スタートアップの社数・一覧は、大学サイト(kit.ac.jp)および産学公連携推進センターサイト(liaison.kit.ac.jp)のいずれにも掲載が見当たらなかった。センターサイトの産学連携カテゴリは産学連携制度の紹介・科学技術相談・スタートアップ相談室・産学連携の成果の4本のみで、認定企業一覧のページが存在しない。支援規則の施行が令和7年3月1日と新しく、機関自身の公開実績を確認できないため unknown。', 'unknown', 'https://www.liaison.kit.ac.jp/liaison/sangaku/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_cert_rule', 'established', '「京都府立医科大学発ベンチャー」認定制度（法人規程第49号）', '「京都府公立大学法人における大学発ベンチャー企業の認定等に関する規程」（令和7年1月31日、京都府公立大学法人規程第49号、令和7年4月1日施行、全14条＋様式10種）をPDF全文で確認。府立医大と府立大を設置する京都府公立大学法人の共通規程。第6条第2項で府立医大に関連する認定ベンチャーは「京都府立医科大学発ベンチャー」の称号を使用できると規定。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_eligible_scope', 'established', '知財活用型と役員・教職員・在籍学生の設立型の2類型', '第2条第1号ア「知的財産活用型ベンチャー」＝法人に帰属する知的財産を活用するために設立の準備を行い、又は設立した企業。同号イ「教職員・学生等設立ベンチャー」＝法人の役員、教職員又は学生が代表者・役員・経営に実質的に関与する者となり運営している企業。第2条第5号で学生は「府立医大又は府立大に在籍中の学部生、大学院生及び研究生」と定義。卒業生・退職者を対象に含める規定は同規程内にない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_recognition_decider', 'established', '理事長決定（法人理事会審議・学内審査委員会が審査）', '第4条。代表者が認定申請書（様式第1号）を理事長に提出→理事長が京都府立医科大学発ベンチャー審査委員会に審査を付託（第2項）→同委員会が「別に定める審査（認定）基準」に基づき審査し理事長に上申（第3項）→理事長が上申を踏まえ法人理事会で審議（第4項）→理事長が結果通知書（様式第2号）で通知（第5項）。審査委員会の設置根拠は第3条、必要事項は「別に定める」。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_cert_pre_registration', 'established', '知財活用型は設立準備段階で可、設立型は1期決算後', '第2条第1号アが「設立の準備を行い、又は設立した企業」と定義し、設立前の申請を認める。様式第1号に「1 設立状態（□新規 □既設）」「13 準備活動状況及びスケジュール（新規の場合）」欄があり、添付書類も「新規設立の場合は、定款案、事業計画案」で足りる。一方、第5条第2号により第2条第1号イ（教職員・学生等設立型）は設立後少なくとも一事業年度の決算を経過し決算報告を終えていることが申請条件。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_validity_years', 'established', '知財活用型5年・設立型2年、再申請で延長可', '第4条第6項「認定期間について、第2条第1号アとして認定する場合は認定の日から5年間、第2条第1号イとして認定する場合は認定の日から2年間とする。ただし、再申請による延長を妨げない。」第10条で毎年決算日から3か月以内の事業報告（様式第8号）が義務。第11条に認定取消事由（実態不存在、事業報告未提出、反社会的勢力該当など）を規定。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_head_office_registration', 'established', '可（貸与施設を所在地とする商業登記を許可）', '第7条第1項第2号「貸与した施設について、貸与期間中における認定ベンチャーの所在地とする商業登記を許可すること」。同項第1号の施設貸与とセットで、貸与期間中に限られる。申請は便宜措置申請書（様式第5号）を称号授与大学の学長へ提出し、学長が便宜措置通知書（様式第7-1号）で許可（第7条第3項・第4項）。有償無償の定めは同規程内になく、対価に関する条項も見当たらない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_facility_lease', 'established', '学内の事務室・研究室を貸与（学長が期間決定）', '第7条第1項第1号「事務室又は研究室として称号授与大学内の施設を貸与すること」。専用のインキュベーション施設は規程上も大学サイト上も確認できず、既存の学内施設を事務室・研究室として貸すかたち。貸与は「管理・運営及び教育・研究・診療等に支障が生じない範囲内」に限定（第7条第1項柱書）。期間は認定期間の末日までの範囲で学長が定める（第7条第2項）。賃料の定めは同規程内になし。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_shared_equipment', 'established', '研究設備等の利用許可（料金区分の定めなし）', '第7条第1項第3号「研究設備等の利用を許可すること」。便宜措置申請書（様式第5号）のチェック欄にも「□第3号：研究設備等の利用許可」がある。学内料金・学外料金といった料金区分や利用料の定めは同規程内になく、法人規程一覧（規則4本、規程1〜49号、ポリシー6本）にも大学発ベンチャー向けの共用機器利用規程は掲載されていない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_name_logo_use', 'established', '称号とロゴマークを認定期間中は使用可', '第6条第1項で理事長が称号記（様式第4号）により称号を授与。第2項で府立医大に関連する認定ベンチャーは「京都府立医科大学発ベンチャー」の称号を使用できる。第3項「前項の称号を授与された認定ベンチャーは、当該大学のロゴマークを使用することができるものとする」。第4項で使用期間は認定期間の末日まで。第9条で称号の使用により法人に損害を与えた場合の賠償義務、第11条第3項で認定取消と同時に称号・ロゴの効力が失われることを規定。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_ip_license', 'unknown', null, '［自動検証で否認: 23765.pdfは知財ポリシーのみ、規程31号の記載なし］元の主張(not_started): 認定ベンチャー向けの実施許諾優遇規定なし。認定規程第7条の便宜措置は施設貸与・商業登記許可・研究設備利用許可の3号と「その他学長が必要と認めること」のみで、知財の優先実施許諾や対価減免は含まれない。京都府公立大学法人知的財産ポリシー（平成21年4月1日制定、令和2年3月4日改正）も第8項で「技術移転を推進」と述べるにとどまり、大学発ベンチャー向け優遇の記載はない。教職員等の職務発明等に関する規程（規程第31号）第12条は発明者への実施補償金（収入額の50％）の定めで、ライセンス先の優遇規定ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_equity_rule', 'not_started', '出資・株式取得の規程なし（定款の業務範囲外）', '京都府公立大学法人定款第24条が定める業務の範囲は6号（大学の設置運営、学生支援、受託・共同研究等の連携活動、生涯学習機会の提供、教育研究成果の普及活用、附帯業務）で、研究成果活用事業者への出資は含まれない。法人サイトの規則・規程一覧（規則4本、規程第1〜49号、ポリシー6本）にも株式・新株予約権の取得や評価・保有・処分に関する規程は掲載されていない。認定規程第7条の便宜措置にも株式等の取得は含まれない。', 'official', 'https://www.kpu-m.ac.jp/corporation/teikan.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: 実際は「スタートアップ創出プログラム」で不一致］元の主張(established): KSAC-GAPファンド（JST基金）を学内公募。大学サイトの研究案内に「KSAC-GAPファンド」のページがあり、JST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムの下で「研究成果と事業化との間のギャップを埋めるため、達成すべきマイルストンを設定し、ビジネスモデルのブラッシュアップ、試作品製作、仮説検証のためのデータ等の整備を進めるための資金」を提供すると記載。第3回学内公募は2025年10月1日〜10月30日正午、提出先は研究支援課。学内独自のGAP資金・起業準備金は確認できず。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_accelerator', 'unknown', null, '［自動検証で否認: K-MICS詳細はsource_url本文に無く別ページの情報］元の主張(established): KSAC-GAP採択課題へ伴走支援、K-MICSが技術相談窓口。KSAC-GAPファンドのページに、採択された研究開発課題には「研究代表者が所属する大学の起業支援を担う人材が伴走型の支援を提供」と明記。事前説明会も学内で3回開催（2025年10月）。相談窓口は令和6年4月1日設置の産学公連携機構K-MICS（産学公連携機構総括部門と知的財産部門）で、技術相談を無料で受け付けると産学公連携ページに記載。起業に特化した常設のアクセラレーションプログラムは確認できず。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_coi_sidejob', 'established', '研究成果活用兼業は理事長許可制・COI規程審査が前提', '京都府公立大学法人教職員兼業規程（規程第10号）第3条は営利企業の役員兼業を原則不許可とした上で、技術移転兼業・研究成果活用兼業・監査役兼業の3類型を理事長の許可により可能とする。第5条で研究成果活用企業を定義し、報酬・財産上の利益を含む年次報告を義務付け、兼業終了後2年間は利害関係業務に従事させない。第11条で事前許可申請、第12条で許可期間1年以内・更新可。認定規程第5条第8号は、教職員がベンチャー役員等になる場合に兼業規程・利益相反管理規程の手続と学部長の承諾を認定の条件としている。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/kitei10.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_support_fee', 'unknown', null, '認定規程全14条と様式10種に認定手数料の定めはなく、京都府公立大学法人手数料等徴収規程（規程第26号）の別表も「証明の事務 1件につき400円」のみで認定手数料は載っていない。一方、第7条の便宜措置（施設貸与・商業登記許可・研究設備利用許可）の対価・使用料に関する条項は認定規程内に存在せず、法人規程一覧にも大学発ベンチャー向けの施設使用料規程はない。有償か無償かを公開情報から確定できないため unknown とした。', 'unknown', 'https://www.kpu-m.ac.jp/corporation/files/6796.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_certified_count', 'unknown', null, '認定制度は令和7年4月1日施行と新しい。大学サイトの産学公連携メニュー（産学公連携機構K-MICS、利益相反、研究シーズ集、包括連携協定、連携講座）と研究案内メニュー、法人サイトの法人のお知らせのいずれにも認定ベンチャー一覧や称号授与の公表ページは見当たらない。認定規程にも認定企業を公表する条項はない。社数・一覧公開の有無とも公開情報からは確認できず。', 'unknown', 'https://www.kpu-m.ac.jp/doc/alliance/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_cert_rule', 'established', '信州大学発スタートアップ（認定規程・称号記授与）', '「国立大学法人信州大学における大学発スタートアップの認定に関する規程」（平成30年3月28日規程第158号、令和6年4月1日施行の改正版）第6条第1項で、学長が称号記（別記様式第2号）により「信州大学発スタートアップ」の称号を授与すると規定。平成30年4月1日施行で運用開始。令和5年度規程第141号（令和5年4月1日施行）以降、名称が「信州大学発ベンチャー」から「大学発スタートアップ」に変更されている。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・知財/研究成果活用型', '認定規程第2条は「大学の研究成果又はその他の活動成果を事業化することを主たる目的」とする法人のうち、(1)本法人帰属の知的財産権をもとに起業したもの、(2)本法人で達成された研究成果又は習得した技術に基づいて起業したもの、(3)教職員・学生等が発起人又は設立時に取締役相当となって起業したもの（退職・卒業等から起業までが3年以内のものに限る）、(4)学長が特に必要と認めたもの、と4類型を定める。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_recognition_decider', 'established', '学長（大学発スタートアップ認定委員会の議を経る）', '認定規程第5条第2項で学長が認定委員会の議を経て認定を決定。第4条第1項により認定委員会は学術研究・産学官連携推進機構に置かれる。認定委員会細則（平成30年3月28日細則第107号）第3条は委員を機構長、学術研究支援本部長、新価値創成本部長、リサーチアドミニストレーション室長、スタートアップ・事業化推進室長、知的財産室長、研究推進部長、総務部長、人事課長、広報室長ほかと定め、第4条で機構長が委員長。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001086.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_cert_pre_registration', 'not_started', '不可（登記簿の写し・定款の写しの添付が必須）', '認定規程第2条は認定対象を「起業した」法人と定義。認定申請書（別記様式第1号、第5条関係）の添付資料に「登記簿の写し」「定款の写し」が明記されており、設立登記前の申請は受理できない。様式には⑦事業開始日等として「事業開始予定日」欄もあるが、これは設立済法人の事業開始時期を記す欄で、登記簿の写しの必須性を覆すものではない。条件付認定や認定予定通知の規定は規程・様式のいずれにも無い。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/actdata/110001085/13000617301000000123.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_validity_years', 'established', '5年間・再申請可', '認定規程第6条第2項「「信州大学発スタートアップ」の称号は，5年間使用することができる。ただし，再申請することを妨げないものとする」。認定申請書（別記様式第1号）の①申請区分にも「□新規申請／□再申請」の選択欄がある。第8条で認定企業は決算日から3か月以内に事業報告書・収支決算書を毎年度提出する義務があり、未提出は第10条第1項第2号の取消事由となる。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_head_office_registration', 'established', '可（貸与施設・シェアオフィスで商業登記）', '認定規程第11条第1項第2号「貸与したインキュベーション施設等について，大学発スタートアップの所在地とする商業登記を認めること」。起業ガイドブックp16も「インキュベーション施設（学内住所）等での商業登記の許可」を支援内容に挙げる。同p18のシェアオフィスは「起業時には、会社登記が可能であり、起業済スタートアップも利用・移転登記できます」と明記。無償である旨の記載はなく、第11条第2項により関係規則等（施設は不動産貸付事務細則）に従う。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/SUGuidebook_2024_Web.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: OVIC規程に施設貸与・有償の明記なし］元の主張(established): インキュベーション施設・シェアオフィスを各キャンパスで貸与。認定規程第11条第1項第1号で事務室又は研究室として学内インキュベーション施設等を貸与。起業ガイドブックp18-19によりOVIC・Fii・SU-PLAF・AREC（上田）、SASTec・AICS・UFO Nagano（長野工学）、CSMIT（松本）、FabLab Nagano（長野教育）と、5キャンパスのシェアオフィス（Matsumoto／Ueda／Nagano TEC／Nagano EDU／INA）を整備。OVIC規程第7条は施設貸付を不動産貸付事務細則によるとし有償貸付。入居期間の定めは公開情報で未確認。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_shared_equipment', 'unknown', null, '認定規程第11条第1項の支援メニュー6号に共用機器・設備利用は含まれない（第6号は「その他，学長が必要と認めること」の包括条項）。一般規程として信州大学共同利用大型機器利用規程（平成16年4月1日規程第6号）があり、第2条で利用資格を職員・学生のほか「機器管理責任者が適当と認めた者」とし、第10条で経費は利用者負担・額は別に定めるとする。認定スタートアップ向けの学内料金区分や優遇の有無は公開情報で確認できなかった。', 'unknown', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110000171.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_name_logo_use', 'established', '称号を5年間使用可（ロゴ使用規程は規則集に不見当）', '認定規程第6条で学長が称号記により「信州大学発スタートアップ」の称号を授与し、第6条第2項で5年間使用可。第10条第3項により取消時は称号記を返付し、以後認定の事実を事業に活用してはならない。認定申請書には称号使用で損害が生じても大学に賠償請求しない旨の誓約がある。大学ロゴ・校章の使用条件を定める規程は、信州大学規則集（2026年7月31日内容現在）の現行規則一覧に見当たらなかった。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_ip_license', 'established', '発明者の事業化に優先的実施許諾・対価は株式等も可', '知的財産権実施許諾等取扱規程（平成20年6月19日規程第92号）第6条第1項第2号は「知的財産権の発明者が事業化するとき」に優先的実施許諾ができると定め、第2条第3項で優先的実施許諾には専用実施権・独占的通常実施権の形態を含む。実施許諾は第3条第2項で原則有償だが、認定スタートアップは株式等取扱規程により対価の一部又は全部を株式・新株予約権で支払える。対価減免の定めは学術研究機関・リサーチツール特許向け（第8条）で、スタートアップ向けではない。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110000371.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_equity_rule', 'established', '認定SU限定の株式等取扱規程あり（ライセンス対価）', '「国立大学法人信州大学における認定大学発スタートアップを対象としたライセンス等の対価として取得する株式等取扱規程」（令和4年11月16日規程第183号、令和7年10月3日施行の改正版）。第3条で認定スタートアップからの申出があり事業の有望性等3要件を満たす場合に株式・新株予約権を取得。第4条で機構長を委員長とする審査委員会が審査、第5条で学長が決定し契約締結。第8条で共益権は原則不行使、第9条で換金可能になり次第売却。寄附による株式取得は別規程（規程第110001171号）。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001254.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_gap_fund', 'established', 'IJIE-GAPファンドと信州大学POCファンド', '起業ガイドブックp14により、甲信・北関東7大学のプラットフォームInland Japan Innovation Ecosystem（IJIE）が、参画大学の研究者・大学院生を対象に基礎研究と事業化の間のGAPを埋める研究開発費を支給する「IJIE-GAPファンドプログラム」を実施（事業化推進機関（VC等）の参画が必須）。同p16の信州大学POCファンドは試作品作成等による概念実証を支援し、技術移転・スタートアップ創出を促進する。IJIEは大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムの一環。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/SUGuidebook_2024_Web.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_accelerator', 'established', 'スタートアップ・事業化推進室が伴走支援・ピッチ・講座', 'スタートアップ・事業化推進室規程（令和6年3月18日規程第365号）第3条が起業シーズの発掘育成、知財戦略、イベント・コミュニティ形成、本学発スタートアップ支援、IJIE運営、アントレプレナー教育、事業化創出支援を所掌。起業ガイドブックp14では事業計画作成・学内手続き・会社設立サポート・金融機関マッチングのハンズオン支援、大学院公開授業「大学発技術系ベンチャー実践論」、信州大学ベンチャーピッチ（最優秀賞はNEDO NEPとの連携優遇課題選定）を実施。各キャンパスのシェアオフィスが起業相談窓口。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001305.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_coi_sidejob', 'established', '研究成果活用役員兼業は学長許可・COI自己申告制', '認定規程第3条第1項第4号が、教職員は職員兼業規程（平成16年規程第47号）と産学官連携利益相反マネジメント規程（平成18年規程第83号）の手続・許可が適正になされていることを申請要件とし、認定申請書の添付資料にも「許可を受けた兼業許可申請書の写し」が必須。起業ガイドブックp10-11によれば大学発スタートアップは「研究成果活用役員兼業」に該当し学長の許可が必要（申請から許可まで最低2か月）。代表取締役兼業は禁止されないが責任が重大・所要時間が長大な場合は認められない。設立時に利益相反自己申告書を提出（利益相反規程第11条）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/SUGuidebook_2024_Web.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_support_fee', 'established', '施設貸付・実施許諾・機器利用は有償', '認定規程第11条第2項は支援を行う際は「本法人における関係規則等によるものとする」と定め、個別の支援は各規則の対価規定に従う。施設貸与はOVIC規程第7条により不動産貸付事務細則に基づく貸付（有償）。知財の実施許諾は実施許諾等取扱規程第3条第2項で原則有償（認定スタートアップは株式・新株予約権での支払いが可能）。共同利用大型機器は利用規程第10条で経費を利用者負担。認定・称号授与そのものについての手数料規定は認定規程・様式に無い。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_certified_count', 'established', '18社・認定企業一覧を公開（2026年3月現在）', '「信州大学発スタートアップ認定企業（2026年3月現在）」ページに、企業名・代表者名・設立日・所在地・企業紹介を付した認定企業が18社掲載されている（ウェルナス、スキノス、精密林業計測、ナフィアス、SCOP、Spiral Tech、A-SEEDS、SSST、信州ボルタ、発酵長寿研究所、Morus、ヴェルヌクリスタル、みらくる、TRILL.、Unseed、MedSciSportLab、HAKKOU JAPAN、OMOMO）。同ページから認定企業一覧PDF（R8.3.11日現在）にもリンク。称号の有効期間が5年のため、この18社は現在有効な認定数であり累計認定数とは一致しない可能性がある。', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/irl/venture/post-29.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_cert_rule', 'established', '北大発認定スタートアップ企業（称号授与規程）', '「国立大学法人北海道大学における北大発認定スタートアップ企業称号授与規程」（平成27年11月1日 海大達第262号制定、令和6年1月1日 海大達第5号最終改正）第2条が「北大発認定スタートアップ企業」の称号を定める。産学・地域協働推進機構スタートアップ創出本部が事務局で、公式サイトに「北大発認定スタートアップ企業の称号付与について」の申請案内ページがある。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_eligible_scope', 'established', '知財活用・研究成果活用・在籍教職員／学生・退職卒業1年以内など8類型', '称号授与規程第3条第1項の8号。(1)本学の知的財産権を活用、(2)本学の研究成果または技術を活用、(3)設立後5年以内に技術事業化の共同研究を実施、(4)設立後5年以内に技術移転または成果有体物の提供を受けた、(5)本学の教職員または学生が発起人・取締役として設立し現在も在籍、(6)本学の退職者または卒業生が退職・卒業後1年以内に発起人・取締役として設立し現在も在籍、(7)本学の出資・施設貸与その他の支援により設立、(8)総長が前各号に準ずると認めたもの。学生・卒業生も対象だが、卒業生は「卒業後1年以内の設立」に限る。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/apply/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_recognition_decider', 'established', '総長が決定・北大発認定スタートアップ企業審査委員会が審査', '称号授与規程第8条第1項で、別に定める様式により産学・地域協働推進機構長を経て総長に申請し、同条第4項で総長が認定するか否かを決定する。審査は第4条の「北大発認定スタートアップ企業審査委員会」（副機構長、本部長、副本部長、部門長、産学連携課長で構成）が担う。実務は申請書のメール提出（startup@mcip.hokudai.ac.jp）、大学担当者との面談、認定審査、結果通知の順。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_cert_pre_registration', 'not_started', '不可（履歴事項全部証明書が必須）', '称号付与ページの必要書類に、申請書（Word）に加えて「履歴事項全部証明書（3ヶ月以内）」「定款の写し」「株主名簿」が限定列挙されている。いずれも設立登記後でなければ取得・提出できない書類であり、登記前の申請は受け付けられない。称号授与規程第8条にも申請ページにも、設立予定段階での申請、認定予定通知、条件付認定を認める定めはない。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/apply/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_validity_years', 'unknown', null, '称号授与規程を全文確認したが、称号の有効期間や更新手続を定める条文はない。第12条第1項が取消し事由を10号（対象要件該当性の喪失、社会的信用失墜行為、報告義務の懈怠、辞退の申出、会社解散、破産・再生・更生手続開始決定、不正競争罪の有罪確定、その他大学の不名誉となるおそれ等）列挙し、同条第2項で取消し後は当該事実を事業に使用してはならないと定めるのみ。称号付与ページにも有効期間の記載がない。', 'unknown', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_head_office_registration', 'established', '可（学内拠点HXの有料法人会員・年額12万円）', '産学・地域協働推進機構スタートアップ創出本部が運営する学内拠点「HX（エイチクロス）」（フード＆メディカルイノベーション国際拠点1F）の有料法人会員に、「HXの本店所在地としての住所登記」が認められる。年会費120,000円、資格は北海道大学の研究成果を活用した事業等を営む法人設立後2年以内の未上場株式会社。申込→面談→利用審査の手順。個人会員と無料法人会員は登記不可。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_facility_lease', 'established', '北キャンパスに賃貸型インキュベーション施設（有償）', '北海道大学北キャンパス内に、中小企業基盤整備機構が北海道・札幌市の要請を受け北海道大学と連携して整備・運営する「北大ビジネス・スプリング」（全31室ウェットラボ、25.27〜52.83㎡、敷金は月額賃料3か月分、当初契約期間は原則5年以内で再審査により2年以内の再契約可、北海道・札幌市の賃料補助制度あり）がある。入居対象は大学発ベンチャー、起業しようとする研究者・学生等。ほかに北海道大学自身の総合イノベーション創発機構オープンラボラトリーや北キャンパス総合研究棟3・6・7・8号館オープンラボラトリー等が並ぶ。称号授与規程第3条第7号も「施設貸与」を認定対象要件に挙げる。', 'official', 'https://www.smrj.go.jp/incubation/ho-bis/room/info/fbrion000000bcuz-att/nyukyoshabosyuyoko_20251202.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_shared_equipment', 'established', 'オープンファシリティを学外料金で利用可（認定企業の優遇なし）', '「国立大学法人北海道大学オープンファシリティ使用規程」（平成17年10月24日 海大達第231号、令和8年7月1日最終改正）第3条第5号が「研究開発等のために設備を利用する民間企業その他の法人に所属する者」の使用を認め、第5条が学内利用者と学外利用者の使用料を区分する（基本料＋時間単価）。管理責任者が特に認めるときは使用料の全部または一部を免除できる。総合研究基盤連携センター（GFC）の料金区分は学内（装置管理部局内／部局外）と学外（大学・公的機関／一般）の4区分で、大学発ベンチャーや認定スタートアップ企業向けの区分・割引の記載はない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000599.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_name_logo_use', 'established', '称号使用可・大学が認定ロゴを配布', '称号付与ページに、認定後の効果として「本学が配布する認定ロゴをご使用いただけます」と明記されている。称号授与規程第12条第2項は、称号を取り消された場合に当該事実を事業に使用してはならないと定める。校章そのものの使用条件についての記載は、称号授与規程にも称号付与ページにもない。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/apply/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_ip_license', 'established', 'ライセンス対価として株式・新株予約権を取得可', '「ライセンス等又はスタートアップ支援の対価として取得する株式等の取扱いに関する規程」（令和2年4月1日 海大達第50号、令和6年1月1日 海大達第6号最終改正）が、知的財産の譲渡もしくは提供、実施権の設定または実施権・利用権の許諾の対価として株式・新株予約権を取得できると定め、知的財産専門部会の審査を経て産学・地域協働推進機構長が決定する。現金以外の対価を認める点が認定企業への実質的な優遇。一方、優先的実施許諾・独占実施・実施料減免を明文で定めた規定は、称号授与規程にも産学官連携ポリシー（平成17年1月11日）にも見当たらない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000929.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_equity_rule', 'established', '株式等取扱規程あり・株式と新株予約権の両方', '同規程が、ライセンス等の対価とスタートアップ支援の対価の2経路で株式・新株予約権を取得できると定める。スタートアップ支援は「北大発認定スタートアップ企業に対する研究開発の成果の普及及び活用の促進に必要な支援（ライセンス等を除く）」と定義され、審査は北大発認定スタートアップ企業審査委員会、ライセンス等は知的財産専門部会が行い、産学・地域協働推進機構長が決定する。換金可能となったときは速やかに売却し、特別の事情がある場合に限り保有。配当等の経済的利益の受取以外の権利は原則行使しない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000929.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_gap_fund', 'established', 'HSFC GAPファンド（U型500万円・Z型300万円／最長1年）', 'JST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムの拠点都市プラットフォームとして、北海道大学を主幹機関とする「HSFC（北海道未来創造スタートアップ育成相互支援ネットワーク）」が採択され、事務局は産学・地域協働推進機構スタートアップ創出本部に置かれる。2026年度ステップ1公募は、研究シーズをもとに起業を目指す研究者・大学院生を対象に、U型（ユニコーン志向）上限500万円/件、Z型（ゼブラ志向）上限300万円/件、支援期間最長1年。事業戦略・知財戦略・資本戦略の構築支援とDemo Dayでのベンチャーキャピタルとのマッチングが付く。ステップ2の公募も別途ある。', 'official', 'https://hsfc.jp/events/20260319880/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_accelerator', 'established', '起業相談窓口＋HXの起業塾・ピッチ＋GAPファンド伴走支援', 'スタートアップ創出本部がアントレプレナー教育部門・スタートアップ支援部門・戦略企画部門の3部門を置き、アントレプレナーシップ育成プログラム、HX、GAPファンドプログラムを運営する。起業相談は学内者用・学外者用の専用フォームを公開。HXには常駐のXディレクターによるコンサルティング（ビジネスモデル検討、事業計画策定）があり、起業塾・ピッチイベントを定期開催する。GAPファンドは資金と伴走支援の両面で支援しDemo Dayを実施。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.mcip.hokudai.ac.jp/about/organization/startup_creation_headquarters/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_coi_sidejob', 'established', '役員兼業は総長許可・役員兼業審査専門部会の審査を前置', '「国立大学法人北海道大学職員兼業規程」（平成16年4月1日 海大達第104号、令和8年4月1日 海大達第59号最終改正）第18条が、教員が技術移転事業者の役員、研究成果活用企業の役員、監査役等を兼ねる場合は、利益相反マネジメント規程（平成16年海大達第262号）第11条の2の「営利企業への役員兼業審査専門部会」の審査を経て許可すると定める。第3条で許可権者は原則部局等の長だが、営利企業の役員兼業は総長。第19〜24条が技術移転兼業・研究成果活用兼業の許可基準を置き、第28条第1項第4号は親族の持株が発行済株式総数の4分の1を超える場合を許可基準不適合とする。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000466.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_support_fee', 'established', '認定申請に手数料の定めなし・施設と機器は有償', '称号授与規程と称号付与ページのいずれにも、認定申請や称号付与に係る手数料の定めはない。認定後の支援は有償・無償が混在し、HXは個人会員と無料法人会員が無償、有料法人会員が年額120,000円（本店登記可）。北大ビジネス・スプリングは賃料と敷金（月額賃料3か月分）を要する賃貸で、光熱水費・通信費・産業廃棄物処理費も入居者負担（北海道・札幌市の賃料補助制度あり）。オープンファシリティはオープンファシリティ使用規程第5条の使用料（学外区分）が必要。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_certified_count', 'established', '106社（2026年7月現在）・一覧を公開', '産学・地域協働推進機構の「北大発認定スタートアップ企業一覧」ページに「北大発認定スタートアップ企業一覧（2026年7月現在 106件）」と明記され、企業名・企業ロゴ・企業ウェブサイトへのリンクを付した一覧が公開されている。一部の企業はウェブサイトリンクが未設定。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/su_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_cert_rule', 'established', '「北陸先端科学技術大学院大学発ベンチャー」称号を授与', '根拠は「国立大学法人北陸先端科学技術大学院大学における大学発ベンチャーの認定及び支援に関する規則」(令和2年12月23日規則第81号、令和7年10月1日規則第105号改正まで反映)。第5条第2項で学長が認定し、第6条で称号記(別紙様式1)により「北陸先端科学技術大学院大学発ベンチャー」の称号を授与すると規定。第11条で認定状況を公表する義務も置く。第10条第3項は取消し後に認定・称号を受けていた事実を事業に使用してはならないと定める。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_eligible_scope', 'established', '知財・研究成果活用型、教職員・学生（退職等後3年以内）', '認定規則第2条で「本学の研究成果を事業化することを主たる目的」とし、(1)本学帰属の知的財産権を基に起業・起業準備、(2)本学で達成された研究成果又は習得技術に基づく起業・起業準備、(3)教職員及び学生が発起人又は設立時に取締役相当となる企業（退職・修了等の後の起業は退職等から起業まで3年以内に限る）、(4)学長が特に必要と認めた企業、のいずれかと定義。第4条第1項第4号で「単に他者の製品を販売する小売業・サービス業等ではないこと」を除外要件としている。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_recognition_decider', 'established', '学長（大学発ベンチャー審査委員会の議を経る）', '認定規則第5条第2項「学長は、前項の申請書の提出があったときは、審査委員会の議を経て、認定の可否を決定するものとする」。第3条で大学発ベンチャー審査委員会を置き、委員は研究担当理事、未来創造イノベーション推進本部長、産学官連携推進センター長、学長が指名する同センターの教授・准教授、副理事(研究担当)ほかで構成し、委員長は未来創造イノベーション推進本部長。過半数出席で成立、出席委員の過半数で議決。第13条により事務は共創活動推進課が処理する。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_cert_pre_registration', 'established', '可（認定後6月以内に商業登記完了見込みで申請可）', '認定規則第4条第1項第1号後段「起業準備の段階にある企業等については、認定の決定後6月以内に商業登記が完了する見込みであること」。同項第5号は教職員を役員に就任させる場合、兼業規則等の手続・許可が適正になされていることを求め、起業準備段階のものは「商業登記までに当該手続が完了する見込みであること」とする。VBL利用経費細則第2条の表は、認定大学発ベンチャーの利用のうち「商業登記を完了した月までの利用」は経費を徴収しないと定めており、登記前の入居を想定した設計になっている。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_validity_years', 'established', '5年・更新可（初回更新5年、2回目以降1年）', '認定規則第4条第2項「大学発ベンチャーの認定期間は5年間とし、当該期間の更新を申請することができる」、第3項「更新後の認定期間は、初回は5年間とし、2回目以降は1年間とする」。第4項で更新の申請手続は新規申請と同じ。ただし第12条第3項により、支援そのものの期間は「認定した日から3年を超えない範囲で学長が必要と認める期間」で、認定期間より短い。公開の認定一覧も各社の認定期間を5年間で表示している。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_head_office_registration', 'established', '可（VBL利用許可期間内に限りVBL住所で登記）', '認定規則第12条第1項第2号「ベンチャー・ビジネス・ラボラトリーの利用が許可された場合において、利用許可期間内に限り認定大学発ベンチャーの登記住所を当該施設の住所とすることを認めること」。あわせて登記申請前に登記申請書の写しを大学へ提出し、VBL退去時には登記住所を変更したことを示す書面を提出する義務を課す。学内本店登記が支援メニューとして条文に明記されている点が特徴。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 研究員室等の部屋種別・クリーンルームは258に記載無し］元の主張(established): VBLに3年以内入居可・有償（本学学生は無償）。認定規則第12条第1項第1号でベンチャー・ビジネス・ラボラトリー(VBL)の利用を支援メニューとして規定。VBL利用規則第2条第2号は「認定後3年を経過していないもの」を利用資格者とし、第3条で学長の許可、第5条でベンチャー・ビジネス研究課題選定・評価委員会と施設マネジメント委員会の議を経て許可、第7条で利用期間は3年以内。部屋は研究員室、共同実験室（クラス5,000のクリーンルーム、P2バイオハザード室）、シェアオフィス。学生（規則第2条第1号ロ）は経費を徴収しない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_shared_equipment', 'established', 'VBL共同実験室を月4万円で利用可・学内料金の別なし', 'VBL利用経費細則第2条の負担月額は共同実験室40,000円、研究員室20,000円（1人当たり）、シェアオフィス10,000円（消費税込）。共同実験室にはクリーンドラフトチャンバー、超純水製造システム、qPCR装置が設置され、既入居者との共同利用となる場合がある（随時募集要領3(5)）。学内共用設備の一般利用としては別途「技術サービス」があり、学外企業も設備利用が可能だが1日（8時間換算）60,000円で、認定ベンチャー向けの学内料金区分は公開情報に見当たらない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000259.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_name_logo_use', 'established', '称号は授与・学章は事前許可制（営利利用は有償契約）', '称号は認定規則第6条で称号記により授与され、第10条第3項で取消し後の使用を禁止。大学のマークは別規程で、「国立大学法人北陸先端科学技術大学院大学学章等の使用に関する規則」（平成28年4月25日北院大規則第111号）第4条第1項が学章・シンボルマークの使用に学長の事前許可を要すると定め、第6条で商品販売・役務提供その他営利目的の使用には使用契約の締結、第7条で使用料の納付を求める。第8条は形状・色彩の改変禁止と第三者への使用許諾禁止。', 'official', 'https://public1.legalcrud.com/jaist/act/110000302.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_ip_license', 'established', 'ライセンス対価を新株予約権で受領可・減免規定なし', '「国立大学法人北陸先端科学技術大学院大学における新株予約権の取得に関する規則」（令和6年12月2日規則第55号）第1条が「知的財産等のライセンス、施設の利用、その他の支援業務の対価として新株予約権を取得する」と規定し、第2条第4号で対象を認定済みの大学発ベンチャー及び申出書提出から1年以内に認定予定の企業等に限定。現金対価に代えて新株予約権で受けられる点が認定ベンチャー向けの優遇にあたる。独占的実施許諾や実施料の減免を明記した規定は、発明規則を含む公開の例規集では確認できなかった。', 'official', 'https://public1.legalcrud.com/jaist/act/110000429.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_equity_rule', 'established', '新株予約権取得規則あり（株式取得の規定なし）', '「新株予約権の取得に関する規則」（令和6年12月2日規則第55号）が科学技術・イノベーション創出の活性化に関する法律に基づく取得を規定。第3条で対象企業が学長に申し込み、学長が審査会に付議、第5条で審査会が可否と経済条件を審議、第7条で学長が決定し会計課が契約処理。姉妹規則として「新株予約権の管理に関する規則」（act/110000430.html、共創活動推進課分野の一覧で確認）がある。株式そのものの取得・保有を定める規程は例規集の当該分野に見当たらない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000429.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_gap_fund', 'established', 'TeSH GAPファンド（ステップ1で500万円）', '学長メッセージ「「Tech Startup HOKURIKU（TeSH）」がスタート」（令和6年3月19日）で、JAISTが金沢大学とともに主幹機関を務めるJST大学発新産業創出基金事業のプラットフォームTeSHを説明。参加大学・高専の教員と大学院学生を対象に、GAPファンドプログラム ステップ1で500万円を措置し、北陸全体で年15件を選定、基礎研究には使えず試作品製作・実用化データ取得・市場調査等に限ると明記。JAIST単独の学内GAPファンドは公開情報では確認できない。なおVBL随時募集要領3(4)は「研究開発に係る経費及び事業化に向けた資金は措置しない」と明記している。', 'official', 'https://www.jaist.ac.jp/about/president/20240319.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_accelerator', 'established', '共創活動推進課が窓口・TeSH（JAIST主幹）と連動', '認定申請とVBL公募の受付窓口は共創活動推進課イノベーション創出支援係（sien@ml.jaist.ac.jp）で、認定ページと随時募集要領の双方に提出先・問合せ先として明記。VBL採択課題は毎年度末にベンチャー・ビジネス研究課題選定・評価委員会でテクニカルレビュー（活動成果の発表）を受け、進捗評価を行う（随時募集要領5）。広域の伴走はJAISTが主幹機関を務めるTeSHが担い、JSTプロジェクトデータベースでは事業化推進機関としてベンチャーキャピタル等9機関、協力機関29機関が参画。JAIST単独名義のアクセラレーションプログラムやメンタリング制度の明示は見つからない。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業は許可制・COI委員会審査', '「職員の兼業に関する規則」（平成16年4月1日北院大規則第23号）第4条第1項で学長の事前許可、第2項で営利企業の役員兼業は原則不許可としつつ、技術移転事業者、研究成果活用企業、株式会社の監査役の3類型を許可対象とする。第3項は研究成果活用企業の役員兼業で本学の職務に従事できないときの休職を認める。認定規則第4条第1項第5号がこの手続の適正な履行を認定要件に接続。利益相反マネジメント規則第3条第1号は企業等からの報酬・株式保有等の経済的利益を管理対象とし、第6条の利益相反マネジメント委員会が審査・回避要請を所掌する。', 'official', 'https://public1.legalcrud.com/jaist/act/110000059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_support_fee', 'established', '認定は無償・VBL利用と設備利用は有償', '認定規則には認定手数料の定めがなく、認定・称号授与自体は無償。VBL利用経費細則第2条で共同実験室40,000円/月、研究員室20,000円/月・人、シェアオフィス10,000円/月を徴収し、規則第2条第1号の者（職員・学生・連携協力関係にある学外研究者）と、認定大学発ベンチャーの商業登記を完了した月までの利用は徴収しない。第3条第1項第3号は認定大学発ベンチャーの負担方法を原則請求書納入とする。加えて新株予約権取得規則第1条により、ライセンス・施設利用・支援業務の対価を新株予約権で受け取ることがある。', 'official', 'https://public1.legalcrud.com/jaist/act/110000259.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_certified_count', 'established', '累計8社を認定・一覧を公開', '産学官連携本部「大学発ベンチャーの認定」ページが認定企業名と認定期間を一覧で公開。株式会社AI Samurai、株式会社ライダウェイ、株式会社マイクロエミッション（いずれも2021年2月22日～2026年2月21日）、グリーンサイエンス・マテリアル株式会社、BioSeeds株式会社（2021年6月17日～2026年6月16日）、株式会社OWL研究所（2026年1月15日～）、株式会社おもしろテクノロジー（2026年2月12日～）、One Additive株式会社（2026年6月9日～）の計8社。認定規則第11条が認定状況の公表を義務づけている。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_cert_rule', 'established', '関連スタートアップ支援規程（称号の定めなし）', '「国立大学法人千葉大学関連スタートアップ支援に関する規程」（令和8年4月1日制定・施行）が第2条で「関連スタートアップ」を定義し、第5条で申請、第6条で支援の可否決定を定める。称号を付与する条項は無く、認定というより「支援決定」の制度。呼称としては公式サイトで「千葉大学関連スタートアップ」を使用。別に「大学発ベンチャー企業等から対価として取得する株式等取扱規程」第2条第4項が「大学等の研究成果等をもとに起業し、又は…共同研究を実施し、若しくは…技術移転、出資等の支援を受けている企業」と定義する。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_eligible_scope', 'established', '教職員・ポスドク・現役学生・研究成果活用型の7類型', '関連スタートアップ支援規程第2条が7号を列挙。一号=本学研究成果に基づく知的財産権や新技術を事業化する目的で新規設立、二号=創業者の技術を事業化するため設立5年以内に本学と共同研究等、三号=設立5年以内に本学から技術移転等、四号=本学の取組と深い関連があり現役の学生が関係して設立、五号=本学の教職員等（教職員・ポスドク）が設立、六号=本学が組織的に関係し深い関連があると認めたもの、七号=学長が特に必要と認めたもの。卒業生・退職者を対象とする号は無く、学生は「現役の学生」に限定。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_recognition_decider', 'unknown', null, '［自動検証で否認: 決定権の条文(支援規程第6条)がsource_url内に無い］元の主張(established): 機構長（学術研究・イノベーション戦略企画本部会議の議）。関連スタートアップ支援規程第6条「機構長は、前条の提出があったときは、学術研究・イノベーション戦略企画本部会議の議を経て、支援の可否を決定するものとする」。機構長＝学術研究・イノベーション推進機構（IMO）長。第10条で事務は研究推進部産学連携課。本部会議は同会議規程第3条により機構長・副機構長・研究担当副学長・その他機構長が必要と認める者で構成、議長は機構長（第4条）、第7条で執行部会への付託・その議決を本部会議の議決とすることが可能。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_cert_pre_registration', 'established', '可（使用開始までに要件を満たせる起業予定者も申請可）', 'IMO貸出用郵便受け使用細則（令和8年4月1日制定）第2条「スタートアップ支援規程第4条の各号に掲げる要件を全て満たしている企業等又は使用期間開始までに全て満たすことができる者…が、使用申請を行うことができる」。同細則第3条は使用希望月の初日の60日前までの申請を求める。スタートアップ・ラボの告知でもサービス対象を「本学の関連スタートアップ企業／起業予定の本学教職員・学生」とし、設立前の申請を明示的に想定。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_validity_years', 'established', '設備貸与は原則3年上限・再申請可、規程本体に期限なし', 'IMO貸出用郵便受け使用細則第5条「使用を許可された場合の使用期間は、原則として3年間を上限とする。ただし、再申請を妨げない」。関連スタートアップ支援規程には有効期間・更新の条項が無く、第7条の使用者側からの解除申出、第8条の取消事由（第2条の要件を満たさなくなった、社会的信用の失墜、企業活動の実態消滅等）まで継続する構造。第9条で年度ごと決算日から3か月以内の事業報告書・収支決算書の提出義務がある。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_head_office_registration', 'established', '可（IMO棟・BizCAFE／月額1万円税別・要許可）', '関連スタートアップ支援規程第3条第2号「前号の設備等を貸与した場合、貸与した設備が設置されている住所を関連スタートアップの登記住所とすることを認めること」。IMO貸出用郵便受け使用細則第9条「使用者は、IMO棟の所在地を商業・法人登記における住所地として登記しようとする場合には、事前に別記様式第1号により機構長に申請し、その許可を受けなければならない」、使用終了後は速やかに住所変更。第10条で使用料は月額1万円（消費税別）、1年度分一括前納、原則返還なし。設置場所はIMO棟3階およびBizCAFE（千葉大学）店。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_facility_lease', 'established', 'IMO管理設備を貸与（郵便受けは月1万円・原則3年）', '関連スタートアップ支援規程第3条第1号「学術研究・イノベーション推進機構が管理する設備等を貸与すること」。現時点で細則により具体化されている貸与設備はIMO棟3階およびBizCAFE店の貸出用郵便受けのみ（使用細則、月額1万円税別、原則3年上限）。起業用の居室としては千葉大亥鼻イノベーションプラザ（千葉市中央区亥鼻1-8-15、亥鼻キャンパス内）があるが、これは独立行政法人中小企業基盤整備機構が運営する大学連携型起業家育成施設で、IMOは入居者募集の告知を行う立場。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_shared_equipment', 'unknown', null, '［自動検証で否認: 学内外料金区分の記載がsource_url内に無い］元の主張(established): 共用機器センターを学外料金区分で有料利用可。国立大学法人千葉大学研究設備等利用規程（令和6年4月1日制定、令和8年7月1日施行）はコアファシリティの利用を定め、第4条で管理部局の所定手続による申請・許可、第5条で利用者の料金支払義務、第3条で管理責任者が算定し研究基盤管理機構ファシリティ戦略会議へ報告・学長承認を経て利用料金を公表と規定。千葉大学共用機器センターは料金区分として「学内利用料金」「学外学術利用料金」「学外一般利用料金」を公開しており、法人である関連スタートアップは学外区分に該当する。認定スタートアップへの学内料金適用など優遇区分は公開情報では確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_name_logo_use', 'established', '学章・コミュニケーションマークは学長の許可制', '「千葉大学の学章、コミュニケーションマーク及び大学カラーに関する規程」（平成25年4月1日制定、令和4年4月1日施行）第5条で使用できる者を役員・職員・学生・その他学長が使用することが適当と認めた者と限定。法人であるスタートアップは第5条第4号に該当し、第7条により別記様式1で学長へ許可願を提出し別記様式2で許可を受ける必要がある。第8条で本学の名誉毀損や許可内容と異なる使用があれば停止・取消。大学カラーはガーネット色（第4条）。称号（「千葉大学発ベンチャー」等）の付与・使用を定めた条項は関連スタートアップ支援規程にも見当たらない。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000154.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_ip_license', 'established', 'ライセンス対価を株式・新株予約権で取得可', '「大学発ベンチャー企業等から対価として取得する株式等取扱規程」（平成31年4月1日制定）第1条が、大学発ベンチャーの支援により研究開発成果の普及及び活用を促進するため、ライセンス供与等の対価として株式等を取得する場合の取扱いを定めると規定。第2条第2項で「ライセンス供与等」は知的財産権の譲渡及び提供又は実施権の設定、実施許諾を含み、同条第3項で「株式等」は株式及び新株予約権。すなわち現金以外の対価による実施許諾が制度化されている。実施料の減免や独占的実施許諾といった優遇はIMOの知財ライセンスページにも記載が無く、公開情報では確認できなかった。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000228.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_equity_rule', 'established', '株式等取扱規程あり・学長決定（委員会審査＋役員会）', '「大学発ベンチャー企業等から対価として取得する株式等取扱規程」第5条「株式等取扱委員会の審査及び役員会の議を経て、学長が決定するものとする」、第7条で取得した株式等の保有、第9条で売却も同じく委員会審査・役員会の議を経て学長が決定。規程集には別途「国立大学法人千葉大学株式等取扱委員会規程」も存在。加えて「国立大学法人千葉大学における出資に関する規程」（令和6年7月1日制定）が産業競争力強化法に基づく認定特定研究成果活用支援事業者への出資を定める。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000228.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: GTIE言及が関連3URLどこにも無い］元の主張(established): なのはなコンペ（学内GAP・最大100万円）とGTIE。千葉大スタートアップ・ラボの学内公募告知によれば「なのはなコンペ」は千葉大学独自のGAPファンドプログラムで、支援額は単年度最大100万円、採択3件程度、実証期間10月〜3月。2025年度より千葉大学アントレプレナーシップセンターが主催（前年度までIMOスタートアップ・ラボ主催）。加えて外部プラットフォームのGTIE（東京大学・東京科学大学・早稲田大学が主幹）GAPファンド エクスプロールコース（3年、最大6000万円）に本学研究者が応募・採択されている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 「無料」の明記が2箇所とも無い］元の主張(established): 無料の起業相談窓口＋GTIE・千葉市C-CAPと連携。千葉大スタートアップ・ラボの起業支援ページに「スタートアップなんでも相談窓口」を掲載し、千葉大学の学生・研究者のスタートアップに関する相談をいつでも無料で受け付け、場所はIMO棟1の3階オープンスペースまたはIMO棟2の1階BiZCAFEと明記。伴走支援としてGTIE、千葉市アクセラレーションプログラム（C-CAP、5か月間の個別メンタリングと課題解決講座）、NEDO、JETRO、INPIT（産学連携・スタートアップアドバイザー派遣）、Research Studioと連携。ビジネス＆テクノロジーアドバイザーおよびEIRを配置。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_coi_sidejob', 'established', '役員兼業は学長許可制・COI委員会あり', '国立大学法人千葉大学職員兼業規程（平成16年4月1日制定、令和8年4月1日最終改正）は営利企業の兼業を類型化し、第3条で技術移転兼業、第7条で研究成果活用兼業、第11条で監査役等兼業について、いずれも大学教員が役員等を兼ねる場合に学長の許可を要すると規定。許可は期限付き（第4条第2項等）、第5条・第9条・第13条で報酬額を含む年1回の報告義務、第6条・第14条で終了後2年間の利害関係業務の制限。関連スタートアップ支援規程第4条第4号は、本学教職員等が設立したものについて兼業規程その他関係規程等の手続・許可が適正になされていることを支援の要件とする。利益相反マネジメントポリシーおよび利益相反委員会規程も規程集に存在。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 「相談無料」がsource_url外・未確認］元の主張(established): 相談は無料、設備貸与と登記住所は有償（月1万円）。起業相談は千葉大スタートアップ・ラボの「スタートアップなんでも相談窓口」で無料。設備貸与および登記住所の提供はIMO貸出用郵便受け使用細則第10条により月額1万円（消費税及び地方消費税を別途加算）の使用料で、1年度分を一括前納、納付済使用料は原則返還しない（災害等・取消・変更許可の場合は月割返還）。共用機器の利用は研究設備等利用規程第5条により公表された利用料金を支払う有償利用。関連スタートアップ支援規程本体には支援の有償無償を定める条項は無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_certified_count', 'established', '関連スタートアップ一覧を公開・74社／団体', '千葉大スタートアップ・ラボの「千葉大学関連スタートアップ一覧」ページに企業名・URL・事業概要をアコーディオン形式で掲載。2026年9月5日取得時点でエントリ数は74件（株式会社・合同会社のほか一般社団法人・NPO法人・特定非営利活動法人を含む）。掲載企業には千葉エコ・エネルギー、ACSL、Liberaware、Craif、HarvestX、Smart119、CULTA等。掲載基準や認定手続の説明文はページ上に記載されておらず、支援決定を受けた社数とは一致しない可能性がある。', 'official', 'https://startup-lab.chiba-u.jp/startup/chiba-university-startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_cert_rule', 'established', '名古屋大学発ベンチャー称号授与規程による称号授与制度', '名古屋大学発ベンチャー称号授与規程（平成28年7月19日制定、直近改正令和7年11月20日）第1条で「本学の研究成果又は人的資源を活用して起業されたベンチャー企業に対して称号を授与」と規定。第2条で称号は「名古屋大学発ベンチャー」、現在の学生が設立者又は深く関与した場合は「名古屋大学発学生ベンチャー」と定める。公式ページでは2016年7月制定の制度と記載。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_eligible_scope', 'established', '知財・研究成果活用型と教職員・学生関与型（退職卒業後1年以内まで）', '規程第3条で、(1)本学又は役員・職員・学生が所有する知的財産権の活用、(2)本学での研究成果の活用、(3)本学の役員・職員・学生（過去の在籍者を含む）が設立者又は設立に深く関与、のいずれかに該当する企業と規定。称号申請ページでは(3)の具体的要件として、在職6年以上の役員・職員、在職6年以上で退職後1年以内に設立した元役員・職員、在学2年以上の学生、在学2年以上で卒業後1年以内に設立した元学生を明記。', 'official', 'https://www.aip.nagoya-u.ac.jp/venture/nu-venture-application', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_recognition_decider', 'established', '総長（名古屋大学発ベンチャー審査委員会の審査を経て決定）', '規程第5条で、申請者が申請書により総長に申請し、総長が名古屋大学発ベンチャー審査委員会に付託、審査委員会の審査報告を受けて総長が認定又は不認定を決定し通知すると規定。第4条で同審査委員会を設置し「詳細は別に定める」とする。第13条で事務は学術研究・産学官連携推進本部イノベーション・アントレプレナーシップ推進室が処理。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_cert_pre_registration', 'not_started', '不可（登記簿謄本の提出が必須）', '称号申請ページの提出書類が、申請書（様式1）、登記簿謄本（発行から3月以内のもの）、定款の写し、その他参考資料と定められており、設立登記済みでなければ申請できない。規程第3条も対象を「新たな技術又はビジネス手法を基に起業した企業」としている。授与日も9月〜2月申請は4月1日、3月〜8月申請は10月1日と固定で、設立予定段階での認定予定通知や条件付認定の記載はない。', 'official', 'https://www.aip.nagoya-u.ac.jp/venture/nu-venture-application', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_validity_years', 'established', '5年・更新可（学生ベンチャーは在学期間まで）', '規程第6条で、称号は称号記の交付により授与し、名古屋大学発ベンチャーの授与期間は5年で更新可能と規定。名古屋大学発学生ベンチャーは授与日から5年、ただし設立に関与した学生の在学期間までとし、退学等の場合は称号を取り消す。更新は総長に申請し第5条の手続に準ずる。第8条で毎年6月末日までに前年度の活動内容報告書の提出義務あり。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_head_office_registration', 'established', '可（インキュベーション施設の長期貸付時に商業登記地を認可）', '規程第12条の支援メニュー第2号で、施設を長期貸付する場合に当該施設住所を商業登記地とすることを認める（退去時は変更手続の書面提出が必須）と規定。第3号で郵便物受取の便宜も定める。名古屋大学インキュベーション施設の公式サイトでも「すべての部屋で登記・住所と郵便ポストが利用できます」と明記されている。', 'official', 'https://incubation.aip.nagoya-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_facility_lease', 'established', 'インキュベーション施設プロジェクト開発室・有償・最長5年', '名古屋大学インキュベーション施設規程第1条で産学連携推進とシーズを活かしたベンチャー育成の全学共用施設として設置、第3条でプロジェクト開発室を置き、第5条で使用資格を「名古屋大学発ベンチャー又は名古屋大学発学生ベンチャーの称号を授与された企業で設立後10年以内のものに所属する者」と規定。プロジェクト開発室使用細則第4条で使用期間は2年以内、2年ごと更新で5年を限度。公式サイトの月額例はSpace A（24㎡〜）32,970円〜、C（88㎡〜）109,770円〜。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110000283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_shared_equipment', 'established', '全学技術センターの技術支援を企業区分別料金で利用（優遇なし）', '名古屋大学全学技術センター技術支援業務等に関する取扱規程第3条第2項で機構外の機関に所属する者も業務依頼が可能。第5条と別表1〜5で料金を依頼者区分別に定め、機構の組織は技術料500円/時、他大学・公設試2,600円/時、収益事業を行わない法人3,250円/時、中小企業等（資本金1億円未満）3,900円/時、大企業等6,500円/時。大学発ベンチャー向けの区分や減免は設けられておらず、称号授与規程第12条の支援メニューにも機器利用の記載はない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110011370.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_name_logo_use', 'established', '称号・ロゴ使用可（品質保証利用は禁止、広告利用は事前届出）', '規程第12条第4号で、称号を授与された企業である旨の表示に限りロゴの使用権を付与すると規定。第7条で、称号により製品・サービスの内容や品質を保証してはならず、広告・宣伝に使用する場合は事前に総長へ届け出ること、不適当と認めるときは総長が審査委員会の議を経て使用を停止できると定める。第9条の取消後は称号授与の事実を事業に使用できない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_ip_license', 'established', '知財実施料の現金支払を免除・軽減し株式／新株予約権で代替可', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則（令和2年度機構細則第61号）第2条第1項で、科学技術・イノベーション創出の活性化に関する法律第34条の4の成果活用事業者が、(1)事業の有用性が高い、(2)現金支払の免除・軽減が経営の加速に特に必要、の両方を満たす場合に現金支払を免除又は軽減できると規定。同条第2項で現金に代えて発行価額が無償の株式又は新株予約権を取得できるとする。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010858.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_equity_rule', 'unknown', null, '［自動検証で否認: 第4条は不行使を明記せず別細則へ委任］元の主張(established): 株式・新株予約権を取得可（発行済総数の半数未満・議決権不行使）。上記細則第2条第2項で株式・新株予約権の取得を認め、第3条で取得株式数は発行済株式総数の半数未満（既保有分を含む算定式あり）に制限。第4条で議決権は行使せず、第5条で当該企業との共同研究や物品購入契約における利益相反防止措置を義務づけ、第7条で売却益等は知的財産等に係る収入配分細則により分配。東海国立大学機構株式等管理事務取扱細則（令和2年度機構細則第58号）が出納保管・売却・新株予約権の行使と信託を定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_gap_fund', 'established', 'Tongali GAPファンドプログラム（JST大学発新産業創出基金）', '名古屋大学学術研究・産学官連携推進本部のGAPファンドプログラムのページで、JSTの大学発新産業創出基金事業「スタートアップ・エコシステム共創プログラム」を原資とするTongali GAPファンドプログラムを実施と記載。ステップ1とステップ2の2段階で公募し、令和6年度から令和8年度まで継続。名古屋大学が主幹機関で、JST中間評価で最高ランクの評価を得たとする。学内独自財源による起業支援金の記載は確認できなかった。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.aip.nagoya-u.ac.jp/venture-support/gap-fund', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_accelerator', 'established', 'スタートアップ統括室・イノベーション推進室とTongaliによる伴走', '東海国立大学機構スタートアップ統括室規程（令和7年3月19日機構規程第71号、令和7年4月1日施行）第1条で、大学との連携の下「教育及び研究から起業，成長及び国際展開までの一貫したスタートアップの支援」を行う組織として設置。第7条で5つの部門を置く。称号授与規程第13条の事務担当は学術研究・産学官連携推進本部イノベーション・アントレプレナーシップ推進室。GAPファンド等のプログラムは名古屋大学が主幹機関を務めるTongaliが運営。［検証エージェントは出典を開けず未照合］', 'official', 'https://public1.legalcrud.com/thers_ac/act/110011592.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業は許可制、利益相反マネジメント規程で管理', '東海国立大学機構役員及び職員の兼業・兼職に関する規程（令和2年度機構規程第24号）第1条第2項で、職務の公平中立な執行、職務への支障、機構の信用確保の3原則に適合するときに許可できると規定。第5条で兼業類型として「研究成果活用企業の役員等を兼ねる場合」「国立大学法人等出資企業の役員等を兼ねる場合」「監査役及び社外取締役を兼ねる場合」を区分。第2条で許可権限を機構長から各大学長に委任。利益相反は東海国立大学機構利益相反マネジメント規程と名古屋大学利益相反マネジメント専門委員会細則で管理。［検証エージェントは出典を開けず未照合］', 'official', 'https://public1.legalcrud.com/thers_ac/act/110011018.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_support_fee', 'established', '施設・技術支援は有償、新株予約権割当で使用料免除可', 'インキュベーション施設規程第10条・第11条で光熱水料とプロジェクト開発室負担金の負担義務を規定。使用細則第7条で光熱水料は実費相当額、第8条で負担金は東海国立大学機構固定資産貸付基準第8条の貸付料に面積を乗じた月額とする。同条第3項で「新株予約権を本学に割り当てることにより，貸付料の一部又は全部を免除する」と定める。全学技術センターの技術支援も有償。称号授与そのものに申請料の定めは確認できなかった。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_certified_count', 'unknown', null, '［自動検証で否認: 学生ベンチャーは現在3社、主張は2社］元の主張(established): 88社＋学生ベンチャー2社・一覧公開。名古屋大学発ベンチャー称号授与制度のページに、2026年8月25日現在で名古屋大学発ベンチャー称号88社、名古屋大学発学生ベンチャー称号2社と記載。東海国立大学機構スタートアップ支援総合サイトの大学発ベンチャーページで、認定企業をICT/AI、ハードウェア、モビリティ、ロボティクス、医療関連などの分野別に企業名・事業内容・自社サイトリンク付きで一覧公開している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_cert_rule', 'unknown', null, '産官学連携サイト(MRCS)の産官学連携メニュー(受託・共同研究/奨学寄附金/知的財産/LED共同研究センター/NanoTerasu/分析センター/Q&A)、知的財産ページ、社会連携センターPLATのアントレプレナーシップ教育・EXPLORER・DRAFT・M-STUDIO・shakeの各ページを読んだが、大学発ベンチャーの認定制度・称号授与制度に相当する記載は見当たらない。知的財産ポリシー(令和7年4月1日施行)は「スタートアップ」への優遇を定めるが、認定要件・審査・称号の条項は置いていない。', 'unknown', 'https://plat.meijo-u.ac.jp/entrepreneurship/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_eligible_scope', 'unknown', null, '認定制度自体が公開情報で確認できないため、認定対象の要件も不明。参考として、M-STUDIO利用ルール(PDF全文確認)は利用可能者を「①本学の学生/教職員 ②Tongaliプロジェクトによるプログラム参加者 ③企業・自治体・NPOの方で本学とプロジェクトにて連携する方」と限定し、アクセラレーションプログラムDRAFTは「U35」を対象としている。', 'unknown', 'https://plat.meijo-u.ac.jp/assets/documents/%E5%88%A9%E7%94%A8%E6%A1%88%E5%86%85M-STUDIO.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_recognition_decider', 'unknown', null, '認定制度が確認できず、審査主体・決裁者を定めた公開規程も無い。関連する窓口として、知的財産ポリシー5.(1)は学術研究支援センターに技術移転・知財管理担当者を置くと規定し、起業支援側の窓口はM-STUDIO利用ルール記載の社会連携センター事務室(天白キャンパスTOWER75 11階)。名城大学は規程集を一般公開しておらず、公開されているのは学則・寄附行為・ガバナンス・コードのみ。', 'unknown', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_cert_pre_registration', 'unknown', null, '認定制度が確認できないため、設立登記前の申請・認定予定通知・条件付認定の扱いを示す公開資料も存在しない。PLATのEXPLORER・DRAFTは法人設立の有無を問わないアイデア段階からの支援だが、法人の認定申請時期を定めた文書ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_validity_years', 'unknown', null, '認定制度が確認できないため、有効期間・更新の定めも公開情報に無い。参考として、期間が定められている支援はDRAFTのメンター伴走プロジェクト3か月間(shakeプロジェクトルーム無料利用・メンタリング・PLATネットワークを3か月提供)のみ。', 'unknown', 'https://plat.meijo-u.ac.jp/draft', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_head_office_registration', 'unknown', null, '企業が入居・賃借するインキュベーション施設が公開情報に無く、大学住所での本店登記を認める記載も見つからない。むしろM-STUDIO利用ルールは制限事項に「２．営利を目的に利用するとき」を挙げ、「販売目的での施設利用は禁止です」と明記しており、常設の営利拠点としての利用は想定されていない。ただし商業登記そのものの可否を述べた文書は確認できていない。', 'unknown', 'https://plat.meijo-u.ac.jp/assets/documents/%E5%88%A9%E7%94%A8%E6%A1%88%E5%86%85M-STUDIO.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: value中のshake記述がsource(M-STUDIO PDF)本文に無い］元の主張(established): M-STUDIO・shake PJルームを無償提供（入居制度なし）。天白キャンパスTOWER75 5階の起業活動拠点ものづくりスペースM-STUDIOは、利用ルールで「スペースや設備利用は無料」、利用時間12:00〜20:00(月〜金)、拠点利用は原則予約不要と規定。ナゴヤドーム前キャンパス西館2階の社会連携ゾーンshakeにはプロジェクトルーム3室があり、アクセラレーションプログラムDRAFT採択者へ3か月間無料提供される。企業が賃借するインキュベーション施設・レンタルラボの公開情報は無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_shared_equipment', 'established', 'M-STUDIOのFab機器を無料利用（材料費は自己負担）', 'M-STUDIO利用ルールは、3Dプリンター(熱溶解式RAISE3D、光造形式Form3)、レーザーカッター、UVプリンター、3Dスキャナー等のFab機器を事前申込制・職員滞在時のみ利用可とし、機器によっては事前講習とライセンス取得が必要と規定。料金は「スペースや設備利用は無料。Fab機器等の材料費については活動目的により異なる」。利用可能者に「本学とプロジェクトにて連携する企業」が含まれる。研究用共用機器(分析センター)は学外・ベンチャー利用の料金区分を示す公開ページが無い。', 'official', 'https://plat.meijo-u.ac.jp/assets/documents/%E5%88%A9%E7%94%A8%E6%A1%88%E5%86%85M-STUDIO.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_name_logo_use', 'established', 'ロゴは使用申請書の提出と許可が必要（称号制度は不明）', '大学公式の「ロゴマーク・公式マスコット」ページに「卒業生・外部団体の使用」の区分があり、「いかなる使用の場合も事前にロゴマーク使用申請書の提出と許可が必要になります」と明記。申請フォームで受付後、内容確認を経て使用可の連絡とロゴデータが渡される。イベントの後援・協賛・共催での使用は別途「後援名義使用申請」が必要。大学発ベンチャーの称号使用については制度自体が確認できない。', 'official', 'https://www.meijo-u.ac.jp/about/outline/logo.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_ip_license', 'established', 'スタートアップへ優先許諾・独占的通常実施権に配慮', '名城大学知的財産ポリシー(平成16年6月11日制定、令和7年4月1日施行)3.(2)「スタートアップへの知的財産のライセンス」に、本学知財を活用して起業したスタートアップへ「優先的に知的財産権の実施許諾や権利の移転等を行うことを原則とする」、「独占的通常実施権の許諾など、スタートアップがこれを専有的に実施できることに配慮する」と明記。産官学連携Q&Aも「非独占の通常実施権のほか、ご相談により独占的な実施権の付与も可能」「権利譲渡も相談により可能な場合がある」とする。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_equity_rule', 'established', '知財対価として新株予約権・株式の受領を選択肢に明記', '知的財産ポリシー3.(2)に「スタートアップの多くは、手元資金が乏しいことに配慮して、知的財産権の実施許諾や権利の移転等の対価として、新株予約権や株式を受け取ることを選択肢の一つとする」と規定。ただし取得後の評価・保有・処分を定める出資規程や株式等取扱規程は公開されていない。名城大学は規程集を一般公開しておらず、大学サイトで公開されているのは学則・寄附行為・ガバナンス・コード等に限られる。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_gap_fund', 'established', 'EXPLORERで5チーム程度×10万円程度の活動資金', '社会連携センターPLATの起業家育成プログラムEXPLORERのページに、プロトタイプ作成費や交通費に充てる活動資金として「5チーム程度×10万程度」の費用提供が明記されている。研究シーズ向けの学内GAPファンドやPOC資金の制度は確認できない。名城大学は東海地区のTongaliプロジェクトに実施機関(アントレプレナーシップ教育・起業支援の両区分)として掲載されており、GAPファンドを含むスタートアップ・エコシステム共創プログラムはTongali側のメニュー。', 'official', 'https://plat.meijo-u.ac.jp/entrepreneurship/explorer/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_accelerator', 'established', 'アクセラレーションプログラムDRAFT（U35・3か月伴走）', 'PLATのDRAFTはU35を対象に、メンター(will応援隊)・フォロワー・NEEDとの出会いの場を提供し、マッチング成立後に3か月間のメンター伴走プロジェクトを実施、3か月後に成果発表の場を設ける。提供内容は「shake PJルーム無料利用」「メンタリング」「PLATネットワーク」。EXPLORERは起業相談窓口(起業マニュアル・学外ネットワーク提供)、専門家による個別メンタリング、月1回の壁打ちピッチ会を提供。Tongaliプロジェクトにも参画。', 'official', 'https://plat.meijo-u.ac.jp/draft', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_coi_sidejob', 'established', '利益相反自己申告を利益相反マネジメント委員会が審査', '産官学連携サイトの利益相反ページに、名城大学利益相反マネジメントポリシーおよび名城大学利益相反マネジメント要項、厚生労働科学研究における利益相反(COI)の管理に関する指針が掲げられ、対象者(本学の教職員および利益相反マネジメント委員会が認めた者)が利益相反自己申告書を提出し、利益相反マネジメント委員会が審査する運用と記載。教職員の役員兼業許可や株式保有の可否を定めた兼業規程は一般公開されておらず(様式集は学内限定)、大学発ベンチャー役員兼業との接続は確認できない。', 'official', 'https://sangaku.meijo-u.ac.jp/proper/self_report/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 「メンタリング無償」がsource(M-STUDIO PDF)に無い］元の主張(established): 施設・メンタリングは無償、Fab機器の材料費は自己負担。M-STUDIO利用ルールに「スペースや設備利用は無料。Fab機器等の材料費については活動目的により異なる」と明記。DRAFTはshakeプロジェクトルーム無料利用とメンタリングを3か月間提供し、EXPLORERは逆に活動資金を支給する側。一方で知的財産の実施許諾は産官学連携Q&Aのとおり「通常、一時金及びランニングロイヤリティをいただきます」と有償。認定制度が確認できないため、認定後の支援対価という区分自体が公開情報に無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_certified_count', 'unknown', null, '認定制度・称号制度が確認できず、認定ベンチャー一覧に相当するページも見つからない。産官学連携サイトには共同研究実績、研究シーズ集、科研費・府省庁の採択実績は公開されているが、本学発ベンチャーの社数を機関自身が公開しているページは無い。文科省・経産省の機関別件数は本調査では使用しない方針のため unknown とする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_cert_rule', 'established', '「国立がん研究センター発ベンチャー」認定制度', '研究支援センター産学連携・知財戦略課の「国立がん研究センター発ベンチャー」ページに、役職員が創出した知的財産権や研究成果等を活用するために設立されたベンチャー企業からの申請を受け「一定期間認定しています」と明記。認定企業であることを示す認定ロゴマークも掲載。2021年3月11日プレスリリースの用語解説＊3では「国立がん研究センターベンチャー認定制度」と呼称。認定規程そのものは非公開で、規程名・条文番号は公開情報にない。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_eligible_scope', 'established', 'センター役職員の知財・研究成果を活用する設立済み企業', '認定ページに「センターの役職員が創出した知的財産権や研究成果等を活用するために設立されたベンチャー企業からの申請を受け」と記載。大学ではないため学生・卒業生の区分はなく、対象は役職員（教職員に相当）の研究成果活用型。2021年3月11日プレスリリース用語解説＊4で、対象分野は「医薬品、医療機器及び再生医療等製品、MedTechなどのベンチャー」と説明。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_recognition_decider', 'established', 'ベンチャー認定委員会に諮問、事務局は産学連携・知財戦略課', '2021年3月11日プレスリリース用語解説＊3に「ベンチャー認定委員会に諮問の上、研究成果の活用が期待できるベンチャーと判断された場合『国立がん研究センター発ベンチャー』と認定される」と明記。産学連携・知財戦略課ページには、同課が共同研究審査委員会・職務発明審査委員会と並んで「ベンチャー認定審査委員会の事務局」を担当し「ベンチャー認定申請窓口」であると記載。最終決裁者（理事長かどうか）は公開情報に記載なし。', 'official', 'https://www.ncc.go.jp/jp/information/pr_release/2021/0311/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_cert_pre_registration', 'unknown', null, '認定ページは「活用するために設立されたベンチャー企業からの申請を受け」と設立済み企業からの申請を前提にした書き方だが、設立登記前の申請可否・認定予定通知・条件付認定に触れた記述はなく、可否を断定できない。なお別事業のNCC SAP（S0/S1）とNCC VIPは起業前のチームを対象と明記しているが、これらは認定制度とは別枠の支援プログラム。', 'unknown', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_validity_years', 'established', '一定期間の認定、期間経過や成長で卒業（年数非公表）', '認定ページに「一定期間認定しています」「設立または認定から一定期間が経過したベンチャー企業や、十分な成長を遂げた企業については、センター発ベンチャーとしての認定を卒業することとなります」と明記。実例としてノイルイミューン・バイオテックが2025年7月2日、朝日サージカルロボティクス（旧A-Traction）が2026年4月9日に卒業と公表。具体的な年数と更新可否は非公開。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_head_office_registration', 'unknown', null, 'センターの土地・建物の住所を会社の本店所在地として登記できるかに触れた公開情報は見つからなかった。認定制度ページ、NCC SAP（大学発医療系スタートアップ支援拠点）の募集要項とよくあるご質問、NCC VIP公募要領、産学連携・知財戦略課Q&Aのいずれにも商業登記の受け入れに関する記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 引用元FAQは「準備中」のみで該当文なし］元の主張(not_started): 起業チーム向けの専用ラボ・貸室なし。NCC SAPのよくあるご質問に「現時点ではこのプログラム専用のラボ設備はご用意できていません。使用を希望される場合には、NCC内のラボと交渉することになります」と明記。施設・実験機器の利用は共同研究契約を結ぶ場合に実施ラボと個別相談する形で、費用も共同研究締結時に決定する。認定ベンチャー向けのインキュベーション施設や貸室制度は公開情報に存在しない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_shared_equipment', 'unknown', null, '［自動検証で否認: 費用個別決定の根拠FAQが「準備中」で空］元の主張(established): 研究設備の利用可、費用は共同研究契約で個別決定。認定ページに、認定されることで「研究設備の利用、知的財産権の実施許諾、シーズ開発支援等を受けることが可能」と明記（2015年10月21日の先端医療開発センターNEWSも同旨）。NCC SAPのよくあるご質問では「共同研究の内容によっては施設・実験機器の利用は可能ですが、実際にそれを実施するラボとの相談となります。費用についても、共同研究を締結する際に実施内容に従って決定する」と説明。学内料金・外部料金の区分表は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_name_logo_use', 'established', '称号と認定ロゴマークの使用可', '認定ページに「国立がん研究センター発ベンチャーとして認定された企業であることを示す、認定ロゴマークを作成しました」と記載し、認定ロゴマークを掲示。称号「国立がん研究センター発ベンチャー」は認定企業一覧で使われている。使用申請の手続、使用条件、卒業後の取扱いは公開情報にない。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_ip_license', 'established', '知的財産権の実施許諾を受けられる', '認定ページに、認定の効果として「知的財産権の実施許諾」を明記。産学連携・知財戦略課Q&Aでは、共同研究から生じた発明は共同出願とし「本センターが研究機関であり原則として商業化を実施しない事を踏まえ、共同研究相手先に優先的な使用権があることを認めた上で、実施に係る取り決めを行う」と説明。職務発明は職務発明委員会の審査を経る（職務発明規程）。認定ベンチャー向けの独占許諾・対価減免・株式対価の条件は非公開。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_equity_rule', 'established', '科技イノベ活性化法34条の5で新株予約権・株式を保有', '組織COI情報公開ページに「NCCは、ARC Therapies株式会社を法人発ベンチャーとして認定しており、科学技術・イノベーション創出の活性化に関する法律第34条の5第1項及び第2項を根拠として、同社の発行した新株予約権、株式等を取得・保有する」（2024年9月28日開始）と明記。出資行為は「現在、企業に対して出資行為を行っておりません」。取得・保有の内部規程名は非公開。NCC SAP募集要項9項では、支援先からの成功報酬（新株予約権を想定）の導入を検討中とする。', 'official', 'https://www.ncc.go.jp/jp/about/disclosere/COI.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_gap_fund', 'established', 'NCC SAPで年1,000万〜1億5,000万円の研究費', '令和6年9月1日にAMED「大学発医療系スタートアップ支援拠点」に採択され、NCC Seed Acceleration Program（NCC SAP）を運営。令和7年度第2回公募の募集要項6項で、起業前のS0は最長2年・最大1,000万円／年度、S1は原則2年（最長3年）・最大3,000万円／年度、起業直後のS2は最長2年・最大1億5,000万円／年度（いずれも間接経費は直接経費の10％以内で別）。採択者の所属機関と委託研究開発契約を結び、センターから研究費を配分する。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/libs/files/startup_r7_v2_requirements_260121.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 有料の相談窓口の記載がPDFに無い］元の主張(established): NCC SAPの伴走支援とNCC VIP、有料の相談窓口。NCC SAP募集要項7項に、採択チームごとにプロジェクトマネージャーが月1回の進捗ミーティング、月2回・6〜7か月の教育プログラム、JETROと米国Texas Medical CenterのJ-ACTプログラムによる海外展開支援を行うと記載。ほかにUTEC・Beyond Next Venturesと組むNCC Venture Incubation Program（2021年度開始、共同研究契約締結から原則1年、起業前も応募可）、中央病院の医療系ベンチャー等相談窓口を運用。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: COI管理室の記載が該当ページに無い］元の主張(established): 研究成果活用企業への役員兼業可、COI管理室が管理。「国立研究開発法人国立がん研究センター職員の役員兼業状況」ページで令和7年度の研究成果活用企業役員兼業を公表（ARC Therapies取締役2名ほか、氏名・所属・従事日数・報酬区分まで開示）。研究者個人の利益相反はCOI管理室（2017年10月設置）と利益相反委員会が管理し、組織としての利益相反は「国立研究開発法人国立がん研究センター組織COI管理規程」に基づき管理・公開。兼業規程本体は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_support_fee', 'established', '研究費は配分、伴走支援等の対価は料金表で徴収予定', 'NCC SAP募集要項6項に「支援対価（教育プログラム・伴走支援その他）についても拠点が定める料金表に基づき徴収を予定しています。徴収を開始する時期、料金表については採択後にご案内」と明記。中央病院の医療系ベンチャー等相談は本相談1回1時間10万円、超過は1万3千円の追加、納入後の返金不可（事前相談は無料）。認定そのものの手数料に関する記載は公開情報にない。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/libs/files/startup_r7_v2_requirements_260121.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_certified_count', 'established', '認定5社・卒業2社を一覧公開', '認定ページに認定企業一覧として凜研究所、Jmees、Surg storage、ARC Therapies（旧Sustainable Cell Therapeutics）、DELISPECTの5社、卒業一覧としてノイルイミューン・バイオテック（2025年7月2日卒業）、朝日サージカルロボティクス（旧A-Traction、2026年4月9日卒業）の2社を掲載。各社の事業内容と企業サイトへのリンクも公開されている。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_cert_rule', 'established', '「国環研ベンチャー」認定制度（ベンチャー支援規程）', '国立研究開発法人国立環境研究所ベンチャー支援規程（令和4年11月1日制定・施行、令4規程第1号）第2条が「国環研ベンチャー」を定義。研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用するベンチャー企業であって、同規程に基づき国環研ベンチャーと称号することが認められたものをいう。第1条は目的を「研究成果の実用化を促進するため」の適正な支援と定める。産学連携サイト「国環研ベンチャー」ページも同一の定義を掲載。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_eligible_scope', 'established', '研究成果・知財を活用する企業（創業者の身分要件なし）', '第2条で対象は「研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用するベンチャー企業」。第5条の認定要件は、①事業が当該研究成果を活用する事業であること、②創業者又は当該事業について責任を有する者が必要十分な知識を有すること、③経営戦略が適切で事業性が見込めること、④研究所の信用を傷つけないこと、⑤その他不適当でないこと、の5点。役職員・退職者・学生といった個人の身分要件は置いていない。役職員が活動する場合は第6条4項で兼業扱いとなる。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_recognition_decider', 'established', '理事長（ベンチャー審査委員会の答申に基づき決定）', '第4条。希望者は「国立研究開発法人国立環境研究所ベンチャー認定申請書」に事業内容・使用する知的財産等に関する書類を添えて理事長に提出。理事長が申請の審査をベンチャー審査委員会に諮問し、同委員会が審査と必要に応じた面接を行って理事長に答申、理事長が可否を決定して希望者へ通知する。第3条で同委員会は認定・取消し・支援内容等を審議する常設機関（運営等は別に定める）。主管部署は連携推進部研究連携・支援室（第12条）。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_cert_pre_registration', 'unknown', null, '規程本文にも産学連携サイトにも登記前申請の可否は明記されていない。第4条1項の添付書類は「事業内容、使用する知的財産等に関する書類」で登記事項証明書の要求はない一方、第2条は対象を「ベンチャー企業」と定義しており法人の存在を前提と読める。第6条3項は「研究所の役職員が国環研ベンチャーの活動を準備する段階において」第1項5号（会社設立支援等）を講じ、同1号（場所）・3号（設備）の措置に必要な検討を行えると定めるが、これは準備段階の支援であって認定自体の前倒しではない。', 'unknown', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_validity_years', 'established', '5年（申請によりさらに5年延長可）', '第5条柱書。「その有効期間は認定の日から５年間とする。なお、有効期間については、申請に基づく延長が可能なものとし、その有効期間はさらに５年とする」。延長は第4条の認定手続と同じ経路（認定申請書を理事長に提出→ベンチャー審査委員会へ諮問→答申→理事長決定）で扱われる。第9条で理事長による認定取消し、第10条で国環研ベンチャー側からの認定解除の申出が定められている。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_head_office_registration', 'established', '可（無償貸与の事務室・研究室の住所を登記可）', '第6条1項2号。「取扱細則第２８条又は第２９条の定めるところにより、前号により貸与した事務室又は研究室の住所を国環研ベンチャーの登記の住所とすることを認めること」。前号（1号）で無償貸与された研究所内の事務室・研究室が対象で、賃料の定めはなく無償貸与された場所をそのまま登記住所にできる。根拠として引用される固定資産等管理事務取扱細則（令2細則第1号）本体は情報公開の規程集に掲載がなく、細則の条文自体は未確認。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_facility_lease', 'established', '所内に事務室・研究室を確保し無償貸与', '第6条1項1号。「事務室又は研究室としての場所を研究所内に確保し、国立研究開発法人国立環境研究所固定資産等管理事務取扱細則（令２細則第１号）第２８条の定めるところにより、無償で貸与すること」。同項柱書に「研究所の業務に支障のない範囲で」の制約があり、2項で支援措置の内容・条件について契約を締結し契約書を取り交わす。貸与期間の上限は規程上定めがない。専用のインキュベーション施設・入居要項は公開情報上確認できない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_shared_equipment', 'established', '研究設備等を無償貸与', '第6条1項3号「研究設備等を無償で貸与すること」。学内料金・外部料金といった料金区分ではなく無償貸与として規定されている。同項柱書の「研究所の業務に支障のない範囲で」が前提で、2項により具体的な内容・条件は国環研ベンチャーとの契約で定める。3項では役職員の準備段階においても同3号の措置に必要な検討を行うことができるとされる。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 称号使用可の根拠がkt_logo.pdf本文に無い］元の主張(established): 称号は使用可、ロゴは別規程で理事長の許可制。称号はベンチャー支援規程第6条1項6号「国環研ベンチャーの称号を使用すること」。認定取消し後は称号使用の事実を利用した事業を禁止（第9条2項）。ロゴマークは別途、国立研究開発法人国立環境研究所ロゴマーク使用規程（平23規程第2号、令和8年4月1日一部改正）第5条2項により、職員等以外の者は研究所のPR又は関係機関としての紹介を主目的とする場合等に限られ営利目的は不可、同条3項で使用10日前までにロゴマーク使用許可申請書を理事長に提出し許可を得る必要がある。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_ip_license', 'established', '独占的・一部独占的許諾、実施料の無償化や猶予・免除', 'ベンチャー支援規程第6条1項4号「国環研ベンチャーが研究所の所有する知的財産を利用する場合は、独占的又は一部独占的な利用の許諾、実施料の無償化又は支払いの一定期間の猶予若しくは免除等を認めること」。一般規律である知的財産取扱規程（平13規程第34号、令和8年3月30日改正）第32条は独占的・優先的許諾に一般公示と異議申立ての機会を義務づけ、第35条の特例列挙（共有者、共同研究相手、委託者、創出者の転出先）に国環研ベンチャーは含まれていない。株式を対価とする許諾の定めはない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_equity_rule', 'not_started', '取得規程なし（支援は第6条の6項目に限定列挙）', 'ベンチャー支援規程第6条1項は支援を1号〜6号に限定列挙し、株式・新株予約権の取得は含まれない。知的財産取扱規程には「株式」「新株予約権」の語がなく株式対価ライセンスの定めもない。情報公開の規程集（業務全般〜その他の全分類）にも出資・株式取扱いに関する規程は掲載されていない。ただし利益相反マネジメント実施規程第2条3号ヘが「出資及び出資により取得した株式の処分」を産学官連携活動として定義しており、出資自体が制度上排除されているとまでは確認できない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_gap_fund', 'not_started', '資金給付制度なし（資金調達の支援のみ）', 'ベンチャー支援規程第6条1項5号は「会社設立支援、事業計画策定支援、資金調達支援、研究開発支援、販売販路開拓支援、専門家の紹介及び会社経営に関するセミナーについての情報の提供等」であり、研究所自身が資金を給付する制度ではない。同項は支援を6号に限定列挙しており、GAPファンド・起業準備資金・POC資金は含まれない。産学連携サイトのトップページおよび国環研ベンチャーページにも学内ファンドや起業支援金の掲載はない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_accelerator', 'established', '設立・事業計画・資金調達・販路開拓の支援と専門家紹介', '第6条1項5号が「会社設立支援、事業計画策定支援、資金調達支援、研究開発支援、販売販路開拓支援、専門家の紹介及び会社経営に関するセミナーについての情報の提供等」を支援メニューとして規定。第6条3項により役職員の準備段階でも同5号の措置を講じられる。産学連携サイトの手続きの流れは、産学連携窓口への問い合わせ→知財等や支援内容の相談→申請書提出→審査委員会→通知の5段階で、相談段階が制度化されている。年次公募型のアクセラレーションプログラムは公開情報上なし。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: COI委員会の別途審査はkt_kengy.pdf本文に無い］元の主張(established): 役員兼業は理事長許可制・原則2年、COI委員会が別途審査。ベンチャー支援規程第6条4項「研究所の役職員が国環研ベンチャーの活動を行う場合は、兼業等規程（平18規程第13号）に定めるところにより兼業として行う」。兼業等規程第2条3号・4号は取締役等（発起人を含む）の職を兼ねることを役員兼業と定義し、第4条で開始1か月前までに理事長へ申請、第3条の兼業等審査委員会が審査、第5条で特別な利害関係がないこと等7要件、許可は原則2年以内。第8条で半期ごと報告、第9条で概要公表、第10条で終了後2年の業務制限。利益相反マネジメント実施規程第9条は兼業報酬等100万円以上と未公開株式保有の全件自己申告を義務づける。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_support_fee', 'established', '認定・場所・設備は無償、実施料も減免あり', '第6条1項1号（事務室・研究室）と3号（研究設備等）はいずれも「無償で貸与」と規定。4号は実施料の無償化又は支払いの一定期間の猶予若しくは免除等を認めるとする。認定申請や称号使用について手数料の定めは規程上ない。ただし2項により支援措置の内容・条件は個別に契約を締結して契約書を取り交わすため、実際の負担は契約次第。第11条は故意・過失による損害賠償請求を研究所側・ベンチャー側の双方向で定める。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_certified_count', 'established', '1社（一覧公開・2024年9月5日認定）', '産学連携サイト「国環研ベンチャー」ページの「国環研ベンチャー企業一覧」に、株式会社野生動物医科学ラボラトリー（認定日：2024年9月5日）の1社のみ掲載。2026年9月5日時点の同ページで確認。累計認定数や取消件数の公表はなく、一覧は現に認定されている企業を掲げる形式。認定制度は令和4年11月1日施行で、施行から約4年で公表社数は1社にとどまる。', 'official', 'https://www.nies.go.jp/sangaku/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_cert_rule', 'unknown', null, '共創機構サイトの全ページ一覧(page-sitemap)、大阪大学規程集の五十音索引(全560件)、大学サイトの全文検索を確認したが、「大阪大学発ベンチャー」を認定・称号付与する規程も申請ページも見つからなかった。共創機構の「大阪大学発ベンチャー」ページは24社を掲載するが「2020年時点で学生インターンの受け入れなどにご協力いただいた企業を中心としたものであり、すべての阪大発ベンチャーを網羅するものではありません」と注記し、認定一覧ではない。テクノアライアンス棟利用規程第3条第3号は「本学で得られた研究成果を基に設立されたベンチャー」と定義するのみで認定手続きを置かない。', 'unknown', 'https://www.ccb.osaka-u.ac.jp/service/venture_made/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_eligible_scope', 'unknown', null, '認定制度が確認できないため認定対象の定義も公開情報には無い。近い定義として、テクノアライアンス棟利用規程第3条は利用資格に「本学で得られた研究成果を基に設立されたベンチャーの役職員」と「大学発ベンチャーの設立を目指す研究プロジェクトの研究開発者」を挙げる。産学法務支援室の弁護士無料相談の対象は「大阪大学の教職員(非常勤職員を含む)及び大阪大学の学生」(大学発ベンチャー起業に係るFAQ 3.(1))。卒業生・退職者を対象にする記述は見つからなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_recognition_decider', 'unknown', null, '認定制度が無いため認定の決裁者・審査主体は確認できない。近接する決裁は、営利企業の役員兼業が総長許可で大阪大学教員等の営利企業役員等への兼業に関する審査委員会が審査(同規程第2条)、発起人になる場合は所属長許可(FAQ 1.(2))、施設利用はテクノアライアンス棟管理運営責任者が管理運営委員会の議を経て決定(同規程第5条)、株式等取得は共創機構の審査(株式等取扱規則第3条)。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_cert_pre_registration', 'unknown', null, '認定制度が無いため設立登記前の認定申請という枠組みは確認できない。設立前手続きとしては、教職員が発起人になる場合は設立前に所属長の許可書を受理する必要があり(兼業申請手続き、申請から許可書受理まで2週間〜1か月)、取締役就任は総長許可で2か月〜2か月半を要すると案内されている(FAQ 2.(4))。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_validity_years', 'unknown', null, '認定制度が無いため有効期間・更新の定めは確認できない。期間の定めがあるのは施設利用側で、テクノアライアンス棟の利用期間は原則3年以上10年以下、大学発ベンチャー目的の利用は原則1年以上5年以下、管理運営委員会が特に認めれば延長可(同規程第8条)。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_head_office_registration', 'established', '可（テクノアライアンスC棟・VB室で手続）', '大学発ベンチャー起業に係るFAQ(令和8年4月1日版)2.(6)に「学内ではテクノアライアンスＣ棟を登記場所とすることができます。手続き等の詳細は、VB室にお問い合わせください」と明記。VB室は共創機構イノベーション戦略部門ベンチャー・事業化支援室。登記場所とする際の使用料の有無は同FAQに記載が無く、テクノアライアンス棟利用規程第9条が利用経費を原則利用者負担と定めるにとどまる。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2026/03/%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E8%B5%B7%E6%A5%AD%E3%81%AB%E4%BF%82%E3%82%8BFAQ%EF%BC%88%E4%BB%A4%E5%92%8C8%E5%B9%B44%E6%9C%881%E6%97%A5%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_facility_lease', 'established', 'テクノアライアンス棟に入居可・有償・原則1〜5年', '大阪大学テクノアライアンス棟利用規程(平成23年4月1日施行、令和7年3月21日改正)第3条第3号が大学発ベンチャーの役職員と設立を目指す研究プロジェクトの研究開発者を利用資格に明記し、第4条第3号で大学発ベンチャーとしての研究成果活用活動を利用目的に挙げる。第5条で利用申込書を管理運営責任者へ提出し管理運営委員会の議を経て可否決定。第8条で利用期間は原則3年以上10年以下、大学発ベンチャー目的は原則1年以上5年以下、延長可。第9条で経費は原則利用者負担(額は別に定める)。産学共創棟の募集施設一覧・入居調査票は学内専用。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_shared_equipment', 'not_started', '原則不可・共同研究の範囲内のみ使用可', '大学発ベンチャー起業に係るFAQ(令和8年4月1日版)2.(7)が「ベンチャー企業は、一民間企業ですので、大学の設備を使うことは原則としてできません。ただし、共同研究目的の範囲内においては使用可能なため、その場合には、大学との共同研究契約等を締結の上、使用することができます。なお、大学の設備を使用して営業生産することはできません」と明示。大学発ベンチャー向けの学内料金区分は確認できない。全学の設備共用は大阪大学コアファシリティ機構規程(令和5年4月1日施行)が担うが、大学発ベンチャーの利用や料金の定めは置かれていない。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2026/03/%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E8%B5%B7%E6%A5%AD%E3%81%AB%E4%BF%82%E3%82%8BFAQ%EF%BC%88%E4%BB%A4%E5%92%8C8%E5%B9%B44%E6%9C%881%E6%97%A5%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_name_logo_use', 'established', '営利目的は担当理事の許可制・事実表示に限定', '国立大学法人大阪大学における学外者による名義及び学章の使用に関する取扱規程(令和6年9月18日施行)第5条・第6条により、営利目的の名義・学章使用は部局長を経て担当理事の許可が必要。別表が認めるのは「特許出願番号○○号 出願人国立大学法人大阪大学」等の実施許諾の事実表示、「大阪大学○○教授との共同研究」等に限られ、「大阪大学との共同研究」といった表示は不可。ベンチャー関連では「大阪大学ベンチャー○○社1号ファンド」等のファンド名の類型のみで、企業が「大阪大学発ベンチャー」を称号として名乗る枠組みは別表に無い。第7条は使用に伴う経済的支援を行わないと定める。', 'official', 'https://www.osaka-u.ac.jp/ja/guide/files/qzg291/@@download/file', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_ip_license', 'established', '原則有償・減免時は新株予約権等を取得', '大学発ベンチャー起業に係るFAQ 1.(8)は、大学保有の知的財産権をベンチャーが利用する場合に実施許諾等の権利関係の整理が必要と定める。本学発ベンチャー企業支援に関する新株予約権等取得についてのガイドライン(令和元年11月5日制定、令和6年4月1日改正)2.(1)(2)は、知的財産のライセンスや施設・設備の提供、技術指導等を支援と位置づけ「原則として有償」としつつ、資力等を勘案し特に必要と認める場合は無償または時価より低い対価とし、その代わりに新株予約権等を取得すると定める。独占的実施許諾の優遇規定は公開資料では確認できなかった。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%9B%BD%E2%BD%B4%E2%BC%A4%E5%AD%A6%E6%B3%95%E2%BC%88%E2%BC%A4%E9%98%AA%E2%BC%A4%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E6%9C%AC%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E2%BD%80%E6%8F%B4%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E6%96%B0%E6%A0%AA%E4%BA%88%E7%B4%84%E6%A8%A9%E7%AD%89%E5%8F%96%E5%BE%97%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6%E3%81%AE%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%EF%BC%88R6.4%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_equity_rule', 'established', '新株予約権等取得ガイドラインと株式等取扱規則あり', '大阪大学における知的財産権等の運用又は処分の対価として取得する株式等の取扱いに関する規則(平成21年4月27日制定、令和6年4月1日改正)第2条が、現金を保有しない等の場合に対価の軽減措置を講じて株式等を取得できる受入基準を定め、第3条で共創機構の審査を経ることとする。本学発ベンチャー企業支援に関する新株予約権等取得についてのガイドライン(令和元年11月5日制定、令和6年4月1日改正)は、支援の無償化・減額と引換えに株式・新株予約権を取得し、自益権は行使、共益権は原則不行使、保有と売却は国立大学法人大阪大学株式等管理細則によると定める。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%A4%A7%E9%98%AA%E5%A4%A7%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E7%9F%A5%E7%9A%84%E8%B2%A1%E7%94%A3%E6%A8%A9%E7%AD%89%E3%81%AE%E9%81%8B%E7%94%A8%E5%8F%88%E3%81%AF%E5%87%A6%E5%88%86%E3%81%AE%E5%AF%BE%E4%BE%A1%E3%81%A8%E3%81%97%E3%81%A6%E5%8F%96%E5%BE%97%E3%81%99%E3%82%8B%E6%A0%AA%E5%BC%8F%E7%AD%89%E3%81%AE%E5%8F%96%E6%89%B1%E3%81%84%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E5%89%87%EF%BC%88R4.1%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_gap_fund', 'established', '学内ギャップファンド（シーズ育成・社会実装支援）', '共創機構「ベンチャー創成・社会実装支援」ページに「大阪大学は、研究成果の実用化を目指す本学教職員・学生の支援制度として下記のギャップファンドを設けています」とあり、シーズ育成グラントと社会実装支援グラントを掲げる。加えてJST・NEDO・AMED等の外部グラントを案内。過去の完了報告書は学内専用。統合報告書2024(36頁)も「各種ギャップファンドで起業やライセンス化を支援するプレ・インキュベーション活動」と記載。金額・上限・件数は公開ページに記載が無い。', 'official', 'https://www.ccb.osaka-u.ac.jp/service/venture_shien/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_accelerator', 'unknown', null, '［自動検証で否認: VB室・産学法務支援室はこのページに無し］元の主張(established): VB室・産学法務支援室の相談窓口、連携VC41社。共創機構イノベーション戦略部門ベンチャー・事業化支援室(VB室)が起業手続きの窓口(FAQ 2.(4))。2024年4月設置の産学法務支援室が教職員・学生の起業に関する弁護士無料相談を担当(FAQ 3.(1)(2))。「起業の進め方」ページは医学系・工学系・豊中の3分室で研究現場のベンチャー起業を支援と記載。「ベンチャー創成支援」ページは連携VC41社の紹介と年5回の連携VC連絡会での事業化構想発表を記載。統合報告書2024はシリコンバレー拠点とBerkeley SkyDeckのInnovation Partners Program活用を記す。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: COI自己申告は兼業手続き資料に無し］元の主張(established): 役員兼業は総長許可・審査委員会審査、COI自己申告。共創機構の兼業申請手続きにより、営利企業の役員兼業は総長許可(部局審査委員会・人事課・大学の審査委員会を経て2か月〜2か月半)、一般兼業は所属長許可。大阪大学教員等の営利企業役員等への兼業に関する審査委員会規程第2条が技術移転企業・研究成果活用企業の役員兼業と監査役等兼業を審査対象とする。FAQ 1.(2)は発起人が所属長許可、1.(3)は新株予約権で報酬を得る場合に兼業依頼状への記載を要すると定める。利益相反マネジメントガイドライン(令和5年4月28日)は株式保有・役員就任・兼業報酬年100万円以上の自己申告を求める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_support_fee', 'established', '原則有償・資力に応じ無償化し新株予約権等取得', '本学発ベンチャー企業支援に関する新株予約権等取得についてのガイドライン2.(1)は「知的財産のライセンス、実験設備や事務用具が設置された施設やその他の設備の提供、さらには技術指導にとどまらない当該ベンチャー企業に対する全ての指導・助言等」を支援とし「これらの支援は原則として有償」と明記。2.(2)で資力等を勘案し特に必要と認める場合に無償・減額し新株予約権等を取得する。テクノアライアンス棟利用規程第9条も経費は原則利用者負担。名義等の使用については経済的支援を行わない(名義等使用取扱規程第7条)。産学法務支援室の弁護士相談は無料。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%9B%BD%E2%BD%B4%E2%BC%A4%E5%AD%A6%E6%B3%95%E2%BC%88%E2%BC%A4%E9%98%AA%E2%BC%A4%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E6%9C%AC%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E2%BD%80%E6%8F%B4%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E6%96%B0%E6%A0%AA%E4%BA%88%E7%B4%84%E6%A8%A9%E7%AD%89%E5%8F%96%E5%BE%97%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6%E3%81%AE%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%EF%BC%88R6.4%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_certified_count', 'unknown', null, '認定制度が確認できないため認定社数の公表も無い。共創機構「大阪大学発ベンチャー」ページは24社を五十音順で掲載するが、「2020年時点で学生インターンの受け入れなどにご協力いただいた企業を中心としたものであり、すべての阪大発ベンチャーを網羅するものではありません」と明記されており、認定一覧ではない。経済産業省の大学発ベンチャー実態等調査による機関別件数は指示により本調査の根拠に用いていない。', 'unknown', 'https://www.ccb.osaka-u.ac.jp/service/venture_made/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_cert_rule', 'established', '「奈良先端大発スタートアップ」認定制度（令和6年規程第5号）', '「国立大学法人奈良先端科学技術大学院大学における大学発スタートアップの認定等に関する規程」（令和6年3月27日 規程第5号、令和6年4月1日施行、令和7年10月1日改正施行）。第5条で学長が別記様式第2号の称号記を交付し「奈良先端大発スタートアップ」の称号を授与する。産官学連携ページの同制度説明にも「2024年度から開始したもの」と明記。第9条で認定・取消しをホームページ等で公表できると定める。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_eligible_scope', 'established', '教職員・学生・退職修了3年以内・研究成果活用型', '第2条各号。(1)本学所有の知的財産権又は役員・職員・学生等が創出した研究成果を基に設立、(2)本学で達成された研究成果又は習得した技術等に基づき設立、(3)本学の職員又は学生（起業を理由とする退職・修了・退学から設立までが3年以内の者を含む）が設立者となるもの又は設立に深く関与するもの、(4)学長が前3号に準じる資格を有すると認めたもの。第4条で公序良俗違反がないこと、本学への名誉毀損等のおそれがないことも要件。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_recognition_decider', 'established', '学長（研究・イノベーション推進会議の議を経る）', '第3条第2項。学長は申請があったとき、研究・イノベーション推進機構規程（平成27年規程第7号）第4条の2に規定する研究・イノベーション推進会議の議を経て認定する。同会議は機構長を議長とし、各領域長・研究推進部門長・イノベーション推進部門長・事業推進部長等で組織（同規程第4条の2第2項）。認定の取消しも同会議の議を経る（第8条）。事務は事業推進部研究協力課（第12条）。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_cert_pre_registration', 'established', '可（設立準備中でも定款案等を添えて申請可）', '別記様式第1号（第3条・第5条関係）の添付書類欄の注記に「設立準備中の場合は、本申請書に準備書類（定款案、法人概要案及び組織図案）を添付して提出し、設立後に上記添付書類を全て提出すること」と明記。通常の添付書類は登記簿の写し・定款の写し・法人概要及び組織図・事業報告書等だが、設立前はその案で代替できる。様式の記入欄も「事業開始（予定）日」と「設立日」を分けている。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_validity_years', 'established', '5年・更新可', '第5条第2項「認定期間は、認定した日から5年とし、更新することができる」。第3項で更新は企業の代表者が別記様式第1号（申請区分に「新規／更新」欄あり）で学長に申請し、手続及び審査は第3条第2項（研究・イノベーション推進会議の議）及び第4条を準用する。別記様式第2号の称号記にも【有効期間：年月日〜年月日】欄がある。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_head_office_registration', 'established', '可（学内インキュベーション施設を本店所在地に登記）', '第11条第1項第2号「前号の施設について、当該認定スタートアップの所在地とする商業登記を認めること」。第1号の学内インキュベーション施設の使用が前提。さらに第3号で「第2号の規程による商業登記をした場合、郵便物等の収受において便宜を与えること」と定める。有償無償は同条第2項が「本学における関係規則等によるものとする」とするのみで、公開情報からは特定できなかった。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 別表第2/3305平米の根拠規程が確認8URLに見当たらず］元の主張(established): 学内インキュベーション施設の使用可・料金は別規則。第11条第1項第1号「本学内にインキュベーション施設として確保した施設を使用させること」。産官学連携ページの制度説明でも認定企業への支援の筆頭に挙げられている。施設の有効活用に関する規程（平成20年規程第3号）は別表第2で学際融合領域研究棟1号館・2号館のオープンラボ等（計3,305平米）をプロジェクトスペースとして定め、第5条で学長は利用に係る経費を利用者に負担させることができるとする。施設の固有名称・貸与期間・単価は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_shared_equipment', 'established', '企業区分で利用可・別表額＋間接経費30%', '認定規程第11条第1項第4号「本学の研究設備等の利用を許可すること」。研究設備等の整備・共用の推進に関する規程（令和6年規程第4号）第2条で学外利用者への共用推進を定める。生命科学研究基盤センター共用推進事業実施要領（令和6年3月27日学長裁定）第4条第3号が「企業等に所属する研究者及び有識者」を利用資格者とし、第8条で利用料金は別表額＋消費税（直接経費）に直接経費の30%の間接経費を加算、第3項でセンター長は一部又は全額を免除できると定める。認定SU専用の学内料金区分は確認できず。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03320.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_name_logo_use', 'established', '称号使用可（品質保証目的は禁止）・ロゴは許可制', '第5条で「奈良先端大発スタートアップ」の称号を授与。第6条第1項で自社の製品・サービス等の内容及び品質を保証するために称号を使用してはならないと制限し、第2項で称号を用いた新たな情報公開は事前に大学へ通知することを義務付ける。第11条第1項第7号で「認定スタートアップのロゴマークの使用許可を与えること」。大学ロゴ自体はロゴマーク等使用要領（平成16年11月17日学長裁定）第4条により学外者は使用目的・使用図案等を学長に申請し許可を得る。認定取消し時は称号記を返還し使用不可（第8条第3項）。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_ip_license', 'established', '発明者自身の事業化に優先的実施許諾（原則有償）', '実施許諾等取扱規程（平成16年規程第36号）第6条第1項第4号で「本学が所有する知的財産権に係る知的財産の創作者（発明者）自身が事業化する場合」に優先的実施許諾ができると定める。第2条第2項の優先的実施許諾には専用実施権又は独占的通常実施権の形態を含む。ただし第3条第2項で実施許諾は原則有償であり、対価の無償・特別条件は知的財産ポリシーのアカデミックユース特例（学術研究機関向け）に限られる。株式・新株予約権を対価とする規定は確認できず。認定規程第11条の支援列挙にも知財実施許諾は含まれない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/04080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_equity_rule', 'unknown', null, '公開されている規程集の全一覧（PDF227件）を通覧したが、出資・株式・新株予約権・ストックオプションの取得を定める規程は存在しない。知的財産ポリシー・産官学連携ポリシー・職務発明等取扱規程・資金管理取扱規程・寄附受入及び管理取扱規程の本文も「株式」「新株予約権」「出資」で検索したが該当規定なし（寄附受入規程の「株式会社が発行する債券」は寄附財産の種類の列挙）。認定規程第11条の支援列挙にも株式・SO取得はない。制度が無いのか非公開なのかは公開情報では判別できないため unknown とした。', 'unknown', 'https://reiki.naist.jp/kiyaku/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_gap_fund', 'unknown', null, '認定規程第11条第1項の支援列挙（施設使用、商業登記、郵便物収受、研究設備利用、他企業紹介・共同研究仲介、広報、ロゴ使用許可、その他学長が認めるもの）に資金支援は含まれない。イノベーション推進部門の推進内容ページ・研究イノベーション推進機構ページ・産官学連携の制度サービスページを開いたが、学内GAPファンド、起業準備資金、POC資金の記載は確認できなかった。本学はJ-PEAKS参画機関だが、GAPファンドの有無を示す一次資料に到達できなかったため unknown とした。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 引用文がページ本文に実在せず、研究企画係も未確認］元の主張(established): イノベーション推進部門の伴走支援と企業紹介の仲介。認定規程第11条第1項第5号「他企業への紹介又は他企業との共同研究等の仲介を行うこと」、第6号「本学主催のイベント、本学の広報誌又はホームページ等により広報を行うこと」を支援として明記。イノベーション推進部門は推進内容の4本柱の一つに「NAIST認定スタートアップの創出と連携の拡張支援」を掲げ、部門紹介で「新産業・スタートアップの創出に向けて、企画立案および伴走型の事業推進・支援を行う部門」と説明。認定の相談窓口は事業推進部研究協力課研究企画係（規程第12条）。名称のあるアクセラレーションプログラムや年次コホートは確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_coi_sidejob', 'established', '役員兼業許可と利益相反手続の完了が認定要件', '認定規程第4条第4号で「本学の職員が設立したものにあっては、国立大学法人奈良先端科学技術大学院大学職員兼業規程（平成16年規程第53号）、同利益相反マネジメント規程（平成17年規程第4号）その他本学における関係規則等に定める所要の手続及び許可等が適正になされていること」を申請の条件とする。別記様式第1号の確認欄（教職員）でも同旨を申告させる。職員兼業規程は営利企業の役員兼業を原則不許可としつつ、技術移転事業者・研究成果活用企業の役員兼業を許可対象と明記している。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_support_fee', 'established', '認定申請は無料・施設と設備利用は有償', '認定規程には申請手数料・認定料の定めがなく、認定自体は無償。一方で第11条第2項が「前項各号に掲げる支援を行うときは、本学における関係規則等によるものとする」とし、個別支援は各規則の料金体系に従う。施設の有効活用に関する規程第5条はプロジェクトスペース利用経費を利用者負担とし、共用設備は実施要領第8条で別表額＋消費税＋間接経費30%（免除規定あり）。実施許諾は実施許諾等取扱規程第3条第2項で原則有償。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_certified_count', 'established', '認定9社・公式サイトで一覧公開', '産官学連携制度・サービスページの「奈良先端大発スタートアップ」節にある「認定スタートアップ一覧」に9社が社名と各社サイトへのリンク付きで掲載（株式会社mica、奈良・先端画像技術株式会社、MICBON株式会社、LENZO株式会社、mocomoco株式会社、NODAS株式会社、株式会社EASE創研、株式会社LEP、株式会社ROBOZOO）。2026-09-05時点の掲載。制度は2024年度開始。認定規程第9条が認定・取消しのホームページ公表を根拠づける。', 'official', 'https://www.naist.jp/sankan/content/ja/service/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_cert_rule', 'established', '宇都宮大学発ベンチャー（令和7年規程第62号）', '「国立大学法人宇都宮大学における大学発ベンチャーに関する規程」（令和7年規程第62号、令和7年11月1日施行、令和8年規程第66号で改正・令和8年4月1日施行）を全文確認。第7条第1項で学長が称号記（様式第4）により「宇都宮大学発ベンチャー」の称号を授与すると規定。同附則第5項で旧「大学発ベンチャーの支援内容に関する細則」（令和2年3月24日制定）を廃止し、支援内容を規程本体第8条に統合している。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・知財/研究成果活用型', '規程第2条第1号ア〜エ。ア=教職員等・学生等が学内で行った発明等に係る知的財産権の技術を基に設立/設立準備中の企業等、イ=学内で得られた研究成果又は成果有体物等を基に設立/設立準備中、ウ=教職員等・学生等であった者が退職・卒業・修了後原則3年以内に大学保有の知財又は研究成果等を基に設立、エ=前号までに準じ学長が特に認めるもの。教職員等=役員・教職員その他雇用契約のある全員（第2号）、学生等=学部生・大学院生・研究生・研究員（第3号）。企業等=株式会社・合同会社・LLP・協業組合等（第6号）。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_recognition_decider', 'established', '学長（大学発ベンチャー認定委員会の審議を経て）', '規程第4条第2項で、学長は申請を宇都宮大学発ベンチャー認定委員会に付議し、その審議結果を踏まえて可否を決定、認定・支援可否通知書（様式第3）で通知。委員会の組織は「宇都宮大学発ベンチャー認定委員会細則」（令和4年12月21日制定、令和8年3月27日改正・令和8年4月1日施行）第3条で、理事のうち学長指名者（委員長）、地域創生推進機構長、イノベーション支援センター知財部門長、財務部長、社会共創・研究部長、その他委員会が必要と認めた者。事務は社会共創・研究部社会共創・研究推進課社会共創係（規程第13条）。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001877.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_cert_pre_registration', 'established', '可（設立準備中の企業等も認定対象）', '規程第2条第1号ア・イがいずれも「設立した又は設立の準備を行っている企業等」と明記しており、設立登記前でも認定対象に含まれる。エも「設立した又は設立準備を行っている企業等」を対象とする。申請要件を定める第5条各号（定義該当、公序良俗・法令適合、名誉毀損等のおそれがないこと、単なる小売・サービス業でないこと、申請書・添付書類・財務状況から適切な事業と判断できること、教職員の役員就任時の兼業・利益相反手続）に登記簿謄本の提出要件はない。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_validity_years', 'established', '5年・延長1回3年（最長8年）', '規程第4条第3項で認定及び支援期間は決定日から5年を限度。第6条で延長申請が可能で、期間終了日の6か月前までに様式第2により学長へ申請、委員会付議のうえ学長が可否決定（第6条第2項）。延長申請は1ベンチャーにつき1回限り（第6条第3項）、延長後の期間は3年を限度（第6条第4項）。第11条で7つの取消事由（定義に該当しなくなった、社会的信用失墜、事業実態なし、存続が危惧される、代表者の申出、事業報告未提出、その他不適当）を規定。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_head_office_registration', 'established', '可（貸与施設に限り商業登記を許可）', '規程第8条第1項第3号で「貸与した施設において、宇都宮大学発ベンチャーの所在地とする商業登記を認めること」を支援内容として明記。ただし別表第1に定める施設の退去時または支援終了時のいずれか早い日から1か月以内に、登記場所を変更したことを示す書面を大学へ提出する義務がある。したがって学内本店登記は施設入居とセットの支援で、入居終了時に本店移転が必要。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 施設名・割引率は要項本文になく規程別表が典拠］元の主張(established): イノベーション支援センター等4施設・使用料95%割引。規程第8条第1項第1号と別表第1。対象施設はイノベーション支援センター本棟プロジェクト実験室、同北棟プロジェクト実験室、ロボティクス・工農技術研究所インキュベーション室、オプティクス教育研究センター。割引率は第4条第3項の認定5年間は95%、第6条第4項の延長3年間は1年目80%・2年目65%・3年目50%と逓減。研究開発スペースの利用は「イノベーション支援センター研究開発スペース利用要項」（平成30年12月13日制定、令和7年10月27日改正・令和8年4月1日施行）第3条第3号・第4号で教職員等・学生が設立者となったベンチャー企業等を利用者に明記、許可はセンター長、期間は単年度（延長可）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_shared_equipment', 'established', '学内者向け料金で利用可', '規程第8条第1項第2号で「本学が管理する機器を、学内者向け料金で使用させること」を支援内容として明記。認定ベンチャーは外部利用料金ではなく学内料金区分が適用される。一般の学外者利用は「宇都宮大学機器分析センター機器の学外者利用に関する規程」および同実施細則（学長裁定 平成22年3月19日、令和3年4月1日改正）に基づき、利用希望日の1か月前までに利用申請書をセンター長へ提出し許可書の交付を受ける手続で、料金は別に定めるとされている。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_name_logo_use', 'established', '称号は認定期間内使用可・学章ロゴは学長許可制', '称号は規程第7条で学長が称号記（様式第4）により授与し、第7条第2項で原則として認定及び支援期間内に限り使用可。第11条第3項で取消通知後は称号も認定を受けていた事実も事業に使用できない。大学名称・学章・ロゴマークは別規程「国立大学法人宇都宮大学『学章』及び『ロゴマーク』の制定並びに『大学名称等』の使用に関する規程」（令和7年規程第61号）が管轄し、第6条の使用資格は役職員・学生・認定課外活動団体・その他学長が認めた者。ベンチャーは第6条第3号に当たり、第8条により使用許可願兼企画書であらかじめ学長の許可を要する。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000012.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_ip_license', 'established', '独占的通常実施権・低額対価・株式対価の優遇措置', '規程第8条第1項第4号で、大学が所有する知的財産権又は研究成果等の譲渡・提供・実施権設定・実施許諾・利用許諾に関する優遇措置を規定。第8条第2項が優遇措置の中身を3号で具体化し、(1)知的財産権の独占的通常実施権を設定すること、(2)契約で大学が受け取る対価を通常と比べて低額に設定すること、(3)対価を株式又は新株予約権で受け取ること。第8条第3項で株式・新株予約権の取扱いは別に定めるとし、ライセンス等の対価として取得する株式等取扱要項へ接続する。第8条第1項第5号でイノベーション支援センターによる知財戦略アドバイスも規定。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_equity_rule', 'unknown', null, '［自動検証で否認: ライセンス対価要項はURLなく実在未確認］元の主張(established): ライセンス対価株式等取扱要項・寄附株式取扱規程。2本立て。(1)「ライセンス等の対価として取得する株式等取扱要項」（令和2年3月24日制定、令和7年10月16日改正・令和7年11月1日施行）が大学発ベンチャーからライセンス対価として株式・新株予約権を取得する場合を規律し、大学発ベンチャー規程第8条第2項第3号・第3項から接続。(2)「国立大学法人宇都宮大学における寄附により取得する株式取扱規程」（令和7年規程第64号）を新たに確認。第1条で寄附による株式取得を規律し、ライセンス対価分は前者によると棲み分けを明示。株式には新株予約権・新株予約権付社債を含み（第2条第1号）、受入れは役員会の議を経て学長が決定（第6条）、取得株式は原則速やかに売却（第10条）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_gap_fund', 'not_started', null, '規程第8条第1項が支援内容を9号で列挙するが、資金支援の号はない。列挙は施設貸与（第1号）、機器利用（第2号）、商業登記（第3号）、知財優遇（第4号）、知財戦略アドバイス（第5号）、他企業紹介・仲介（第6号）、大学主催イベント・広報誌・HPでの広報（第7号）、学外ビジネスマッチング情報提供（第8号）、その他学長が必要と認める事項（第9号）。地域創生推進機構サイトのイノベーション支援センター、イノベーション部門、関連事業の各ページ、および令和6年度イノベーション部門（CDI）活動成果報告書（22ページ）を確認したが、GAPファンド・起業資金・POC資金の記載は一切なし。第9号の包括条項はあるため制度化された資金支援は確認できない。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_accelerator', 'established', '知財戦略助言・企業紹介仲介・マッチング情報提供', '規程第8条第1項第5号でイノベーション支援センターが認定ベンチャーの知的財産権に関する戦略等のアドバイスを行うこと、第6号で同センター等による他企業への紹介又は仲介、第7号で大学主催イベント・広報誌・ホームページでの広報、第8号で学外ビジネスマッチングイベント等の開催情報提供を規定しており、認定後の伴走支援が規程上制度化されている。知財の相談窓口はイノベーション支援センター知財部門（電話028-689-6324）。ただし名称のついたアクセラレーションプログラムやコホート型の起業家育成プログラム、専任メンター制度は公開情報では確認できなかった。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_coi_sidejob', 'established', '役員就任は兼業・利益相反規程の手続完了が認定要件', '規程第5条第6号が申請要件として「本学の教職員等を役員に就任させる場合にあっては、国立大学法人宇都宮大学職員兼業規程、国立大学法人宇都宮大学利益相反マネジメント規程、国立大学法人宇都宮大学の役員の兼業に関する申合せ等の本学の関係規程等に定める所要の手続が適正に行われていること」と明記。認定審査と兼業許可・利益相反マネジメントが制度的に接続している。規程集には別途「国立大学法人宇都宮大学職員営利企業役員等兼業審査委員会規程」も収録されている。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 料金表・返還規定等は通知PDFに記載なし］元の主張(established): 認定は無償・施設は有償（95%割引）・機器は学内料金。認定申請自体に手数料の定めはない。施設は有償で、規程別表第1により認定5年間は使用料95%割引、延長3年間は80%・65%・50%。素の料金は令和8年度研究開発スペース利用募集通知（令和7年12月11日、イノベーション部門長 佐藤剛史）で1平方メートルあたり年44,160円（水光熱料込・消費税抜）、利用要項別表第1の建物利用基本料金表では36平方メートルのプロジェクト実験室が年1,589,760円のため、95%割引で年約79,000円。納付済み利用料は返還されず（利用要項第6条第3項）、明け渡し時の移転・改修費は利用者負担（同第12条）。機器は学内者向け料金。第12条で大学は損害賠償責任を負わない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_certified_count', 'established', '認定7社・一覧公開', '大学公式サイトの「宇都宮大学発ベンチャー」ページに宇都宮大学発ベンチャーリストとして7社を社名・設立日・代表者名・概要・認定状況の表で公開。REACT株式会社（旧アイ・イート、2014/10/31、中村克）、株式会社CrowLab（2017/12/21、塚原直樹）、株式会社ナーステックラボ（2019/8/13、川上勝）、株式会社ネイチャートレイル研究所（2022/10/11、髙橋俊守）、株式会社Ferment Base（2023/6/16、平松光幸）、株式会社ホロデザイン（2023/9/1、長谷川智士）、合同会社AIRR JP（2023/12/27、兼子颯大郎）。全7社が「認定」表示。ページに更新日の記載はない。', 'official', 'https://www.utsunomiya-u.ac.jp/activity/community/spinoff.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_cert_rule', 'established', '「山形大学発ベンチャー」認定制度（認定等に関する規程）', '「国立大学法人山形大学における大学発ベンチャーの認定等に関する規程」（令和4年9月28日制定、令和5年5月10日施行）第1条が認定と称号授与を定め、第5条で学長が称号記（別記様式2）により「山形大学発ベンチャー」の称号を授与する。第10条で、認定・称号授与は製品やサービスの品質・経営状況を保証するものではないと免責を明記している。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_eligible_scope', 'established', '教職員・学生（退職・卒業後1年以内）／特許・研究成果型', '認定規程第2条が4類型を定める。(1)教職員又は学生を発明人とする特許をもとに起業、(2)本学で創出された研究成果又は習得した技術に基づく起業、(3)教職員又は学生が設立者又は設立に深く関与（退職・卒業・修了後1年以内の設立を含む）、(4)学長が特に認めたもの。第4条第4号で、教職員が設立する場合は本学採用後原則3年以上経過していることが条件。別記様式1の代表者区分は「本学教職員（退職者含む）・学生（卒業生含む）・その他」。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_recognition_decider', 'established', '学長（研究戦略企画本部の議を経て決定）', '認定規程第3条第2項で学長が研究戦略企画本部の議を経て決定し、必要があれば申請者への面接を行う（第3項）。取消しも同本部の議を経る（第8条第1項）。認定・称号授与の事務は研究情報部（第11条）。研究戦略企画本部は令和5年3月22日制定の同本部規程（令和5年4月1日施行）により、研究・産学連携担当の理事又は副学長、研究ディレクター、研究情報部長、本部長指名者で構成される。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_cert_pre_registration', 'established', '可（申請書で新規・既設を選択、新規は設立予定を記載）', '別記様式1（第3条関係）「山形大学発ベンチャー認定申請書」の項目1が「設立状態 □新規 □既設」、項目11が「準備状況及び設立スケジュール（新規のみ）」となっており、未設立の会社を「新規」として申請できる様式構成。規程本文（第3条・第4条）にも登記事項証明書などの添付要件はない。ただし「設立予定での申請可」と明文で書いた条文はなく、根拠は様式の記載事項である。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/word/w679FG00008792s.png', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_validity_years', 'established', '支援は称号授与から5年限度・1年単位で延長可', '認定規程第9条第3項「山形大学発ベンチャーへの支援は、称号を授与した日から5年間を限度とし、学長が必要と認めた場合には、1年単位で延長することができる」。認定・称号自体に有効期間の定めはなく、第7条の代表者からの解除・返付申出、又は第8条の取消し（定義からの著しい逸脱、法令違反、事業実態の消失等）まで存続する。代表者は毎年6月末日までに前年度の事業報告書を学長へ提出する義務がある（第6条第1項）。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_head_office_registration', 'established', '可（貸与を受けた施設を所在地として法人登記）', '認定規程第9条第1項第2号「貸与した施設について、当該山形大学発ベンチャーの所在地とする法人登記を認めること」。支援申請書（別記様式4）の(2)に同文のチェック欄がある。施設の貸与を受けることが前提で、同条第1項ただし書により対価を求められる場合がある。様式4の(5)その他の記載例に「郵便物の収受受付」が挙がっており、登記に伴う郵便受取も支援として申請できる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_facility_lease', 'established', '本学施設の貸与可（5年限度・対価を求める場合あり）', '認定規程第9条第1項第1号「本学施設の貸与」と支援申請書（別記様式4）(1)。支援期間は称号授与から5年（1年単位で延長可、第9条第3項）。専用インキュベーション施設の名称や賃料表は公開情報では特定できなかった。参考として学内スペースの使用料水準は山形大学総合研究所使用細則第8条が建物使用料 年10,000円/m²＋光熱水料と定めるが、同細則の申請者は本学職員・部局等であり、認定ベンチャーが直接借りる制度ではない。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_shared_equipment', 'established', '学外者として有料で利用可・依頼分析も受付', '大学サイト「研究機器の利用・依頼分析」が、学外の者による分析計測機器等の利用及び依頼分析（有料）を明記し、実験機器共同利用ポータルサイトで受け付けると案内している。「山形大学研究設備・機器の整備・共用推進に関する方針」（令和5年3月29日役員会決定）は、汎用性のある一定規模以上の機器は原則共用（2項）、利用者から適正な利用料金を徴収（4項）、学外者への共用体制を構築し地域・産業界に貢献（6項）と定める。認定ベンチャー向けの学内料金区分は確認できなかった。', 'official', 'https://www.yamagata-u.ac.jp/jp/research/facility/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_name_logo_use', 'established', '称号「山形大学発ベンチャー」使用可・大学HPで広報', '認定規程第5条で学長が称号記（別記様式2）により「山形大学発ベンチャー」の称号を授与。第9条第1項第4号と支援申請書(4)で、ホームページ等での広報を支援メニューに位置づけ、実際に産学官連携ページで認定企業名を公開している。第8条第4項は、取消しを受けた者が以後、認定を受けていた事実を事業に使用することを禁じる。大学ロゴ・校章そのものの使用条件は規程にも公開ページにも記載がなく確認できていない。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_ip_license', 'established', '特許・研究成果・技術の使用に優遇措置を許可', '認定規程第9条第1項第3号「本学が所有する特許、研究成果及び習得した技術の使用に関する優遇措置を許可すること」、支援申請書(3)にチェック欄。独占許諾か非独占か、対価の減免水準かは規程に明記がない。関連して株式等取扱規程第2条第4号・第3条により、知的財産権の実施許諾、学術指導、研究成果有体物の提供、施設・設備の貸与の対価を、現金での支払が困難な認定ベンチャーに限り株式・新株予約権で受け取ることができる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_equity_rule', 'established', '事業対価を株式・新株予約権で取得する規程あり', '「国立大学法人山形大学における大学発ベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等取扱規程」（平成26年10月1日制定）。対象は認定規程に基づく認定ベンチャーに限定（第2条第6号）。取得できるのは対価を現金で支払うことが困難な場合に限る（第3条第1項）。知的財産本部長が財務状況等を審査し学長の承認を得て取得（第4条）。配当等の経済的権利は行使するが、議決権など経営参加の権利は原則不行使（第6条第2項）。現金出資（投資）の規程は確認できなかった。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00000107.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_gap_fund', 'unknown', null, '認定規程第9条第1項の支援メニュー（施設貸与、貸与施設での法人登記、知財使用の優遇、HP広報、その他学長が必要と認めた支援）に資金支援は挙がっていない。ただし第5号が包括条項のため限定列挙とは言えない。J-PEAKSページ、産学官連携ページ、オープンイノベーション推進本部サイトを開いたが、学内GAPファンド・起業準備資金・POC資金の公開情報は見つからなかった。', 'unknown', 'https://www.yamagata-u.ac.jp/jp/j-peaks/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_accelerator', 'unknown', null, '産学官連携ページには研究情報部研究推進課（産学連携担当）の問い合わせ先が載るが、起業相談窓口・アクセラレーションプログラム・メンタリングとして制度化された記載はない。オープンイノベーション推進本部規程（令和5年3月22日全部改正）第2条の業務は組織的な大型共同研究の戦略的推進であり、起業支援は含まれない。研究戦略企画本部規程第2条の業務にも起業支援の項目はない。', 'unknown', 'https://www.yamagata-u.ac.jp/jp/research/reseach/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_coi_sidejob', 'established', '役員兼業は学長の事前許可制・利益相反規程の手続が認定要件', '認定規程第4条第4号は、教職員が設立する場合に本学採用後原則3年以上経過していること、及び兼業に関する規程と利益相反マネジメント規程に定める手続・許可が適正になされていることを申請条件とする。兼業規程（平成16年4月1日）第4条・第6条により営利企業の職を兼ねるには事前の学長許可が必要で、役員等以外の許可期間は1年以内（第10条）。利益相反マネジメント規程（平成23年9月14日）は未公開株式の保有等の個人的利益を対象とし（第2条第3号）、全学委員会が審査する（第9条）。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_support_fee', 'established', '支援内容に応じて一定の対価を求める場合あり', '認定規程第9条第1項ただし書「本学は支援内容に応じて一定の対価を求めることができるものとする」。有償・無償の区分や料金表は規程にも公開ページにも定めがなく、個別判断となる。認定申請自体の手数料の定めはない。株式等取扱規程により、施設・設備の貸与や知財使用の対価は、現金での支払が困難な場合に限り株式・新株予約権での支払も認められる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_certified_count', 'established', '認定8社・大学サイトで社名一覧を公開', '大学サイト「研究＞産学官連携」の「山形大学発ベンチャー認定企業」欄に、株式会社Cool ALD、株式会社アルファテック、株式会社ベジア、株式会社フューチャーインク、株式会社Ciel、株式会社F-EAT、ORIDA株式会社、株式会社ヒューセンス（準備中）の8社を掲載（2026年9月5日閲覧）。社名のみの掲載で、認定日・認定年度・事業内容の記載はない。', 'official', 'https://www.yamagata-u.ac.jp/jp/research/reseach/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_cert_rule', 'unknown', null, '［自動検証で否認: 「令和2年制定」は675頁になく他頁のみ記載］元の主張(established): 山梨大学発ベンチャー認定制度（令和2年制定）。研究推進・社会連携機構「起業・新規事業支援」ページに「山梨大学発ベンチャー認定制度を整備しました」と明記。大学公式ニュース（2026年7月21日）にも「本学では令和2年に大学発ベンチャー認定制度を制定しました」とある。称号は「山梨大学発ベンチャー」で、認定時に学長から称号記（認定証）を交付。規程本文そのものは「学内手続等は学内専用ページ」とされ非公開。原URLは https://www.scrs.yamanashi.ac.jp/business/675/ （当方の回線からは403のためアーカイブ版を閲覧）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_eligible_scope', 'established', '教職員・学生等、退職卒業3年以内、知財・研究成果活用型', '「山梨大学発ベンチャー定義」として、大学の研究成果の事業化を主たる目的とし、①山梨大学の知的財産権をもとに起業したもの、②山梨大学での研究成果又は習得した技術に基づいて起業したもの、③山梨大学の教職員及び学生等が発起人または設立時に取締役相当などになって起業したもの、のいずれかに該当する法人と規定。さらに「教職員が退職（学生等は卒業等）の後に起業した場合は、設立まで他の職に就かず、かつ退職等から起業までの期間が3年以内のものに限る」と明記。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_recognition_decider', 'established', '学長が認定、窓口は社会連携・知財戦略室', '大学公式ニュース（2026年7月21日掲載、令和8年6月25日の称号記授与式）に「中村和彦学長から認定証が授与されました」と記載。過去の授与式記事（2024年8月26日認定分ほか）も同様に学長が授与。申請・相談窓口は研究推進・社会連携機構 社会連携・知財戦略室（スタートアップ推進マネジャー）。審査委員会の名称・構成・議決要件は公開情報では確認できず、学内専用ページ扱い。', 'official', 'https://www.yamanashi.ac.jp/59209', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_cert_pre_registration', 'unknown', null, '公式ニュースの見出しが「大学発ベンチャー企業の設立と認定に伴う称号記授与式」となっており設立と近接した時期に認定されている例が多いが、設立登記前の申請受付、認定予定通知、条件付認定を認めるかどうかの記載は、認定制度紹介ページにも大学公式ニュースにもない。学内手続は学内専用ページとされ本文未公開のため判断できない。', 'unknown', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_validity_years', 'unknown', null, '認定の有効期間、更新の要否、取消事由に関する記載は、認定制度紹介ページ（定義・支援項目のみ記載）にも大学公式ニュースにもない。規程本文が学内専用のため公開情報からは確認できない。', 'unknown', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_head_office_registration', 'established', '貸与施設を本店所在地とする商業登記を許可', '認定ベンチャーへの「支援項目」の2番目に「貸与した施設について、大学発ベンチャーの所在地とする商業登記を認めること」と明記。支援項目1の「大学発ベンチャーの事務室又は研究室として山梨大学内の施設を貸与すること」を受けた措置で、貸与を受けた施設が対象。有償か無償か、登記に係る条件・期間の記載はない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_facility_lease', 'established', '事務室・研究室として学内施設を貸与', '支援項目1に「大学発ベンチャーの事務室又は研究室として山梨大学内の施設を貸与すること」と明記。ただし施設名（インキュベーション棟等の固有名）、使用料の有無、貸与期間の上限は公開資料に記載がなく、学内手続は学内専用ページとされている。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_shared_equipment', 'established', '学内の研究設備等の利用を許可', '支援項目3に「山梨大学の所有する研究設備等の利用を許可すること」と明記。共用機器の窓口は研究機器統轄センターの「山梨大学設置機器総合ポータルサイト」で、同サイトは学内利用料金と学外利用料金を分けて公開している（2026年8月に機器分析センターの学内利用料金を改定）。認定ベンチャーが学内料金と学外料金のどちらで扱われるかは公開情報では確認できない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 「称号使用可」の明記は59209本文になし］元の主張(established): 称号記の交付で称号使用可、ロゴ条件は不明。認定に伴い学長から「称号記」が交付される（大学公式ニュース、2026年7月21日ほか）。支援項目6に「山梨大学が主催又は参加するイベント、山梨大学の広報誌又はホームページ等において広報を行うこと」とあり、機構サイトの「山梨大学発ベンチャー企業の紹介」に社名・事業内容が掲載される。大学ロゴ・校章そのものの使用条件については記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_ip_license', 'unknown', null, '起業・新規事業支援ページは「ベンチャー企業に対しては、本学の知的財産のライセンス、その収入をもって研究力強化を図ります」と方針を述べるが、優先的実施許諾、独占許諾、対価の減免、株式による対価といった認定ベンチャー向け優遇条件の記載はない。認定制度の支援項目6項目にも知財ライセンスは含まれない。機構が公開する知的財産ポリシー（Ⅱ-2）と研究ライセンスポリシー（Ⅱ-4、非営利研究目的の非排他的実施許諾が対象）にも大学発ベンチャー向け優遇条項は見当たらない。', 'unknown', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_equity_rule', 'unknown', null, '大学による株式・新株予約権の取得、評価、保有、処分を定めた規程は公開情報では確認できない。機構が公開するポリシー6本（産学官連携、知的財産、国際産学官連携、研究ライセンス、利益相反マネージメント、医学研究に係る利益相反）のいずれにも出資・新株予約権の取得規定はなく、利益相反マネージメントポリシーは「未公開株式」を職員個人が得る利益の例として挙げるにとどまる。認定制度の支援項目にも株式取得は含まれない。', 'unknown', 'https://web.archive.org/web/20251113225331/https://www.scrs.yamanashi.ac.jp/overview/11/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_gap_fund', 'established', 'IJIE（JST基金事業）の起業シーズ育成資金', '起業・新規事業支援ページに「スタートアップ創出プログラム」としてIJIE（Inland Japan Innovation Ecosystem）への参画を掲げ、「スタートアップ創出プログラムの公募要項等は学内専用ページでご確認ください」と記載。IJIEは信州大学を主幹機関としてJST大学発新産業創出基金事業「スタートアップ・エコシステム共創プログラム（地域プラットフォーム共創支援）」に採択されたプラットフォームで、山梨大学は6大学の一つ。大学プレスリリース（令和6年1月15日）に「起業シーズを育成するための研究開発費の支援」と明記。学内独自のGAPファンド枠の有無・上限額は非公開。', 'official', 'https://www.yamanashi.ac.jp/46115', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_accelerator', 'unknown', null, '［自動検証で否認: IJIEの記載は59209に一切ない］元の主張(established): 起業・経営相談とIJIEの伴走支援。認定制度の支援項目4に「山梨大学に所属する教職員等が大学発ベンチャーの起業や起業後の経営等に関する相談業務に対応すること」、5に「他企業への紹介又は仲介を行うこと」と明記。大学公式ニュース（2026年7月21日）は「令和6年度には社会連携・知財戦略室に専任のスタートアップ推進マネージャーを配置し、起業を希望する研究者への支援を積極的に行っています」と記載。IJIEのプレスリリースは「ベンチャーキャピタル、アクセラレーター、金融機関、自治体との有機的な連携による伴走支援」を掲げる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 「許可制」はCOI方針本文に記載なし］元の主張(established): 兼業規程による許可制と年1回の利益相反自己申告。「国立大学法人山梨大学利益相反マネージメントポリシー」（平成16年4月1日制定、平成28年3月29日最終改正）の3(2)対象事象の第一に「国立大学法人山梨大学職員兼業規程により行う兼業活動」を挙げる。狭義の利益相反に「実施料収入、兼業報酬、未公開株式等」を含め、責務相反を兼業活動に伴う職務遂行責任の衝突と定義。手続は5でステージ1（年1回の利益相反自己申告書提出を義務化）、ステージ3（利益相反アドバイザーによる検討）、ステージ4（利益相反専門委員会が対応方策を決定）と規定。兼業規程本文は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_support_fee', 'unknown', null, '認定制度の支援項目6項目は、施設貸与、商業登記の許可、研究設備等の利用許可、相談業務、紹介・仲介、広報を列挙するだけで、対価（施設使用料、設備利用料、ライセンス料、認定手数料）の有無や算定方法には触れていない。学内手続と料金は学内専用ページ扱いのため、無償か有償かを公開情報から判定できない。', 'unknown', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_certified_count', 'unknown', null, '［自動検証で否認: 12社は3510になく他頁との合算］元の主張(established): 認定12社・一覧公開（制度発足前2社は別掲）。機構サイト「山梨大学発ベンチャー企業の紹介」が認定法人を社名・事業概要つきで一覧公開。2026年3月時点のページで認定8社（(一社)小さな水、(株)SD Global AgrtoTec Japan、(株)IHPM、(株)Taomics、(株)MIOrder、PYRUSMEDIX(株)、マイセンド(株)、ダイバーテクノロジー(株)）を掲載し、「認定制度発足前の法人」として(株)プリメドジャパン、(有)山梨臨床薬理研究所の2社を別掲。2026年6月25日の授与式で(株)ロバストエコシステム、(株)葡萄守、GPUテック(株)、(株)IoA-8Labの4社を追加認定したため、2026年9月時点の認定累計は12社と算定される。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_cert_rule', 'established', '岐阜大学発ベンチャー（認定規程・称号授与）', '「岐阜大学における大学発ベンチャーの認定等に関する規程」（平成31年4月1日岐阜大学規程第6号、令和6年5月27日岐大規程第5号まで改正）。第1条で認定及び支援に必要な事項を定め、第6条第1項で認定企業に「岐阜大学発ベンチャー」の称号を授与、第2項で称号記（別記様式第2号）の交付をもって授与する。第4条で審査委員会を設置、第10条で認定・取消しをホームページ等で公表、第14条で事務は研究推進部研究推進課が処理。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業1年以内・知財活用型・研究成果活用型', '認定規程第2条。(1)本学又は本学に勤務する機構役職員・学生が所有する知的財産権を活用する企業、(2)機構役職員又は学生（過去に役員・職員・学生であった者を含む）が本学の研究成果・習得技術を活用して起業した企業、(3)別表該当者が設立者又は設立に深く関与した企業、(4)学長が準ずると認めた企業。別表（第2条第3号関係）は役員・職員は在職6年以上、退職者は在職6年以上かつ退職から設立まで1年以内、学生は在学2年以上、卒業生は在学2年以上かつ卒業等から設立まで1年以内。年限は審査委員会が功績を認めれば不問。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_recognition_decider', 'established', '学長（岐阜大学発ベンチャー審査委員会の審査を経て決定）', '認定規程第5条。申請者は認定申請書（別紙様式第1号）で学長に申請し、学長が審査委員会に審査を付託、委員会が審査結果を学長に報告、学長が認定・不認定を決定して通知する。審査委員会細則（平成31年4月1日岐阜大学規則第21号、令和4年3月31日改正）第3条の委員は学術研究・産学官連携推進本部長、同副本部長、産学官連携推進部門長、本部運営会議委員1名、研究推進部長ほか。第5条で委員長は本部長、第6条で出席委員の3分の2以上の同意により議決。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010597.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_cert_pre_registration', 'not_started', '不可（登記簿謄本・定款の写しの添付が必須）', '認定申請書（別紙様式第1号、第5条関係）は添付資料として「登記簿謄本（発行から3月以内のもの）」「定款の写し」を掲げ、記入欄に「企業設立年月」を置く。産学官連携推進本部の公式案内も必要書類を申請書・登記簿謄本（3月以内）・定款の写し・参考資料とし、すべてを1つのPDFにしてsangaku宛に提出させる。設立予定段階の申請、認定予定通知、条件付認定の定めは規程・様式・公式案内のいずれにも無く、設立登記の完了が申請の前提になっている。', 'official', 'https://ari.gifu-u.ac.jp/sangaku/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_validity_years', 'established', '3年・2年を限度に更新可', '認定規程第6条第3項「称号の授与期間は，授与した日から3年とし，2年を限度として更新することができる」。第4項で更新希望者は授与期間末日の3ヶ月前までに称号更新申請書（別紙様式第3号）で学長に申請し、審査は新規と同じ手続を準用。称号記（別記様式第2号）にも有効期間の記載欄がある。第8条で認定企業は毎年6月末日までに前年度の活動内容報告書を学長に提出する義務。実際に期間満了した企業は公式一覧で「元岐阜大学発認定ベンチャー」として関連ベンチャー欄に移されている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_head_office_registration', 'established', '可（オープンラボ入居者・許可制・有償）', '認定規程第13条第1項第2号「前号の施設等について，認定企業の所在地とする商業登記を認めること」、同条第2項で退去時は登記を変更したことを示す書面の提出義務。TOIC岐阜サイト産学連携オープンラボ使用内規（令和5年5月17日制定、令和7年10月1日改正）第6条第2項は「産学連携オープンラボを，企業の所在地とする商業登記先として希望するベンチャー企業については，別紙様式1により，管理責任者に申請しその許可を受けなければならない」と定め、第16条第2項で使用終了時の登記変更を義務づける。無償の定めはなく有償入居が前提。', 'official', 'https://ari.gifu-u.ac.jp/file/abc6da5c8456e4cf7a239d77c30c6eb7_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_facility_lease', 'established', '産学連携オープンラボ17室・1回3年・有償', '東海国立大学機構Tokai Open Innovation Complex岐阜サイト（経産省令和3年度産学連携推進事業費補助金で整備）の産学連携オープンラボ。オフィス仕様10室、実験室仕様7室。使用期間は1回の申請につき3年、延長も1回3年まで（使用内規第10条・第12条）。使用料は月額1㎡あたりオフィス2,700円、実験室3,100円（税込）。使用資格に「東海国立大学機構におけるスタートアップの活動に資すること」を明記し、申請者区分に大学発ベンチャー企業を置く。審査は学術研究・産学官連携推進本部運営会議。別に認定規程第13条第1項第1号のオープン・スペース利用枠がある。', 'official', 'https://ari.gifu-u.ac.jp/file/4df8ec91cbb0ebe0bf4294ff8af38b8f_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_shared_equipment', 'established', '共用設備を学内料金で利用可', '認定規程第13条第1項第5号「共用設備を学内料金により使用させること」。同条は認定企業への支援を9号にわたり列挙しており、共用設備の利用は学外料金ではなく学内料金を適用する優遇として明記されている。産学官連携推進本部サイトは別途「機器共同利用サービス」への案内リンクを置いているが、料金表と認定ベンチャーの具体的な扱いは今回アクセスした範囲では読み取れていない（当該サイトは接続タイムアウト）。共用機器に関する岐阜大学独自の規程は機構規則集の現行884件を検索した範囲では見当たらない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_name_logo_use', 'established', '称号・ロゴ使用可（品質保証目的の使用は禁止）', '認定規程第6条で称号を授与し、第13条第1項第4号で「岐阜大学発ベンチャーのロゴを使用する権利を与えること」を支援に列挙。第7条第1項は製品・サービス等の内容及び品質を保証するための称号使用を禁止し、第2項は学長が不適当と認めた広告・宣伝での使用を停止できると定める。称号記（別記様式第2号）にも品質を保証しない旨と「新たな広告又は宣伝に称号を用いる場合，事前に学長に届け出てください」との注記。第9条第2項で取消後は認定の事実を事業に使用できない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_ip_license', 'established', '知財対価の現金支払を免除・軽減し株式等で受領', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則（令和2年度機構細則第61号）第2条第1項は、科学技術・イノベーション創出の活性化に関する法律第34条の4に定める成果活用事業者が各号の要件をすべて満たす場合、知的財産権等の運用・処分に係る現金による支払を免除又は軽減できると定める。第2号は「現金の支払を免除又は軽減することが成果活用事業者の経営の加速のために特に必要であること」。認定ベンチャー限定の優先実施許諾・独占実施許諾の規定は、機構発明等取扱規程と岐阜大学認定規程のいずれにも見当たらない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010858.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_equity_rule', 'established', '知財対価として株式・新株予約権取得可（50%未満）', '同細則第2条第2項で、現金支払の免除・軽減に代えて成果活用事業者が発行した株式又は新株予約権（発行価額が無償のもの）を取得できる。第3条で機構が取得できる議決権付き株式は発行済株式総数の半数未満とし、既保有分を合算する算定式を置く。第5条で当該企業との共同研究・受託研究・物品購入等の契約における利益相反防止措置を義務づけ、第6条・第7条で株式等管理事務取扱細則に基づく管理・売却と収入配分細則に基づく分配を定める。金銭出資の規程ではなく、知財の運用・処分を起点とする株式取得に限られる。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010858.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_gap_fund', 'established', 'Tongali GAPファンドプログラム（機構共通枠）', '東海国立大学機構スタートアップ支援総合サイト（岐阜大学は機構の構成大学）の2026年4月9日付お知らせで「Tongali GAPファンドプログラムに採択された研究者が、技術シーズを基に生み出したビジネスや事業構想を紹介する動画」を公開している。岐阜大学学術研究・産学官連携推進本部のベンチャーページは起業支援の窓口としてTongaliの岐阜大学ページ（起業ナビ）と機構スタートアップ統括室をリンクしている。岐阜大学単独の学内GAPファンドの規程・募集要項は、今回開いた範囲では確認できていない。', 'official', 'https://www.spo.thers.ac.jp/news/3017', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_accelerator', 'established', '機構スタートアップ統括室・ワンストップ起業相談窓口', '東海国立大学機構スタートアップ統括室規程（令和7年3月19日機構規程第71号、令和8年5月20日改正・令和8年6月1日施行）第1条で教育研究から起業・成長・国際展開までの一貫した支援を目的に統括室を設置、第2条で戦略立案と推進事業の計画・調整を所掌、第7条で人材育成部門・事業支援部門・社会実装制度対応支援部門・インテグリティ部門・渉外部門を置く。機構スタートアップ支援総合サイトに「ワンストップ起業相談窓口」。岐阜大学側はTongali（起業ナビ）でアントレ講座やぎふビジネスアイデア・プレゼンテーションを継続開催。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110011592.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: COI委員会の規定なし、岐阜職員は週6時間で相違］元の主張(established): 役員兼業は許可制（学長へ委任）・COI委員会が管理。機構役員及び職員の兼業・兼職に関する規程第5条は営利企業の役員兼業を原則不許可としつつ、大学教員等は許可を受けて技術移転事業者、研究成果活用企業、国立大学法人等出資企業の役員等を兼ねられると定める。第2条第1項第1号で岐阜大学職員に係る許可権限は岐阜大学長に委任。第13条で兼業は週平均20時間以内、第5条各号の兼業は3件まで、第12条で勤務時間を割いた分は給与を減額。認定規程第3条第4号は、機構役職員が認定を受ける場合に利益相反マネジメント規程と兼業・兼職規程等の手続・許可が適正になされていることを申請要件としている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_support_fee', 'established', '認定は無償・施設は有償（認定で減額）・設備は学内料金', '認定規程に申請手数料・認定料の定めは無い。施設はTOIC岐阜サイト産学連携オープンラボの使用料が月額1㎡あたりオフィス仕様2,700円・実験室仕様3,100円（税込）で有償。大学認定を受けた大学発ベンチャーは1㎡あたり500円、学生が代表のものは500円、両方に該当すると1,000円を軽減する。電気料は検針による実費、ガス・水道・通信は指定業者と別契約。使用内規第14条で機構所属者は負担金・機構外の者は貸付金、第15条で光熱水料、第16条で原状回復を負担。共用設備は認定規程第13条第1項第5号により学内料金。', 'official', 'https://ari.gifu-u.ac.jp/file/4df8ec91cbb0ebe0bf4294ff8af38b8f_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_certified_count', 'established', '認定7社を一覧公開・通番は第14号まで', '岐阜大学学術研究・産学官連携推進本部の公式ページ「岐阜大学発ベンチャー」に企業名・設立年・事業概要つきの一覧を掲載。2026年9月5日時点の掲載はNo.007 FiberCraze、No.008 サグリ、No.010 Gifu BioPharma、No.011 OhGooD、No.012 Vascular Works、No.013 Arrowsmith、No.014 Umai Japanの7社。認定番号は第14号まで発番され、第一号・第三号・第四号・第五号・第六号・第九号は「元岐阜大学発認定ベンチャー」として別枠の関連ベンチャー欄（30社超）に掲載。認定規程第10条がHP公表を定める。', 'official', 'https://ari.gifu-u.ac.jp/sangaku/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_cert_rule', 'unknown', null, '［自動検証で否認: 令和3年度創設の記述がkitei頁本文に無い］元の主張(established): 岡山大学発ベンチャー称号付与制度（令和3年度創設）。根拠規程は「岡山大学発ベンチャー称号授与等規程」。研究・イノベーション共創機構（ORSD）の「規程・様式」ページ内「大学発ベンチャー支援関連（学内限定）」区分に、この規程名と関連様式（様式1〜5）が明記されている。ただし本文PDFは学内限定でHTTP 403。制度は令和3年度に創設され、申請に応じて審査のうえ「岡山大学発ベンチャー」の称号を付与する。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_eligible_scope', 'established', '本学学生・教職員の起業、または研究成果活用型', '令和3年度称号授与式の大学公式記事に「本学の学生・教職員により、または研究成果を活用して起業したベンチャー企業に『岡山大学発ベンチャー』の称号を授与し」と明記。ベンチャー支援サイトも「本学教職員・学生が立ち上げたベンチャー企業」とする。卒業生・退職者の起業（退職後○年以内など）を対象に含むかどうかは、規程本文が学内限定のため公開情報では確認できなかった。', 'official', 'https://www.orsd.okayama-u.ac.jp/topics/20220207/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_recognition_decider', 'unknown', null, '［自動検証で否認: 申請窓口名は本文で「創出本部」でなく別名称］元の主張(established): 学長が称号授与・創出本部が申請窓口。令和3年度称号授与式では槇野博史学長が授与企業の代表者7人に認定盾を授与しており、称号の授与主体は学長。申請→審査の流れが公式記事とベンチャー支援サイトの双方に記載。事務局は当時の「イノベーションマネジメントコア ベンチャー支援フィールド」で、現在は「スタートアップ・ベンチャー創出本部」が相談・申請窓口。審査を行う委員会の名称・構成は公開情報になく、認定委員会内規も公開されていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_cert_pre_registration', 'unknown', null, 'ORSD規程ページに「【様式1】大学発ベンチャー届出書」と「【様式2】岡山大学発ベンチャー称号授与申請書」が別様式として並んでおり、届出と称号申請が二段構えである点までは確認できた。しかし設立登記前の申請可否、認定予定通知や条件付認定の有無を明示した公開記述は見つからなかった。様式・規程本文はいずれも学内限定でHTTP 403のため、推測を避け unknown とする。', 'unknown', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_validity_years', 'unknown', null, 'ORSD規程ページに「【様式4】岡山大学発ベンチャー活動内容報告書」「【様式5】岡山大学発ベンチャー称号・称号記返還申出書」が存在し、認定後の定期報告義務と称号返還の手続きがあることは分かる。ただし称号の有効期間（年数）や更新可否を定めた条文は、称号授与等規程本文が学内限定でHTTP 403のため確認できなかった。', 'unknown', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_head_office_registration', 'established', '可（本学貸与施設の住所・月2,200〜5,500円）', '称号のメリット3に「本学貸与施設の住所による商業登記が可能」と明記。共創イノベーションラボKIBINOVEの利用案内は「ベンチャー企業等で登記場所をKIBINOVEにしたい方」を明示的な区分として設け、①②のスペースを賃借する法人は登記用住所利用＆ポスト利用料が無料、③コワーキングスペース契約法人は2,200円/月、住所利用のみの法人・個人は5,500円/月、非会員は不可としている。料金表でも「④住所利用（スタートアップ企業の利用想定）2,200〜5,500円」と記載。', 'official', 'https://www.orsd.okayama-u.ac.jp/kigyo/kibinove/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 称号企業優遇・有償の記述が本文に無い(施設名列挙のみ)］元の主張(established): KIBINOVE等へ有償入居可・称号企業は優遇。KIBINOVE月単位貸し（税込）はドライラボ3F／レンタルオフィス4F 15〜18㎡が60,500〜71,060円、ウェットラボ2F・3F 56〜112㎡が181,500〜335,500円、コワーキングスペース4Fが24,200円。ほかに岡山大学オープンラボラトリー規程（平成16年岡大規程第46号）に基づくオープンラボA〜K（第6条で利用期間3年、延長して通算5年まで。第7条により学外者は固定資産管理規程に基づく貸付許可）、産学官融合センター、OMIC、BIZEN、岡山大インキュベータ（中小機構）が企業向けに貸出可。称号付与によりこれらの有償貸与が優遇される。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_shared_equipment', 'established', '優遇有償で本学研究設備を利用可', '称号のメリット2に「本学施設・研究設備等の優遇有償貸与・利用」と明記され、令和3年度授与式記事も「本学施設有償貸与の際の優遇」を支援内容に挙げる。KIBINOVE 2階には最先端のクライオ電子線トモグラフィーほか有償共用分析設備が配置されている。学内料金／学外料金といった具体的な料金区分の別や、大学発SU向け共用機器利用規程は公開されていない。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 認定盾交付の記述が当該URL本文に無い］元の主張(established): 称号使用可・認定盾交付／ロゴ規定は非公開。制度の本旨として「岡山大学発ベンチャー」の称号を使用でき、メリット1として本学ホームページなどでの広報・PRを受けられる。令和3年度授与式では学長から「岡山大学発ベンチャー認定盾」が交付された。様式5が「称号・称号記返還申出書」であることから称号記の返還手続きも制度化されている。一方、大学ロゴマーク・校章の使用条件を定めた規定は公開情報からは確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_ip_license', 'established', '知的財産権に関する優遇措置あり', '称号のメリット1に「知的財産に関する優遇措置」、令和3年度授与式の公式記事にも「授与企業には知的財産権に関する優遇措置」と明記されており、優遇の存在自体は公式に確認できる。ただし独占的実施許諾・対価減免・株式対価といった優遇の具体的内容は、称号授与等規程本文が学内限定のため不明。関連する公開規程は国立大学法人岡山大学職務発明等取扱規程（登録済み）。', 'official', 'https://www.orsd.okayama-u.ac.jp/topics/20220207/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_equity_rule', 'established', 'ベンチャー株式等取扱規程あり（2024年3月改正）', 'ORSD規程ページの「大学発ベンチャー支援関連（学内限定）」区分に「国立大学法人岡山大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程（2024年3月改正）」および「株式等による支払い申込書（2021年5月改正）」が掲載されている。収益を伴う事業（実施許諾等）の対価として株式等を取得する制度が整備されていることが規程名から確認できる。本文PDFは学内限定でHTTP 403のため条文は未確認。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_gap_fund', 'established', 'PSI・GAPファンド（ステップ2は最大6,000万円）', '本学はJST「START 大学エコシステム推進型」の中国・四国地域の大学発スタートアップ創出プラットフォーム「Peace & Science Innovation Ecosystem（PSI）」に参画し、PSI・GAPファンド支援プログラム（ステップ1／ステップ2）を学内公募している。ORSDサイト内検索結果に「大学発スタートアップ創出に向けた『PSI GAPファンド（ステップ2）』公募前説明会」として最大6,000万円・3年間支援と記載。個別記事ページ自体は学内限定。学内独自のGAPファンドの有無は確認できなかった。', 'official', 'https://www.orsd.okayama-u.ac.jp/?s=GAP%E3%83%95%E3%82%A1%E3%83%B3%E3%83%89', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_accelerator', 'established', '起業相談窓口V-Story＋ブートキャンプ等', '「岡大ベンチャーサポートテラスV-Story」が起業に関する学内の総合相談窓口で、在籍する学生・教職員なら誰でも何度でも相談可能。初回はスタートアップ・ベンチャー創出本部の職員が対応し、必要に応じてメンターや支援機関を紹介する予約制。ほかに学生チーム向けの「おかやまテックガレージ」（GOB株式会社が伴走、自然科学系総合研究棟6階オープンラボC）、アントレプレナーブートキャンプ、MoAP（ももスタ・アクセラレータープログラム）等が案内されている。', 'official', 'https://venture.okayama-u.ac.jp/consultation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: 「兼業規程」に該当する記述が本文に無い］元の主張(established): 兼業規程・利益相反マネジメント規程で対応。ORSD規程ページに利益相反マネジメント規程、同ガイドライン、利益相反マネジメント委員会関係文書、個人／組織の利益相反に関する文書が公開されている。教職員の営利企業役員兼業は登録済みの国立大学法人岡山大学職員兼業規程が学長承認制で定める。ただし大学発ベンチャーの役員兼業に特化した公開規程は確認できず、称号制度と利益相反審査の接続を明記した公開記述も見つからなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 起業相談無償の記述が当該URL本文に無い］元の主張(established): 施設・設備は有償（優遇料金）・起業相談は無償。称号のメリットが「本学施設・研究設備等の優遇有償貸与・利用」と明記されており、施設・設備の利用は有償が前提で、称号付与により料金が優遇される建て付け。KIBINOVEの料金表（ラボ・オフィス月60,500〜335,500円、コワーキング24,200円、住所利用2,200〜5,500円）のとおり実費負担が発生する。起業相談窓口V-Storyの相談は無料。称号付与自体に手数料が生じるかどうかの公開記述はない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_certified_count', 'established', '13社・一覧公開（大学発SUは別途50社超）', '称号付与企業一覧ページに13社を掲載（そなえ、ABABA、粒子線医療研究所、TechSword、ビジュアルサーボ、Stork Visit、フルエリア、ハイドロヴィーナス、Redge、Corvus Securitas、Medswell、健康科学評価アカデミー、L-Create）。HTMLの表行を数えて13社を確認。初年度の令和3年度は申請のあった6社に授与。同ページに「称号付与に限らず、岡山大学発のベンチャー企業は50社を超えて活動中」との記載があり、称号付与企業と大学発ベンチャー全体は別集計。', 'official', 'https://venture.okayama-u.ac.jp/title_company_list/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_cert_rule', 'established', '川崎医科大学発ベンチャー支援に関する規程（称号付与）', '産学連携知的財産管理室の「川崎医科大学発ベンチャー」ページが起業手続きを案内し、様式一式を公開。様式1「大学発ベンチャー支援申請書」は学長宛で、「１．支援希望内容」(1)に称号「川崎医科大学発ベンチャー」又は「川崎学園発ベンチャー」を掲げる。様式3「大学発ベンチャー事業報告」本文に「川崎医科大学発ベンチャー支援に関する規程により」と記載があり、根拠規程名を確認した。規程本文PDFは学外非公開（「規程・ポリシー」ページは学内専用で401）。認定という語ではなく「支援申請・支援決定」の建て付け。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_eligible_scope', 'established', '教職員の関与が前提（資格区分は兼業規程第2条4号）', '様式1「大学発ベンチャー支援申請書」は申請者欄（会社名・代表者氏名㊞・所在地）と並べて「関係する教職員　所属・職名／氏名㊞」の記名押印欄を置き、教職員の関与を前提としている。様式1（第5条関係）「大学発ベンチャー兼業許可申請書」の⑩欄が「大学発ベンチャーの申請資格　規程第2条第（1・2・3・4）号」となっており、資格が4区分に分かれる構成までは確認できたが、各号の内容（学生・卒業生・退職後年数・知財活用型の別）は規程本文が非公開のため不明。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_2.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_recognition_decider', 'established', '学長決裁（支援決定通知は学長名）', '様式1「大学発ベンチャー支援申請書」と様式3「大学発ベンチャー事業報告」はいずれも「川崎医科大学　学長殿」宛。様式2「大学発ベンチャー支援決定申請書」は「川崎医科大学　学長㊞」名義で「下記のとおり支援の可否を決定しましたので通知します」とし、支援決定／不支援と不支援理由を通知する形式。よって決裁者は学長。審査を担う委員会（認定委員会等）の記載は公開資料になく、審査体制は不明。実務窓口は産学連携知的財産管理室。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_cert_pre_registration', 'not_started', '不可（履歴事項全部証明書の添付が必須）', '様式1「大学発ベンチャー支援申請書」の「３．添付書類」は(1)履歴事項全部証明書、(2)定款、(3)会社概要、(4)事業計画、(5)利用する知的財産権・研究成果の概要、(6)その他学長が指定した資料等を列挙する。(1)は設立登記後でなければ取得できず、申請者欄も会社名・代表者氏名㊞・所在地の記入を求める。設立予定段階での申請、認定予定通知、条件付認定にあたる仕組みは様式にも公開ページにも置かれていない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_validity_years', 'established', '支援期間は最長2年（更新可否は未公開）', '様式1に「２．支援期間（最長２年を限度）　年　月　日　～　年　月　日」と明記されており、支援には上限2年の期限がある。更新・再申請の可否、期間満了後の称号使用の扱いは様式・公開ページに記載がなく不明。期間中は様式3「大学発ベンチャー事業報告」により年度毎に事業報告書と収支決算書の提出を求める。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_head_office_registration', 'established', '可（施設・設備の使用期間中に限り本学所在地）', '様式1「１．支援希望内容」(4)に「本学施設・設備の使用期間中の限り、登記住所を本学所在地とする。」の希望有無チェック欄があり、学内住所での商業登記を支援メニューとして正面から認めている。ただし対価（無償か有償か）と対象建物の記載はなく、(2)の施設・設備の使用が前提条件で、支援期間が最長2年であるため登記住所の維持も同期間に限られる。付帯事項に「審査の結果、希望に添えない場合もあります」と留保がある。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_facility_lease', 'established', '本学施設の使用（支援メニューに明記）', '様式1「１．支援希望内容」(2)「本学施設・設備の使用」に希望有無のチェック欄がある。使用期間は支援期間（最長2年）に連動し、(4)の登記住所の特例も「本学施設・設備の使用期間中の限り」と規定される。インキュベーション施設の名称、貸与する部屋の種別、使用料の有無・金額は公開資料に記載がなく不明。付帯事項に「審査の結果、希望に添えない場合もありますので予めご承知おきください」とあり、希望が通る保証はない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_shared_equipment', 'established', '本学設備の使用（料金区分は未公開）', '様式1「１．支援希望内容」(2)が「本学施設・設備の使用」と施設と設備を併記しており、支援決定を受けたベンチャーは学内設備を使用できる。ただし中央研究センター（動物資源分野、分子細胞生物分野、イメージング分野、中央研究センターGMCの4ユニット）の公開ページは各分野の概要のみで、共用機器の学外利用可否、学内料金と外部料金の区分、利用申請手続はいずれも学内限定ページ側にあり公開情報から確認できない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_name_logo_use', 'established', '称号は大学発・学園発の2種から選択', '様式1「１．支援希望内容」(1)「大学発ベンチャーの称号：「川崎医科大学発ベンチャー」又は「川崎学園発ベンチャー」」に希望有無のチェック欄がある。大学名だけでなく設置法人である学校法人川崎学園名義の称号も選べる点が特徴。大学ロゴ・校章・シンボルマークの使用条件については様式にも公開ページにも記載がなく不明。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_ip_license', 'established', '知的財産権・ノウハウ使用の優遇措置', '様式1「１．支援希望内容」(3)が「本学が所有する知的財産権、ノウハウ等の使用に関する優遇措置」で、希望有の場合は内容と知的財産名称等を記載させる。添付書類(5)にも「利用する知的財産権、研究成果の概要」を求める。優遇の中身（独占的実施許諾の可否、実施料の減免、株式対価の可否）は規程本文が非公開で不明。知的財産ポリシー（令和2年6月8日施行）は職務発明の認定と権利承継、発明者への補償と実施料配分を定めるが、ベンチャー向けの個別条項は掲載されていない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_equity_rule', 'unknown', null, '大学がベンチャーの株式・新株予約権を取得する規程は公開情報から確認できなかった。様式1の支援希望内容(1)〜(4)にも出資・株式取得は含まれない。利益相反マネジメント規程（2023年9月1日改正）第3条(1)は「企業等から一定額以上の金銭もしくは株式等を取得する場合」を教職員側の利益相反マネジメント対象とする規定であって、大学の出資規程ではない。産学官連携ポリシー・知的財産ポリシーにも出資条項は見当たらない。', 'unknown', 'https://m.kawasaki-m.ac.jp/kenkyu/riekisouhan/document/kitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_gap_fund', 'unknown', null, '学内GAPファンド、起業準備資金、POC資金にあたる制度は公開情報から確認できなかった。「助成金・WishList」ページは学外の民間財団による研究助成の公募一覧と、機関管理で受け入れる場合に助成金額の20%を管理費として控除する旨を掲載するのみで、起業向けの学内資金制度の記載はない。様式1の支援希望内容(1)〜(4)にも資金提供は含まれないが、(5)「その他の希望」という自由記載枠があるため、制度として存在しないと断定はできない。', 'unknown', 'https://m.kawasaki-m.ac.jp/sanchi/jyosei.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 教員4名等の体制情報が典拠URL本文に無い］元の主張(established): 産学連携知的財産管理室が起業相談・申請窓口。「川崎医科大学発ベンチャー」ページに「大学発ベンチャーの起業について問合せは産学連携知的財産管理室までご連絡ください」と窓口が明示され、内線番号とメールアドレスを掲載している。同室は2016年発足で担当教員4名（兼務）、知財コーディネータ1名（専任）、事務職員3名（専任）の体制、発明相談も受け付ける。2017年から医学・医療・福祉・健康科学の展示会「KMSメディカル・アーク」を自ら主催しシーズとニーズのマッチングを行う。一方、期間を区切ったアクセラレーションプログラムやメンタリング制度は公開情報になく、伴走支援の型までは確認できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: COI委員会審査の根拠URLが無い(規程本文未提示)］元の主張(established): 役員兼業は学長許可制・COI委員会が審査。起業時の提出書類として「大学発ベンチャー兼業許可申請書」を求め、その本文に「川崎医科大学　大学発ベンチャー企業起業にかかる兼業に関する規程第５条に基づき、下記のとおり兼業の申請をいたします」と明記。申請は学長宛で、兼業職名、兼業内容、所定労働時間内の兼業の有無と週あたり従事時間、報酬の有無と金額まで記載させる。別途、利益相反マネジメント規程（2023年9月1日改正）第3条(1)が一定額以上の金銭・株式等の取得を対象とし、第11条で申告義務、第12条で利益相反委員会が審査して回避の助言・勧告を行う。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_support_fee', 'unknown', null, '支援の対価に関する記載が公開資料にない。様式1は支援希望内容、支援期間、添付書類、付帯事項（支援を受けたことにより生じた損失・損害について大学は責任を負わない旨）を定めるのみで、施設使用料、設備使用料、実施料、申請手数料のいずれについても有償無償の別や金額を示していない。共同研究・受託研究では直接費×20%の一般管理費、外部助成金の機関管理では助成金額の20%控除を求めるが、いずれも大学発ベンチャー支援の対価ではない。', 'unknown', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_certified_count', 'established', '1社（株式会社クロバーナ）を公開', '「川崎医科大学発ベンチャー」ページの「川崎医科大学発ベンチャー」欄に株式会社クロバーナ1社のみを社名と外部リンク付きで掲載している。累計の支援決定社数、認定年、過去の企業を示す一覧や年次統計の公開はなく、公開されている実績はこの1社にとどまる。同社サイトはアクセス制限（406）で本文を確認できなかったため、社数の根拠は大学ページの掲載のみ。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/venture.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_cert_rule', 'established', '広島大学知的財産利用ベンチャー企業認定（要項に基づく）', '「ベンチャー企業に対する大学知的財産利用認定に関する要項」(2015年5月12日 理事・副学長決裁、令和2年8月5日施行・令和2年4月1日適用)第1条が「広島大学知的財産利用認定」を定める。様式第1号の名称は「広島大学知的財産利用ベンチャー企業 認定申請書」。第1条は「本認定により、企業による本学知的財産の利用や、利用に当たっての優遇措置の適用を円滑に行うことができる」とする。全8条を通読したが「○○大学発ベンチャー」といった称号を付与する条項はなく、知財の利用と優遇を通すための認定である。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_eligible_scope', 'established', '大学知財の利用を予定する企業。教職員・学生・退職者が対象', '要項第3条「大学知的財産の利用を予定し、本学から利用許諾あるいは権利譲渡等を受けることを希望する企業」。第4条第2項で申請者が教職員の場合は所属部局長を経由。起業計画書の様式に「（学生の場合）指導教員名」欄があり学生の申請を想定。技術移転細則第6条と職務発明規則第19条は「職員等が退職又は兼業によりベンチャー企業を設立し」た場合を優遇対象とし、退職者を明記。職務発明規則第2条第2号ニは学生・ポストドクターも「職員等」に含む。卒業後○年以内といった期限の定めはない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181968/%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E8%B5%B7%E6%A5%AD%E8%A8%88%E7%94%BB%E6%9B%B820200401.doc', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_recognition_decider', 'established', '学長（学術・社会連携室発明審査会に諮り決定）', '要項第4条は認定申請書及び起業計画書を理事（学術・社会連携担当）を経て広島大学長に提出すると定める。第5条「学長は、前条の申請があったときは、広島大学学術・社会連携室発明審査会に諮り、企業が広島大学の知的財産を利用することの有効性及び妥当性を評価して、認定の可否を決定する」。第7条の取消も発明審査会の判定に基づき学長が行う。発明審査会は職務発明規則第8条第1項が置く常設の審査会で、認定専用の委員会ではない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_cert_pre_registration', 'established', '可（設立予定日で申請、登記簿謄本の提出規定なし）', '認定申請書（様式第1号、第4条関係）の本文が「広島大学の知的財産を利用（を予定）するベンチャー企業設立に当たって…認定を受けたいので、下記の通り申請します」とし、記入欄に「企業設立（予定）日」を置く。起業計画書にも「企業等の名称（予定）」「企業等設立時期（予定）」「資本金（予定）」「従業員数（予定）」欄がある。要項第1条も対象を「知的財産の活用を予定して設立されるベンチャー企業」と書く。登記簿謄本の添付を求める条項は要項・様式のいずれにもない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181969/%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E8%AA%8D%E5%AE%9A%E7%94%B3%E8%AB%8B%E6%9B%B820200401.doc', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_validity_years', 'established', '有効期間・更新の定めなし（第7条の取消規定のみ）', '要項全8条＋附則を通読した結果、認定の有効期間・期限・更新に関する条項は存在しない。認定の終了に関する定めは第7条（認定の取消し等）だけで、社会的信用を失墜する行為、契約違反により本学に損害を与えた場合等に発明審査会の判定を経て学長が取り消す。第8条は「この要項に定めるもののほか、この要項の実施に関し必要な事項は、別に定める」とするため、学内細則で運用期限が置かれている可能性は残るが、その細則は公開されていない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_head_office_registration', 'unknown', null, '学内住所を会社の本店所在地として商業登記できるかを述べた公開資料は見つからなかった。関連する枠組みとして、広島大学における教育・研究施設の有効活用に関する規則第8条が「本学の職員又は学生以外の者（学外者）が産学連携使用スペースの使用を許可されたときは、広島大学財務会計処理細則の定めるところにより不動産の使用の許可を得なければならない」と定め、学外法人が学内不動産の使用許可を受ける経路自体は存在する。ただし同細則は公開規則集に収録がなく、登記の可否は確認できない。', 'unknown', 'https://public1.legalcrud.com/hiroshima_univ/act/110000216.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_facility_lease', 'established', 'インキュベーションオフィス14室、有償、原則3年', '大学発ベンチャーのページに、東広島地区9室（53㎡×7室、28㎡×1室、25㎡×1室）、広島地区の霞キャンパス総合研究棟5室（41㎡×4室、26㎡×1室）、料金は年1㎡当たり1万円（東広島）・2万円（広島）、入居期間は原則3年を超えない、例年12月上旬に学内公募し翌年4月使用開始と明記。根拠規則は広島大学における教育・研究施設の有効活用に関する規則で、第5条第1項第3号の産学連携使用スペースが「本学の研究成果を活用した事業を行う者」を対象とし、第6条が原則3年、第10条が再申請による継続を定める。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_shared_equipment', 'established', '共用機器を学外者料金で利用可（規則別表に料金区分）', '広島大学共用機器に関する規則（令和2年10月23日規則第212号、令和8年6月30日規則第43号まで改正）第8条が利用者の範囲を「大学連携研究設備ネットワークに利用者登録している者」「その他理事（研究担当）が適当と認める者」とし、学外法人の利用を認める。第14条と別表が機器ごとに学外者・学内者の料金を分けて定め（例：SQUID帯磁率測定装置は学外8,400円／時間、学内2,800円／時間）、学外者はおおむね学内者の2〜3倍。認定ベンチャー向けの割引区分は別表にない。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110001063.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_name_logo_use', 'established', '学章は営利目的なら許可制＋使用契約。称号の定めなし', '広島大学学章使用細則（平成25年9月27日理事決裁）第2条第1項第6号が「理事が学章の使用を認めた団体等が使用する場合」を挙げ、第3条第1項が「営利を目的として学章を使用する者は、広島大学学章使用許可願を理事に提出し、許可を得なければならない」、同第3項が「使用許可を得た者は、別途使用の契約を本学と締結する」と定める。第4条は本学の名誉を傷つけるおそれがあるときの許可取消を規定。認定要項には称号の付与や「広島大学発ベンチャー」の名称使用に関する条項はない。［検証エージェントは出典を開けず未照合］', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000668.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_ip_license', 'established', '低率の独占的通常実施権、設立3年まで実施料免除', '広島大学技術移転細則第6条（ベンチャー企業の支援）「職員等が退職又は兼業によりベンチャー企業を設立し、自らの発明等に基づく知的財産権を活用して研究成果の普及を推進する場合は、当該ベンチャー企業に対し…出願手続及び維持管理に要した権利化費用（直接経費）を目安とした有償による譲渡、低率な実施料による独占的通常実施権の許諾、当該ベンチャー企業の設立から3年を上限とする実施料の免除等を行うことができる」。第3条は第三者への実施権許諾等を原則有償とするため、第6条は明示的な例外。職務発明規則第19条も同趣旨の特例を置く。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000109.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_equity_rule', 'established', 'ライセンス対価としての株式・新株予約権取得、寄附受入も可', '広島大学におけるライセンス等の対価として取得する株式等取扱細則（平成29年2月21日理事決裁、令和7年1月10日改正）第3条が、相手がベンチャー企業で対価の現金支払が困難な場合に株式・新株予約権で取得できると定める。第4条で発明審査会が財務状況等を審査、第5条で理事が取得を決定、第6条で行使可能時に速やかに行使、第7条で公開後速やかに売却、第8条で経営参加権は原則不行使。別に広島大学株式等による寄附金取扱規則（令和元年10月1日規則第167号）が株式等受入審査会を置き、寄附としての受入も可能。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000832.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_gap_fund', 'unknown', null, '大学発ベンチャーのページと「ベンチャービジネスの創出・育成支援」ページに掲載された支援メニューは、起業相談窓口、インキュベーションオフィス、知的財産活用支援、起業マニュアル・立上げ支援手引書、学外制度の紹介であり、学内GAPファンド・起業準備資金・POC資金の記載はない。公開規則集（537件の目録）にも該当する規程は見当たらなかった。紹介されている資金は学外の「ひろしまベンチャー助成金」（公益財団法人ひろしまベンチャー育成基金）のみ。制度が無いと明記された文書は確認できていないため unknown とする。', 'unknown', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_accelerator', 'established', 'スタートアップ推進部門の起業相談窓口と起業家教育科目', '「ベンチャービジネスの創出・育成支援」ページが「起業に関するご相談」窓口としてスタートアップ推進部門（TEL 070-1542-7123）を明示し、MOT教育・アントレプレナーシップ養成、ひがしひろしま創業塾の開催を挙げる。アントレプレナー教育ページは、同部門が教養科目「アントレプレナーシップ」「MOT教育」「イノベーション演習」、社会人と学ぶ「ひろしまアントレプレナーシッププログラム」、海外学生と学ぶ「国際夏の学校」を提供すると記す。期別採択のコホート型アクセラレーションプログラムの公表はない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/vbl', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_coi_sidejob', 'established', '研究成果活用企業の役員兼業は例外許可、専門審査会あり', '広島大学職員兼業規則（平成16年4月1日規則第89号、令和3年4月1日施行改正）第4条第1項は営利企業の役員等兼業を原則不許可としつつ、ただし書で「技術移転事業者の役員等」「研究成果活用企業の役員等」（いずれも監査役・社外取締役を除く）を例外とする。同条第2項は許可に当たり営利企業役員等兼業審査会の意見聴取を義務づける。第2条の許可基準が「職員と兼業先との間に特別な利害関係がなく、又はその発生のおそれがな」いことを求め、利益相反審査を組み込む。第10条で許可期間は原則2年以内、第12条で週の兼業時間は原則15時間が上限。別に広島大学利益相反管理に関する規則がある。［検証エージェントは出典を開けず未照合］', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000154.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_support_fee', 'established', '認定申請は無償、施設・機器は有償、実施料は3年免除', '認定要項には申請手数料・認定料の条項がなく、認定自体に費用の定めはない。一方で支援メニューは有償が基本で、インキュベーションオフィスは年1㎡当たり1万円（東広島）・2万円（広島）、共用機器は共用機器に関する規則別表の学外者料金、知財は技術移転細則第3条により実施権許諾・譲渡が原則有償。ただし同細則第6条により設立から3年を上限に実施料を免除でき、譲渡対価も権利化に要した直接経費が目安。施設有効活用規則第9条第1項ただし書は学長が認めた場合の使用料免除も認める。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_certified_count', 'established', '累計116社（2026年4月1日現在）、一覧PDF公開', '「広島大学発ベンチャー起業実績」ページに「令和8年4月1日現在、累計116社の広島大学発ベンチャー企業が設立されています」と記載され、「0101_2025_大学等発ベンチャー状況（大学案内用）.pdf」（1.45MB）で一覧を公開。ただしこの116社は設立された大学発ベンチャーの累計であり、知的財産利用認定を受けた社数ではない。認定社数は公表されていない。掲載は起業した教職員・学生からのフォーム自己申告で収集している。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyouzisseki', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_cert_rule', 'established', '徳島大学発ベンチャー認定制度（規則第21号）', '「国立大学法人徳島大学における大学発ベンチャーの認定に関する規則」（平成28年10月19日規則第21号制定、令和3年7月29日規則第13号改正・令和3年8月1日施行）をPDF全文で確認。第1条は大学発ベンチャーの円滑かつ適正な支援を図ることを趣旨とし、第5条で学長が称号記（別記様式第2号）により「徳島大学発ベンチャー」の称号を授与すると定める。認定番号が付される（様式第2号「認定番号 第 号」）。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・研究成果活用型', '第2条が4号を列挙。(1)本学又は本学の役職員若しくは学生が所有する知的財産権を基に設立したもの、(2)退職・卒業・修了から設立までの期間が3年以内の者が所有する知的財産権を基に設立したもの、(3)本学で達成された研究成果又は習得した技術等を基に設立し、国立大学法人法第22条第1項第5号の業務遂行に寄与すると本学が認めたもの、(4)職員等が設立者となるもの又は設立に深く関与しているもの。第4条第5号で学生が設立したものは本学教職員からの推薦が必要。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_recognition_decider', 'established', '学長（産官学連携センター会議の議）', '第3条第1項で申請者が大学発ベンチャー認定申請書（別記様式第1号）を学長に提出。第2項で学長は徳島大学研究支援・産官学連携センター会議の議を経て認定を決定し、第3項で文書により通知する。第4項でセンター長は審議に際しセンター会議の委員以外の者に意見を求め、又は申請者への面接を行うことができる。第10条で認定事務は研究・産学連携部常三島研究・産学支援課が処理。第8条の取消しもセンター会議の議を経る。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_cert_pre_registration', 'not_started', '不可（登記簿の写しが添付必須）', '第2条の各号がいずれも「設立したもの」を対象とし、別記様式第1号の添付資料に「登記簿の写し」「定款，寄付行為，規則又は規約の写し」が必須と明記されている。様式の記載事項も「６(2)設立日」を求める。認定制度ページ（tokudai-venture-seido.html）の申請方法も同じ5点を必要書類として挙げる。設立登記前の申請、認定予定通知、条件付認定を認める規定は規則本文にも様式にも置かれていない。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_validity_years', 'established', '称号は原則永年・施設等支援は設立後5年', '第5条第2項「「徳島大学発ベンチャー」の称号は，原則として永年使用することができる」。更新手続の定めは無く、第7条の解除申出（別記様式第3号）か第8条の取消し（定義からの著しい逸脱、社会的信用の失墜、事業報告書等の不提出、解散・破産等の報告）で終了する。一方、第9条第2項で施設貸与・商業登記・研究設備利用の支援は設立の日から5年間を限度とし、学長が必要と認めた場合は延長できる。第6条で年度毎に決算日から3か月以内の事業報告書等の提出義務。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_head_office_registration', 'established', '可（貸与施設を所在地とする商業登記）', '第9条第1項第2号「貸与した施設について，当該認定大学発ベンチャーの所在地とする商業登記を認めること」。同項第1号の施設貸与を受けていることが前提となる。第2項により設立の日から5年間が限度（学長が必要と認めた場合は延長可）。第3項で支援は本学における関係規則等によるとされ、有償無償は施設側の使用料規定に従う。認定規則が支援メニューとして明文で商業登記を認めている点が特徴。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_facility_lease', 'established', '学内施設貸与・研究室は年6,000円/㎡・3年以内', '認定規則第9条第1項第1号で「事務室又は研究室として本学内の施設を貸与すること」、第2項で設立の日から5年間を限度（延長可）。実際の施設は地域共同インキュベーション研究室・ベンチャービジネス育成研究室で、研究支援・産官学連携センターの研究室ページに使用料 年間6,000円/㎡、入居期間3年以内、利用代表者は徳島大学教員に限る旨と、大学発ベンチャーは「不動産貸付申請書」で申請する旨が記載されている（教員は「研究室利用申請書」）。', 'official', 'https://www.tokushima-u.ac.jp/ccr/active/venture/kenkyusitsu.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_shared_equipment', 'established', '研究設備等の利用許可（設立後5年まで）', '認定規則第9条第1項第3号「研究設備等の利用を許可すること」。第2項で設立の日から5年間が限度（学長が認めれば延長可）、第3項で本学における関係規則等によるとされる。研究室ページには2〜3階にJSTが整備した徳島地域産学官共同研究拠点があり共用の研究機器・設備を備える旨の記載がある。認定ベンチャーに適用される料金区分（学内料金か外部料金か）を示す公開資料は、今回開いた範囲では確認できなかった。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_name_logo_use', 'established', '称号は永年使用可・大学名義使用は許可制', '認定規則第5条で学長が称号記により「徳島大学発ベンチャー」の称号を授与し、第2項で原則として永年使用できる。第8条第3項は取消しを受けた者は称号記を返付し、以降は認定を受けていた事実を事業に使用してはならないと定める。大学名・ロゴ側は「国立大学法人徳島大学又は徳島大学における名義使用に関する要項」（令和2年7月21日学長裁定）と「営利目的での大学名義使用に関する承認ガイドライン」があり、名義使用許可申請書（第6条第2項関係）による許可制（知財法務の大学名義使用ガイドラインページで確認）。', 'official', 'https://www.tokushima-u.ac.jp/ccr/active/ip/meigi/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_ip_license', 'established', '実施権設定等の対価を株式等で受領可', '「認定大学発ベンチャーから本学の収益を伴う事業の対価として取得する株式等取扱規則」（令和6年3月27日規則第90号、令和7年4月1日施行）第2条第2号が、知的財産権の譲渡・提供・実施権設定、学術指導の提供、研究成果有体物の提供、施設・設備等の資産貸与の対価を、現金に代えて株式等で受け取る対象事業として列挙する。認定大学発ベンチャー限定の優遇。優先的実施許諾や実施料の減免を定めた明文は、認定規則第9条の支援列挙にも職務発明規則にも見当たらなかった。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000834.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_equity_rule', 'established', '株式等取扱規則あり（令和6年規則第90号）', '同規則第2条第3号が株式等を「株式、新株予約権及び新株予約権付社債」と定義。第3条で(1)当該認定大学発ベンチャーの事業の有望性が高いこと、(2)現金支払の免除が経営加速に特に必要であること、(3)反社会的勢力との関係がない等信用度に問題がないこと、の3要件を課す。第6条第1項で学長が知的財産専門委員会の審査結果に基づき取得の可否を決定。第7条で発明者への補償金は当該株式等を換金し収入を得た場合に支払う。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000834.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_gap_fund', 'established', 'PSI GAPファンド（起業ハンドブック掲載）', '徳島大学起業ハンドブック（TU STARTUP HANDBOOK、発行：研究支援・産官学連携センター）chapter2-04「使える助成金、外部資金のご案内」に「PSI GAPファンド」が項目として掲載。Peace & Science Innovation Ecosystem のビジョン実現のため「GAPファンドの構築、支援人材の拡充、起業環境の整備、グローバル拠点の構築などを行っていきます」と記載。同章には産学連携キャピタル（産学連携1号ファンド 約10億円）、NEDO NEP、クラウドファンディングOtsucleも並ぶ。金額・上限・公募要領はハンドブック内に記載が無く、学内公募事業ページにも掲載されていなかった。', 'official', 'https://www.tokushima-u.ac.jp/ccr/file/venture/TU-STARTUP-HANDBOOK.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_accelerator', 'established', '大学産業院 スタートアップスタジオU-tera', '起業ハンドブック chapter2-01。学長直轄の大学産業院にスタートアップスタジオU-teraが置かれ、弁理士・弁護士・デザイナー・戦略コンサルタント等の専門家が在籍し「実際に投資が受けられるまで伴走支援が可能」と記載。ファーストステップ／セカンドステップ／ファイナルステップ（支援終了）の3段階で到達要件（PoCができるMVPの完成、投資が受けられる状態等）を定義。chapter3で事業相談・設立準備の窓口をU-tera（088-656-7248）、知財・利益相反相談を研究支援・産官学連携センター、兼業相談を人事課と明示。', 'official', 'https://www.tokushima-u.ac.jp/ccr/file/venture/TU-STARTUP-HANDBOOK.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_coi_sidejob', 'unknown', null, '［自動検証で否認: source_urlは職員兼業規則、利益相反委員会の記載なし］元の主張(established): 役員兼業は学長許可制・利益相反委員会が審査。認定規則第4条第4号が、教職員が設立したものは職員兼業規則（平成16年度規則第17号）と利益相反管理規則（平成26年度規則第22号）に定める所要の手続・許可が適正になされていることを申請条件とする。職員兼業規則（平成16年4月1日規則第17号）第2条で学長の事前許可制、第6条で営利企業の役員兼業を許可対象（技術移転事業者・研究成果活用企業の役員等）として限定列挙。利益相反管理規則は徳島大学利益相反委員会を置き、兼業・報酬・株式保有等を管理対象とする。センター規則第4条第1項第6号で大学発ベンチャーへの役員兼業の利益相反審査は知財法務部門が担当。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_support_fee', 'established', '認定は無償・施設は有償（年6,000円/㎡）', '認定規則に認定手数料の定めは無く、認定と称号授与自体は無償。第9条第3項で支援は本学における関係規則等によるとされ、施設は有償。研究室ページに使用料 年間6,000円/㎡（学外機関は要問合せ）と記載。徳島大学研究支援・産官学連携センター施設管理規則（平成27年4月1日センター長制定）第8条第1項は、施設利用責任者がセンター以外の研究者等である場合は別に定める使用料及び光熱水料等の経費を負担すると定め、第2項で施設管理責任者が特に必要と認めたときは全部又は一部を免除できるとする。', 'official', 'https://www.tokushima-u.ac.jp/ccr/active/venture/kenkyusitsu.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_certified_count', 'established', '33社・一覧公開（2026年5月11日現在）', '「徳島大学発ベンチャー企業一覧」ページで2026年5月11日現在の認定企業33社を、認定番号・企業名・認定年月日つきで公開。認定番号は第1号（ナイトライド・セミコンダクター株式会社、2016年12月20日）から第43号（合同会社健康運動げんきLabo、2025年11月18日）まで付番され、掲載は33社で番号に欠番がある。2025年以降の新規認定は第38号〜第43号の6社。', 'official', 'https://www.tokushima-u.ac.jp/ccr/active/venture/tokudai-venture_.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_cert_rule', 'established', '慶應義塾大学関連スタートアップ制度（定義のみ、認定は行わない）', 'イノベーション推進本部スタートアップ部門が運用する「慶應義塾大学関連スタートアップ制度」。同ページは「本制度は支援対象企業等を定義することを目的としており、慶應義塾大学によるスタートアップの認定やその信用保証をするものではありません」と明記する。称号付与・認定証・申請様式の仕組みは無く、大学が支援対象企業を主体的に定義する枠組み。根拠となる学内規程名は公開されておらず、研究連携推進本部の規程集・ガイドライン一覧にも認定規程は掲載されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_eligible_scope', 'established', '技術移転・共同研究・人材供給・出資・起業支援ほか6要件のいずれか', '同ページ「関連スタートアップの定義」。①技術移転（慶應義塾の知的財産権の譲渡または実施許諾を受けている）②共同研究（慶應義塾との共同研究・委託研究の実績）③人材供給（慶應義塾に在籍、または在籍した教職員・学生が創設メンバーや科学技術顧問）④資金調達（慶應義塾または株式会社慶應イノベーション・イニシアティブ等の出資）⑤起業支援（慶應義塾の起業支援を受けている）⑥その他慶應義塾との関連が認められるもの。卒業・退職後の年数制限は付されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_recognition_decider', 'unknown', null, '［自動検証で否認: 推進本部規程第3条・第4条が本文に無い］元の主張(not_started): 認定・審査の手続きなし。主管はイノベーション推進本部。制度ページが「認定やその信用保証をするものではありません」と明記し、6要件のいずれかに該当するかで定義されるだけで、申請・審査・決裁の手続きは置かれていない。制度運営のハブはイノベーション推進本部スタートアップ部門（慶應義塾大学イノベーション推進本部規程第3条第3項が同部門の所掌を規定、第4条で統括本部長は研究担当常任理事）。支援プログラムKSIPの採否のみ、運営部門による書類・対面審査で決定される。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_cert_pre_registration', 'established', '認定申請なし。KSIPは法人設立予定の段階でも応募可', '関連スタートアップ制度には申請手続きが無い。起業支援プログラムKSIPの募集要件は「法人設立済又は法人設立予定で、VC等からのエクイティファイナンスをまだ実施していないこと」とされ、設立登記前のグループを明示的に対象に含む。KSIP助成金も応募主体は慶應義塾大学に在籍する教職員（特任・研究員含む）または学生で、法人格を要件としていない。', 'official', 'https://innov.keio.ac.jp/startup/support/ksip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_validity_years', 'not_started', '認定を行わないため有効期間・更新の定めなし', '制度ページが「慶應義塾大学によるスタートアップの認定やその信用保証をするものではありません」と明記しており、認定という行為自体が存在しないため、有効期間・更新・取消の規定も置かれていない。定義6要件への該当で判断される仕組みで、期限や再審査に関する記載は公開情報に無い。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_head_office_registration', 'established', 'CRIK信濃町で登記可（賃貸オフィス・専用デスク会員の有料オプション）', '慶應義塾大学信濃町リサーチ＆インキュベーションセンター（CRIK信濃町、東京都新宿区信濃町35 信濃町キャンパス2号館9階）の会員プラン比較表に「登記」行があり、賃貸オフィス会員・専用デスク会員は「オプション（有料）」、ラウンジ会員は「なし」。ページ下部の「有料オプション設備」一覧にもラウンジ・会議室・テレカンブースと並んで「登記」が挙がっている。利用条件は慶應義塾大学の研究・教育に由来するシーズを持つスタートアップ、慶應義塾大学関連スタートアップ、起業を考える個人・団体等。', 'official', 'https://crik.keio.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: SFC-IV・入居企業6社が本文に無い］元の主張(established): CRIK信濃町（賃貸オフィス29室・専用デスク26席）とSFC-IV。CRIK信濃町は賃貸オフィス29室、デスクルーム26席、ラウンジ、会議室3部屋、データアクセスルーム、テレカンブース6箇所を備える会員制施設で、家具付きセットアップオフィス、ラウンジを除き24時間利用可。入居スタートアップ21社と入居企業6社を公開。ほかに慶應藤沢イノベーションビレッジ（SFC-IV）を中小企業基盤整備機構・神奈川県・藤沢市と連携運営しインキュベーションマネージャーを配置、矢上キャンパスにはYIL（矢上イノベーションラボラトリー）。賃料額・入居期間は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_shared_equipment', 'unknown', null, '関連スタートアップ向けに学内の研究機器・共用設備を学内料金で使えるとする公開規程や料金表は見つからなかった。公開情報で確認できたのはCRIK信濃町の共用設備（コミュニティスペース、共有部Wi-Fi、フリードリンク）と有料オプション（ラウンジ、会議室、テレカンブース、登記）、および慶應義塾大学病院の医療データを扱うデータアクセスルームでの共同研究のみ。研究連携推進本部の規程集・ガイドライン一覧にも設備共用規程の掲載は無い。', 'unknown', 'https://crik.keio.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_name_logo_use', 'unknown', null, '「慶應義塾大学発ベンチャー」等の称号を付与する制度は無く、制度ページは「認定やその信用保証をするものではありません」と明記する。一方で大学名・ペンマーク等のロゴ使用条件を定めた規程は、研究連携推進本部の規程集・ガイドライン一覧（組織／産学官連携／知的財産等の区分）にも掲載が無く、公開情報では可否・条件を確認できなかった。', 'unknown', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_ip_license', 'established', '特許満了まで独占実施許諾可、譲渡・共有知財の持分譲渡にも応諾', '慶應義塾スタートアップ向け技術移転ガイドライン（2024年12月17日制定、2025年1月1日施行）3項。(2)実施許諾契約の期限は特許期間満了までを可能とし、その期間中、適切な対価による独占での実施を認める（ノウハウを含む場合は満了後も可）。(3)創作した研究者に将来の利用意向がない場合、適切な対価で譲渡に応じる。(4)スタートアップとの共同研究の共有知財は原則共有とし、事業戦略上重要な場合は独占利用を考慮、持分譲渡にも応じる。主管はイノベーション推進本部。', 'official', 'https://drive.google.com/file/d/1AE1WRTQbHpZKFonRmhDn6UOh-juN7yGJ/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_equity_rule', 'established', '実施許諾・譲渡の対価として株式等での支払いを求める', 'スタートアップ向け技術移転ガイドライン3項(1)「資金を成長等に投資する必要があるスタートアップからは、知的財産権の実施許諾および譲渡の対価として、一時金もしくはランニングロイヤリティ等の支払いの全部またはそれらの一部を代替することを目的として、株式等による支払いを求めるものとする」。処分側は慶應義塾対価収入の配分に関する細則1項が、株式・新株予約権等の売却収入を実施料収入に含め、売却等に要した費用を控除して発明者等50％・所属学部等25％・義塾25％で配分すると定める。別に大学系VCの株式会社慶應イノベーション・イニシアティブが投資を行う。', 'official', 'https://drive.google.com/file/d/1AE1WRTQbHpZKFonRmhDn6UOh-juN7yGJ/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_gap_fund', 'established', 'KSIP助成金 上限300万円／件の学内ギャップファンド', '慶應スタートアップインキュベーションプログラム（KSIP、2023年10月開始）の学内向けギャップファンド「KSIP助成金」。資金的支援は上限300万円／件で、加えて支援担当者による伴走支援、提携先事業会社・支援者コミュニティからの支援が受けられる。対象は慶應義塾大学に在籍する教職員（特任・研究員含む）または学生、対象案件は研究成果・研究シーズを基盤に事業化を目指すもの。事業の要となる知的財産を慶應義塾が保有、または慶應義塾への承継を予定していることが要件。2026年度公募はエントリー5月29日締切で受付終了。', 'official', 'https://innov.keio.ac.jp/startup/ksip/gap-fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_accelerator', 'established', 'KSIPが通年募集で個別伴走支援、年10件程度採択', 'KSIPは本学教職員・学生が創業メンバーの主体として参画するグループを対象とした、ディープテックスタートアップの創業と成長を支援する全学レベルのインキュベーションプログラム。イノベーション推進本部スタートアップ部門が株式会社慶應イノベーション・イニシアティブと連携し、起業ツールキットの提供、チーム目標設定とメンタリング、ビジネス人材プールからのチーム参画、専門家相談やアイデア検証機会を提供。通年応募、運営部門による書類・対面審査で約10件／年を採択、常時5件程度を支援。相談窓口は同部門。', 'official', 'https://innov.keio.ac.jp/startup/support/ksip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_coi_sidejob', 'established', '役員兼業は許可制。COI担当委員会の助言＋就業規則第11条', '研究成果活用企業の役員等の兼業手続きに関するガイドライン（2018年5月22日制定）第3条は、義塾に本務を有する常勤教職員が研究成果活用企業の役員等を兼ねる場合、あらかじめ慶應義塾利益相反マネジメント内規に定める部門利益相反マネジメント担当委員会の助言を得たうえ、慶應義塾教職員就業規則第11条の手続きを行うと定める。第4条は職務遂行に支障が無いこと、学生が不利な立場に置かれないこと、義塾と当該企業の取引に不公正が生じないことなど5要件を規定。身分が変わる場合は再手続き（第5条）。', 'official', 'https://drive.google.com/file/d/1ijqaECzDs9a9T6nVJDCdh2UW7fGNHMJ7/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_support_fee', 'established', '助成金・伴走支援は無償、施設は有償の会員制', 'KSIP助成金は上限300万円／件の給付で、伴走支援やコミュニティ参加を含め受益者負担の記載は無い。一方CRIK信濃町は賃貸オフィス会員・専用デスク会員・ラウンジ会員の会員制で、ラウンジ・会議室・テレカンブース・登記は有料オプション。知的財産の実施許諾・譲渡は技術移転ガイドライン3項により「適切な対価」を要し、その支払いを株式等で代替する扱い。', 'official', 'https://innov.keio.ac.jp/startup/ksip/gap-fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_certified_count', 'unknown', null, '［自動検証で否認: 22社の数字が本文に無い］元の主張(not_started): 認定なし・関連SU企業名は非公表（紹介サイトに22社）。制度ページに「慶應義塾大学関連スタートアップの具体的な企業名リストは公表しておりません」と明記され、認定制度自体が無いため認定社数も存在しない。参考として慶應スタートアップ公式サイトのStartupsページが22社（iXgene、AdipoSeeds、Synspective、ケイファーマ、Heartseed、TELEXISTENCE、坪田ラボ等）を紹介掲載し、CRIK信濃町サイトは入居スタートアップ21社を掲載している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_cert_rule', 'not_started', '認定制度なし（W-INC会員資格制度のみ）', '会員一覧ページ「『早稲田大学発ベンチャー』の呼称について」節に「個別特定のベンチャー企業に対して、"早稲田大学発ベンチャー"およびこれに類する呼称を早稲田大学のもとで認定ないし付与することは行っておりません」(2011年12月1日)と明記。代替枠組みはアントレプレナーシップセンターの「コミュニティ会員」で、同ページは「センターが提供しているサービスを利用するための資格制度」と定義する。認定規程は規程集・産官学連携ページのいずれにも存在しない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_eligible_scope', 'established', '在学生・常勤教員・研究者（卒業生は不可）', 'コミュニティ会員サービスページに「会員になることができる方は本学の現役の学生、本学の常勤の教員、研究者となります」。入会の流れページは「本学の在学生・専任教職員が対象です。卒業生、教職員を退職した方の入会はできません」と明記。2016年入居募集要領では対象を(1)本学学生が代表取締役を務める営利法人(2)本学専任教職員が取締役・執行役員等として経営に深く関与する営利法人（兼業が認められていること）とし、NPO等非営利団体は対象外。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_recognition_decider', 'established', 'アントレプレナーシップセンターの入会審査（月1回）', '入会の流れページに、②書類審査（事業概要計画資料＋本学教職員による推薦書）→③コンサルタントとの入会面談（二次審査）→④入会申請→⑤「提出書類をもとにアントレプレナーシップセンターにて、入会審査を行います。（毎月1回開催）」→⑥結果通知、と5段階が記載。審査全体で通常2か月程度。個室オプションは書面・面接審査。2016年募集要領では更新判断をインキュベーション推進室運営委員会が担うとあった（現組織は改称済み）。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/membership-flow/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_cert_pre_registration', 'established', '可（6か月以内の設立予定でも入会申請可）', '入会の流れページ冒頭に「６カ月以内の法人設立を目指す準備中の方、または法人設立して間もないベンチャー企業をコミュニティ会員として迎え、サポートしています」と明記。④入会申請の提出書類でも履歴事項全部証明書には「**設立済の場合」と注記があり、未設立でも申請できる建て付け。ただし個室への法人登記は入会後に別途審査・承認が必要。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/membership-flow/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_validity_years', 'unknown', null, '認定制度自体が存在しないため認定の有効期間という概念がない。コミュニティ会員資格の期間・更新条件は公開ページに記載がなく、確認できたのは会費が6か月分前払い制であることと、会員規約に基づく資格取消の実例（2020年・2021年・2025年に各1社）のみ。個室入居については2016年の入居募集（掲載終了）に「入居期間は、原則として3年を限度」「事業計画見通しなどにより1年とし運営委員会の基準により更新（最大3年）」とあるが、現行ページには期間の記載がない。', 'unknown', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_head_office_registration', 'established', '可（19-3号館・会員限定・所定審査で承認）', 'コミュニティ会員サービスページの提供サービス②に「法人登記ができます。早稲田大学アントレプレナーシップセンター（19-3号館）では、一定の条件を満たした場合、法人登記を行うことができます。ただし、利用にあたっては、ご入会後に事業内容や活動実態等を確認させていただき、当センター所定の審査を経て、承認された場合に限りご利用いただけます」と明記。センター概要ページも「法人登記可能な事業拠点としてのアントレプレナーシップセンター施設利用」と記載。有料会員制のため実質有償。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 共益費額はsource_urlに無く別ページ由来］元の主張(established): 個室7室（9.3〜58.7㎡）共益費月4.1万〜25.8万円。総合案内ページの施設概要に、早稲田大学アントレプレナーシップセンター（19-3号館、旧インキュベーションセンター、2008年10月開設、778㎡）の内訳としてオフィススペース全7室（個室、9.3㎡〜58.7㎡）、会議室2室、共用のStartup Lounge・フリースペース・メールボックス等。コミュニティ会員サービスページの個室オプションは「入居契約を交わした上で」利用でき、共益費は月額40,920円（9.3㎡）〜258,280円（58.7㎡）税込。会員費は別途。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_shared_equipment', 'unknown', null, '［自動検証で否認: 学外者相談制はsource_urlに記載なし］元の主張(established): 学内中心・学外者は相談制・ベンチャー枠なし。研究活動サイト「共用設備・機器」ページに「各箇所では技術職員や専門スタッフが管理・運用をしており、学内者を中心に利用を開放しております。一部の設備・機器は学外の研究者にも開放しております」。共用機器ポータル(cf.waseda.ac.jp)の利用案内は利用対象者を研究室所属者とし「総合窓口にて、その他の学生、学外の方の利用相談も受け付けています」「利用する機器により料金が発生することがあります」と記載。W-INC会員サービスは①〜⑥の限定列挙で研究機器利用を含まず、ベンチャー向け料金区分の記載も見当たらない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_name_logo_use', 'not_started', '称号の認定・付与なし（2011年公表）', '会員一覧ページの「『早稲田大学発ベンチャー』の呼称について」に「個別特定のベンチャー企業に対して、"早稲田大学発ベンチャー"およびこれに類する呼称を早稲田大学のもとで認定ないし付与することは行っておりません。したがって、特定のベンチャー企業が自らを"早稲田大学発ベンチャー"と名乗っている場合であっても、早稲田大学が何らかの認定を行ったものではありません」(2011年12月1日)。大学ロゴ・校章のベンチャー向け使用許諾規程は公開情報では確認できず。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_ip_license', 'unknown', null, '知財・研究連携支援セクションのページで確認できたのは、知的財産憲章・知的財産に関する基本理念・早稲田大学職務発明規程に基づき発明審査委員会が承継可否を審査し、2024年7月以降は特許化・技術移転業務を株式会社早稲田大学TLO（2024年4月設立、早稲田大学グループホールディングス傘下）が担当するという枠組みまで。大学発ベンチャーへの優先実施許諾・独占許諾・対価減免・株式対価といった優遇条項の記載は見当たらない。COI規程は研究開発型ベンチャーを「本学が承継した知的財産権を実施するまたは譲渡を受ける株式会社」と定義しており実施許諾・譲渡自体は行われている。', 'unknown', 'https://www.waseda.jp/inst/research/tlo/collaboration', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_equity_rule', 'unknown', null, 'サポーターページで確認できたのは、早稲田大学ベンチャーズ株式会社（WUV、2022年4月設立、ディープテック創業投資に特化）が「早稲田大学の名を冠するベンチャーキャピタル」であること、提携VC2社（ウエルインベストメント、Beyond Next Ventures）と投資ファンド組成・ハンズオン支援の提携契約を締結していること。いずれも大学とは別法人による投資であり、大学自身がベンチャーの株式・新株予約権を取得する規程の公開は確認できなかった。', 'unknown', 'https://www.waseda.jp/inst/entrepreneur/supporter/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_gap_fund', 'established', '早稲田PoCファンド（最大100万円）', '早稲田PoCファンドプログラムページに、2025年度公募はタイプA（研究開発費最大100万円、初期仮説検証。GTIEギャップファンド等の外部資金申請につなげることが目標）とタイプG（同額、GTIEギャップファンド面接不採択者向けフォローアップ）。2020年開始、2020-2024年度はJST大学・エコシステム推進型採択によるタイプSと、提携VCの寄附を財源とするタイプA・Bで実施し、29件を採択・うち7件が起業。採択テーマと代表者は年度別に公開。', 'official', 'https://www.waseda.jp/inst/entrepreneur/poc/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 事業化アドバイザー等はsource_urlに無し］元の主張(established): 起業相談3回無料・コンサル常駐・PoC伴走。コンサルティングサービスページに、在学生・本学教職員向けの起業相談を3回まで無料で実施し、コミュニティ会員には弁護士・公認会計士・中小企業診断士などシニアコンサルタントによる経営相談会を実施。研究者向け事業化支援ページには常駐の「事業化アドバイザー」を配置。教育面はW-EDGE（アントレプレナーシップ教育、2026年度から全学副専攻を開始予定）、PoCファンドはDemo Dayを実施。単年度型のアクセラレーションプログラムという形式ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_coi_sidejob', 'established', '役員兼業COI規程（2021年施行）・委員会審査', '研究倫理オフィス「利益相反マネジメント」ページに、「研究開発型ベンチャーの役員兼業に関する利益相反マネジメント規程」を制定（2021年4月1日施行）し、同規程に基づく委員会で運用と明記。対象は中小企業かつ本学が承継した知的財産権を実施または譲渡を受ける株式会社に兼業する専任教員・特任教授・任期付教員・上級/主任/次席研究員等。手順は兼業開始時・年1回定期・随時の自己申告書提出→委員会審査→結果通知→必要時の改善要請と不服申立て。兼業申請状況も定期更新で公開。W-INC入会申請でも教職員は兼業許可申請書の提出が必要。', 'official', 'https://www.waseda.jp/inst/ore/conflict', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_support_fee', 'established', '有償会員制（学生5,500円〜/月・個室別途）', 'コミュニティ会員サービスページの会費表は6か月分前払い制で、学生5,500円／月、教職員11,000円／月、卒業生・修了生・その他22,000円／月（いずれも税込）。個室オプションは共益費が別途月額40,920円〜258,280円（税込）。センター概要ページは起業活動支援のみ「*のみ有料会員制」と注記し、起業家教育とPoCファンドは無償。起業相談は3回まで無料、2022年12月以降はフリースペースを非会員の学生にも開放。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_certified_count', 'established', '認定なし・W-INC会員36社を一覧公開', '認定制度がないため認定社数は存在しない。会員一覧ページは個室入居会員7社（Urth、Power Diamond Systems、BASYO、CourseVALU、HatsuMuv、VETA、Pestalozzi Technology）と一般会員29社（bitBiome、Nanofiber Quantum Technologies、BioPhenoMA、エコロギー、エキュメノポリス等）の計36社を社名・事業内容・自社サイトリンク付きで公開（2026年9月5日閲覧時点）。会員資格取消企業3社も理由付きで明示。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_cert_rule', 'not_started', '認定制度なし・関連スタートアップの定義のみ', '産学協創推進本部サイト（起業・大学発ベンチャー支援、サイトマップ、規則・様式等一覧）に認定規程・称号授与制度の記載がない。プレスリリース「東京大学関連スタートアップ（2025年度）累積創出数は743社になりました」の【参考】欄は、関連スタートアップを申請・認定ではなく（1）人材の関連性（2）大学の知の関連性（3）リソース提供の関連性の3区分の定義で整理し、大学の調査で把握した企業として集計すると明記している。称号付与や認定申請の窓口は確認できない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400105176.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_eligible_scope', 'established', '教職員・学生・卒業間もない卒業生が関与する未上場法人（設立10年以内）', 'アントレプレナープラザ募集要項3.支援対象企業は、①本学の役員・教職員・学生等の研究教育成果の実用化を主要事業とする未上場法人（設立後10年以内）②役員・教職員・学生（卒業間もない卒業生を含む）が出資等で設立に深く関与した未上場法人③東京大学協創プラットフォーム開発または連携VCの出資先④その他本学と密接な関係を有する法人、の4区分。シェアオフィスは同4区分を設立2年以内に狭め、加えて1年以内に起業予定の個人を対象に含める。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_recognition_decider', 'established', '産学協創推進本部長を委員長とする審査委員会', 'アントレプレナープラザ募集要項4.(2)審査委員会は、産学協創推進本部長を審査委員長とし産学協創推進本部メンバーを中心に構成、東京大学協創プラットフォーム開発と東京大学エッジキャピタルパートナーズがオブザーバー参加。4.(3)選考基準は大学との関係性の強さ、事業の成長ポテンシャル、大学からの支援の必要性・有用性。4.(4)(6)により書類提出と約30分の面接審査会で選考し、通常1.5〜2か月を要する。認定制度の決裁ではなく施設入居・支援の審査主体である。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_cert_pre_registration', 'established', '可（1年以内に起業予定の個人も対象）', '南研究棟アントレプレナーラボ共用オフィス（シェアオフィス）の募集要項「対象」5号は、本学の役員・教職員・学生等の研究教育成果の実用化を目指す個人であって、当該目的のため1年以内に起業を予定している者を支援対象と明記。インキュベーション施設ページも対象を「スタートアップ（ベンチャー）および個人」とし、駒場連携研究棟インキュベーションルームは起業前のチームを対象とする。アントレプレナープラザ募集要項の申請書類も登記簿謄本・定款を「（法人の場合）」と限定している。', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/incubation/elab_sharedoffice.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_validity_years', 'established', '施設利用1〜3年・再契約可・通算10年上限', 'アントレプレナープラザ募集要項2.(1)により、利用期間は事業の状況等を勘案して審査委員会が1年・2年・3年のいずれかを決定。契約更新はできないが期間終了前の再申請と審査会承認で再契約可能、回数制限はないが産学協創推進本部の運営するインキュベーション施設を通算10年以上利用することはできない。上場や買収・合併・事業譲渡で事業統合された場合は速やかに終了。シェアオフィスは1年・再契約1回、シェアラボは1年・再契約2回まで。認定制度自体がないため認定の有効期間はない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_head_office_registration', 'unknown', null, 'インキュベーション施設ページ、アントレプレナープラザ募集要項、アントレプレナーラボ個室・シェアオフィスの各紹介ページを読んだが、施設の住所を会社の本店所在地として商業登記できるかについての記載はない。アントレプレナープラザは㈱成信が貸主となる建物賃貸借契約で、賃貸条件は別紙2「建物賃貸に関するご案内」に委ねられているが同別紙は公開されていない。公開情報では可否を確認できない。', 'unknown', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/incubation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_facility_lease', 'established', '本郷・駒場II・柏IIの6施設に入居可（有償・1〜3年）', 'インキュベーション施設ページの比較表によれば、アントレプレナープラザ（本郷・約58㎡×30室、23室ウェットラボ可・1〜3年）、南研究棟アントレプレナーラボ個室（約25〜75㎡×32室、24室ウェットラボ可・1〜3年）、同共用バイオ実験室（専有ベンチ12台・1年）、同共用オフィス（専有デスク15席とオープンデスク22席・1年）、駒場連携研究棟インキュベーションルーム（約54㎡または68㎡×3室・1〜3年）、柏IIアントレプレナーハブ（約65㎡×14室、全室ウェットラボ可・1〜3年）の6施設を運営。いずれも再契約可。', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/incubation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_shared_equipment', 'established', '学内6拠点の共用研究設備・機器を有料で利用可', '「共用研究設備・機器の利用」ページは、ベンチャー企業が本学の共用研究設備・機器を有料で利用できるとし、①ワンストップ創薬共用ファシリティセンター（薬学系研究科）②マテリアルイノベーション研究センター（新領域創成科学研究科）③駒場分析コア（生産技術研究所）④ものづくり部門（工学系研究科）⑤ライフサイエンス研究機器支援室（医学系研究科）⑥生命データサイエンスセンターを列挙。①〜④は特定研究成果活用支援事業でインキュベーション施設の機能強化のため設置された。学内料金と外部料金の区分の記載はない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/shared.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_name_logo_use', 'established', '称号制度なし・大学名やマークは契約範囲内のみ', '「東京大学における研究成果に係る出所由来表示及び推薦に関するガイドライン」（平成17年12月20日総長裁定、令和2年11月1日実施）2.(1)は、本学が法人として契約を締結していない、または契約の内容を超えた範囲で本学の名称・本学を想起させる呼称・マーク等の使用を第三者に認めることは法人として許容しがたいと明記。3.は「特許出願番号○○号出願人国立大学法人東京大学」「東京大学○○教授との共同研究」など事実に基づく表示を推奨する。「東京大学発ベンチャー」等の称号使用制度は確認できない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400103789.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_ip_license', 'established', 'ライセンス及びベンチャー支援に伴う株式等取得規則', '産学協創推進本部「規則・様式等一覧」の規則・細則欄に「東京大学におけるライセンス及びベンチャー支援に伴う株式等取得取扱規則」が掲載され、ライセンスやベンチャー支援に伴って株式等を取得する枠組みがあることを確認した（本文リンクは学内限定で403、条文は未確認）。同ページの東京大学ライセンス・ポリシー（平成21年9月30日制定、令和2年11月1日改正）本文は、社会的効用の最大化や実用化可能性の重視など基本方針のみを定め、スタートアップ向けの独占許諾や対価減免の規定は置いていない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/rules_and_forms/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_equity_rule', 'unknown', null, '［自動検証で否認: 寄附規則はこのURLに掲載なし、根拠不明］元の主張(established): 寄附・出資・ライセンス対価の3系統の株式等取得規則。「規則・様式等一覧」の規則・細則欄に「東京大学におけるライセンス及びベンチャー支援に伴う株式等取得取扱規則」と「東京大学における出資を目的とした株式等取得取扱規則（令和6年3月18日改正、新旧対照表あり）」が掲載されている。既登録の「東京大学における寄附による株式等取得取扱規則」（平成18年1月30日・東大規則第55号）と合わせ3系統。前2者の本文リンクはそれぞれ403と404で条文は確認できなかったが、規則名と改正年月日は公開ページ上で確認した。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_gap_fund', 'established', 'スタートアップ創出支援事業（東京都事業・2027年3月まで）', '「2026年度スタートアップ創出支援事業のご案内」によれば、産学協創推進本部が株式会社先端技術共創機構（ATAC）と連携し、東京都大学発スタートアップ創出支援事業の採択を受けて東京都との協定のもと実施。対象経費は研究開発支援経費（知財調査・レポート購入・市場調査等）、外部人材への外注費、広報・ブランディング経費、法人設立経費・商標登録費。実施期間は2027年3月31日まで、上限到達で早期締切。事務局の個別ヒアリングと審査を経る。別途GTIE（JST事業）でもGAPファンド応募を想定した支援を行う。', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/education/2025SU01.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_accelerator', 'established', '起業・法務・経営相談の窓口とFoundX等の育成プログラム', '起業相談／経営相談ページによれば、産学協創推進本部が起業相談のワンストップ窓口を整備し、顧問契約を結ぶ法律事務所による法務支援（契約書レビュー等）と、VC・弁護士・会計士等の専門家を手配する経営相談を提供する。育成プログラムはアントレプレナー道場（授業科目化）、本郷テックガレージ、Spring/Summer Founders Program、100 Program、Todai To Texas／Todai To X、ソーシャルテックSUアクセラレータープログラム、FoundX（卒業生・研究者向け）、Tech Incubation Palette（三菱商事寄付）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/education/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_coi_sidejob', 'established', '役員兼業は審査承認制・許可状況を公表', '東京大学教職員兼業規程（平成16年4月1日役員会議決・東大規則第26号）第3条第1項は営利企業の役員等の兼業を原則禁止し、第2項で大学教員が(1)技術移転事業者（TLO）(2)研究成果活用企業(3)本学が承認する技術移転関連事業者の役員等、(4)監査役、(5)社外取締役を兼ねることを、審査に基づく承認により許可されたものとする。第3項は許可された兼業の状況を公表すると規定。利益相反側は東京大学利益相反マネジメント委員会規則（令和2年3月26日・東大規則第121号）とセーフ・ハーバー・ルールが担う。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_syuki/syuki16.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 機器有料・FoundX無償はこのURLに記載なし］元の主張(established): 施設賃料と機器利用は有償・FoundXは無償。アントレプレナープラザ募集要項2.(2)と4.(8)により、入居は貸主㈱成信との建物賃貸借契約で、保証金および賃料前払い分の入金確認後に入居可能。共用研究設備・機器の利用は「有料」と明記されている。一方、卒業生・研究者向けFoundXは期間限定の個室（4名まで）の無償貸与とリソース提供を無償で行うと記載。GTIE 1stフェーズは大学・研究機関の研究者は参加費無料、企業の研究開発者は5万円／人。起業相談・法務支援・経営相談には料金の記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_certified_count', 'established', '関連スタートアップ743社・一覧は非公開', 'プレスリリース「東京大学関連スタートアップ（2025年度）累積創出数は743社になりました」により、2025年度（2026年3月末まで）に把握できた累積創出数は743社、うちIPO累計39社、M&A累計79社、2024年度から105社増と確認。743社の企業一覧は公開されていない。公開されているのはインキュベーション施設の「支援企業一覧」（PROVIGATE、ヒラソル・エナジー、BionicM、AlzMed等の入居企業）と「主な卒業企業一覧」で、これは認定社数ではなく施設利用企業の一覧である。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400105176.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_cert_rule', 'established', '東京科学大学認定ベンチャー（称号授与規則）', '「東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則」（令和6年10月4日規則第132号）第2条で、称号を「東京科学大学認定ベンチャー」、英語名称を「Science Tokyo Venture」と定める。附則第2項で旧・東京工業大学の同名規則（平成16年規則第140号）と東京医科歯科大学の規則（平成24年規則第96号）を廃止し、統合大学の制度として再制定。附則第3項により旧「東工大発ベンチャー」称号企業は引き続き旧称号を利用できる。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_eligible_scope', 'established', '研究成果・技術移転・共同研究・学生・関連の5類型', '規則第3条は「法人格を有するものに限る」とした上で、①研究成果ベンチャー（設立時の中核事業で本学の特許権等・研究成果・習得技術を活用）②技術移転ベンチャー（本学特許権等の実施許諾を受け活用）③共同研究ベンチャー④学生ベンチャー（本学学生が設立に関与し申請時に経営参画）⑤関連ベンチャー（他大学等在籍時に起業した本学職員、本学の学生であった者、その他学長が特に認めるもの）の5類型を列挙。卒業後・退職後の年数制限は置いていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_recognition_decider', 'established', '学長（審査委員会・イノベーション合同会議の議）', '規則第5条第5項「学長は、審査委員会による審査結果を踏まえ、称号の授与を決定する」。第4条でイノベーションデザイン機構に「東京科学大学認定ベンチャー称号授与審査委員会」を置き、委員は機構長（委員長）・副機構長・産学共創機構長・医療イノベーション機構長等。第5条第4項で審査結果を研究・イノベーション本部規程第7条のイノベーション合同会議の議を経て学長へ報告。第6条第1項で学長が称号記を交付する。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_cert_pre_registration', 'not_started', '不可（法人格必須・履歴事項全部証明書を提出）', '規則第3条柱書が申請資格を「法人格を有するものに限る」と限定。イノベーションデザイン機構の申請資格・手続きページが公開する必要書類一覧PDFでも、5類型すべてで「履歴事項全部証明書」と「定款」が必須書類とされている。設立予定段階での申請、認定予定通知、条件付認定に相当する規定は、規則本文にも申請案内にも見当たらない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.idp.ori.titech.ac.jp/venture/application/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_validity_years', 'established', '期間の定めなし（更新規定なし・取消規定あり）', '規則に有効期間および更新手続の規定はない。第6条第2項で「企業の買収、統廃合等により法人格の同一性が保たれない場合は、その効力を失う」、第9条で社会的信用を失墜する行為等があるときは学長が審査委員会の議を経て称号を遡って取り消し、称号記を返付させると定める。第8条で称号企業は大学の求めに応じ事業報告書を提出する義務を負う。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_head_office_registration', 'established', '可（TIPシェアラボを本店として登記・申請制）', '「TIPに係る共用実験室利用細則」（令和6年12月6日細則第82号）第12条（住所の登記）に「利用責任者は、医療イノベ機構長への申請により当該スタートアップの所在地としてシェアラボを登記することができる」と明記。シェアラボはTIP（湯島・駿河台地区）の共用実験室で、第3条により研究開発型スタートアップ（起業準備を含む）や起業を目指す教職員・学生が利用対象。田町のINDEST側の使用細則には登記に関する規定はない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: 同URLに規則134号もTIP原則3年の記載も無い］元の主張(established): INDEST・TIPに入居可（有償・原則3年）。Innovation Design Studio規則（令和6年規則第134号）第2条・第3条で、認定ベンチャーと起業しようとする教職員・学生を支援する施設としてキャンパス・イノベーションセンター（田町）2〜4階にオフィス、コワーキング、イベントスペース等を設置。使用細則（令和6年細則第67号）第4条が使用者に認定ベンチャーを明示し、第6条で入居審査専門委員会の審査を経て可否を決定、第7条でセットアップオフィスは定期建物賃貸借契約。TIPはオープンラボ19室とシェアラボがあり、シェアラボの利用期間は原則3年、延長2回で最大5年。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_shared_equipment', 'established', 'シェアラボ利用者は共通実験機器を利用可（有料）', 'TIP共用実験室利用細則第3条第3項で「バイオサイエンスセンターのうち湯島地区に設置している共通実験機器等は、シェアラボの利用者の研究のために利用できる」と定め、第8条第4項で当該機器の利用料等を、第3条第7項・第8条第5項で機器のオプション利用とその料金を負担させる。全学の設備共用は別途「東京科学大学設備共用推進体設置要項」（令和7年6月6日制定）による。認定ベンチャー向けの学内料金区分の明示は確認できていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_name_logo_use', 'unknown', null, '［自動検証で否認: 同URLに称号名称使用可の根拠記載が無い］元の主張(established): 称号名称は使用可・新ロゴの配布は取りやめ。規則第2条で「称号を授与された企業は、東京科学大学認定ベンチャー及びScience Tokyo Ventureの名称を利用することができる」。ロゴについてはイノベーションデザイン機構の過去の活動・支援ページに「統合により、東京科学大学認定ベンチャーへの本ロゴの配布は取りやめましたが、東工大発ベンチャーは引き続き使用いただけます」と明記され、旧「東工大発ベンチャー」ブランドロゴのみブランドロゴガイドラインに従って継続使用できる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_ip_license', 'established', '実施許諾の対価を株式・新株予約権で受領可', '「研究開発成果活用促進支援に伴う株式等の取得に関する規則」（令和6年規則第116号）第2条で、特許権等の譲渡・実施許諾（成果有体物の貸与およびノウハウの使用許諾を含む）とインキュベーション目的の施設使用を「研究開発成果活用促進支援」と定義し、第3条でその対価として対象企業の株式等を譲渡・付与する提案を受けられると定める。認定ベンチャーへの優先的・独占的実施許諾や実施料の減免を定める明文は、公開されている規程と支援ページには見当たらない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_equity_rule', 'established', '株式等取得規則あり（株式等受入審査委員会）', '「研究開発成果活用促進支援に伴う株式等の取得に関する規則」（令和6年10月1日規則第116号、令和8年6月16日改正）。第2条第6号で株式等を株式および新株予約権と定義し、第3条で理事長が株式等受入審査委員会の議を経て取得の可否を決定。第6条の委員はイノベーション担当理事（委員長）、産学共創・医療イノベーション・イノベーションデザインの各機構長、学外有識者若干人。第10条で評価・売却の取扱いは別に定める。監督組織としてベンチャー支援出資事業モニタリング委員会要項がある。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_gap_fund', 'established', 'Science Tokyo GAP Fund等・採択者一覧公開', 'イノベーションデザイン機構の資金支援ページに、Science Tokyo GAP Fund Program 2026、社会変革チャレンジ賞（第3回公募）、学生スタートアップ支援、GTIE GAPファンドを掲載。GAPファンドを「大学での研究と事業化との間のギャップを埋めるために、PoC、試作品製作、ビジネスモデルのブラッシュアップ等を実施する資金」と説明。採択者・採択課題一覧を2022年度分から年度別に公開。寄附を原資とする特定基金「スタートアップ支援基金」も設置されている。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/funding-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_accelerator', 'established', 'Startup Studio Program等の伴走プログラム', '起業・ベンチャー支援ページで、イノベーションデザイン機構が起業ステップに合わせたプログラムを提供すると明記。起業準備フェーズの学生向け「Startup Studio Program」、ベンチャーや専門家との交流イベント、経営を担う人材の採用支援、日本政策金融公庫×INDESTの融資・資金計画個別相談会（2026年8月28日開催）を実施。東京科学大学・東京大学・早稲田大学を主幹機関とするプラットフォームGTIEにも参画している。［検証エージェントは出典を開けず未照合］', 'official', 'https://partnerships.isct.ac.jp/ja/023/entrepreneurship-startups/activities', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_coi_sidejob', 'established', '役員兼業は理事長許可制・COI回避要請時は不許可', '役職員兼業規則第3条で事前に理事長の許可を得て兼業でき、許可期間は2年以内（法令に任期の定めがある職は4年）。第12条第2号で研究成果活用企業の役員等の兼業、第1号で技術移転事業者の役員等の兼業を兼業審査委員会の審査事項とする。第3条第1項第3号は、兼業先と共同研究等を実施しており、産学連携活動の実施における利益相反マネジメント規則により利益相反マネジメント委員会が回避要請を通知したときは許可しないと定め、COI審査と明文で接続。第4条で兼業は学外で従事し大学施設の使用を原則禁止。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_support_fee', 'established', '施設利用は有償（対価を株式等とする制度もあり）', 'TIPオープンラボは年額の平方メートル単価（8号館南84,000円、M&Dタワー102,300円、22号館74,700円）に光熱水料8,800円を加算し、TIP事務局の審査で30%を上限に減額可（細則第81号第3・4条）。コワーキングスペースとイノベーションサロンは無料、イノベーションギャラリーは会員1日20,000円。シェアラボはベンチ単位の月額（細則第82号第8条）。INDESTは使用細則第9条で使用料を納付し、教職員・学生は施設長が認めれば大学予算から支出可。認定申請自体の手数料の定めは規則・申請案内にない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002139.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_certified_count', 'established', '認定35社（2026年8月）・一覧PDF公開', 'イノベーションデザイン機構の申請資格・手続きページに「累計35社の企業に『東京科学大学認定ベンチャー』の称号を授与しました（2026年8月24日現在）」と記載し、認定ベンチャー一覧PDFを公開。旧称号企業は東工大発ベンチャーが第T001〜T175号、東京医科歯科大学発ベンチャーが第MD01〜MD15号として新称号を利用でき、それぞれの一覧PDFも公開されている。', 'official', 'https://www.idp.ori.titech.ac.jp/venture/application/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_cert_rule', 'established', '「東京理科大学発スタートアップ企業」認定制度（2002年開始）', '産学連携機構「大学認定スタートアップになるには」に、2002年開始の制度のもとで現役教員または学生のスタートアップを「東京理科大学発スタートアップ企業」または「東京理科大学発学生スタートアップ企業」として認定し、称号使用許可と施設・設備の貸与を行うと明記。起業ハンドブック（2025年12月改版）7章は同制度を「学内発スタートアップ企業／学内発学生スタートアップ企業」と呼び、審査から支援基本契約締結までの流れを示す。認定要件を定めた規程本文は学外に公開されていない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_eligible_scope', 'established', '現役の教育職員・学部生・大学院生（2022年度に学生へ拡大）', 'tobecomeページは「本学が2002年に開始した制度のもとに認定する現役教員または学生による研究成果や学びを梃としたスタートアップ」と規定。起業ハンドブック7章に「2022年度より、対象を学内発スタートアップ企業（教育職員）だけでなく、学内発学生スタートアップ企業（学部生または大学院生）に拡大しました」と明記。卒業生はTUSIDEの支援対象として挙げられるが、認定対象としての記載は確認できなかった。知財活用型に限定する記述もない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_recognition_decider', 'established', '学内発スタートアップ企業等審査委員会の審査を経て理事長が認定', '起業ハンドブック7章「申請から認定までの大まかな流れ」に、「『学内発スタートアップ企業等審査委員会』での審査を経て、その結果に基づき理事長が認定」「認定された場合には、『支援基本契約書』（契約期間原則5年以内）を締結」と記載。決裁主体は学長ではなく学校法人東京理科大学の理事長。申請窓口は教員が学内ポータルCENTIS、学生がBoxの限定公開フォームで、いずれも学外から内容を確認できない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_cert_pre_registration', 'unknown', null, '起業ハンドブック6章（会社を設立する）の末尾に「起業時に、学内発スタートアップ企業への申請・認定のご検討を推奨いたします（7.参照）」とあるのみで、設立登記前の申請受付、認定予定通知、条件付認定の可否を示す記述は公開情報に見当たらない。7章の認定フローも申請時点で登記済みかどうかを規定していない。教員向け申請フォームは学内ポータル限定のため要件を確認できなかった。', 'unknown', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_validity_years', 'established', '認定後に支援基本契約書を締結、契約期間は原則5年以内', '起業ハンドブック7章のStep3に「認定された場合には、『支援基本契約書』（契約期間原則5年以内）を締結」と明記。認定そのものの有効期間や更新手続を定めた条文は学外に公開されていないため、支援関係が5年以内の契約で区切られることまでが確認できる範囲。なお学内インキュベーション施設の入居は別枠で原則3年以内、1年ごとに中間審査と定められている。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_head_office_registration', 'established', 'TUSIDE提供のインキュベーション施設で会社登記が可能', '大学ドメイン上のTUSIDEサポートページ、サポートプログラム「出会いたい」の欄に「インキュベーション施設の提供／会社登記が可能な活動拠点の提供／成長ステージに合わせた数人から30人程度まで利用可能なオフィスを整備」と明記。対象施設はTUSIM社等が共同運営する東京都認定インキュベーション施設quantum cross point（飯田橋・市ヶ谷）など。葛飾キャンパスの学内インキュベーションルームについては、募集要項・利用規則とも登記の可否に触れていない。', 'official', 'https://www.tus.ac.jp/tuside/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_facility_lease', 'established', '葛飾キャンパスの2施設を有償貸与、原則3年以内', '2026年度入居者募集要項に、葛飾キャンパス第1研究棟1階のインキュベーションルーム（33.24㎡、月額28,400円税抜）と産学試作開発室（99.72㎡、月額84,100円税抜）、敷金は賃料3か月分、光熱水費・通信費は別途実費、利用期間は原則3年以内で1年ごとに継続の中間審査、入居契約は10月1日〜翌年9月30日と明記。応募条件に「東京理科大学学内発スタートアップ企業等であること」を明示し、審査は入居審査委員会。別に学生向けコワーキング「ベンチャースタジオ」を3キャンパスに設置。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2025/10/1.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%83%AB%E3%83%BC%E3%83%A0%E5%8F%8A%E3%81%B3%E7%94%A3%E5%AD%A6%E8%A9%A6%E4%BD%9C%E9%96%8B%E7%99%BA%E5%AE%A4%E5%85%A5%E5%B1%85%E8%80%85%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85_2026%EF%BC%884%E6%9C%8821%E6%97%A5%E8%BF%BD%E8%A8%98%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_shared_equipment', 'unknown', null, 'tobecomeページは認定の効果を「称号使用許可、施設・設備の貸与」と書くが、起業ハンドブック13章の「学内認定スタートアップへの支援内容」は「本学施設（インキュベーション施設）の貸与」までで、共用機器・研究設備の利用可否や料金区分（学内料金／外部利用料金）を示す記載はない。葛飾キャンパス産学連携スペース利用規則も什器・電源・排水など室内設備の運用条件のみで、学内共用機器の利用には触れていない。産学連携FAQも共同研究で購入した機器の所有権を述べるにとどまる。', 'unknown', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_name_logo_use', 'established', '「東京理科大学発」称号の使用許可、ロゴ条件は非公開', 'tobecomeページに「東京理科大学発の称号使用許可、施設・設備の貸与など、ソフト・ハード両面からバックアップします」と明記。起業ハンドブック13章の「学内認定スタートアップへの支援内容」も1番目に「『東京理科大発スタートアップ企業』の称号授与」を挙げる。大学ロゴ・校章の使用可否や使用条件を定めた記載は、確認した公開資料の範囲では見当たらなかった。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_ip_license', 'unknown', null, '［自動検証で否認: 新株予約権部分は該当URL本文に記載なし］元の主張(established): ベンチャーへ特段の配慮、新株予約権対価も検討。学校法人東京理科大学知的財産ポリシーⅤ-1に「発明等にかかる実施許諾に関する業務は、東京理科大学産学連携機構が行う。（中略）民間企業等のうち、ベンチャー企業や中小企業に対しては、特段の配慮を行うこととし、別に定める」と明記。起業ハンドブック8章は、大学特許の実施許諾契約が必須であること、実施料の支払い方法として一時金・ランニングロイヤリティのほか「新株予約権（将来成功時支払い）での本学との契約も検討いたします」と記載。独占許諾や対価減免の具体条件を定めた細則は非公開。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_equity_rule', 'established', '実施料対価の新株予約権を検討、出資はTUSICが担当', '起業ハンドブック8章に「新株予約権（将来成功時支払い）での本学との契約も検討いたします」と記載。9章の資金調達手段はVCとして「東京理科大学IC（株）」を挙げ、12章およびTUSIDEサポートページは東京理科大学イノベーション・キャピタル株式会社（TUSIC）が「数千万円～数億円の成長投資」と「経営支援（役員派遣）」を行うと説明。大学本体が株式・新株予約権を取得・保有・処分する手続を定めた規程そのものは公開されていない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: 学生向け助成金は該当URL本文に記載なし］元の主張(established): 学内PoC助成金・学生向け助成金、GTIE・1stRound。支援内容ページに学内助成金として「起業助成金（PoC支援助成金）」、学外としてJST基金/GTIEギャップファンド（本学はスタートアップ創出共同機関として参画）と1stRound（共催大学として参画、起業直前～3年以内が対象、年2回）を掲載。起業ハンドブック13章は産学連携機構の支援メニューに「起業助成金（PoC支援助成金）制度（教育職員向け）」と「起業推進支援助成金制度（学生向け）」の2本を列挙。金額・上限は学内掲示（CENTIS）扱いで公開されていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_accelerator', 'established', '起業支援・地域連携部門による伴走支援と起業相談窓口', '産学連携機構に起業支援・地域連携部門が置かれ、大学発スタートアップ支援、起業相談・支援、起業家教育支援、事業化相談・推進を担うと起業ハンドブック13章および支援体制ページに明記。支援内容ページに「伴走支援メニュー」、TUSIDEサポートページに事業計画・資本政策のメンタリング、smartround提供、専門家・提携金融機関の紹介、ピッチコンテスト参加、卒業生3名によるTUSIDE Medical Advisory Boardを掲載。期別のアクセラレーションプログラムという形式の記載はない。', 'official', 'https://www.tus.ac.jp/ura/startup/support_system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_coi_sidejob', 'established', '兼職届で学長許可・週8時間以内、代表権保有は不可', '起業ハンドブック11章に「本学では、スタートアップに関与する教育職員に対し、適切なマネジメントの一助となる規程を設けています」として、「スタートアップ企業の代表権を有してはいけない」「兼職届による学長の許可が必要（スタートアップ企業業務の従事は8時間以内/1週間）」を明示。あわせて全教職員に「産学官連携活動における利益相反に関する自己申告書」の毎年提出を義務付け。学校法人東京理科大学利益相反ポリシーが体制整備と情報開示の求めを規定する。兼業規程の本文は学内ポータル限定。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_support_fee', 'established', '認定は費用記載なし、インキュベーション施設は有償', '起業ハンドブック13章の「学内認定スタートアップへの支援内容」（称号授与、施設貸与、資金調達・経営・マーケティング支援、特許等の申請支援、アドバイザーの指導、専門家・金融機関・VCの紹介）に対価の記載はなく、認定料や年会費を定めた公開情報も見当たらない。一方、学内インキュベーションルームは月額28,400円、産学試作開発室は月額84,100円（いずれも税抜、敷金3か月分・光熱水費別）と有償。大学特許の利用は実施許諾契約に基づく実施料が必要。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2025/10/1.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%83%AB%E3%83%BC%E3%83%A0%E5%8F%8A%E3%81%B3%E7%94%A3%E5%AD%A6%E8%A9%A6%E4%BD%9C%E9%96%8B%E7%99%BA%E5%AE%A4%E5%85%A5%E5%B1%85%E8%80%85%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85_2026%EF%BC%884%E6%9C%8821%E6%97%A5%E8%BF%BD%E8%A8%98%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_certified_count', 'established', '21社（2026年8月現在）・企業名一覧を公開', '実績ページに「大学認定スタートアップ 21社を認定し支援中！（2026年8月現在）」と表示し、「東京理科大学認定スタートアップ企業」と「東京理科大学認定学生スタートアップ企業」に分けて社名と事業内容を一覧公開している（イノフィス、MediEng、サイエンス構造、XMat、量子総合研究所ほか）。同ページには経済産業省調査による本学の大学発ベンチャー企業数（2025年度257件）も併載。起業ハンドブック7章にも2025年4月時点の認定企業一覧が掲載されている。', 'official', 'https://www.tus.ac.jp/ura/startup/achievements/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_cert_rule', 'established', '東京科学大学認定ベンチャー（令和6年規則第132号）', '「東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則」（令和6年10月4日規則第132号）第2条で称号を「東京科学大学認定ベンチャー」、英語名称を「Science Tokyo Venture」と規定。附則第2項で旧東工大規則（平成16年規則第140号）と旧東京医科歯科大規則（平成24年規則第96号）を廃止し統合。規程集上の現行本文URLを特定した（既存登録の備考にあった未特定を解消）。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_eligible_scope', 'established', '研究成果・技術移転・共同研究・学生・関連の5区分', '第3条で5区分。①研究成果ベンチャー（本学特許権等・研究成果・習得技術を活用）②技術移転ベンチャー（本学特許権の実施許諾）③共同研究ベンチャー④学生ベンチャー（学生が設立に関与し申請時に経営参画）⑤関連ベンチャー（イ 本学職員が他研究機関所属時に起業し申請時に経営参画、ロ 本学の学生であった者が設立し申請時に経営参画、ハ 学長が特に認めるもの）。卒業後・退職後の年数要件は置いていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_recognition_decider', 'established', '学長が決定（機構長委員長の審査委員会が審査）', '第5条で学長に申請し、学長が審査委員会に審査させ、審査委員会が研究・イノベーション本部規程（令和6年規程第144号）第7条のイノベーション合同会議の議を経て学長に報告、第5項で学長が授与を決定。審査委員会は第4条でイノベーションデザイン機構に置き、機構長・副機構長・産学共創機構長・医療イノベーション機構長・機構長指名者で組織、委員長は機構長。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_cert_pre_registration', 'not_started', '不可（法人格必須・履歴事項全部証明書が必要）', '第3条柱書が申請資格を「法人格を有するものに限る。」と限定。イノベーションデザイン機構が公開する提出書類一覧でも履歴事項全部証明書を必須書類とし「必ず正本を提出」と明記する。設立予定段階での申請、認定予定通知、条件付認定を認める規定は規則にも申請手続にも見当たらない。', 'official', 'https://www.idp.ori.titech.ac.jp/wp-content/uploads/2024/12/list.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_validity_years', 'established', '期限の定めなし（更新規定なし・取消規定あり）', '規則に有効期間と更新の条項はない。第6条第2項で企業の買収・統廃合等により法人格の同一性が保たれない場合に効力を失う。第9条で社会的信用を失墜する行為等があれば学長が審査委員会の議を経て遡って取り消し、取消企業は称号記を返付し以後その事実を事業に使用できない。第8条で本学の求めに応じた事業報告書の提出義務。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_head_office_registration', 'established', '可（INDESTは月3,000円、TIPは申請制）', 'INDEST入居者募集要項の賃貸借契約欄に「法人の登記住所として本施設の住所を使用する場合は、3,000円（税込）/1か月の登記手数料が発生します」と明記。湯島・駿河台のTIP共用実験室は利用細則第12条（住所の登記）で「利用責任者は、医療イノベ機構長への申請により当該スタートアップの所在地としてシェアラボを登記することができる」と規定。', 'official', 'https://www.idp.ori.titech.ac.jp/wp-content/uploads/2026/09/bosyuyoukou-indest401-402.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_facility_lease', 'established', 'INDEST月30万円台・認定企業20%引・最長3年', 'INDEST（田町キャンパス、キャンパス・イノベーションセンター2〜4階）は定期建物賃貸借契約。公募中のセットアップオフィス401が302,000円、402が328,000円（いずれも税込・月額）、敷金なし、入居期間は1年6か月更新の最大3年。「東京科学大学認定ベンチャー称号取得企業は、賃料は上記金額から20％割引」。ほかコワーキング、オープンオフィス、セミプライベートオフィスがある。', 'official', 'https://www.idp.ori.titech.ac.jp/wp-content/uploads/2026/09/bosyuyoukou-indest401-402.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_shared_equipment', 'established', 'TIPシェアラボ利用可・学外SU月15万円の区分料金', 'TIPに係る共用実験室利用細則（令和6年細則第82号）第3条第1項が「研究開発型のスタートアップ（起業準備を含む。）」を利用対象と明記し、第3項でバイオサイエンスセンター湯島地区の共通実験機器等を利用可とする。別表のベンチ1台月額は学外者1（スタートアップ）15万円、学外者2（新規事業企業）25万円、学内者7万円の3区分。利用期間は原則3年、最大5年（第9条）。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_name_logo_use', 'established', '称号名称の使用可・取消後は使用禁止', '第2条で「称号を授与された企業は、東京科学大学認定ベンチャー及びScience Tokyo Ventureの名称を利用することができる」と明記し、第6条第1項で称号記を交付。第9条第2項で取消後は称号記を返付し、称号を授与されていた事実を事業に使用してはならない。大学ロゴ・校章の使用条件を定めた規程は規程集（521件、令和8年6月19日現在）に見当たらなかった。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_ip_license', 'established', 'ライセンス対価を株式・新株予約権で受領可', '株式等の取得に関する規則（令和6年規則第116号）第2条第5号が「研究開発成果活用促進支援」を大学保有の特許権等・ノウハウのライセンス、施設使用その他の支援業務と定義し、第3条でその対価として対象企業の株式等を取得できると定める。発明規則（令和6年規則第114号）第9条は実施許諾・譲渡等による活用に努める旨の一般規定で、ベンチャーへの優先的実施許諾や実施料減免の条項は確認できなかった。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_equity_rule', 'established', '株式等取得規則あり・理事長が審査委員会を経て決定', '研究開発成果活用促進支援に伴う株式等の取得に関する規則（令和6年10月1日規則第116号、令和8年6月16日改正）。第2条第6号で株式等を株式及び新株予約権と定義。第3条で、研究成果等を活用して起業されたベンチャー（活用しようとする企業を含む）から支援の対価として株式等の譲渡・付与の提案があった場合、理事長が株式等受入審査委員会の議を経て可否を決定。委員会は第6条で構成、評価・売却は第10条で別に定める。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_gap_fund', 'established', 'Science Tokyo GAP Fund Programを公募', 'イノベーションデザイン機構の資金支援ページが、研究と事業化の間のギャップを埋めるためのPoCを支援する制度として「Science Tokyo GAP Fund Program 2026」を2026年度公募中と公表。ほかに第3回社会変革チャレンジ賞、学生スタートアップ支援、外部のGTIEギャップファンドを案内し、年度ごとの採択者・採択課題一覧を公開。支援金額の上限はページ上に記載がなく、規程集にもGAPファンドの規則は見当たらない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/funding-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_accelerator', 'established', '1st Round・起業相談室Go Startup・EIR', 'イノベーションデザイン機構のベンチャーページが、認定ベンチャー向け支援として1st Round、ネットワーキングイベント、称号記授与式、活動スペースの支援を掲げ、起業志望者向けに起業相談室「Go Startup」、学生向け起業支援プログラムSTARTech、客員起業家（EIR）とのマッチングを案内。INDESTは入居前にコミュニティマネージャーの面談を行い入居後も支援する（募集要項3）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.idp.ori.titech.ac.jp/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_coi_sidejob', 'established', '役員兼業は理事長許可制・COI委員会と接続', '役職員兼業規則第3条で事前に理事長の許可を得て兼業でき、許可期間は2年以内。第12条で研究成果活用企業・技術移転事業者の役員等の兼業を兼業審査委員会の審査事項とする。別紙の許可基準は、共同研究等を実施していても利益相反マネジメント委員会が回避要請を通知しなければ許可することがあると定める。第17条で兼業先の未公開株式・出資持分の保有状況の報告義務。学長・理事の営利企業役員兼業は不可、出資事業者は特例（第7条）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_support_fee', 'established', '認定は無償・施設は有償（認定企業20%引）', '称号授与規則に申請料・認定料の定めはなく、機構の申請手続ページと提出書類一覧にも費用の記載がない。一方で支援の中心である施設は有償で、INDESTは月302,000〜328,000円（税込）の賃料と登記利用時の月3,000円の手数料、TIPシェアラボはベンチ1台月7万〜25万円。INDESTの電気・水道・空調・インターネット・会議室等の共用設備は無料（別紙②施設利用について）。認定企業はINDEST賃料が20％割引。', 'official', 'https://www.idp.ori.titech.ac.jp/wp-content/uploads/2026/09/besshi2-shisetsuriyou20260902.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_certified_count', 'established', '累計222社・一覧PDFを公開', '機構が公開する「東京科学大学認定ベンチャー称号授与企業」一覧PDF（2026年8月24日現在）に「累計数-222社」と記載。既に解散した企業や称号を利用しなくなった企業は掲載しない旨を注記。授与番号・名称・承認日・事業概要・設立年月日を掲載し、統合後の新規授与は番号1〜35（最新は2026年8月24日承認の3社）、旧東工大分はT番号、旧東京医科歯科大分はMD番号で継続掲載している。', 'official', 'https://www.idp.ori.titech.ac.jp/wp-content/uploads/2026/09/sciencetokyoventure_list.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_cert_rule', 'established', '東京都立大学発ベンチャー（大学等発ベンチャー支援規程）', '東京都公立大学法人大学等発ベンチャー支援に関する規程（平成24年12月28日制定、平成24年度法人規程第2号、令和8年4月1日施行版）第3条第1項第1号。称号は「東京都公立大学法人発ベンチャー」「東京都立大学発ベンチャー」「東京都立産業技術大学院大学発ベンチャー」「東京都立産業技術高等専門学校発ベンチャー」のうち適当なものを選択して使用できる。法人が運営する3校（都立大・産業技術大学院大学・産業技術高専）に共通の制度。産学公連携センターの「大学等発ベンチャー支援」ページでも同じ内容を公開している。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業後原則1年以内・知財活用型', '同規程第2条。(1)教職員等または学生等が所有する知的財産権をもとに起業、(2)法人で達成された研究成果・技術に基づく起業、(3)教職員等または学生等が設立者となり設立に深く関与、(4)教職員等または学生等であった者が原則として1年以内に設立者となり設立に深く関与、のいずれかに該当すること。教職員等は教員・職員・客員教員・非常勤教職員・特別研究員、学生等は学生・大学院生・専攻科生・研究生・研究員等を含む。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_recognition_decider', 'established', '産学公連携センター長（ベンチャー支援審査会の議）', '同規程第8条「センター長は、申請があったときは、審査会の議を経て、支援の可否を決定する」。第7条でベンチャー支援審査会を設置し、構成員はセンター長、東京都立大学総合研究推進機構長、センター長補佐、副センター長、機構長補佐、事務長、センター長指名の知的財産委員会委員（各校1名）、知的財産マネージャー1名、URAまたは産学公連携コーディネーター1名、その他指名者若干名。議長はセンター長。第9条で申請者へ決定を通知し法人内関係部署へ報告する。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_cert_pre_registration', 'not_started', '不可（申請に登記簿の写しが必須）', '同規程第6条は提出書類を「大学等発ベンチャー支援申請書」「登記簿の写し」「企業概要及び事業内容が分かる資料」と列挙しており、登記簿の写しが必須。設立予定段階での申請、認定予定通知、条件付認定の規定は置かれていない。支援企業一覧でも設立日の2〜4か月後に支援開始となっており、登記後に申請する運用。ただし場所については、インキュベーションルーム管理運営規程第5条第1号〜第3号で「起業を志すもの」も入居対象とされ、設立前でも入居申請はできる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_validity_years', 'established', '5年以内でセンター長が定める期間・再申請可', '同規程第5条「支援期間は、5年を超えない範囲でセンター長が必要と認める期間」とし、再申請を妨げない。第11条第1項で代表者は毎年度事業報告書をセンター長に提出する義務があり、解散・破産・再生手続・更生手続・不正競争防止法の罰則確定は速やかに報告（同条第2項）。第12条で定義からの著しい逸脱、社会的信用の失墜、企業活動の実態消滅、事業報告の拒否等があればセンター長が支援決定を取り消せる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_head_office_registration', 'established', '可（インキュベーションルーム入居中に限る・有償）', '大学等発ベンチャー支援規程第3条第1項第2号「法人の管理するインキュベーションルームに入居している場合において、その入居期間中に限り、登記の住所を当該施設の住所とすること」。東京都立大学日野キャンパス6号館インキュベーションルーム管理運営規程第9条第3項も同旨で、登記を行うときは管理責任者へ申請が必要（同条第4項）。入居料等の負担が前提のため無償ではなく、入居期間が終われば登記住所として使えなくなる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000307.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_facility_lease', 'established', '日野キャンパス6号館インキュベーションルーム・有償・3年', '東京都立大学日野キャンパス6号館インキュベーションルーム管理運営規程（令和5年6月8日、令和5年度法人規程第3号）。第5条第4号で認定ベンチャーの称号使用を認められた者のうち起業後5年以内のものが入居対象。第6条第2号で入居期間は原則として創業後10年目を超えない範囲で3年以内、連携室会議の審査を経て2年以内の更新を2回まで可。別表（第10条関係）で入居料は36平米が月額108,000円、73平米が月額219,000円、機器使用料は月額21,000円。管理責任者は総合研究推進機構長。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000307.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_shared_equipment', 'established', '共用センターの3Dプリンター4種を学内料金で利用可', '総合研究推進機構「研究機器共用センター」ページに「3Dプリンター（樹脂カラー、カーボン樹脂、微細加工、金属ワイヤーの4種）は、共同研究先機関・企業や、本学のインキュベーションルームに入居する方等、学外の方にも利用いただけます。料金は学内料金と同額です」と明記。学内料金は樹脂カラー2,200円/時、カーボン樹脂1,910円/時、微細加工1,270円/時、金属ワイヤー1,530円/時。原子分解能分析電子顕微鏡は学内3,000円/時に対し学外26,000円/時の設定。設置要綱の本体は学内限定で非公開。', 'official', 'https://research-miyacology.tmu.ac.jp/infrastructure/hino-center/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_name_logo_use', 'established', '称号使用可・ロゴは学外者の取扱いを別に定める', '大学等発ベンチャー支援規程第3条第1項第1号で4種の称号から選んで使用できる。同条第2項は「大学等発ベンチャーの称号を使用したことによって生じた損失及び損害について、法人は、いかなる法的責任も負わない」と定める。シンボルマーク・ロゴタイプは東京都立大学におけるシンボルマーク等の取扱いに関する規程（令和2年3月26日、平成31年法人規程第23号）第3条第2項で使用できるのが大学等関係者に限られ、第5条で「大学等関係者以外の者が使用しようとする場合については、別に定める」とされ、その定めは公開されていない。［検証エージェントは出典を開けず未照合］', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000282.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_ip_license', 'established', '実施料の延払い・減免、対価の新株予約権化', '東京都公立大学法人知的財産取扱規則（平成17年4月1日、平成17年度法人規則第47号）第29条「大学発ベンチャーに対する優遇措置」＝法人は教職員等が設立したベンチャー企業に対し、法人に帰属された知的財産権の実施許諾について実施料の延払い及び減免等の優遇措置を講じるなどの支援ができる。第30条で専用実施権の設定等も可能（適切な実施がない場合は解消）。譲渡・放棄・実施許諾は審査会の審議に基づきセンター長が決定（第28条）。加えて大学等発ベンチャー支援規程第3条第1項第3号でライセンス対価の全部または一部を新株予約権にできる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000083.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_equity_rule', 'established', 'ライセンス対価を新株予約権化可・株式の規程なし', '大学等発ベンチャー支援規程第3条第1項第3号「法人が所有する知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること」が根拠。産学公連携センターのベンチャー支援ページにも同文を掲載。一方、株式そのものの取得・評価・保有・処分を定めた規程は、法人例規集の規則集・規程集の全章の目次を確認した範囲では見当たらず、知的財産取扱規則にも株式に関する条文はない。新株予約権の評価方法や処分手続を定めた下位規程も公開されていない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_gap_fund', 'established', 'TMU GAPファンドと設立経費（登記費用）支援', '総合研究推進機構「ベンチャー支援」ページの支援メニューに「TMU GAPファンド（学内限定ページ）」「ベンチャー設立経費（登記費用）」「TAMA-LEAP」「インキュベーションルーム」「外部の補助金・支援金等（GTIE、大学発ベンチャー支援、海外特許申請費）」を掲載。同ページのニュース欄に「2026年度 TMU GAPファンド（起業活動支援プログラム）募集について」（2026年4月13日、募集終了）があり、毎年度の公募として運用されている。支援額・採択件数・応募要件は学内限定ページのため未確認。［検証エージェントは出典を開けず未照合］', 'official', 'https://research-miyacology.tmu.ac.jp/igac/support-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_accelerator', 'established', 'TAMA-LEAP（無料）と起業推進係の相談窓口', 'TAMA-LEAPは東京都立大学が事務局となり多摩地域の大学・自治体・金融機関・企業が連携するスタートアップ・エコシステム。コアプレイヤー（研究成果を用いて起業したい者、都立大の大学等発ベンチャー、インキュベーションルーム入居者、起業を目指す教員・学生・OB、多摩エリアの研究開発型ベンチャー）は参加申込書の提出と運営委員会の承認で加入でき、費用は無料。支援内容は資金調達支援、試作・設計、起業・経営相談、法務・知財相談、施設利用、専門家・メンターによる伴走支援。窓口は産学公連携センター事務局（研究推進課 起業推進係）。［検証エージェントは出典を開けず未照合］', 'official', 'https://research-miyacology.tmu.ac.jp/igac/tama-leap/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_coi_sidejob', 'established', '役員兼業は許可制（原則3年）・利益相反委員会審査', '大学等発ベンチャー支援規程第4条第4号で、教職員による起業の場合は兼業等に関する規則等に基づく手続と許可が適正になされていることが支援の条件。教職員の兼業等に関する規程（平成19年3月30日、平成18年度法人規程第27号）第2条で兼業許可は原則3年まで、営利企業の役員兼業は任期を考慮した期限付きで許可可能。第5条は研究成果活用兼業（研究成果を活用する事業の役員就任）の許可要件を定める。利益相反規程（平成20年3月31日）第3条は兼業・共同研究・知財の実施許諾および株式等の経済的利益の取得を管理対象とし、第5条で利益相反マネージメント委員会を設置。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000215.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_support_fee', 'unknown', null, '［自動検証で否認: 入居料下限は実際40,500円、主張108,000円は過小］元の主張(established): 認定と称号は無償・施設と機器は有償（減免可）。大学等発ベンチャー支援規程には申請手数料や認定の対価に関する定めがなく、称号使用とライセンス対価の新株予約権化は費用を伴わない措置。一方インキュベーションルーム管理運営規程第10条で入居者は入居料（月額108,000円〜219,000円）、機器使用料（月額21,000円）、光熱水費等を負担し、同条第4項で管理責任者が必要と認める場合は減額・免除ができる。研究機器共用センターの機器は時間単価制。知財ライセンスは実施料が発生するが知的財産取扱規則第29条で延払い・減免の優遇がある。TAMA-LEAPの参加費は無料。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_certified_count', 'established', '28社認定・一覧公開（うち7社は支援終了）', '産学公連携センターの大学等発ベンチャー支援ページに支援企業一覧（No.1〜28）を、区分・会社名・本社所在地・事業内容・設立日・支援開始日つきで公開。区分は東京都立大学発ベンチャー、東京都立産業技術大学院大学発ベンチャー、東京都公立大学法人発ベンチャー、首都大学東京発ベンチャー。注記でSOCIAL ROBOTICS、スリーダムアライアンス、TCラインズ、ユーカリヤ、R&Dゲート、ABRI、ハルタゴールドの7社が支援終了と明記され、差引21社が支援中。最新はNo.28 株式会社nonob-i lab（2026年2月1日支援開始）。', 'official', 'https://www.tokyo-sangaku.jp/support-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_cert_rule', 'unknown', null, '大学発ベンチャー（スタートアップ）認定制度の規程・称号ページは公開情報に見当たらない。産官学連携担当の事業案内は技術移転・技術相談・受託/共同研究・地域連携・知財創出・セミナー・広報の7メニューでベンチャー認定を含まない。学校法人東京電機大学規程集は「学内者専用閲覧サイト」（教職員ページ）のため規程の有無を外部から確認できない。2024年11月28日付ニュースでは東京都事業の内容を「大学発スタートアップを立ち上げるサポート体制の模索」と記載しており、少なくとも当時は認定制度として確立していない。', 'unknown', 'https://www.dendai.ac.jp/news/20241128-02.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_eligible_scope', 'unknown', null, '認定制度自体が確認できないため対象範囲も不明。参考として、東京都「大学発スタートアップ創出支援事業」での支援対象は「本学教員」と明記（2024年11月28日ニュース）。創業支援施設かけはしの募集対象は大学関係者に限定されず「創業を予定または創業後5年未満の法人または個人」「足立区内で引き続き事業を行う意思」「区内産業の活性化に寄与する事業」（募集要項5.募集対象）で、教職員・学生・卒業生といった身分要件は設けていない。', 'unknown', 'https://www.dendai.ac.jp/news/20241128-02.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_recognition_decider', 'unknown', null, '認定の決裁者・審査主体を定めた公開規程は見つからない。参考として、創業支援施設かけはしの入居可否は「創業支援施設入居者選考委員会」の審査結果に基づき決定し、各分野の専門家で構成される審査会が第一次（書類）・第二次（面接）の二段階で審査する（募集要項2.(3)、9.、10.）。これは施設入居の審査であり、大学発ベンチャー認定の決裁主体ではない。', 'unknown', 'https://www.tdu-kakehashi.com/wp-content/uploads/2026/08/recruitment_guidelines_incubationoffice_202612.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_cert_pre_registration', 'unknown', null, '認定制度が確認できないため、登記前申請・認定予定通知・条件付認定の取扱いも不明。参考として、創業支援施設かけはしは「創業を予定」の段階で申込可能で、入居後2か月以内に創業手続（法人の場合は法人登記、個人は開業届）を完了することを利用条件としている（募集要項5.(2)、6.(5)）。設立前の事業者を受け入れる運用は施設側に存在する。', 'unknown', 'https://www.tdu-kakehashi.com/wp-content/uploads/2026/08/recruitment_guidelines_incubationoffice_202612.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_validity_years', 'unknown', null, '認定の有効期間・更新に関する公開情報なし。参考として、創業支援施設かけはしの入居期間は入居開始日から2年間、審査により認められた場合は1年ごと最長5年間の延長が可能で、起業日または入居開始日のいずれか早い日から起算して5年目に属する年までが上限（募集要項3.入居期間）。シェアードオフィスは原則1年間。', 'unknown', 'https://www.tdu-kakehashi.com/wp-content/uploads/2026/08/recruitment_guidelines_incubationoffice_202612.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_head_office_registration', 'established', '創業支援施設かけはしへ本店登記可（有償・登記義務）', '募集要項6.利用条件で、(1)法人の場合は本社として利用すること（営業所としての利用は不可）、(4)既に法人登記している場合は入居後2か月以内に法人登記の所在地を創業支援施設内の住所へ変更すること、(5)創業予定の場合は原則として入居後2か月以内に創業手続（法人登記）を完了すること、と定める。登記可能というより本店登記が入居条件。施設は東京都足立区千住旭町38番1号（東京千住アネックス、足立区立旧第十六中学校）で、大学キャンパス内ではなく大学と足立区の連携事業施設。利用は有償。', 'official', 'https://www.tdu-kakehashi.com/wp-content/uploads/2026/08/recruitment_guidelines_incubationoffice_202612.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_facility_lease', 'unknown', null, '［自動検証で否認: シェアード入居1年の記載が典拠に無し］元の主張(established): 創業支援施設かけはし個室14室（月25,200円・最長5年）。東京電機大学と足立区の連携事業「創業支援施設かけはし」。インキュベーションオフィスは全14室・各31.5㎡の個室（4階）。使用料は入居1〜3年目が月25,200円、4〜5年目が月29,000円（いずれも税別）、共益費月16,000円（税別）、保証金120,000円。24時間利用可（宿泊不可）。ほかにシェアードオフィス（入居原則1年）。足立区と大学が周辺相場の2/3〜3/4を負担する補助金事業（募集要項1.、7.、8.）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_shared_equipment', 'unknown', null, '千住キャンパス4号館40213室に分析センターがあり「教育/研究に資する機器」を管理運営し、予約システムと講習会を持つが、学外者・企業・ベンチャーの利用可否と料金区分は公開ページで確認できなかった。産官学連携担当の事業案内にも設備・機器利用のメニューはない。かけはしの共用施設は3階交流室2室（無料）にとどまり、研究機器の共用ではない。', 'unknown', 'https://analysis.dendai.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_name_logo_use', 'unknown', null, '称号制度そのものが確認できず、大学名・ロゴ・校章の使用条件を定めた公開規程も見つからない。参考として、創業支援施設かけはしの公式サイトは入居メリットとして「住所に『東京電機大学』が入って信頼感バツグン」と説明しており、施設名と登記住所に大学名が入る点は明示されている。ただしこれは施設住所の表示であり、企業が大学名・ロゴを名乗る許諾の制度ではない。', 'unknown', 'https://www.tdu-kakehashi.com/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_ip_license', 'unknown', null, '知的財産ポリシーは公開されているが、掲載内容は目的・基本的考え方・定義・対象者・推進体制の5項目にとどまり、発明の帰属、実施許諾の条件、大学発ベンチャーへの優先的・独占的実施許諾、対価減免、株式対価といった条項は記載されていない。産官学連携担当の事業案内には「大学が所有する特許の実施許諾」という一般的な技術移転メニューがあるのみ。詳細な知財規程は学内者専用の規程集にあると見られ、外部から内容を確認できない。', 'unknown', 'https://www.dendai.ac.jp/crc/tlo/corporation/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_equity_rule', 'unknown', null, '大学がベンチャーの株式・新株予約権を取得・保有・処分するための規程やポリシーは公開情報に見当たらない。知的財産ポリシーの公開部分にも対価としての株式取得の記載はない。学校法人東京電機大学規程集は「学内者専用閲覧サイト」であり、規程の存否を外部から確認できない。', 'unknown', 'https://www.dendai.ac.jp/staff/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_gap_fund', 'unknown', null, '学内GAPファンド、起業準備資金、POC資金の公開制度は見つからない。産官学連携担当が公表する資金支援は「令和7年度 足立成和信用金庫・東京電機大学 企業ニーズ向け研究費支援事業」で、足立区に本店等を持ち同信金が推薦する企業との共同研究について、大学側が必要とする研究費の3/4（上限100万円/年度、最長3年間）を寄付金原資で支援するもの。地域企業との共同研究費支援であり、起業前シーズへのGAP資金ではない。', 'unknown', 'https://www.dendai.ac.jp/crc/tlo/corporation/supportproject.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_accelerator', 'unknown', null, '［自動検証で否認: 採択9大学等は別URL(1128記事)の内容］元の主張(established): 東京都事業のアクセラ5件・伴走支援とDEMO DAY。2024年度に東京都「大学発スタートアップ創出支援事業」（環境構築型、採択9大学）へ事業名「発明の社会実装拡大による社会貢献」で採択。スタートアップ立ち上げ専門人材による適正評価・提案・実現検証・事業化への伴走型支援を本学教員に提供し、コーディネーターはReGACY Innovation Group。2026年2月19日付で5件のアクセラレータープログラム支援と、2026年3月11日Tokyo Innovation Base（丸の内）でのDEMO DAY開催を告知。かけはしではインキュベーションマネージャー4名が経営相談を無料で受け付ける。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_coi_sidejob', 'unknown', null, '「社会連携・社会貢献に関する基本方針」に、利益相反マネジメント規程へ研究インテグリティの確保を追加し国際化・オープン化に対応する体制を整備した旨の記載があり、利益相反マネジメント規程の存在自体は公式ページで確認できる。ただし規程本文は公開されておらず、教職員の役員兼業・休職兼業の許可制度、株式保有の扱い、COI審査との接続は学内者専用の規程集にあり外部から確認できない。', 'unknown', 'https://www.dendai.ac.jp/crc/tlo/about/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_support_fee', 'unknown', null, '［自動検証で否認: セミナー・学生講座の無料表記が典拠に無し］元の主張(established): 施設利用は有償、経営相談・交流室・セミナーは無料。創業支援施設かけはしの入居は有償で、使用料月25,200円（4〜5年目は29,000円）＋共益費月16,000円（いずれも税別）＋保証金120,000円、電気代・通信費は入居者負担（募集要項8.）。一方、インキュベーションマネージャー4名の経営相談、3階交流室2室、セミナー・交流会は無料（募集要項11.(5)(6)）。学生・若手研究者向けアントレプレナー講座も参加費無料。認定制度に基づく支援の対価は、制度自体が確認できないため不明。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_certified_count', 'unknown', null, '認定ベンチャーの社数や一覧を公開するページは見つからない。創業支援施設かけはしは入居企業一覧を公開しており、インキュベーションオフィス7社（KIMONO工房 奏、株式会社FAVION、株式会社otetemo、西川茂孝税理士事務所、株式会社ハウスクリーニング東京、クロロス株式会社、MemoriaLab）とシェアードオフィス3社の計10社が掲載されているが、これは地域創業支援施設の入居企業であり大学発ベンチャーの認定社数ではない。', 'unknown', 'https://www.tdu-kakehashi.com/introduce/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_cert_rule', 'established', '神戸大学発ベンチャー（認定規程・称号授与）', '「国立大学法人神戸大学における大学発ベンチャーの認定に関する規程」（令和3年7月27日制定、令和8年7月28日最終改正）第1条で研究成果を活用した起業の促進を目的に「神戸大学発ベンチャー」として認定する旨を定め、第5条で学長が別記様式2により称号を授与する。第8条で大学は製品・サービスの品質や経営状況を保証しない旨の免責を明記。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_eligible_scope', 'established', '研究成果・承継特許型と教職員・学生等の設立関与型', '認定規程第2条各号。(1)本学で承継した特許に基づく起業、又は本学で創出された研究成果もしくは習得した技術等に基づく起業、(2)本学の教職員、学生等が設立者となり又は設立に深く関与して起業したもの、(3)本学の支援により起業したもの、又は学長が認めたもの。卒業生・退職者について「卒業後○年以内」といった年限規定は置いていない。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_recognition_decider', 'established', '学長（社会共創部門・イノベーションデザイン部会議の議）', '認定規程第3条第2項。学長は「神戸大学学術・社会共創機構社会共創部門及び共創事業部門イノベーションデザイン部会議」の議を経て認定を決定する。取消も同会議の議を経る（第10条第1項）。事務は学術研究・社会共創推進部社会共創課（第12条）。機構規則（119000011）第5条で社会共創部門・共創事業部門イノベーションデザイン部の設置を確認した。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_cert_pre_registration', 'unknown', null, '［自動検証で否認: 根拠書類名はHTMLコメント内、表示ページに無い］元の主張(not_started): 不可（登記簿謄本と定款の写しが必須）。学術・社会共創機構社会共創部門「スタートアップ支援」ページの認定申請提出書類が、認定申請書（別記様式1）、大学発ベンチャー登録票、登記簿謄本（3か月以内のもの）、定款の写し、参考資料となっており、設立登記済みが前提。認定規程第2条各号も「起業したもの」と既設立を前提としており、設立予定段階の条件付認定や認定予定通知の定めは規程・公式ページのいずれにもない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_validity_years', 'established', '認定日から3年経過年度の8月末日まで・更新可', '認定規程第6条第1項で有効期間は「認定の日から起算して3年を経過する日の属する年度の8月末日まで」。第2項で期間満了の3月前までに更新申請が必要、第3項で認定手続（第3条第2項）を準用。令和8年7月28日改正の附則第2項により、施行時に既に称号を授与されている認定ベンチャーの有効期間は令和11年8月31日まで。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_head_office_registration', 'established', '可（貸与施設を所在地とする商業登記を認容）', '認定規程第11条第1項第2号「貸与した施設について，当該認定ベンチャーの所在地とする商業登記を認めること」を支援メニューとして明記。前提となる施設貸与は同項第1号の優遇措置によるが、施設使用規程（110000442）第8条により施設の使用は原則すべて有償のため、登記自体は認めるが場所の確保は有償となる。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_facility_lease', 'established', '産官学連携本部棟に入居可・月3,500円/㎡・年度更新', '認定規程第11条第1項第1号で事務室又は研究室として学内施設の貸与に優遇措置。「神戸大学産官学連携本部棟入居者募集要領（令和8年度入居用）」で申請対象に大学発ベンチャーの起業者・起業しようとする者を含め、月額平米単価は学内者1,800円、神戸大学発ベンチャー3,500円、その他学外機関4,500円（税込・光熱水料込、別途オフィス賦課金200円）。入居期間は原則1年度で委員会の議により年度毎更新、転貸禁止。BMO拠点棟も別途募集。', 'official', 'http://www.innov.kobe-u.ac.jp/document/epd-applicationguide2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_shared_equipment', 'established', '機構の共用施設・設備機器を利用可・経費は利用者負担', '神戸大学学術・社会共創機構施設利用規程（令和8年6月30日制定）第2条で共用施設の利用（入居を含む）、機構が管理・運用する設備及び機器の利用、受託分析サービスを対象とし、第3条で産官学連携を目的とする利用を認める。第7条で経費は利用者負担、機構長が特に必要と認めるときは減免。利用資格・料金は各施設（コアファシリティセンター等）が個別に定めるため、学内料金／学外料金の区分は公開情報では確認できなかった。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/119000076.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_name_logo_use', 'established', '称号使用可・ロゴマークは使用許可制', '認定規程第5条で学長が「神戸大学発ベンチャー」の称号を授与、第11条第1項第5号で本学のロゴマークの使用許可を支援として列挙。第7条（使用の制限）で自社の製品、サービス等の内容及び品質を保証するために称号を使用してはならないと制限。第10条第4項で認定取消後は称号記を返還し、取消日以降は称号を事業に使用できない。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_ip_license', 'established', '実施料の延べ払い・減免等の優遇措置', '国立大学法人神戸大学知的財産取扱規程第21条（大学発ベンチャーに対する優遇措置）「大学発ベンチャー企業に対するライセンスについては，実施料の延べ払い，減免等の優遇措置を行い，起業の推進と当該ベンチャー企業の育成を支援するものとする」。独占的実施許諾の明文はない。株式等取扱規則第11条により、実施許諾等の対価として株式等を取得した場合の学内取扱いは知財規程を準用する。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000225.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_equity_rule', 'established', '株式等取扱規則あり・寄附と支援対価と出資', '国立大学法人神戸大学株式等取扱規則（令和2年3月13日制定、令和5年3月31日最終改正）第1条で、寄附及び知的財産のライセンス、施設・設備の提供、技術指導等の支援の対価等として取得する株式・新株予約権・新株予約権付社債を対象。株式等受入審査会（第4条）と株式等評価会（第7条）を置き、外部専門家の意見を参考に評価額を決定。受入・管理・売却は役員会の議を経て学長が決定（第10条）。共益権は原則不行使だが出資取得分は必要に応じ行使（第8条）。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000839.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_gap_fund', 'established', 'うりぼーファンド最大300万円とKSAC-GAPファンド', '「2026年度 神戸大学GAPファンドプログラム（うりぼーファンド）応募要領」（2026年2月16日、産官学連携本部長名）。A ディープテック型起業枠は最大300万円程度、B 社会課題解決型起業・若手・学生枠は最大50万円程度、採択10〜15件程度、助成期間2026年4月〜2027年3月末。申請者は本学の教職員・学生。JST START事業大学・エコシステム推進型（2020年度採択）を背景に学内独自ファンドを併設し、KSAC-GAPファンド（JST基金事業）にも共同機関として参画。', 'official', 'http://www.innov.kobe-u.ac.jp/document/2026Uribofund.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_accelerator', 'established', '起業推進部の相談窓口・起業部・うりぼーミートアップ', '学術・社会共創機構社会共創部門起業推進部が認定と起業の相談窓口（arc-startup宛メール）。神戸大学起業部（2022年5月創部）でチームによる事業計画作成とコンテスト応募。うりぼーファンド要領第8項で採択者向けの交流連絡会「うりぼーミートアップ」（アントレプレナーシップ講習を含む）と成果報告会「DemoDay」への参加、公募期間中の相談会（オフィスアワー）を規定。大学VCとして株式会社神戸大学キャピタル、認定TLO関連会社として株式会社神戸大学イノベーション。', 'official', 'http://www.innov.kobe-u.ac.jp/entrepreneur/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_coi_sidejob', 'established', '兼業規程・利益相反規則の手続履行が申請条件', '認定規程第4条第4号で、本学の教職員が設立したものについては「国立大学法人神戸大学職員兼業規程及び神戸大学利益相反マネジメント規則並びにその他本学における関係規則等に定める所要の手続及び許可等が適正になされていること」を認定申請の条件とする。認定制度が兼業許可と利益相反マネジメントの履行を入口で紐付けている。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_support_fee', 'established', '認定は無償・施設入居と設備利用は有償', '認定規程には申請手数料の定めがなく認定自体は無償。第11条第2項で支援は本学の関係規則等によるとされ、施設使用規程第8条は「別に定めのある場合を除き，すべて有償」と規定。産官学連携本部棟の神戸大学発ベンチャー枠は月額平米3,500円（税込）。機構施設利用規程第7条も経費は利用者負担で、機構長が特に必要と認めるときのみ減免。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000442.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_certified_count', 'established', '54社・一覧公開（最新2026年8月27日）', '社会共創部門「スタートアップ支援」ページに「神戸大学発ベンチャー一覧」として会社名と認定日の表を公開。2026年9月5日時点で54件（重複なし）。最初は2021年11月9日認定の株式会社Mediest等、最新は2026年8月27日認定の株式会社やぁMan。多くの行に各社サイトへのリンクが張られている。', 'official', 'http://www.innov.kobe-u.ac.jp/entrepreneur/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_cert_rule', 'established', '群馬大学発ベンチャー（認定及び支援に関する規程）', '「国立大学法人群馬大学における大学発ベンチャーの認定及び支援に関する規程」（令和6年8月1日制定・施行）。第5条第1項で学長が称号記を交付し「群馬大学発ベンチャー」の称号を授与する。第15条で認定・支援の事務は研究推進部産学連携推進課が処理。第17条で改廃は役員会の議を経て学長が行う。附則第2項により施行前から活動する企業も申請・承認を要し、承認日の遡及は不可。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_eligible_scope', 'established', '教職員・学生の知財／研究成果活用型、退職卒業後3年以内', '認定規程第2条各号。(1)本学の教職員又は学生が所有する知的財産権に基づいて設立されたもの、(2)本学で達成された研究成果又は習得した技術を基に設立したもの、(3)本学の教職員、学生等が発起人又は設立時に取締役相当となるなどして設立したもの（退職、卒業等の後に設立した場合は退職・卒業等から設立までの期間が3年以内のものに限る）、(4)その他学長が特に必要と認めたもの。第4条で公序良俗、名誉毀損等のおそれがないことも申請条件。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_recognition_decider', 'established', '役員会が認定、研究・産学連携推進機構会議の議を経る', '認定規程第3条。申請者は認定申請書を学長に提出し、学長は研究・産学連携推進機構会議の議を経て役員会にて認定を行い、結果を文書で通知する（第2項）。第3項で審議に際し外部有識者への意見聴取と申請者面接が可能。機構会議は「群馬大学研究・産学連携推進機構規則」第7条で規定され、機構長（理事・研究企画担当）を議長に、副機構長、各部門・センター長、共同教育学部長ほか各研究科長等、研究推進部長で構成する。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_cert_pre_registration', 'unknown', null, '認定規程第2条は各号とも「設立されたもの」「設立したもの」と設立済み法人を前提にした書きぶりで、附則第2項も「施行前に活動している企業」を対象とする。第3条第1項の申請書に添える必要書類は第16条により「別に定める」とされ規程本文に列挙がなく、申請様式も規則集・ベンチャー支援サイトのいずれでも公開されていない。設立登記前の申請可否、認定予定通知や条件付認定の有無を明示した記述は確認できなかった。', 'unknown', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_validity_years', 'established', '称号使用は5年間、再申請可', '認定規程第5条第2項「『群馬大学発ベンチャー』の称号は、5年間使用することができる。ただし、再申請することを妨げないものとする」。第7条第1項で決算日から3か月以内の事業報告書・収支決算書の提出を毎年度義務づけ、第8条で代表者からの認定解除・称号返付の申出が可能、第9条で定義からの逸脱、社会的信用の失墜、事業報告書の不提出等を取消要件とする。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_head_office_registration', 'established', '可、貸与施設を本店として商業登記を認める', '認定規程第10条第2号「貸与した施設について、当該認定大学発ベンチャーの所在地とする商業登記を認めること。この場合において、退去時に登記場所を変更したことを示す書面を本学に提出しなければならない」。登記できるのは大学から貸与を受けた施設に限られ、その前提となる施設貸与は同条第1号により有償。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_facility_lease', 'established', '機構施設を有償貸与、5年以内、月額400〜500円/㎡', '認定規程第10条第1号で施設・設備等の有償貸与を規定。具体の受け皿は「群馬大学研究・産学連携推進機構施設利用要項」（平成29年2月1日制定、令和6年6月1日改正）で、第3の第13号が「本学の研究成果を基にした実用化研究及びベンチャー事業」を利用目的に、第4の第3号が「本学の研究成果の活用を目指す者」を利用資格に挙げる。利用期間は5年以内（機構長が認めれば延長可）。桐生地区A〜C棟の実験研究室・創造開発室は月額400円/㎡、荒牧の次世代モビリティ社会実装研究センターは500円/㎡、いずれも光熱水料を別途負担。短期利用はCRANTS試験路が日額20,000円。第11の3項で機構長が認めれば全部又は一部を免除できる。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_20/sec_2020/202710.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_shared_equipment', 'established', '学外料金で利用可、学内負担額＋1,000円/単位', '認定規程第10条第1号が設備等の有償貸与を定める。全学の共用体制は「研究設備・機器の共用化推進に関する規程」（令和8年5月11日制定）で、第2条が共用を「本学の裁量により学外者の利用も可能とすること」と定義し、取得価格500万円以上の設備を原則共用対象として共用機器管理システムで予約・料金を管理する。「コアファシリティ総合センターライフサイエンス分野学外者利用要項」（令和7年10月1日制定）第2の3項により、学外者の利用料は学内負担額に1,000円/単位を加算した額。認定大学発ベンチャー専用の減額区分は確認できなかった。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_20/sec_2080/208320.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_name_logo_use', 'established', '称号は商標・商号・広告に使用可、品質保証目的は禁止', '認定規程第5条第3項「『群馬大学発ベンチャー』の称号は、認定期間中は、商標、商号、広告及び宣伝に使用することができる」。第6条で製品・サービスの内容及び品質を保証するための称号使用を禁止し、第13条で大学は品質を保証しないと明記。第9条第3項により取消後は認定を受けていた事実を事業に使用できず、称号記を返付する。大学ロゴ・校章の使用条件を定めた規程は規則集で確認できなかった。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_ip_license', 'established', '独占的通常実施権、対価の低額設定、株式・新株予約権対価', '認定規程第10条第1項第4号が知的財産権・研究成果等の譲渡、提供、実施権設定、実施許諾、利用許諾についての優遇措置を掲げ、第11条がその内容を限定列挙する。(1)知的財産権の独占的通常実施権を設定すること、(2)契約において本学が受け取る対価の金額を通常と比べて低額となるように設定すること、(3)対価を当該認定ベンチャーの株式又は新株予約権で受け取ること。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_equity_rule', 'established', '株式等取扱規程あり、ライセンス対価として取得', '「大学発ベンチャー企業等から対価として取得する株式等取扱規程」（令和6年8月1日制定）。第3条は現金不保有・資金繰り難など4要件のいずれかで対価を株式等で収納可とする。第4条で機構長を委員長とし部門長・財務部長等で組織する審査委員会が財務状況と事業計画を審査（委員の3分の2以上の出席で議決、外部専門家の意見活用可）、第5条で学長が取得を決定。第8条は配当等の経済的権利は行使、議決権等の経営参加権は原則不行使。第9条で未公開株は公開後速やかに売却、第10条でインサイダー取引防止責任者を置く。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061350.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_gap_fund', 'established', 'IJIE-GAPファンド、ステップ2で最大3,000万〜6,000万円', '北関東・甲信地域の大学等で構成するIJIE（Inland Japan Innovation Ecosystem）が、JST大学発新産業創出基金事業スタートアップ・エコシステム共創プログラムの採択を受けて運営する「IJIE-GAPファンドプログラム2026」。群馬大学は参画大学。ステップ1（起業シーズ発掘育成）とステップ2（事業化検討）の2段階、各段階にスタートアップ枠とインパクトビジネス枠を置く。ステップ2スタートアップ枠は1件あたり直接経費で「スタンダード」最大3,000万円、「スタンダード＋α」最大6,000万円、別途30％の間接経費を配分。学内独自のGAPファンドや起業支援金は確認できなかった。', 'official', 'https://ijie.jp/cms/wp-content/uploads/2025/12/IJIE_GAP%E3%83%95%E3%82%A1%E3%83%B3%E3%83%89%E3%83%97%E3%83%AD%E3%82%B0%E3%83%A9%E3%83%A02026%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85%E3%82%B9%E3%83%86%E3%83%83%E3%83%972%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%88%E3%82%A2%E3%83%83%E3%83%97%E6%9E%A0.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_accelerator', 'established', '相談・仲介を規程化、IJIEで事業化推進機関と連携', '認定規程第10条第1項第5号が「本学職員等による相談業務への対応並びに他企業への紹介及び仲介」を支援措置として規定。ベンチャー支援サイトの支援内容は、産学連携・知的財産活用センターへの相談、大学の広報媒体への掲載、連携する金融機関・自治体の起業相談担当者への取次ぎの3本。IJIE-GAPファンドは事業化推進機関・経営者候補人材と連携した実施を要件とし、採択後に起業に関する研修等の受講と研究成果報告会への参加を課す。学内単独の定例アクセラレーションプログラムは確認できなかった。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_coi_sidejob', 'established', '役員兼業許可・利益相反手続の完了が認定申請の条件', '認定規程第4条第4号は、本学の役員及び教職員が設立したものについて「理事の兼業に関する取扱要領、教職員兼業規則、利益相反マネジメント規程及びその他関係規則等に定める所要の手続、許可等が適正になされていること」を申請の条件とする。第5号は本学教職員であった者について在職中の所要の手続・許可の適正を要求。関連規程として教職員兼業規則、利益相反マネジメント規程、教員営利企業役員等兼業審査委員会規程、利益相反管理の荒牧・昭和・桐生各地区部会内規が規則集に置かれている。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_support_fee', 'established', '認定は無償、施設・設備の貸与と機器利用は有償', '認定規程第10条第1号は施設及び設備等を「有償で貸与すること」と定め、認定申請・審査・称号授与そのものに手数料を課す規定は置かれていない。機構施設利用要項第11で利用料と光熱水料は利用者負担（機構長が特に必要と認めれば全部又は一部を免除可）、模様替と原状回復費用も利用者負担（第10の2項）。共用機器は有償。知財の対価は認定規程第11条により通常より低額に設定、又は株式・新株予約権での受領が可能。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_certified_count', 'established', '11社を一覧公開（ベンチャー支援サイト）', '研究・産学連携推進機構のベンチャー支援サイトが「大学発ベンチャー数 11社」と表示し、「群大発ベンチャー企業一覧」ページで11社の企業名を公開している（株式会社グッドアイ、プライム・デルタ株式会社、株式会社GUD air、株式会社先進医用画像解析センター、アルメッド株式会社、クレスール株式会社、株式会社GUD care、（特非）e自警ネットワーク研究会ほか）。ページ上は「群大発ベンチャー」の表記で、令和6年8月施行の認定規程に基づく認定企業かどうかの区別、認定日の表示はない。', 'official', 'https://startup.opric.gunma-u.ac.jp/introduction/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_cert_rule', 'established', '自治医科大学発ベンチャー認定規程（令和2年）', '「学校法人自治医科大学における大学発ベンチャーの認定に関する規程」（令和2年規程第4号、令和2年1月9日施行）を全文確認。第1条で大学発ベンチャーの円滑かつ適正な支援を目的と定め、第5条で理事長が認定企業に「自治医科大学発ベンチャー」の称号を称号記（別記様式第2号）により授与する。第10条で認定事務は研究支援課が行う。産学官連携ページ「大学発ベンチャー」に規程本体・申請書・認定企業一覧が公開されており運用中。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_eligible_scope', 'established', '教職員・学生・退職卒業3年以内・研究成果活用型', '認定規程第2条各号。(1)本学又は本学の教職員若しくは学生（職員等）が発明者である知的財産権を基に設立したもの、(2)本学を退職・卒業・修了した者で退職等から設立までの期間が3年以内の者が所有する知的財産権を基に設立したもの、(3)その他本学で達成された研究成果又は習得した技術等を基に設立し業務の遂行に寄与するもの。認定申請書の「代表者区分」は職員（教職員であった者を含む）・学生（学生であった者を含む）・第三者から選択する。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_recognition_decider', 'established', '理事長決裁（産学連携推進委員会の議）', '認定規程第3条。申請者は認定申請書を理事長に提出し（第1項）、理事長は自治医科大学産学連携推進委員会の議を経て認定を決定し（第2項）、文書で申請者に通知する（第3項）。取消しも同委員会の議を経て理事長が行う（第8条）。同委員会は産学連携推進委員会設置規程（平成31年規程第28号）に基づき、第2条第8号で「大学発ベンチャーに関すること」を審議事項とする。委員長は副学長（第4条）、認定事務は研究支援課（第10条）。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_cert_pre_registration', 'not_started', '不可（申請書に登記簿の写しが必須）', '別記様式第1号「大学発ベンチャー認定申請書」（Word）を開いて添付資料欄を確認。添付資料は「登記簿の写し」「定款、寄付行為、規則又は規約の写し」「会社概要及び組織図」「事業報告書・収支決算書（設立後の期間が短い場合は計画書）」で、登記簿の写しが必須。記入欄も「6(1)事業開始（予定）日」に加え「6(2)設立日」を実績日として求める。認定規程第2条各号もいずれも「設立したもの」を要件とする。設立登記前の申請・認定予定通知・条件付認定の規定は置かれていない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/venture_03.doc', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_validity_years', 'established', '期限なし（企業存続中は称号使用可）', '認定規程第5条第2項「『自治医科大学発ベンチャー』の称号は、原則として企業が存続する間使用することができる」。有効期間・更新の定めはなく、代わりに第6条第1項で代表者に年度毎の事業報告書及び収支決算書を決算日から3か月以内に理事長へ提出する義務を課し、解散・破産・再生・更生・不正競争防止法違反は速やかに報告（第2項）。第7条で代表者からの認定解除申出、第8条で報告書未提出や信用失墜等による認定・称号授与の取消しを定める。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_head_office_registration', 'established', '可（貸与施設を所在地とする商業登記を承認）', '認定規程第9条（大学発ベンチャーへの支援事業）第1項第2号「貸与した施設について、当該大学発ベンチャーの所在地とする商業登記を認めること」と明記。前提として同項第1号の事務室又は研究室としての学内施設貸与を受けることが必要。貸与対象は合同研究棟の個室事務室で年間780,000円の有償（「大学発ベンチャーへの事務室等の貸与について」2(1)）。支援は本学の管理運営及び教育研究に支障のない範囲で行う（第9条第1項柱書）。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_facility_lease', 'established', '合同研究棟の個室事務室・年78万円・3年更新可', '「大学発ベンチャーへの事務室等の貸与について」（認定規程第9条第1項第1号・第3号の細目）を確認。2(1)①貸与場所＝合同研究棟 個室事務室（1室26.49㎡）、不足時は学内空きスペースの利用を検討。②貸与料金＝年間780,000円（30,000円/㎡×26㎡、平成22年10月20日学長決裁の学外オープンラボ料金を適用）。③貸与期間＝3年間とし更新を認める。2(2)手続は貸与要望書＋称号記を研究支援課へ提出し、産学連携推進委員会の承認後、大学管理スペース検討部会が可否を検討。3(1)研究室は原則として新規の貸与を行わない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_shared_equipment', 'established', '共同研究契約が条件・利用料は有償', '「大学発ベンチャーへの事務室等の貸与について」3(2)(3)及び4。研究設備等の利用は、本学と大学発ベンチャーが共同研究契約を締結した場合で、研究実施場所として指定された場所に限り認める。共同研究契約に基づき学内の共同利用実験施設を使用する場合は当該施設の利用規定に従い所定の手続をとり、利用料金が発生した場合は遅滞なく支払う。5でベンチャー社員が学内で研究に従事する場合は共同研究員等の身分を有した後から参加すると定める。学内料金・外部料金の区分規定は置かれていない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_name_logo_use', 'established', '称号は存続中使用可・校章は商標登録済', '認定規程第5条で理事長が称号記により「自治医科大学発ベンチャー」の称号を授与し、第2項で原則として企業が存続する間使用できる。第8条第3項は取消しを受けた者に称号記の返付と、取消日以降に認定を受けていた事実を事業に使用することの禁止を定める。認定申請書には称号使用で損害・不測の事態が生じた場合に大学へ損害賠償請求を行わない旨の誓約がある。校章（登録第5667916号）とシンボルマークは平成26年5月9日付で商標登録済（大学紹介「校章・シンボルマーク」）。ロゴの第三者使用許諾手続は公開情報では未確認。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_ip_license', 'established', 'ライセンス対価を株式・新株予約権で受領可', '「自治医科大学発ベンチャーから取得する株式等取扱規程」第3条「本学は、大学発ベンチャーから研究成果に係るライセンス供与等の対価の全部又は一部を、現金に代えて、株式等により取得することができる」。第2条第3号でライセンス供与等＝知的財産権の譲渡及び提供又は実施権の設定、実施許諾及び利用許諾と定義し、対象知財は発明等取扱規程第2条第4号の権利と成果有体物取扱規程第2条第1号の成果有体物。なお発明等取扱規程本文にはベンチャー向けの独占許諾や実施料減免の規定はなく、優遇は対価の株式化に限られる。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_04.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_equity_rule', 'established', '株式等取扱規程あり・学長が取得可否を決定', '「自治医科大学発ベンチャーから取得する株式等取扱規程」（令和5年規程第30号、令和5年4月1日施行、改正令和6年規程第29号）。株式等＝株式及び新株予約権（第2条第4号）。産学連携推進委員会が財務状況・将来性等の妥当性を審査して委員長が学長へ報告し（第4条）、学長が取得可否を決定（第5条）。新株予約権の権利行使・売却・処分は委員会審査と学長承認、取得後の管理は研究推進課（第6条）。売却は委員会審議を経て学長が決定（第7条）。経営参加権は原則として行使しない（第8条）。委員会の下に株式等取得検討部会を設置（設置規程第9条）。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_04.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_gap_fund', 'established', 'IJIE-GAPファンドにSU創出共同機関で参画', '信州大学を主幹機関とするIJIE（甲信・北関東5県のプラットフォーム、JST大学発新産業創出基金事業）の参画機関ページで、自治医科大学がSU創出共同機関8機関（山梨大学、宇都宮大学、群馬大学、埼玉大学、自治医科大学、埼玉医科大学、東洋大学、信州TLO）の一つとして掲載され、責任者は副学長 大槻マミ太郎。IJIE-GAPファンドプログラム2024ステップ1「プレ」の採択課題一覧に本学の大森司「革新的な血友病Aに対する遺伝子治療薬の創出」がある。学内独自のGAPファンドや起業準備資金は大学サイト上では確認できなかった。', 'official', 'https://ijie.jp/about/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_accelerator', 'established', 'オープンイノベーションセンターが仲介と上市支援', '認定規程第9条第1項第4号「オープンイノベーションセンター等による他企業への紹介又は仲介を行うこと」、第5号「本学主催のイベント、広報誌又はホームページにおいて広報を行うこと」を支援メニューとして規定。大学サイト「教育研究施設等」によればオープンイノベーションセンターは平成30(2018)年設置で、学内の有望研究シーズを見出して大型共同研究を立ち上げ、外部資金を獲得して集中的にマネジメントし、特許出願・特許実施及び上市支援まで行う。オープンラボを比較的低料金で提供し本学発ベンチャーが利用している。相談・申請窓口は研究推進課・知的財産管理係。公募型アクセラレーションプログラムは未確認。', 'official', 'https://www.jichi.ac.jp/laboratory/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_coi_sidejob', 'established', '兼業は就業規則の許可制・COI申告対象', '認定規程第4条第4号で、本学の教職員が従事する企業については「学校法人自治医科大学職員就業規則（昭和48年6月5日制定）第17条に定める所要の手続、許可等が適正になされていること」を申請条件とし、兼業許可を認定要件に接続している。利益相反マネジメント・ポリシー（平成21年4月1日制定）4(1)は、②兼業（診療活動は除く。）を行った場合、⑨企業等の株式（未公開株を含む。）・新株予約権等を取得した場合をマネジメント対象に明記し、狭義の利益相反に兼業報酬・未公開株式を挙げる。窓口は研究推進課・知的財産管理係で、利益相反委員会内規もある。就業規則本体は非公開。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/interest/interest_policy.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_support_fee', 'established', '認定は無償・事務室と設備利用は有償', '認定規程第3条〜第5条の認定手続には手数料・審査料の定めがなく、申請は申請書と添付書類の提出のみ。一方、支援は有償で、事務室貸与は年間780,000円（30,000円/㎡×26㎡）、毎年の使用料は研究支援課が請求書を発行し原則として使用日までに前納する（「大学発ベンチャーへの事務室等の貸与について」2(1)②・2(2)③）。共同利用実験施設は利用料金が発生した場合に遅滞なく支払う（同3(3)）。知財のライセンス対価は現金又は株式等（株式等取扱規程第3条）。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_certified_count', 'established', '10社・企業名と事業内容を公開', '産学官連携「大学発ベンチャー」ページの「認定企業一覧」に、2026-09-05閲覧時点で10社を実名公開。DeepEyeVision（眼科学講座・高橋秀徳准教授）、IchiGoo（分子病態研究部・西村智教授）、ナーステックラボ（看護学部・川上勝准教授）、テレバイオ（形成外科学部門・吉村浩太郎教授）、M-Axis（機能生化学部門・遠藤仁司教授）、Broad Bean Science（抗加齢医学研究部・黒尾誠教授）、キュアセル（小児科学・小坂仁教授）、Statera合同会社（内分泌代謝学部門・矢作直也教授）、レビテクノロジー（形成外科学講座・吉村浩太郎教授）、miRIPure（消化器一般移植外科学部門・大澤英之准教授）。各社に関係講座・教員名、事業内容、企業URLを併記。', 'official', 'https://www.jichi.ac.jp/kenkyushien/cooperation/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910')
