-- 385_su_support_programs_and_regulations_2026-09-10.sql
-- 2026-09-05 ultracode並列ワークフロー (1機関1エージェントの公開情報調査 + 別エージェントの引用URL照合) の結果。
-- 支援プログラム比較16項目 (institution_policy_assessments)、未登録だった規程種別 (institution_regulations / cells / versions)、
-- 新規研究機関 (institutions) を投入する。照合で否認された主張は unknown に落とし、否認理由を evidence_note に残す。
-- 既存4機関 (香川大・工学院大・NIMS・愛媛大) は 2026-05-31 入力済みの行を、新しい調査が unknown のとき上書きしない。

on conflict (regulation_id) do update set title = excluded.title, stage = excluded.stage, lifecycle_state = excluded.lifecycle_state, current_state_note = excluded.current_state_note, updated_by = excluded.updated_by, updated_at = now();

on conflict (institution_id, regulation_type_id) do nothing;

on conflict (version_id) do nothing;

on conflict (institution_id, policy_item_id) do update set status = excluded.status, attribute_value = excluded.attribute_value, evidence_note = excluded.evidence_note, source_type = excluded.source_type, source_url = excluded.source_url, confirmed_at = excluded.confirmed_at, evaluator = excluded.evaluator, updated_at = now();
